/* New Concept English Book 1 · First Things First — 课程数据
 * 说明：数据外置，避免 index.html 体积膨胀；由主脚本启动时合并进 NC_LESSONS。
 * 课文为原创改写（不使用原书原文），词汇释义 / 例句 / 讲解 / 练习均为原创。
 * 字段约定：n 课号 / title 标题 / topic 本课重点 / reading 课文 / zh 中文
 *   vocab[] {w, ph, en, zh, eg}
 *   exprs[] {en, zh, scene, struct, ex[], cat}
 *   pats[]  {en, zh, scene, struct, ex[], cat}
 *   quiz    {v, e, p}  ·  speak 口语输出任务
 */
window.NC_LESSONS_B1 = [
{n:1,title:"Excuse Me!",topic:"礼貌引起注意 · 确认物品归属",reading:"Excuse me!\n\nYes? Can I help you?\n\nIs this your bag? The black one on the chair.\n\nPardon? Is this my bag?\n\nYes, it is. Is it yours?\n\nOh, yes! It is. Thank you very much.\n\nYou are welcome. It is a very nice bag.\n\nThank you. It is a gift from my sister. I like it a lot.\n\nIt looks new. Well, have a good day!\n\nThank you. You too! Goodbye!",zh:"（原创改写）打扰一下！\n\n嗯？需要帮忙吗？\n\n这是你的包吗？椅子上那个黑色的。\n\n请再说一遍？这是我的包吗？\n\n是的。它是你的吗？\n\n哦，对！是的。太感谢你了。\n\n不客气。这个包很漂亮。\n\n谢谢。这是我姐姐送我的礼物，我特别喜欢。\n\n看起来还很新。那祝你今天愉快！\n\n谢谢，你也是！再见！",vocab:[{"w": "excuse", "ph": "/ɪkˈskjuːz/", "en": "to politely get someone's attention", "zh": "v. 原谅；打扰一下", "eg": "Excuse me, is this seat taken?"}, {"w": "pardon", "ph": "/ˈpɑːdn/", "en": "used to ask someone to say something again", "zh": "int. 请再说一遍", "eg": "Pardon? I didn't hear you."}, {"w": "bag", "ph": "/bæɡ/", "en": "a thing you use to carry your things", "zh": "n. 包；袋子", "eg": "Her bag is on the chair."}, {"w": "yours", "ph": "/jɔːz/", "en": "the thing that belongs to you", "zh": "pron. 你的（东西）", "eg": "Is this pen yours?"}],exprs:[{"en": "Excuse me.", "zh": "打扰一下", "scene": "想引起陌生人注意、从人群中挤过去，或开口提问之前。", "struct": "Excuse me（单独成句，或后接问句）", "cat": "dailychat", "ex": ["Excuse me, is this your bag?", "Excuse me, I need to get off the bus."]}, {"en": "Pardon?", "zh": "请再说一遍", "scene": "没听清对方的话，请对方重复。", "struct": "Pardon?（升调，单独成句）", "cat": "dailychat", "ex": ["Pardon? Can you say that again?", "Pardon? I didn't hear your name."]}, {"en": "You are welcome.", "zh": "不客气", "scene": "对方说 Thank you 之后的固定回应。", "struct": "You are welcome. / You're welcome.", "cat": "dailychat", "ex": ["Thanks for your help. — You are welcome.", "You are welcome. Have a nice day!"]}],pats:[{"en": "Is this your …?", "zh": "这是你的……吗？", "scene": "捡到东西、想确认物品是不是对方的。", "struct": "Is this your + 名词?", "cat": "dailychat", "ex": ["Is this your bag?", "Is this your English book?"]}, {"en": "Yes, it is. / No, it isn't.", "zh": "是的，它是。／不，它不是。", "scene": "回答 Is this / Is that 开头的一般疑问句。", "struct": "Yes, it is. / No, it isn't.", "cat": "dailychat", "ex": ["Is this your pen? — Yes, it is.", "Is that your car? — No, it isn't."]}],quiz:{"v": {"q": "pardon 的意思是：", "opts": ["请再说一遍", "不客气", "祝你好运"], "a": 0}, "e": {"q": "没听清对方说话，最自然的说法是：", "opts": ["Pardon?", "Excuse me!", "You are welcome."], "a": 0}, "p": {"q": "______ this your bag?", "opts": ["Is", "Are", "Am"], "a": 0}},speak:"说 2 句话：先用 Excuse me 开口，再用 Is this your …? 问东西是不是对方的。"},
{n:2,title:"Is This Your Pen?",topic:"一般疑问句 Is this…? · 确认物品归属",reading:"Excuse me, is this your pen?\n\nNo, it isn't. My pen is blue.\n\nIs this your pen, Anna?\n\nYes, it is. Thank you.\n\nHere you are.\n\nThank you very much.\n\nIs that your book?\n\nNo, it isn't my book. It is Tom's book. His book is red and big.\n\nI see. Well, is this your ruler?\n\nYes! It is mine. Thank you very much.\n\nYou are welcome. Goodbye!",zh:"（原创改写）打扰一下，这是你的钢笔吗？\n\n不，不是。我的钢笔是蓝色的。\n\n安娜，这是你的钢笔吗？\n\n是的，是我的。谢谢。\n\n给你。\n\n非常感谢。\n\n那是你的书吗？\n\n不，那不是我的书。那是汤姆的书。他的书又红又大。\n\n我明白了。那这把尺子是你的吗？\n\n对！是我的。太感谢你了。\n\n不客气。再见！",vocab:[{"w": "pen", "ph": "/pen/", "en": "a thing you use to write with ink", "zh": "n. 钢笔", "eg": "My pen is blue."}, {"w": "blue", "ph": "/bluː/", "en": "the colour of the sky on a fine day", "zh": "adj. 蓝色的", "eg": "I have a blue shirt."}, {"w": "ruler", "ph": "/ˈruːlə/", "en": "a long thin thing you use to draw lines", "zh": "n. 尺子", "eg": "Can I use your ruler?"}, {"w": "mine", "ph": "/maɪn/", "en": "the thing that belongs to me", "zh": "pron. 我的（东西）", "eg": "That bag is mine."}],exprs:[{"en": "Here you are.", "zh": "给你", "scene": "把东西递给对方时说的固定话。", "struct": "Here you are.（递东西瞬间）", "cat": "dailychat", "ex": ["Here you are. Your pen.", "Here you are. Be careful, it's hot."]}, {"en": "I see.", "zh": "我明白了", "scene": "听完解释后表示懂了，比 I know 更礼貌。", "struct": "I see.（单独成句）", "cat": "dailychat", "ex": ["It's Tom's book. — Oh, I see.", "I see. So you are new here."]}, {"en": "Excuse me, is this yours?", "zh": "打扰一下，这是你的吗？", "scene": "捡到东西想还给对方，比直接问名字更自然。", "struct": "Is this yours?（yours 后不接名词）", "cat": "dailychat", "ex": ["Is this yours? I found it on the floor.", "Excuse me, is this yours? It was on the desk."]}],pats:[{"en": "Is this your …?", "zh": "这是你的……吗？", "scene": "确认近处的东西属于谁。", "struct": "Is this your + 名词?", "cat": "dailychat", "ex": ["Is this your ruler?", "Is this your new bag?"]}, {"en": "It is Tom's. / It's mine.", "zh": "是汤姆的。／是我的。", "scene": "说明东西属于谁，用名词所有格或名词性物主代词。", "struct": "It's + 名词's. / It's + mine, yours, his, hers.", "cat": "dailychat", "ex": ["It's my sister's.", "It's mine, not his."]}],quiz:{"v": {"q": "mine 的意思是：", "opts": ["我的（东西）", "你的（东西）", "他的（东西）"], "a": 0}, "e": {"q": "把东西递给别人时应该说：", "opts": ["Here you are.", "Here are you.", "Give you it."], "a": 0}, "p": {"q": "Is this ______ pen?", "opts": ["you", "your", "yours"], "a": 1}},speak:"说 3 句话：先问 Is this your …? 得到否定回答后，再问另一个人，最后用 Here you are. 把东西递过去。"},
{n:3,title:"Sorry, Sir.",topic:"礼貌致歉 · 存取物品 Here is…",reading:"My coat and my bag, please.\n\nHere is my ticket.\n\nThank you, sir. Number five.\n\nHere is your bag.\n\nThis is not my bag. My bag is black.\n\nSorry, sir. Is this your bag?\n\nYes, it is. Thank you.\n\nAnd here is your coat.\n\nThank you very much. Is this the door?\n\nNo, sir. The door is over there. Goodbye, sir.\n\nIs this your umbrella?\n\nNo, it isn't. My umbrella is blue.\n\nI see. Here it is. Thank you, sir.",zh:"（原创改写）请给我我的外套和我的包。\n\n这是我的票。\n\n谢谢您，先生。五号。\n\n这是您的包。\n\n这不是我的包。我的包是黑色的。\n\n对不起，先生。这个是您的包吗？\n\n是的，是它。谢谢。\n\n这是您的外套。\n\n非常感谢。这是门吗？\n\n不是的，先生。门在那边。再见，先生。\n\n这是您的雨伞吗？\n\n不，不是。我的雨伞是蓝色的。\n\n我明白了。在这儿。谢谢您，先生。",vocab:[{"w": "coat", "ph": "/kəʊt/", "en": "a warm piece of clothing you wear outside", "zh": "n. 外套；大衣", "eg": "My coat is in the car."}, {"w": "ticket", "ph": "/ˈtɪkɪt/", "en": "a small piece of paper that shows you paid", "zh": "n. 票；小票", "eg": "Here is my ticket."}, {"w": "umbrella", "ph": "/ʌmˈbrelə/", "en": "a thing you hold over your head in the rain", "zh": "n. 雨伞", "eg": "Take your umbrella. It's raining."}, {"w": "sir", "ph": "/sɜː/", "en": "a polite way to speak to a man", "zh": "n. 先生（对男子的尊称）", "eg": "Excuse me, sir. Is this yours?"}],exprs:[{"en": "Here is your …", "zh": "这是你的……；给你你的……", "scene": "把东西交还给对方，或指出东西在哪。", "struct": "Here is + 名词. / Here's + 名词.", "cat": "dailychat", "ex": ["Here is your coat.", "Here's your ticket and your bag."]}, {"en": "Sorry, sir.", "zh": "对不起，先生", "scene": "犯了小错（拿错东西、走错路）后向男性客人道歉。", "struct": "Sorry, + 称呼.", "cat": "dailychat", "ex": ["Sorry, sir. This is not your bag.", "Sorry, madam. The shop is closed."]}, {"en": "This is not my …", "zh": "这不是我的……", "scene": "对方拿错、给错东西时的澄清。", "struct": "This is not my + 名词. / This isn't my + 名词.", "cat": "dailychat", "ex": ["This is not my coat. Mine is blue.", "This isn't my ticket. Sorry."]}],pats:[{"en": "My …, please.", "zh": "请给我我的……", "scene": "在衣帽间、寄存处取回自己的东西。", "struct": "My + 名词, please.", "cat": "dailychat", "ex": ["My coat and my bag, please.", "My ticket, please."]}, {"en": "Here is + 名词.", "zh": "……在这儿 / 给你……", "scene": "递东西、指出物品位置。", "struct": "Here is / Here's + 名词.", "cat": "dailychat", "ex": ["Here is my ticket.", "Here's your umbrella, sir."]}],quiz:{"v": {"q": "umbrella 的意思是：", "opts": ["雨伞", "外套", "票"], "a": 0}, "e": {"q": "在寄存处想取回自己的外套，应该说：", "opts": ["My coat, please.", "Your coat, please.", "Give coat me."], "a": 0}, "p": {"q": "Here ______ my ticket.", "opts": ["is", "are", "am"], "a": 0}},speak:"说 3 句话：先说 My … , please. 取东西，然后递上票 Here is my ticket.，最后拿错时用 Sorry, sir. This is not my … 道歉纠正。"},
{n:4,title:"Is This Your Suit?",topic:"一般疑问句 · 物主形容词 my/your/his/her",reading:"Is this your suit?\n\nNo, it isn't. My suit is grey.\n\nIs this your suit, Mr. Lee?\n\nYes, it is.\n\nHere you are.\n\nThank you.\n\nIs this your hat?\n\nNo, it isn't. It is her hat. Her hat is white.\n\nAnd is this your dress, Mary?\n\nYes, it is. Thank you very much.\n\nYou are welcome. Have a nice day!\n\nAnd is this your coat, Mr. Lee?\n\nYes, it is. It's a very nice coat.\n\nThank you. It's new and warm.",zh:"（原创改写）这是你的西装吗？\n\n不，不是。我的西装是灰色的。\n\n李先生，这是你的西装吗？\n\n是的，是我的。\n\n给你。\n\n谢谢。\n\n这是你的帽子吗？\n\n不，不是。这是她的帽子。她的帽子是白色的。\n\n玛丽，这是你的连衣裙吗？\n\n是的，是我的。太感谢了。\n\n不客气。祝你今天愉快！\n\n李先生，这是您的外套吗？\n\n是的，是我的。这件外套很漂亮。\n\n谢谢。它又新又暖和。",vocab:[{"w": "suit", "ph": "/suːt/", "en": "a jacket and trousers or a skirt worn together", "zh": "n. 西装；套装", "eg": "His suit is grey."}, {"w": "grey", "ph": "/ɡreɪ/", "en": "the colour between black and white", "zh": "adj. 灰色的", "eg": "I don't like grey coats."}, {"w": "hat", "ph": "/hæt/", "en": "a thing you wear on your head", "zh": "n. 帽子", "eg": "Her white hat is very nice."}, {"w": "her", "ph": "/hɜː/", "en": "belonging to a woman or girl", "zh": "pron. 她的", "eg": "Her dress is red."}],exprs:[{"en": "No, it isn't.", "zh": "不，不是的", "scene": "否定回答 Is this / Is that 的提问。", "struct": "No, it isn't.（= No, it is not.）", "cat": "dailychat", "ex": ["Is this your suit? — No, it isn't.", "Is that your hat? — No, it isn't."]}, {"en": "Here you are.", "zh": "给你", "scene": "把找到或借用的东西交到对方手上。", "struct": "Here you are.（递东西时）", "cat": "dailychat", "ex": ["Here you are. Your grey suit.", "Here you are. Two tickets for you."]}, {"en": "It's hers. / It's his.", "zh": "是她的。／是他的。", "scene": "说明东西归属，后面不再接名词。", "struct": "It's + hers / his / ours / theirs.", "cat": "dailychat", "ex": ["That bag is hers.", "The blue car is his."]}],pats:[{"en": "Is this your + 名词?", "zh": "这是你的……吗？", "scene": "确认近处物品归属。", "struct": "Is this your + 名词? → Yes, it is. / No, it isn't.", "cat": "dailychat", "ex": ["Is this your hat?", "Is this your dress, Mary?"]}, {"en": "This is / This isn't my + 名词.", "zh": "这是／这不是我的……", "scene": "声明或否认某物属于自己。", "struct": "This is (not) my + 名词.", "cat": "dailychat", "ex": ["This is my new suit.", "This isn't my bag. It's hers."]}],quiz:{"v": {"q": "grey 是什么颜色？", "opts": ["灰色", "绿色", "棕色"], "a": 0}, "e": {"q": "别人把东西递给你时，你应该说：", "opts": ["Thank you.", "Sorry.", "Pardon?"], "a": 0}, "p": {"q": "Is this ______ hat?", "opts": ["you", "your", "she"], "a": 1}},speak:"说 3 句话：用 Is this your …? 问两件不同的东西，其中一件用 Her … is … 说明是别人的。"},
{n:5,title:"Nice to Meet You",topic:"国籍与初次见面介绍 · This is…",reading:"Good morning, Mr. Blake.\n\nGood morning, Miss Lin.\n\nThis is Sophie. She is a new student. She is French.\n\nNice to meet you, Sophie.\n\nThis is Hans. He is German.\n\nNice to meet you, Hans.\n\nAnd this is Naoko. She is Japanese.\n\nHello, Naoko. Nice to meet you.\n\nThis is Chang-woo. He is Korean. Nice to meet you all!\n\nThis is Kim. He is Korean. And this is Luming. He is Chinese.\n\nNice to meet you, Luming.\n\nNice to meet you too. Welcome to our school!",zh:"（原创改写）早上好，布莱克先生。\n\n早上好，林小姐。\n\n这位是索菲。她是新来的学生。她是法国人。\n\n很高兴认识你，索菲。\n\n这位是汉斯。他是德国人。\n\n很高兴认识你，汉斯。\n\n这位是直子。她是日本人。\n\n你好，直子。很高兴认识你。\n\n这位是昌宇。他是韩国人。很高兴认识大家！\n\n这位是金。他是韩国人。这位是路明。他是中国人。\n\n很高兴认识你，路明。\n\n我也很高兴认识你们。欢迎来我们学校！",vocab:[{"w": "meet", "ph": "/miːt/", "en": "to see and talk to someone for the first time", "zh": "v. 遇见；结识", "eg": "Nice to meet you, Mr. Blake."}, {"w": "student", "ph": "/ˈstjuːdnt/", "en": "a person who studies at a school", "zh": "n. 学生", "eg": "She is a new student in our class."}, {"w": "French", "ph": "/frentʃ/", "en": "from France", "zh": "adj. 法国的；法国人", "eg": "My friend is French."}, {"w": "Japanese", "ph": "/ˌdʒæpəˈniːz/", "en": "from Japan", "zh": "adj. 日本的；日本人", "eg": "Naoko is Japanese."}],exprs:[{"en": "Nice to meet you.", "zh": "很高兴认识你", "scene": "第一次见到某人时的固定说法。", "struct": "Nice to meet you.（初次见面）", "cat": "dailychat", "ex": ["Nice to meet you, Miss Lin.", "Nice to meet you. I'm Robert."]}, {"en": "This is …", "zh": "这位是……", "scene": "把一个人介绍给另一个人。", "struct": "This is + 人名.", "cat": "dailychat", "ex": ["This is my friend Sophie.", "Mum, this is my teacher."]}, {"en": "Good morning.", "zh": "早上好", "scene": "中午之前的正式问候，对老师和客户都能用。", "struct": "Good morning.（+ 称呼）", "cat": "dailychat", "ex": ["Good morning, Mr. Blake.", "Good morning, everyone."]}],pats:[{"en": "This is + 人名.", "zh": "这位是……", "scene": "介绍他人互相认识。", "struct": "This is + 人名.", "cat": "dailychat", "ex": ["This is Hans. He is German.", "This is my sister, Emma."]}, {"en": "He / She is + 国籍.", "zh": "他／她是……国人", "scene": "说明某人来自哪个国家。", "struct": "主语 + be + 国籍形容词（French, German, Japanese…）", "cat": "dailychat", "ex": ["She is Japanese.", "He is Korean, not Chinese."]}],quiz:{"v": {"q": "student 的意思是：", "opts": ["学生", "老师", "医生"], "a": 0}, "e": {"q": "第一次见到某人，最自然的说法是：", "opts": ["Nice to meet you.", "Nice to see you again.", "How do you do it?"], "a": 0}, "p": {"q": "She ______ French.", "opts": ["is", "are", "am"], "a": 0}},speak:"说 3 句话：用 Good morning 打招呼，用 This is … 介绍一位朋友，再说他／她是哪国人。"},
{n:6,title:"What Make Is It?",topic:"询问品牌 · a/an 与物品描述",reading:"What make is your car?\n\nIt's a Bright.\n\nIs it an English car?\n\nNo, it isn't. It's an American car.\n\nWhat make is your watch?\n\nIt's a Star. It's a Japanese watch.\n\nIs it new?\n\nYes, it is. It's a very good watch.\n\nMy car is old, but it is a good car too.\n\nThat's good. A good car is important.\n\nWhat make is your bag?\n\nIt's a Sun. It's a Chinese bag.\n\nIs it new?\n\nYes, it is. I like it very much.",zh:"（原创改写）你的车是什么牌子的？\n\n是一辆 Bright。\n\n它是英国车吗？\n\n不，不是。它是美国车。\n\n你的手表是什么牌子的？\n\n是一块 Star。它是日本表。\n\n它是新的吗？\n\n是的。这是一块很好的表。\n\n我的车旧了，但它也是辆好车。\n\n那挺好的。有辆好车很重要。\n\n你的包是什么牌子的？\n\n是 Sun 牌。它是个中国包。\n\n它是新的吗？\n\n是的。我非常喜欢它。",vocab:[{"w": "make", "ph": "/meɪk/", "en": "the name of the company that made something", "zh": "n. 品牌；型号", "eg": "What make is your car?"}, {"w": "car", "ph": "/kɑː/", "en": "a thing with four wheels that takes you places", "zh": "n. 小汽车", "eg": "Their car is very old."}, {"w": "watch", "ph": "/wɒtʃ/", "en": "a small thing you wear on your arm to see the time", "zh": "n. 手表", "eg": "My watch is a Japanese one."}, {"w": "American", "ph": "/əˈmerɪkən/", "en": "from the United States", "zh": "adj. 美国的；美国人", "eg": "This is an American car."}],exprs:[{"en": "What make is it?", "zh": "它是什么牌子的？", "scene": "买东西、聊车聊表时问品牌。", "struct": "What make is + 名词?", "cat": "dailychat", "ex": ["What make is your watch?", "What make is this phone?"]}, {"en": "It's a … / It's an …", "zh": "它是一个……", "scene": "回答品牌或说明某物是什么。", "struct": "It's a + 辅音开头词 / It's an + 元音开头词", "cat": "dailychat", "ex": ["It's a Japanese watch.", "It's an old car."]}, {"en": "It's very good.", "zh": "它很好；它很不错", "scene": "对别人新买的东西给出正面评价。", "struct": "It's (very) + 形容词.", "cat": "opinion", "ex": ["Your bag is nice. — Thanks, it's very good.", "This phone is cheap, but it's very good."]}],pats:[{"en": "What make is your + 名词?", "zh": "你的……是什么牌子的？", "scene": "询问对方物品的品牌。", "struct": "What make is your + 名词?", "cat": "dailychat", "ex": ["What make is your car?", "What make is your new bag?"]}, {"en": "It's a / an + 名词.", "zh": "它是一（个）……", "scene": "说明物品是什么、什么牌子。", "struct": "It's a + 辅音音素开头的词 / It's an + 元音音素开头的词", "cat": "dailychat", "ex": ["It's an English car.", "It's a very old watch."]}],quiz:{"v": {"q": "这个句子里的 make 是什么意思：What make is your car?", "opts": ["品牌", "制作（动词）", "价格"], "a": 0}, "e": {"q": "「它是一块日本表」应该说：", "opts": ["It's a Japanese watch.", "It's Japanese watch.", "Its a Japanese watch."], "a": 0}, "p": {"q": "It's ______ American car.", "opts": ["a", "an", "the"], "a": 1}},speak:"说 3 句话：先用 What make is your …? 问对方一样东西的牌子，再用 It's a/an … 回答，最后用 It's very good. 评价一下。"},
{n:7,title:"Are You a Teacher?",topic:"职业询问 · Are you…? 与 What's your job?",reading:"I am a new student. My name's Robert.\n\nNice to meet you. My name's Sophie.\n\nAre you French?\n\nYes, I am. Are you French too?\n\nNo, I am not. I am Italian.\n\nAre you a teacher?\n\nNo, I'm not. I'm a student. What's your job?\n\nI'm a nurse. I work in a hospital.\n\nMy sister is a teacher. She works in a school.\n\nIs your sister a nurse too?\n\nNo, she isn't. She's a teacher. She's very busy.",zh:"（原创改写）我是新来的学生。我叫罗伯特。\n\n很高兴认识你。我叫索菲。\n\n你是法国人吗？\n\n是的，我是。你也是法国人吗？\n\n不，我不是。我是意大利人。\n\n你是老师吗？\n\n不，我不是。我是学生。你是做什么工作的？\n\n我是护士。我在一家医院工作。\n\n我姐姐是老师。她在学校工作。\n\n你姐姐也是护士吗？\n\n不，她不是。她是老师。她很忙。",vocab:[{"w": "teacher", "ph": "/ˈtiːtʃə/", "en": "a person whose job is to teach", "zh": "n. 老师；教师", "eg": "My sister is a teacher."}, {"w": "nurse", "ph": "/nɜːs/", "en": "a person who looks after sick people", "zh": "n. 护士", "eg": "She is a nurse in a big hospital."}, {"w": "job", "ph": "/dʒɒb/", "en": "the work you do to get money", "zh": "n. 工作；职业", "eg": "What's your job?"}, {"w": "hospital", "ph": "/ˈhɒspɪtl/", "en": "a place where doctors and nurses work", "zh": "n. 医院", "eg": "He is ill and he is in hospital."}],exprs:[{"en": "What's your job?", "zh": "你是做什么工作的？", "scene": "刚认识的人之间聊职业，比较直接但不失礼貌。", "struct": "What's your job? / What do you do?", "cat": "work", "ex": ["What's your job? — I'm a nurse.", "Nice to meet you. What's your job?"]}, {"en": "I'm a …", "zh": "我是（一名）……", "scene": "说明自己的职业。", "struct": "I'm a / an + 职业名词.", "cat": "work", "ex": ["I'm a taxi driver.", "I'm an English teacher."]}, {"en": "I work in a hospital.", "zh": "我在医院工作", "scene": "补充说明工作单位，比只说职业更具体。", "struct": "I work in a / at a + 地点.", "cat": "work", "ex": ["I work in a small school.", "I work at a big shop."]}],pats:[{"en": "Are you + 职业 / 国籍?", "zh": "你是……吗？", "scene": "确认对方的身份、职业或国籍。", "struct": "Are you + 名词 / 形容词? → Yes, I am. / No, I'm not.", "cat": "dailychat", "ex": ["Are you a teacher?", "Are you Italian? — No, I'm not."]}, {"en": "What's your job?", "zh": "你是做什么工作的？", "scene": "直接询问职业。", "struct": "What's your job?", "cat": "work", "ex": ["What's your job? — I'm a doctor.", "What's your job, Robert?"]}],quiz:{"v": {"q": "nurse 的意思是：", "opts": ["护士", "老师", "司机"], "a": 0}, "e": {"q": "想问对方做什么工作，应该说：", "opts": ["What's your job?", "What your job?", "What's you job?"], "a": 0}, "p": {"q": "______ you a teacher?", "opts": ["Are", "Is", "Am"], "a": 0}},speak:"说 3 句话：先自我介绍姓名，再用 Are you …? 问对方是不是某个职业，最后用 I'm a … 说出自己的职业。"},
{n:8,title:"What's Your Job?",topic:"职业词汇 · What's his/her job?",reading:"What's your job?\n\nI'm a taxi driver.\n\nWhat's his job?\n\nHe's a policeman. He is young and strong.\n\nWhat's her job?\n\nShe's a policewoman. She is very busy.\n\nIs your brother a postman?\n\nNo, he isn't. He's a mechanic. He works with cars.\n\nMy sister is an air hostess. She is busy too, but she likes her job.\n\nWhat's your sister's job?\n\nShe's a nurse. She works in a hospital.\n\nIs she busy?\n\nYes, she is. She works all day.",zh:"（原创改写）你是做什么工作的？\n\n我是出租车司机。\n\n他是做什么的？\n\n他是警察。他又年轻又强壮。\n\n她是做什么的？\n\n她是女警察。她特别忙。\n\n你哥哥是邮递员吗？\n\n不，他不是。他是机修工，整天跟汽车打交道。\n\n我姐姐是空乘。她也很忙，但她喜欢自己的工作。\n\n你姐姐是做什么工作的？\n\n她是护士。她在一家医院工作。\n\n她忙吗？\n\n是的，她很忙。她工作一整天。",vocab:[{"w": "policeman", "ph": "/pəˈliːsmən/", "en": "a man whose job is to catch bad people", "zh": "n. 男警察", "eg": "He's a young policeman."}, {"w": "postman", "ph": "/ˈpəʊstmən/", "en": "a man who brings letters to your house", "zh": "n. 邮递员", "eg": "The postman comes at nine."}, {"w": "driver", "ph": "/ˈdraɪvə/", "en": "a person who drives a car, bus or taxi", "zh": "n. 司机", "eg": "My father is a bus driver."}, {"w": "mechanic", "ph": "/məˈkænɪk/", "en": "a person who fixes machines and cars", "zh": "n. 机修工；技工", "eg": "He's a mechanic. He fixes cars."}],exprs:[{"en": "What's his / her job?", "zh": "他／她是做什么工作的？", "scene": "聊到第三个人时问其职业。", "struct": "What's his / her job?", "cat": "work", "ex": ["What's his job? — He's a policeman.", "What's her job? She looks busy."]}, {"en": "He's a … / She's a …", "zh": "他是……／她是……", "scene": "回答第三个人的职业。", "struct": "He's / She's a (an) + 职业名词.", "cat": "work", "ex": ["He's a postman.", "She's an English teacher."]}, {"en": "She's very busy.", "zh": "她很忙", "scene": "形容别人工作多、时间紧。", "struct": "主语 + be + very + 形容词.", "cat": "work", "ex": ["Sorry, she's very busy now.", "He's very busy on Monday."]}],pats:[{"en": "What's his / her job?", "zh": "他／她是做什么工作的？", "scene": "询问第三个人的职业。", "struct": "What's his / her job? → He's / She's a …", "cat": "work", "ex": ["What's his job? — He's a driver.", "What's her job? — She's a nurse."]}, {"en": "Is your brother a …?", "zh": "你哥哥是……吗？", "scene": "确认家人朋友的职业。", "struct": "Is your + 家人 + a + 职业? → Yes, he is. / No, he isn't.", "cat": "work", "ex": ["Is your brother a postman?", "Is your sister a teacher? — Yes, she is."]}],quiz:{"v": {"q": "postman 的意思是：", "opts": ["邮递员", "警察", "司机"], "a": 0}, "e": {"q": "想问「她是做什么工作的」，应该说：", "opts": ["What's her job?", "What's she job?", "What her job?"], "a": 0}, "p": {"q": "What's ______ job?", "opts": ["he", "him", "his"], "a": 2}},speak:"说 3 句话：用 What's his job? 和 What's her job? 各问一个人的职业，并用 He's a … / She's a … 回答。"},
{n:9,title:"How Are You Today?",topic:"日常问候 How are you · 近况寒暄",reading:"Hello, Helen. How are you today?\n\nI'm very well, thank you. And you?\n\nI'm fine, thanks. How is Tom?\n\nHe's fine, thanks. How's Emma?\n\nShe's very well too, thank you.\n\nGoodbye, Helen. Nice to see you.\n\nNice to see you too, Steven. Goodbye!\n\nSee you tomorrow!\n\nHow is your father?\n\nHe's very well, thanks. How's your mother?\n\nShe's fine, thank you. And how is Emma?\n\nShe's very well. She's at school now.\n\nGood. See you soon!",zh:"（原创改写）你好，海伦。今天过得怎么样？\n\n我很好，谢谢。你呢？\n\n我挺好的，谢谢。汤姆怎么样？\n\n他挺好的，谢谢。埃玛呢？\n\n她也很好，谢谢。\n\n再见，海伦。见到你很高兴。\n\n我也是，史蒂文。再见！\n\n明天见！\n\n你父亲怎么样？\n\n他很好，谢谢。你母亲呢？\n\n她挺好的，谢谢。埃玛怎么样？\n\n她也很好。她现在在学校。\n\n那挺好的。回头见！",vocab:[{"w": "hello", "ph": "/həˈləʊ/", "en": "a word you say when you see someone", "zh": "int. 你好", "eg": "Hello, Helen. How are you?"}, {"w": "well", "ph": "/wel/", "en": "in good health", "zh": "adj. 身体好的；健康的", "eg": "I'm very well, thank you."}, {"w": "fine", "ph": "/faɪn/", "en": "OK; good enough", "zh": "adj. 不错的；挺好的", "eg": "I'm fine, thanks. And you?"}, {"w": "goodbye", "ph": "/ˌɡʊdˈbaɪ/", "en": "a word you say when you leave", "zh": "int. 再见", "eg": "Goodbye! See you tomorrow."}],exprs:[{"en": "How are you?", "zh": "你好吗？／最近怎么样？", "scene": "见面时最通用的问候，熟人之间都能用。", "struct": "How are you? / How are you today?", "cat": "dailychat", "ex": ["Hi, Anna. How are you?", "How are you today? You look tired."]}, {"en": "I'm very well, thank you.", "zh": "我很好，谢谢", "scene": "被问到 How are you 时最标准的回答。", "struct": "I'm (very) well / fine, thank you. And you?", "cat": "dailychat", "ex": ["I'm very well, thank you. And you?", "I'm fine, thanks. How is your family?"]}, {"en": "Nice to see you.", "zh": "见到你很高兴", "scene": "见到认识的人时说，比初次见面的 Nice to meet you 更随意。", "struct": "Nice to see you (again / too).", "cat": "dailychat", "ex": ["Nice to see you, Helen.", "Nice to see you again!"]}],pats:[{"en": "How are you?", "zh": "你好吗？", "scene": "见面问候。", "struct": "How are you (today)? → I'm fine / very well, thanks.", "cat": "dailychat", "ex": ["How are you today?", "How are you? — I'm fine, thanks."]}, {"en": "How is + 人名?", "zh": "……怎么样？", "scene": "问候第三个人的近况。", "struct": "How is / How's + 人名? → He's / She's fine.", "cat": "dailychat", "ex": ["How is Tom? — He's fine, thanks.", "How's your mother? — She's very well."]}],quiz:{"v": {"q": "well 在这里是什么意思（I'm very well）：", "opts": ["身体好的", "很好地（方式）", "井"], "a": 0}, "e": {"q": "别人问 How are you today? 最合适的回答是：", "opts": ["I'm very well, thank you.", "I'm a student.", "I'm twenty."], "a": 0}, "p": {"q": "How ______ Tom?", "opts": ["is", "are", "am"], "a": 0}},speak:"说 3 句话：先用 Hello + How are you today? 问候对方，回答后反问 And you?，再问候一位共同的朋友 How is …?"},
{n:10,title:"Look at That Man",topic:"形容人与物 · Look at + 名词",reading:"Look at that man. He's very tall.\n\nLook at that woman. She's very short.\n\nLook at that policeman. He's young and strong.\n\nLook at that nurse. She's very busy.\n\nLook at that cat. It's very fat.\n\nLook at that dog. It's very thin.\n\nLook at that girl. She's pretty and happy.\n\nLook at that old car. It's dirty, but it's very good.\n\nLook at that woman. She's young and pretty.\n\nLook at that man. He's old and thin.",zh:"（原创改写）看那个男人。他很高。\n\n看那个女人。她很矮。\n\n看那个警察。他又年轻又壮。\n\n看那个护士。她特别忙。\n\n看那只猫。它很胖。\n\n看那只狗。它很瘦。\n\n看那个女孩。她又漂亮又开心。\n\n看那辆旧车。它很脏，不过性能很好。\n\n看那位女士。她又年轻又漂亮。\n\n看那位先生。他又老又瘦。",vocab:[{"w": "tall", "ph": "/tɔːl/", "en": "high; not short (for people and trees)", "zh": "adj. 高的", "eg": "My brother is very tall."}, {"w": "short", "ph": "/ʃɔːt/", "en": "not tall; not long", "zh": "adj. 矮的；短的", "eg": "She's short, but she is strong."}, {"w": "fat", "ph": "/fæt/", "en": "with a big round body", "zh": "adj. 胖的", "eg": "Look at that fat cat."}, {"w": "thin", "ph": "/θɪn/", "en": "with a very small body; not fat", "zh": "adj. 瘦的", "eg": "The dog is thin but happy."}],exprs:[{"en": "Look at …", "zh": "看……", "scene": "把别人的注意力引到某个人或东西上。", "struct": "Look at + 名词.", "cat": "dailychat", "ex": ["Look at that man! He's so tall.", "Look at the sky. It's blue."]}, {"en": "very + 形容词", "zh": "很……；非常……", "scene": "加强形容的程度，口语里最高频。", "struct": "be + very + 形容词", "cat": "opinion", "ex": ["She's very busy today.", "This bag is very nice."]}, {"en": "形容词 + and + 形容词", "zh": "又……又……", "scene": "同时给出两个特点，比如 tall and strong。", "struct": "be + 形容词 + and + 形容词", "cat": "dailychat", "ex": ["He's young and strong.", "She's pretty and happy."]}],pats:[{"en": "Look at + 名词.", "zh": "看……", "scene": "提醒对方注意某物。", "struct": "Look at + this / that / the + 名词.", "cat": "dailychat", "ex": ["Look at that woman.", "Look at my new watch."]}, {"en": "主语 + be + very + 形容词.", "zh": "……很……", "scene": "描述人或物的特征。", "struct": "He / She / It is + very + 形容词.", "cat": "dailychat", "ex": ["He's very tall.", "It's very thin."]}],quiz:{"v": {"q": "thin 的意思是：", "opts": ["瘦的", "胖的", "高的"], "a": 0}, "e": {"q": "「看那只猫」应该说：", "opts": ["Look at that cat.", "Look that cat.", "See at that cat."], "a": 0}, "p": {"q": "Look ______ that man.", "opts": ["at", "in", "on"], "a": 0}},speak:"说 3 句话：用 Look at … 引起注意，然后用 very + 形容词 或 形容词 and 形容词 描述两个人或物。"},
{n:11,title:"Is This Your Shirt?",topic:"whose 所有格 · 名词所有格 's",reading:"Whose shirt is this?\n\nIs this your shirt, Dave?\n\nNo, it isn't. My shirt is white.\n\nIs this your shirt, Tim?\n\nYes, it is. It's my shirt.\n\nHere you are. Catch!\n\nThank you, Mum.\n\nWhose tie is that?\n\nIt's my father's. It's his tie.\n\nIt's very nice. Whose bag is this? It's Emma's.\n\nWhose hat is this?\n\nIt's my father's. It's his hat.\n\nAnd whose coat is that?\n\nIt's Tim's. His coat is blue.",zh:"（原创改写）这是谁的衬衫？\n\n戴夫，这是你的衬衫吗？\n\n不，不是。我的衬衫是白色的。\n\n蒂姆，这是你的衬衫吗？\n\n是的，是我的。这是我的衬衫。\n\n给你。接住！\n\n谢谢妈妈。\n\n那是谁的领带？\n\n是我爸爸的。是他的领带。\n\n很好看。这个包是谁的？是埃玛的。\n\n这是谁的帽子？\n\n是我爸爸的。是他的帽子。\n\n那是谁的外套？\n\n是蒂姆的。他的外套是蓝色的。",vocab:[{"w": "shirt", "ph": "/ʃɜːt/", "en": "a piece of clothing for the top of your body", "zh": "n. 衬衫", "eg": "My white shirt is in the bag."}, {"w": "whose", "ph": "/huːz/", "en": "a word you use to ask who something belongs to", "zh": "pron. 谁的", "eg": "Whose bag is this?"}, {"w": "tie", "ph": "/taɪ/", "en": "a long thin thing a man wears around his neck", "zh": "n. 领带", "eg": "His father's tie is blue."}, {"w": "catch", "ph": "/kætʃ/", "en": "to take something that is moving in the air", "zh": "v. 接住；抓住", "eg": "Here you are. Catch!"}],exprs:[{"en": "Whose shirt is this?", "zh": "这是谁的衬衫？", "scene": "看到没人认领的东西，问它属于谁。", "struct": "Whose + 名词 + is this / that?", "cat": "dailychat", "ex": ["Whose bag is this?", "Whose pen is that on the desk?"]}, {"en": "It's my father's.", "zh": "是我爸爸的", "scene": "说明东西属于某个具体的人。", "struct": "It's + 名词's.（名词后加 's）", "cat": "dailychat", "ex": ["It's my sister's.", "It's Tom's, not mine."]}, {"en": "Here you are. Catch!", "zh": "给你，接住！", "scene": "把东西扔给对方时边扔边喊。", "struct": "Here you are. Catch!", "cat": "dailychat", "ex": ["Catch! It's your shirt.", "Here you are. Catch! Be careful."]}],pats:[{"en": "Whose + 名词 + is this / that?", "zh": "这／那是谁的……？", "scene": "询问物品归属。", "struct": "Whose + 名词 + is this / that? → It's + 名词's. / It's mine.", "cat": "dailychat", "ex": ["Whose tie is that?", "Whose book is this? — It's Emma's."]}, {"en": "It's my / his / her + 名词.", "zh": "这是我的／他的／她的……", "scene": "用形容词性物主代词说明归属。", "struct": "It's + my / your / his / her + 名词.", "cat": "dailychat", "ex": ["It's his tie.", "It's her bag, not mine."]}],quiz:{"v": {"q": "whose 的意思是：", "opts": ["谁的", "谁", "哪个"], "a": 0}, "e": {"q": "「这是谁的衬衫？」应该说：", "opts": ["Whose shirt is this?", "Who's shirt is this?", "Whose is this shirt? — 语序错误"], "a": 0}, "p": {"q": "Whose tie ______ that?", "opts": ["is", "are", "am"], "a": 0}},speak:"说 3 句话：用 Whose … is this? 问一件东西的主人，再用 It's my/his/her … 或 It's …'s. 回答，最后用 Here you are. Catch! 还给别人。"},
{n:12,title:"Whose Is This Bag?",topic:"颜色与 whose 综合 · 名词性物主代词",reading:"Whose is this blue bag? Is it yours, Anna?\n\nNo, it isn't mine. My bag is white.\n\nWhose is this red pen?\n\nIt's Tom's. It's his pen.\n\nWhose is that green book?\n\nIt's Mary's. It's her book.\n\nAnd whose is this yellow hat?\n\nIt's my brother's. His hat is yellow.\n\nWhose is this black pen? It's mine! Thank you very much.\n\nWhose is this black pen?\n\nIt's mine. It's my pen.\n\nAnd whose is that white bag?\n\nIt's hers. It's her bag.",zh:"（原创改写）这个蓝包是谁的？安娜，是你的吗？\n\n不，不是我的。我的包是白色的。\n\n这支红笔是谁的？\n\n是汤姆的。是他的钢笔。\n\n那本绿色的书是谁的？\n\n是玛丽的。是她的书。\n\n这顶黄帽子是谁的？\n\n是我弟弟的。他的帽子是黄色的。\n\n这支黑笔是谁的？是我的！太感谢了。\n\n这支黑笔是谁的？\n\n是我的。是我的钢笔。\n\n那个白包是谁的？\n\n是她的。是她的包。",vocab:[{"w": "white", "ph": "/waɪt/", "en": "the colour of milk or snow", "zh": "adj. 白色的", "eg": "My new bag is white."}, {"w": "green", "ph": "/ɡriːn/", "en": "the colour of grass and leaves", "zh": "adj. 绿色的", "eg": "Her green book is on the desk."}, {"w": "yellow", "ph": "/ˈjeləʊ/", "en": "the colour of the sun or a banana", "zh": "adj. 黄色的", "eg": "His yellow hat is very nice."}, {"w": "red", "ph": "/red/", "en": "the colour of blood or a tomato", "zh": "adj. 红色的", "eg": "I have a red pen."}],exprs:[{"en": "Whose is this …?", "zh": "这……是谁的？", "scene": "东西已经拿在手上，直接问归属。", "struct": "Whose is this / that + 名词?", "cat": "dailychat", "ex": ["Whose is this blue bag?", "Whose is that green book?"]}, {"en": "It's mine. / It's yours.", "zh": "是我的。／是你的。", "scene": "简短说明归属，后面不接名词。", "struct": "It's + mine / yours / his / hers / ours.", "cat": "dailychat", "ex": ["It's mine, not yours.", "Whose is it? — It's hers."]}, {"en": "It's Tom's.", "zh": "是汤姆的", "scene": "用人名加 's 说明归属。", "struct": "It's + 人名 + 's.", "cat": "dailychat", "ex": ["It's Mary's.", "It's my brother's, not mine."]}],pats:[{"en": "Whose is this / that + 名词?", "zh": "这／那个……是谁的？", "scene": "询问归属，强调是谁的东西。", "struct": "Whose is this / that + 名词? → It's + 名词's.", "cat": "dailychat", "ex": ["Whose is this red pen?", "Whose is that yellow hat?"]}, {"en": "Is it yours?", "zh": "它是你的吗？", "scene": "把东西递给对方前再确认一次。", "struct": "Is it + yours / his / hers? → Yes, it is. / No, it isn't.", "cat": "dailychat", "ex": ["Is it yours? I found it here.", "Is it hers? It looks like her bag."]}],quiz:{"v": {"q": "yellow 是什么颜色？", "opts": ["黄色", "绿色", "棕色"], "a": 0}, "e": {"q": "「它是我的」应该说：", "opts": ["It's mine.", "It's my.", "It is me."], "a": 0}, "p": {"q": "Whose is this bag? — It's ______.", "opts": ["my", "mine", "me"], "a": 1}},speak:"说 3 句话：用 Whose is this …? 问一件带颜色的东西是谁的，用 No, it isn't mine. 否定，再用 It's …'s. 说出真正的主人。"},
{n:13,title:"A New Dress",topic:"What colour 询问颜色 · 邀请对方看看",reading:"What colour is your new dress?\n\nIt's green.\n\nGreen? That's a nice colour. Is it a long dress?\n\nNo, it isn't long. It's short.\n\nCome upstairs and see it.\n\nThank you. Is it on the bed?\n\nYes, it is. Look!\n\nOh, it's very nice. It's a lovely dress!\n\nThank you. It's a present from my mother. I'm very happy with it.\n\nIs your dress new?\n\nYes, it is. It's from my mother.\n\nIt's a lovely colour. Green is nice on you.\n\nThank you very much!",zh:"（原创改写）你的新连衣裙是什么颜色的？\n\n是绿色的。\n\n绿色？这个颜色很好看。是长裙吗？\n\n不，不长。是短的。\n\n上楼来看看吧。\n\n谢谢。它在床上吗？\n\n是的，在。你看！\n\n哦，真漂亮。这条裙子太好看了！\n\n谢谢。这是我妈妈送我的礼物。我特别喜欢它。\n\n你的裙子是新的吗？\n\n是的。是我妈妈给我的。\n\n这个颜色很好看。你穿绿色好看。\n\n太感谢你了！",vocab:[{"w": "dress", "ph": "/dres/", "en": "a piece of clothing a woman wears", "zh": "n. 连衣裙", "eg": "Her new dress is green."}, {"w": "colour", "ph": "/ˈkʌlə/", "en": "red, blue, green and so on", "zh": "n. 颜色", "eg": "What colour is your bag?"}, {"w": "lovely", "ph": "/ˈlʌvli/", "en": "very nice; beautiful", "zh": "adj. 可爱的；好看的", "eg": "It's a lovely dress!"}, {"w": "upstairs", "ph": "/ˌʌpˈsteəz/", "en": "to or on a higher floor of a building", "zh": "adv. 在楼上；往楼上", "eg": "Come upstairs and see it."}],exprs:[{"en": "What colour is …?", "zh": "……是什么颜色的？", "scene": "想知道某样东西的颜色。", "struct": "What colour is + 单数名词? / What colour are + 复数名词?", "cat": "dailychat", "ex": ["What colour is your new dress?", "What colour is your car?"]}, {"en": "Come and see.", "zh": "过来看看", "scene": "邀请对方到近处看某样东西。", "struct": "Come and see + 代词 / 名词.", "cat": "dailychat", "ex": ["Come and see my new bag.", "Come upstairs and see it."]}, {"en": "That's a nice colour.", "zh": "这个颜色很好看", "scene": "夸别人衣服、包、车的颜色。", "struct": "That's a (nice / lovely) colour.", "cat": "opinion", "ex": ["Green? That's a nice colour.", "That's a lovely colour on you."]}],pats:[{"en": "What colour is your + 名词?", "zh": "你的……是什么颜色的？", "scene": "询问对方物品的颜色。", "struct": "What colour is your + 名词? → It's + 颜色.", "cat": "dailychat", "ex": ["What colour is your new dress? — It's green.", "What colour is your hat?"]}, {"en": "It's + 颜色.", "zh": "它是……色的", "scene": "回答颜色提问。", "struct": "It's + 颜色形容词.", "cat": "dailychat", "ex": ["It's green.", "It's black and white."]}],quiz:{"v": {"q": "lovely 的意思是：", "opts": ["好看的；可爱的", "大的", "便宜的"], "a": 0}, "e": {"q": "想问对方新裙子是什么颜色，应该说：", "opts": ["What colour is your new dress?", "What is colour your new dress?", "Which colour your new dress?"], "a": 0}, "p": {"q": "What colour ______ your new dress?", "opts": ["is", "are", "am"], "a": 0}},speak:"说 3 句话：先用 What colour is your …? 问颜色，再用 It's … 回答，最后用 That's a nice colour. 夸一句。"},
{n:14,title:"What Colour Are Your Shoes?",topic:"名词复数 · 复数颜色的提问与回答",reading:"What colour are your new shoes?\n\nThey're black.\n\nWhat colour are your socks?\n\nThey're white.\n\nWhat colour are your trousers?\n\nThey're grey.\n\nAre your bags brown?\n\nNo, they aren't. They're green.\n\nMy shirts are white and my ties are red. I like bright colours very much.\n\nWhat colour are your gloves?\n\nThey're grey.\n\nAre your hats black?\n\nNo, they aren't. They're brown.\n\nWhat colour is your coat?\n\nIt's black. Black is my favourite colour.",zh:"（原创改写）你的新鞋是什么颜色的？\n\n是黑色的。\n\n你的袜子是什么颜色的？\n\n是白色的。\n\n你的裤子是什么颜色的？\n\n是灰色的。\n\n你的包是棕色的吗？\n\n不，不是。它们是绿色的。\n\n我的衬衫是白色的，领带是红色的。我特别喜欢鲜艳的颜色。\n\n你的手套是什么颜色的？\n\n是灰色的。\n\n你的帽子是黑色的吗？\n\n不，不是。它们是棕色的。\n\n你的外套是什么颜色的？\n\n是黑色的。黑色是我最喜欢的颜色。",vocab:[{"w": "shoes", "ph": "/ʃuːz/", "en": "things you wear on your feet", "zh": "n. 鞋（复数）", "eg": "My new shoes are black."}, {"w": "socks", "ph": "/sɒks/", "en": "soft things you wear inside your shoes", "zh": "n. 袜子（复数）", "eg": "These white socks are mine."}, {"w": "trousers", "ph": "/ˈtraʊzəz/", "en": "a piece of clothing for your legs", "zh": "n. 裤子（复数）", "eg": "His trousers are grey."}, {"w": "brown", "ph": "/braʊn/", "en": "the colour of coffee or chocolate", "zh": "adj. 棕色的", "eg": "I have a brown bag."}],exprs:[{"en": "What colour are your …?", "zh": "你的……是什么颜色的？（复数）", "scene": "问鞋子、袜子、裤子这类成双成条的东西。", "struct": "What colour are your + 复数名词?", "cat": "dailychat", "ex": ["What colour are your shoes?", "What colour are your new socks?"]}, {"en": "They're black.", "zh": "它们是黑色的", "scene": "回答复数物品的颜色。", "struct": "They're + 颜色.", "cat": "dailychat", "ex": ["They're white.", "They're blue and grey."]}, {"en": "I like bright colours.", "zh": "我喜欢鲜艳的颜色", "scene": "聊穿衣偏好时表达自己的喜好。", "struct": "I like + 形容词 + 名词.", "cat": "hobby", "ex": ["I like bright colours in summer.", "She likes dark colours, but I like bright ones."]}],pats:[{"en": "What colour are your + 复数名词?", "zh": "你的……是什么颜色的？", "scene": "询问复数物品颜色。", "struct": "What colour are your + 复数名词? → They're + 颜色.", "cat": "dailychat", "ex": ["What colour are your trousers?", "What colour are your bags?"]}, {"en": "Are your … + 颜色?", "zh": "你的……是……色的吗？", "scene": "猜颜色并请对方确认。", "struct": "Are your + 复数名词 + 颜色? → Yes, they are. / No, they aren't.", "cat": "dailychat", "ex": ["Are your bags brown?", "Are your shoes black? — Yes, they are."]}],quiz:{"v": {"q": "trousers 的意思是：", "opts": ["裤子", "袜子", "鞋子"], "a": 0}, "e": {"q": "「它们是白色的」应该说：", "opts": ["They're white.", "It's white.", "They white."], "a": 0}, "p": {"q": "What colour ______ your shoes?", "opts": ["is", "are", "am"], "a": 1}},speak:"说 3 句话：用 What colour are your …? 问两样复数物品的颜色，并说一句 I like … colours. 表达自己的喜好。"},
{n:15,title:"Your Passports, Please",topic:"海关与护照 · 名词复数与 Are these your…?",reading:"Your passports, please.\n\nHere they are.\n\nAre these your cases?\n\nNo, they aren't. Our cases are brown. Here they are.\n\nThank you. Are you tourists?\n\nYes, we are.\n\nAre you Swedish?\n\nNo, we aren't. We are Danish.\n\nAre your friends Danish too?\n\nNo, they aren't. They are Norwegian. Thank you very much.\n\nAre these your bags?\n\nYes, they are. Thank you.\n\nAre they heavy?\n\nNo, they aren't. They're very light.\n\nThank you. Have a nice day!",zh:"（原创改写）请出示你们的护照。\n\n在这儿。\n\n这些是你们的行李箱吗？\n\n不，不是。我们的箱子是棕色的。在这儿。\n\n谢谢。你们是来旅游的吗？\n\n是的，我们是。\n\n你们是瑞典人吗？\n\n不，不是。我们是丹麦人。\n\n你们的朋友也是丹麦人吗？\n\n不，他们不是。他们是挪威人。非常感谢。\n\n这些是你们的包吗？\n\n是的，是我们的。谢谢。\n\n它们重吗？\n\n不重。它们很轻。\n\n谢谢。祝你今天愉快！",vocab:[{"w": "passport", "ph": "/ˈpɑːspɔːt/", "en": "a small book you need to go to another country", "zh": "n. 护照", "eg": "Here is my passport."}, {"w": "case", "ph": "/keɪs/", "en": "a big box you carry clothes in when you travel", "zh": "n. 箱子", "eg": "Our cases are brown."}, {"w": "tourist", "ph": "/ˈtʊərɪst/", "en": "a person who visits a place for fun", "zh": "n. 游客", "eg": "Are you tourists?"}, {"w": "customs", "ph": "/ˈkʌstəmz/", "en": "the place at the airport where they check your bags", "zh": "n. 海关", "eg": "We are at customs now."}],exprs:[{"en": "Your passports, please.", "zh": "请出示你们的护照", "scene": "海关、酒店前台、办手续时向对方要证件。", "struct": "Your + 名词, please.", "cat": "dailychat", "ex": ["Your passports, please.", "Your tickets, please."]}, {"en": "Here they are.", "zh": "它们在这儿", "scene": "把复数物品交给对方。", "struct": "Here they are.（复数）／ Here it is.（单数）", "cat": "dailychat", "ex": ["Where are the cases? — Here they are.", "Here they are. Two tickets for you."]}, {"en": "Yes, we are. / No, we aren't.", "zh": "是的，我们是。／不，我们不是。", "scene": "代表一行人回答 Are you 的提问。", "struct": "Yes, we are. / No, we aren't.", "cat": "dailychat", "ex": ["Are you tourists? — Yes, we are.", "Are you Swedish? — No, we aren't."]}],pats:[{"en": "Are these your + 复数名词?", "zh": "这些是你们的……吗？", "scene": "确认多件物品归属。", "struct": "Are these your + 复数名词? → Yes, they are. / No, they aren't.", "cat": "dailychat", "ex": ["Are these your cases?", "Are these your bags? — No, they aren't."]}, {"en": "Are you + 国籍 / 身份?", "zh": "你们是……吗？", "scene": "在海关确认对方的国籍或身份。", "struct": "Are you + 形容词 / 复数名词?", "cat": "dailychat", "ex": ["Are you Swedish?", "Are you tourists? — Yes, we are."]}],quiz:{"v": {"q": "passport 的意思是：", "opts": ["护照", "箱子", "机票"], "a": 0}, "e": {"q": "工作人员要你出示护照时会说：", "opts": ["Your passports, please.", "Give passport me.", "You passport, please."], "a": 0}, "p": {"q": "______ you Swedish?", "opts": ["Are", "Is", "Am"], "a": 0}},speak:"说 3 句话：扮演海关人员，先说 Your passports, please.，再问 Are these your cases?，最后问 Are you tourists? 并替对方回答。"},
{n:16,title:"Are You Tourists?",topic:"Are you…? 复数回答 · 国籍与度假",reading:"Are you Russian?\n\nNo, we aren't. We're Polish.\n\nAre your friends Polish too?\n\nYes, they are. They're from Warsaw.\n\nWhat colour are your passports?\n\nThey're blue.\n\nAre you here on holiday?\n\nYes, we are. We're tourists.\n\nWelcome to our city! Have a nice holiday!\n\nThank you very much. It's a lovely city.\n\nWhat colour are your cases?\n\nThey're brown.\n\nAre they new?\n\nYes, they are. They're very nice.\n\nThank you. We like your city.",zh:"（原创改写）你们是俄罗斯人吗？\n\n不，我们不是。我们是波兰人。\n\n你们的朋友也是波兰人吗？\n\n是的，他们是。他们来自华沙。\n\n你们的护照是什么颜色的？\n\n是蓝色的。\n\n你们是来度假的吗？\n\n是的。我们是游客。\n\n欢迎来到我们的城市！祝你们假期愉快！\n\n非常感谢。这座城市真漂亮。\n\n你们的箱子是什么颜色的？\n\n是棕色的。\n\n它们是新的吗？\n\n是的。它们很漂亮。\n\n谢谢。我们喜欢你们的城市。",vocab:[{"w": "Russian", "ph": "/ˈrʌʃn/", "en": "from Russia", "zh": "adj. 俄罗斯的；俄罗斯人", "eg": "Are you Russian?"}, {"w": "Polish", "ph": "/ˈpəʊlɪʃ/", "en": "from Poland", "zh": "adj. 波兰的；波兰人", "eg": "We're Polish, not Russian."}, {"w": "holiday", "ph": "/ˈhɒlədeɪ/", "en": "a time when you do not work and you travel", "zh": "n. 假期；假日", "eg": "Are you here on holiday?"}, {"w": "welcome", "ph": "/ˈwelkəm/", "en": "a word you say when someone comes to your place", "zh": "v./int. 欢迎", "eg": "Welcome to our city!"}],exprs:[{"en": "We're Polish.", "zh": "我们是波兰人", "scene": "说明一行人的国籍。", "struct": "We're + 国籍形容词.", "cat": "dailychat", "ex": ["We're Polish, and they're Russian.", "We're Chinese. We're from Beijing."]}, {"en": "Yes, they are. / No, they aren't.", "zh": "是的，他们是。／不，他们不是。", "scene": "回答关于第三群人的提问。", "struct": "Yes, they are. / No, they aren't.", "cat": "dailychat", "ex": ["Are they tourists? — Yes, they are.", "Are your friends Polish? — No, they aren't."]}, {"en": "Have a nice holiday!", "zh": "祝你假期愉快！", "scene": "送别要去度假或刚到某地的人。", "struct": "Have a nice / good holiday!", "cat": "emotion", "ex": ["Have a nice holiday! See you soon.", "Thanks! Have a good holiday in Spain."]}],pats:[{"en": "Are you + 国籍形容词?", "zh": "你们是……人吗？", "scene": "确认对方一行人的国籍。", "struct": "Are you + 国籍? → Yes, we are. / No, we aren't.", "cat": "dailychat", "ex": ["Are you Russian? — No, we aren't.", "Are you Japanese?"]}, {"en": "Are your friends + 国籍 / 形容词?", "zh": "你们的朋友是……吗？", "scene": "确认同行其他人的情况。", "struct": "Are your friends + 形容词? → Yes, they are. / No, they aren't.", "cat": "dailychat", "ex": ["Are your friends Polish too?", "Are your friends here on holiday?"]}],quiz:{"v": {"q": "holiday 的意思是：", "opts": ["假期", "工作日", "护照"], "a": 0}, "e": {"q": "别人说 We're here on holiday. 你最可能回：", "opts": ["Have a nice holiday!", "Nice to meet you!", "Pardon?"], "a": 0}, "p": {"q": "Are you Russian? — No, ______.", "opts": ["we aren't", "we isn't", "we are"], "a": 0}},speak:"说 3 句话：用 Are you …? 问对方一行人的国籍，用 No, we aren't. We're … 回答，再说一句 Have a nice holiday!"},
{n:17,title:"How Do You Do?",topic:"复数人称与职业 · 正式初次见面问候",reading:"Come and meet our new employees, Mr. Blake.\n\nThank you, Miss Lin.\n\nThis is Nicola Grey, and this is Claire Taylor.\n\nHow do you do?\n\nHow do you do?\n\nThose women are very hard-working. What are their jobs?\n\nThey're sales reps. They work in a big shop.\n\nWho is this young man?\n\nHe's Jim. He's our office assistant. He's busy all day.\n\nHow do you do, Mr. Blake?\n\nHow do you do?\n\nAre those men sales reps too?\n\nYes, they are.",zh:"（原创改写）布莱克先生，来见见我们的新同事吧。\n\n谢谢，林小姐。\n\n这位是尼古拉·格雷，这位是克莱尔·泰勒。\n\n你好。\n\n你好。\n\n那几位女士工作很努力。她们是做什么的？\n\n她们是销售代表。她们在一家大商店工作。\n\n这个年轻人是谁？\n\n他是吉姆。他是我们的办公室助理。他一整天都很忙。\n\n您好，布莱克先生。\n\n您好。\n\n那些男士也是销售代表吗？\n\n是的，他们是。",vocab:[{"w": "employee", "ph": "/ɪmˈplɔɪiː/", "en": "a person who works for a company", "zh": "n. 雇员；员工", "eg": "Our new employees are very nice."}, {"w": "hard-working", "ph": "/ˌhɑːd ˈwɜːkɪŋ/", "en": "working with a lot of effort", "zh": "adj. 工作努力的", "eg": "Those women are very hard-working."}, {"w": "assistant", "ph": "/əˈsɪstənt/", "en": "a person who helps in an office or shop", "zh": "n. 助理；助手", "eg": "He's our new office assistant."}, {"w": "office", "ph": "/ˈɒfɪs/", "en": "a room or building where people work at desks", "zh": "n. 办公室", "eg": "She is in the office now."}],exprs:[{"en": "How do you do?", "zh": "你好（正式）", "scene": "商务场合初次见面的固定问候，对方也回 How do you do?", "struct": "How do you do?（不用来问健康）", "cat": "work", "ex": ["How do you do? I'm Jim.", "This is my boss. — How do you do?"]}, {"en": "Come and meet …", "zh": "来见见……", "scene": "把同事、家人介绍给客人。", "struct": "Come and meet + 名词.", "cat": "work", "ex": ["Come and meet our new employees.", "Come and meet my sister."]}, {"en": "What are their jobs?", "zh": "他们是做什么工作的？", "scene": "聊到一群人时问他们的职业。", "struct": "What are their jobs? → They're + 复数职业.", "cat": "work", "ex": ["What are their jobs? — They're teachers.", "What are their jobs? They look busy."]}],pats:[{"en": "What are their jobs?", "zh": "他们是做什么工作的？", "scene": "询问多人的职业。", "struct": "What are their jobs? → They're + 复数职业名词.", "cat": "work", "ex": ["What are their jobs? — They're sales reps.", "What are their jobs? They're new here."]}, {"en": "They're + 复数职业名词.", "zh": "他们是……", "scene": "说明多人的职业。", "struct": "They're + 职业名词复数.", "cat": "work", "ex": ["They're office assistants.", "They're taxi drivers in this city."]}],quiz:{"v": {"q": "hard-working 的意思是：", "opts": ["工作努力的", "工作很累的", "没有工作的"], "a": 0}, "e": {"q": "正式场合被介绍给一位新同事，你会说：", "opts": ["How do you do?", "How are you doing?", "What's your job?"], "a": 0}, "p": {"q": "What ______ their jobs?", "opts": ["is", "are", "am"], "a": 1}},speak:"说 3 句话：用 Come and meet … 引出介绍，用 How do you do? 打招呼，再用 What are their jobs? 问其中两人的职业并回答。"},
{n:18,title:"What Are Their Jobs?",topic:"复数职业 · Are they…? 与 They're…",reading:"What are their jobs?\n\nThey're taxi drivers. They work in a big city.\n\nWhat are those women's jobs?\n\nThey're shop assistants. They're very busy.\n\nAre they nurses?\n\nNo, they aren't. They work in a school.\n\nAre those men mechanics?\n\nYes, they are. They work with cars all day.\n\nThey're all very hard-working people.\n\nWhat are your jobs?\n\nWe're teachers. We work in a school.\n\nAre you busy?\n\nYes, we are. We work all day.",zh:"（原创改写）他们是做什么工作的？\n\n他们是出租车司机。他们在一座大城市里工作。\n\n那些女士是做什么的？\n\n她们是店员。她们特别忙。\n\n她们是护士吗？\n\n不，她们不是。她们在一所学校工作。\n\n那些男人是机修工吗？\n\n是的，他们是。他们整天跟汽车打交道。\n\n他们都是很努力的人。\n\n你们是做什么工作的？\n\n我们是老师。我们在一所学校工作。\n\n你们忙吗？\n\n是的，很忙。我们工作一整天。",vocab:[{"w": "city", "ph": "/ˈsɪti/", "en": "a big place where many people live and work", "zh": "n. 城市", "eg": "They work in a big city."}, {"w": "shop", "ph": "/ʃɒp/", "en": "a place where you buy things", "zh": "n. 商店", "eg": "She works in a small shop."}, {"w": "busy", "ph": "/ˈbɪzi/", "en": "having a lot of things to do", "zh": "adj. 忙的", "eg": "Sorry, I'm very busy now."}, {"w": "women", "ph": "/ˈwɪmɪn/", "en": "more than one woman", "zh": "n. 女士们（woman 的复数）", "eg": "Those women are shop assistants."}],exprs:[{"en": "They're taxi drivers.", "zh": "他们是出租车司机", "scene": "说明一群人的职业。", "struct": "They're + 复数职业名词.", "cat": "work", "ex": ["They're bus drivers in this city.", "They're nurses in a big hospital."]}, {"en": "They're very busy.", "zh": "他们很忙", "scene": "解释为什么对方没空，或形容别人工作多。", "struct": "They're (very) busy.", "cat": "work", "ex": ["They're very busy on Monday.", "Don't call now. They're busy."]}, {"en": "They work all day.", "zh": "他们工作一整天", "scene": "形容别人工作时间长。", "struct": "主语 + work + 时间短语.", "cat": "work", "ex": ["They work all day and go home late.", "My parents work all day in the shop."]}],pats:[{"en": "What are their jobs?", "zh": "他们是做什么工作的？", "scene": "询问多人的职业。", "struct": "What are their jobs? → They're + 复数职业.", "cat": "work", "ex": ["What are their jobs? — They're shop assistants.", "What are their jobs? I don't know them."]}, {"en": "Are they + 复数职业?", "zh": "他们是……吗？", "scene": "猜测多人的职业并确认。", "struct": "Are they + 复数职业? → Yes, they are. / No, they aren't.", "cat": "work", "ex": ["Are they nurses? — No, they aren't.", "Are those men mechanics? — Yes, they are."]}],quiz:{"v": {"q": "busy 的意思是：", "opts": ["忙的", "累的", "闲的"], "a": 0}, "e": {"q": "「他们是出租车司机」应该说：", "opts": ["They're taxi drivers.", "They're taxi driver.", "They taxi drivers."], "a": 0}, "p": {"q": "______ they nurses?", "opts": ["Are", "Is", "Am"], "a": 0}},speak:"说 3 句话：用 What are their jobs? 问一群人的职业，再用 Are they …? 猜一次并回答，最后说一句 They work all day."},
{n:19,title:"Tired and Thirsty",topic:"身体感受 tired/thirsty · What's the matter?",reading:"What's the matter, Sam? Are you tired?\n\nYes, I am. And I'm thirsty.\n\nSit down here. Have a glass of water.\n\nThank you. It's very hot today.\n\nAre you all right now?\n\nYes, I am. I'm fine now. Thank you.\n\nAre you hungry?\n\nNo, I'm not. But I'm very tired.\n\nThen go home and have a good rest. See you tomorrow!\n\nHave a sandwich too.\n\nThank you. You're very kind.\n\nAre you all right now?\n\nYes, I am. Thank you.",zh:"（原创改写）怎么了，萨姆？你累了吗？\n\n是的，我累。而且我渴。\n\n坐这儿吧。喝杯水。\n\n谢谢。今天太热了。\n\n你现在好点了吗？\n\n是的，我好了。我现在没事了。谢谢。\n\n你饿吗？\n\n不，我不饿。但我很累。\n\n那就回家好好休息吧。明天见！\n\n再吃个三明治吧。\n\n谢谢。你人真好。\n\n你现在好点了吗？\n\n是的，我好了。谢谢。",vocab:[{"w": "tired", "ph": "/ˈtaɪəd/", "en": "needing to rest or sleep", "zh": "adj. 累的；疲倦的", "eg": "I'm very tired after work."}, {"w": "thirsty", "ph": "/ˈθɜːsti/", "en": "needing a drink", "zh": "adj. 渴的", "eg": "I'm thirsty. Can I have some water?"}, {"w": "hungry", "ph": "/ˈhʌŋɡri/", "en": "needing food", "zh": "adj. 饿的", "eg": "Are you hungry? Let's eat."}, {"w": "water", "ph": "/ˈwɔːtə/", "en": "the clear liquid you drink", "zh": "n. 水", "eg": "Have a glass of water."}],exprs:[{"en": "What's the matter?", "zh": "怎么了？／出什么事了？", "scene": "看到朋友脸色不好、情绪低落时开口问。", "struct": "What's the matter (with + 人)?", "cat": "emotion", "ex": ["What's the matter? You look tired.", "What's the matter with Tom?"]}, {"en": "I'm tired. / I'm thirsty.", "zh": "我累了。／我渴了。", "scene": "说出自己的身体状态。", "struct": "I'm + 感觉形容词.", "cat": "emotion", "ex": ["I'm thirsty. Is there any water?", "I'm tired. I want to go home."]}, {"en": "Are you all right now?", "zh": "你现在好点了吗？", "scene": "照顾过对方之后再确认一次。", "struct": "Are you all right (now)?", "cat": "emotion", "ex": ["Are you all right now? — Yes, I'm fine.", "You look ill. Are you all right?"]}],pats:[{"en": "Are you + 感觉形容词?", "zh": "你……吗？（累／渴／饿）", "scene": "关心对方身体状态。", "struct": "Are you + tired / thirsty / hungry? → Yes, I am. / No, I'm not.", "cat": "emotion", "ex": ["Are you thirsty? — Yes, I am.", "Are you tired? — No, I'm not."]}, {"en": "I'm + 感觉形容词.", "zh": "我很……（累／渴／饿）", "scene": "表达自己的身体感受。", "struct": "I'm (very) + 形容词.", "cat": "emotion", "ex": ["I'm very thirsty.", "I'm hungry and tired."]}],quiz:{"v": {"q": "thirsty 的意思是：", "opts": ["渴的", "饿的", "累的"], "a": 0}, "e": {"q": "看到朋友脸色不好，最自然的问法是：", "opts": ["What's the matter?", "What are you?", "What do you want?"], "a": 0}, "p": {"q": "______ you all right now?", "opts": ["Are", "Is", "Am"], "a": 0}},speak:"说 3 句话：先用 What's the matter? 问候身体不适的朋友，再用 Are you tired/thirsty? 追问，最后给个建议 Sit down here. Have a glass of water."},
{n:20,title:"Look at Them!",topic:"形容词反义词 · Look at + 人称代词宾格",reading:"Look at them! They're very tall.\n\nLook at him! He's very fat.\n\nLook at her! She's very thin.\n\nLook at us! We're very happy today.\n\nAre they hot?\n\nNo, they aren't. They're cold.\n\nAre these boxes heavy?\n\nNo, they aren't. They're light.\n\nOpen the window, please. It's very hot in this room.\n\nLook at them! They're very happy.\n\nAre these bags heavy?\n\nNo, they aren't. They're light.\n\nIs this box big?\n\nNo, it isn't. It's small.",zh:"（原创改写）看看他们！他们很高。\n\n看看他！他很胖。\n\n看看她！她很瘦。\n\n看看我们！我们今天很开心。\n\n他们热吗？\n\n不，他们不热。他们冷。\n\n这些箱子重吗？\n\n不，不重。它们很轻。\n\n请把窗户打开。这屋里太热了。\n\n看看他们！他们很开心。\n\n这些包重吗？\n\n不重。它们很轻。\n\n这个箱子大吗？\n\n不大。它很小。",vocab:[{"w": "heavy", "ph": "/ˈhevi/", "en": "weighing a lot; not easy to lift", "zh": "adj. 重的", "eg": "This box is very heavy."}, {"w": "light", "ph": "/laɪt/", "en": "not heavy; easy to lift", "zh": "adj. 轻的", "eg": "These bags are light."}, {"w": "hot", "ph": "/hɒt/", "en": "with a high temperature", "zh": "adj. 热的；烫的", "eg": "It's very hot today."}, {"w": "cold", "ph": "/kəʊld/", "en": "with a low temperature", "zh": "adj. 冷的", "eg": "My hands are cold."}],exprs:[{"en": "Look at them!", "zh": "看看他们！", "scene": "让同伴注意远处的一群人或东西。", "struct": "Look at + me / him / her / us / them.", "cat": "dailychat", "ex": ["Look at him! He's so tall.", "Look at us! We're on TV."]}, {"en": "They're cold. / We're happy.", "zh": "他们很冷。／我们很开心。", "scene": "描述一群人的状态或感受。", "struct": "主语 + be + 形容词.", "cat": "emotion", "ex": ["They're cold. Close the window.", "We're happy to see you."]}, {"en": "Open the window, please.", "zh": "请把窗户打开", "scene": "觉得屋里闷热、想通风时的礼貌请求。", "struct": "动词原形 + 宾语, please.", "cat": "dailychat", "ex": ["Open the window, please. It's hot.", "Open the door, please. My hands are full."]}],pats:[{"en": "Look at + 宾格代词.", "zh": "看……（我／他／她／我们／他们）", "scene": "把注意力引到某人身上。", "struct": "Look at + me / him / her / us / them.", "cat": "dailychat", "ex": ["Look at her! She's very thin.", "Look at me! I'm ready."]}, {"en": "Are they + 形容词?", "zh": "他们……吗？", "scene": "询问多人的状态。", "struct": "Are they + 形容词? → Yes, they are. / No, they aren't.", "cat": "dailychat", "ex": ["Are they hot? — No, they aren't.", "Are these boxes heavy? — Yes, they are."]}],quiz:{"v": {"q": "light 在这里的意思是：", "opts": ["轻的", "灯的", "亮光"], "a": 0}, "e": {"q": "想让别人注意到远处那群人，应该说：", "opts": ["Look at them!", "Look they!", "See them!"], "a": 0}, "p": {"q": "Look at ______! They're very tall.", "opts": ["they", "them", "their"], "a": 1}},speak:"说 3 句话：用 Look at + 宾格引起注意，再用一对反义形容词（hot/cold 或 heavy/light）描述两样东西，最后提一个请求 Open the …, please."},
{n:21,title:"Which Book?",topic:"which one 选择 · Give me… 请求",reading:"Give me a book, please, Jane.\n\nWhich book? This one?\n\nNo, not that one. The red one.\n\nThis one?\n\nYes, please.\n\nHere you are.\n\nThank you. Which pen is yours?\n\nThe blue one is mine.\n\nAnd which bag do you want?\n\nThe big black one, please. It's lovely!\n\nWhich one do you want?\n\nThe green one, please.\n\nHere you are.\n\nThank you. It's a lovely book.\n\nYes, it is. I like it very much.",zh:"（原创改写）简，请给我一本书。\n\n哪本书？这本吗？\n\n不，不是那本。红色的那本。\n\n这本吗？\n\n对，就是它。\n\n给你。\n\n谢谢。哪支钢笔是你的？\n\n蓝色的那支是我的。\n\n那你想要哪个包？\n\n请给我那个又大又黑的。它真好看！\n\n你想要哪本？\n\n请给我绿色那本。\n\n给你。\n\n谢谢。这本书很好看。\n\n是的。我非常喜欢它。",vocab:[{"w": "which", "ph": "/wɪtʃ/", "en": "a word you use to ask someone to choose", "zh": "pron. 哪一个；哪些", "eg": "Which book do you want?"}, {"w": "give", "ph": "/ɡɪv/", "en": "to hand something to someone", "zh": "v. 给", "eg": "Give me a book, please."}, {"w": "one", "ph": "/wʌn/", "en": "used instead of a noun you already said", "zh": "pron. 一个（代替刚说过的名词）", "eg": "I want the red one."}, {"w": "want", "ph": "/wɒnt/", "en": "to feel that you would like to have something", "zh": "v. 想要", "eg": "Which bag do you want?"}],exprs:[{"en": "Give me …, please.", "zh": "请给我……", "scene": "向身边的人要某样东西，礼貌但直接。", "struct": "Give me + 名词, please.", "cat": "dailychat", "ex": ["Give me a book, please.", "Give me that pen, please."]}, {"en": "Which one?", "zh": "哪一个？", "scene": "同类中不止一个，让对方指明。", "struct": "Which one? / Which + 名词?", "cat": "dailychat", "ex": ["I want a bag. — Which one?", "Which one is yours? The red one?"]}, {"en": "The red one.", "zh": "红色的那个", "scene": "用 one 代替刚提过的名词，避免重复。", "struct": "The + 形容词 + one.（复数用 ones）", "cat": "dailychat", "ex": ["I'd like the blue one.", "Give me the big one, please."]}],pats:[{"en": "Give me + 名词, please.", "zh": "请给我……", "scene": "向他人索要某物。", "struct": "Give + 宾格 + 名词, please.", "cat": "dailychat", "ex": ["Give me a book, please.", "Give him a glass, please."]}, {"en": "Which + 名词?", "zh": "哪一个……？", "scene": "让对方在同类物品中做选择。", "struct": "Which + 名词? → The + 形容词 + one.", "cat": "dailychat", "ex": ["Which bag do you want? — The black one.", "Which pen is yours? — The blue one."]}],quiz:{"v": {"q": "want 的意思是：", "opts": ["想要", "给", "拿走"], "a": 0}, "e": {"q": "对方说 Which book? 你想说「红色的那本」，应说：", "opts": ["The red one.", "The one red.", "Red one the."], "a": 0}, "p": {"q": "Give ______ a book, please.", "opts": ["I", "me", "my"], "a": 1}},speak:"说 3 句话：用 Give me …, please. 要一样东西，对方回 Which one? 时，用 The + 颜色 + one. 指明你要哪个。"},
{n:22,title:"Which One Do You Want?",topic:"give + 人称代词宾格 · 物主代词",reading:"Give me a glass, please.\n\nWhich one? The clean one?\n\nNo, not the clean one. Give me the big one, please.\n\nHere you are.\n\nThank you. Give him a spoon, Anna.\n\nWhich spoon? His spoon?\n\nNo, the small one on the table.\n\nHere it is.\n\nGive us two cups, please. And give them some plates.\n\nGive her a cup, please.\n\nHere you are.\n\nThank you. And give me a plate.\n\nWhich plate? The big one?\n\nYes, the big one, please.",zh:"（原创改写）请给我一个玻璃杯。\n\n哪一个？干净的那个吗？\n\n不，不是干净的。请给我那个大的。\n\n给你。\n\n谢谢。安娜，给他一把勺子。\n\n哪把勺子？他的勺子？\n\n不，桌上那把小的。\n\n在这儿。\n\n请给我们两个杯子。再给他们几个盘子。\n\n请给她一个杯子。\n\n给你。\n\n谢谢。再给我一个盘子。\n\n哪个盘子？大的那个？\n\n对，请给我大的那个。",vocab:[{"w": "glass", "ph": "/ɡlɑːs/", "en": "a cup without a handle that you drink from", "zh": "n. 玻璃杯", "eg": "Give me a glass of water, please."}, {"w": "spoon", "ph": "/spuːn/", "en": "a thing you use to eat soup or rice", "zh": "n. 勺子", "eg": "Give him a small spoon."}, {"w": "cup", "ph": "/kʌp/", "en": "a small round thing you drink tea from", "zh": "n. 杯子", "eg": "Give us two cups, please."}, {"w": "plate", "ph": "/pleɪt/", "en": "a flat round thing you put food on", "zh": "n. 盘子", "eg": "There are five plates on the table."}],exprs:[{"en": "Give him a spoon.", "zh": "给他一把勺子", "scene": "让第三方把东西转交给别人。", "struct": "Give + 宾格（me/him/her/us/them）+ 名词.", "cat": "dailychat", "ex": ["Give her a cup of tea.", "Give them some plates, please."]}, {"en": "Which one? / Which spoon?", "zh": "哪一个？／哪把勺子？", "scene": "有多个同类物品时请对方指明。", "struct": "Which + 名词? / Which one?", "cat": "dailychat", "ex": ["Which spoon? The small one?", "Which bag? This one or that one?"]}, {"en": "Here it is.", "zh": "在这儿；给你", "scene": "找到或递出单数物品。", "struct": "Here it is.（单数）／ Here they are.（复数）", "cat": "dailychat", "ex": ["Where's my pen? — Here it is.", "Here it is. The small spoon."]}],pats:[{"en": "Give + 宾格 + 名词.", "zh": "给某人某物", "scene": "分发物品。", "struct": "Give me / him / her / us / them + 名词.", "cat": "dailychat", "ex": ["Give us two cups, please.", "Give them some plates."]}, {"en": "The + 形容词 + one.", "zh": "……的那个", "scene": "在同类物品中指明具体一个。", "struct": "The + 形容词 + one.（复数用 ones）", "cat": "dailychat", "ex": ["The small one on the table.", "The big one, please."]}],quiz:{"v": {"q": "spoon 的意思是：", "opts": ["勺子", "杯子", "盘子"], "a": 0}, "e": {"q": "想让安娜给他一把勺子，应该说：", "opts": ["Give him a spoon, Anna.", "Give he a spoon, Anna.", "Give his a spoon, Anna."], "a": 0}, "p": {"q": "Give ______ a spoon, please.", "opts": ["he", "him", "his"], "a": 1}},speak:"说 3 句话：用 Give + 宾格 + 名词 分三样餐具给不同人（me / him / us），并用 Which one? 和 The … one. 确认具体哪一件。"},
{n:23,title:"Which Glasses?",topic:"which + 复数 · these/those 与 the ones",reading:"Give me some glasses, please, Jane.\n\nWhich glasses? These glasses?\n\nNo, not those. The ones on the shelf.\n\nThese?\n\nYes, please.\n\nHere you are.\n\nThanks. Oh, these glasses are dirty. Give me the clean ones, please.\n\nThe ones in the cupboard?\n\nYes, those ones. Thank you very much.\n\nWhich plates? These plates?\n\nNo, not those. The ones in the cupboard.\n\nThese?\n\nYes, please. Thank you.\n\nYou're welcome. They're all clean now.",zh:"（原创改写）简，请给我几个玻璃杯。\n\n哪些杯子？这些吗？\n\n不，不是那些。架子上那些。\n\n这些吗？\n\n对，麻烦了。\n\n给你。\n\n谢谢。哦，这些杯子是脏的。请把干净的那些给我。\n\n橱柜里那些？\n\n对，就是那些。非常感谢。\n\n哪些盘子？这些吗？\n\n不，不是那些。橱柜里那些。\n\n这些吗？\n\n对，麻烦了。谢谢。\n\n不客气。它们现在都干净了。",vocab:[{"w": "shelf", "ph": "/ʃelf/", "en": "a flat board on a wall where you put things", "zh": "n. 架子；隔板", "eg": "The glasses are on the shelf."}, {"w": "cupboard", "ph": "/ˈkʌbəd/", "en": "a piece of furniture with doors, for cups and food", "zh": "n. 橱柜", "eg": "The clean ones are in the cupboard."}, {"w": "dirty", "ph": "/ˈdɜːti/", "en": "not clean", "zh": "adj. 脏的", "eg": "These glasses are dirty."}, {"w": "clean", "ph": "/kliːn/", "en": "not dirty", "zh": "adj. 干净的", "eg": "Give me the clean ones, please."}],exprs:[{"en": "Give me some …, please.", "zh": "请给我一些……", "scene": "要多个同类物品。", "struct": "Give me some + 复数名词, please.", "cat": "dailychat", "ex": ["Give me some glasses, please.", "Give me some clean plates."]}, {"en": "The ones on the shelf.", "zh": "架子上那些", "scene": "用 ones 加介词短语，指一群同类物品中的某一批。", "struct": "The ones + 介词短语（on the shelf / in the cupboard）.", "cat": "dailychat", "ex": ["I want the ones in the box.", "Give me the ones on the desk."]}, {"en": "No, not those.", "zh": "不，不是那些", "scene": "对方指错了，礼貌地纠正。", "struct": "No, not + these / those / this one.", "cat": "dailychat", "ex": ["These? — No, not those. The red ones.", "Is it this one? — No, not that one."]}],pats:[{"en": "Which + 复数名词?", "zh": "哪些……？", "scene": "让对方在复数物品中指明。", "struct": "Which + 复数名词? → The ones + 介词短语.", "cat": "dailychat", "ex": ["Which glasses? — The ones on the shelf.", "Which books? These or those?"]}, {"en": "The ones + 介词短语.", "zh": "……的那些", "scene": "指明某一批物品。", "struct": "The ones + on / in / under + 名词.", "cat": "dailychat", "ex": ["The ones in the cupboard.", "The ones under the table."]}],quiz:{"v": {"q": "dirty 的意思是：", "opts": ["脏的", "干净的", "旧的"], "a": 0}, "e": {"q": "想说「架子上那些」，应该说：", "opts": ["The ones on the shelf.", "The one on shelf.", "Ones the on shelf."], "a": 0}, "p": {"q": "Which ______? These glasses?", "opts": ["glass", "glasses", "a glass"], "a": 1}},speak:"说 3 句话：用 Give me some …, please. 要几样东西，用 Which …? 和 The ones on/in … 指明位置，最后用 No, not those. 纠正一次。"},
{n:24,title:"Which Ones?",topic:"名词性物主代词 · Which ones? 与 Are these yours?",reading:"Give me some books, please.\n\nWhich ones? These new ones?\n\nNo, not those. The ones on the desk.\n\nThese?\n\nYes, please. Are they yours?\n\nNo, they aren't mine. They're hers.\n\nAre these notebooks ours?\n\nNo, they aren't. They're theirs.\n\nAnd whose bags are these? They're his. Thanks!\n\nGive me some pens, please.\n\nWhich ones? The blue ones?\n\nNo, the black ones on the desk.\n\nHere you are. Are they yours?\n\nNo, they're his. Thank you very much.",zh:"（原创改写）请给我几本书。\n\n哪些？这些新的吗？\n\n不，不是那些。书桌上的那些。\n\n这些吗？\n\n对，麻烦了。它们是你的吗？\n\n不，不是我的。是她的。\n\n这些笔记本是我们的吗？\n\n不，不是。是他们的。\n\n那这些包是谁的？是他的。谢谢！\n\n请给我几支钢笔。\n\n哪些？蓝色的吗？\n\n不，桌上那些黑色的。\n\n给你。它们是你的吗？\n\n不，是他的。非常感谢。",vocab:[{"w": "ours", "ph": "/ˈaʊəz/", "en": "the things that belong to us", "zh": "pron. 我们的（东西）", "eg": "These books are ours."}, {"w": "theirs", "ph": "/ðeəz/", "en": "the things that belong to them", "zh": "pron. 他们的（东西）", "eg": "Those bags are theirs."}, {"w": "desk", "ph": "/desk/", "en": "a table where you write or work", "zh": "n. 书桌", "eg": "My books are on the desk."}, {"w": "notebook", "ph": "/ˈnəʊtbʊk/", "en": "a small book you write notes in", "zh": "n. 笔记本", "eg": "Are these notebooks ours?"}],exprs:[{"en": "Which ones?", "zh": "哪些？", "scene": "对方要多个东西，你请他指明。", "struct": "Which ones?（代指复数）", "cat": "dailychat", "ex": ["I want some books. — Which ones?", "Which ones? The new ones?"]}, {"en": "They're mine / yours / hers / ours / theirs.", "zh": "它们是我的／你的／她的／我们的／他们的", "scene": "说明一批东西归谁，后面不接名词。", "struct": "They're + 名词性物主代词.", "cat": "dailychat", "ex": ["These bags are hers.", "Are they yours? — No, they're theirs."]}, {"en": "Are these yours?", "zh": "这些是你的吗？", "scene": "拿着一堆东西确认归属。", "struct": "Are these / those + yours / hers / ours / theirs?", "cat": "dailychat", "ex": ["Are these yours? I found them here.", "Are those bags theirs?"]}],pats:[{"en": "Which ones?", "zh": "哪些？", "scene": "让对方在复数物品中做选择。", "struct": "Which ones? → The ones + 介词短语. / The + 形容词 + ones.", "cat": "dailychat", "ex": ["Which ones? — The new ones.", "Which ones? The ones on the desk?"]}, {"en": "Are these + 名词性物主代词?", "zh": "这些是……的吗？", "scene": "确认复数物品归属。", "struct": "Are these / those + yours / hers / ours / theirs? → Yes, they are. / No, they aren't.", "cat": "dailychat", "ex": ["Are these notebooks ours? — No, they aren't.", "Are those yours? — Yes, they are."]}],quiz:{"v": {"q": "theirs 的意思是：", "opts": ["他们的（东西）", "他们", "他们的（+名词）"], "a": 0}, "e": {"q": "「它们是她的」应该说：", "opts": ["They're hers.", "They're her.", "They're she."], "a": 0}, "p": {"q": "Are these pens ______?", "opts": ["your", "yours", "you"], "a": 1}},speak:"说 3 句话：用 Which ones? 请对方指明要哪些，再用 Are these yours? 确认归属，最后用 They're mine/hers/theirs. 回答。"},
{n:25,title:"Mrs. Smith's Kitchen",topic:"there be 句型（单数）· 房间与物品描述",reading:"Mrs. Smith's kitchen is small. There is a table in the middle of the room. There is a cooker on the left. It is blue. There is a refrigerator on the right. It is white. There is a clean cup on the table. There is a bottle in the refrigerator. The bottle is empty now. There is a window too. I like this little kitchen very much.\n\nThere is a small window near the cooker. I can see the garden from it.",zh:"（原创改写）史密斯太太的厨房很小。房间中间有一张桌子。左边有一个厨灶，它是蓝色的。右边有一台冰箱，它是白色的。桌子上有一只干净的杯子。冰箱里有一个瓶子，瓶子现在是空的。还有一扇窗户。我非常喜欢这个小小的厨房。\n\n厨灶旁边有一扇小窗户。我能从那儿看到花园。",vocab:[{"w": "kitchen", "ph": "/ˈkɪtʃɪn/", "en": "the room where you cook food", "zh": "n. 厨房", "eg": "She is in the kitchen now."}, {"w": "cooker", "ph": "/ˈkʊkə/", "en": "a big thing you use to cook food on", "zh": "n. 厨灶；炉具", "eg": "The cooker is on the left."}, {"w": "refrigerator", "ph": "/rɪˈfrɪdʒəreɪtə/", "en": "a big cold box that keeps food fresh", "zh": "n. 冰箱", "eg": "The milk is in the refrigerator."}, {"w": "bottle", "ph": "/ˈbɒtl/", "en": "a tall thin thing for water or milk", "zh": "n. 瓶子", "eg": "There is a bottle on the table."}],exprs:[{"en": "There is …", "zh": "有……（一个／一些）", "scene": "告诉别人某个地方有什么东西。", "struct": "There is a / an + 单数名词 + 地点.", "cat": "dailychat", "ex": ["There is a cooker in the kitchen.", "There is a clean cup on the table."]}, {"en": "on the left / on the right", "zh": "在左边／在右边", "scene": "说明东西在房间的哪一侧。", "struct": "on the left / on the right (of + 名词)", "cat": "dailychat", "ex": ["The cooker is on the left.", "The shop is on the right of the bank."]}, {"en": "in the middle of …", "zh": "在……的中间", "scene": "说明东西位于正中央。", "struct": "in the middle of + 名词", "cat": "dailychat", "ex": ["There is a table in the middle of the room.", "He is standing in the middle of the road."]}],pats:[{"en": "There is a / an + 单数名词 + 地点.", "zh": "某处有一个……", "scene": "描述房间里有什么。", "struct": "There is a / an + 单数名词 + 介词短语.", "cat": "dailychat", "ex": ["There is a window in the kitchen.", "There is an empty bottle in the fridge."]}, {"en": "There is + 不可数名词 + 地点.", "zh": "某处有……（不可数）", "scene": "描述水、牛奶这类东西。", "struct": "There is + 不可数名词 + 介词短语.", "cat": "dailychat", "ex": ["There is some milk in the bottle.", "There is no water in the glass."]}],quiz:{"v": {"q": "kitchen 的意思是：", "opts": ["厨房", "客厅", "卧室"], "a": 0}, "e": {"q": "想说「房间里有一张桌子」，应该说：", "opts": ["There is a table in the room.", "There are a table in the room.", "It has a table in the room."], "a": 0}, "p": {"q": "There ______ a cooker in the kitchen.", "opts": ["is", "are", "am"], "a": 0}},speak:"说 3 句话：用 There is … 介绍你家的厨房里有什么，并用 on the left / on the right / in the middle of 说明位置。"},
{n:26,title:"Where Is It?",topic:"Where is…? · Is there a…? 与位置介词",reading:"Where is the cup?\n\nIt's on the table.\n\nIs there a spoon on the table?\n\nYes, there is. It's near the cup.\n\nIs there a cat in the kitchen?\n\nNo, there isn't. It's in the living room.\n\nWhere is the milk?\n\nIt's in the refrigerator. Is there any milk?\n\nYes, there is some. The bottle is full. The milk is very cold.\n\nWhere is the bread?\n\nIt's in the cupboard.\n\nIs there any cheese?\n\nYes, there is some.",zh:"（原创改写）杯子在哪儿？\n\n在桌子上。\n\n桌子上有一把勺子吗？\n\n有的。它在杯子旁边。\n\n厨房里有猫吗？\n\n没有。它在客厅里。\n\n牛奶在哪儿？\n\n在冰箱里。有牛奶吗？\n\n有的，还有一些。瓶子是满的。牛奶很凉。\n\n面包在哪儿？\n\n在橱柜里。\n\n有奶酪吗？\n\n有，还有一些。",vocab:[{"w": "near", "ph": "/nɪə/", "en": "not far away from something", "zh": "prep. 在……附近", "eg": "The spoon is near the cup."}, {"w": "full", "ph": "/fʊl/", "en": "with no more space inside", "zh": "adj. 满的", "eg": "The bottle is full of milk."}, {"w": "empty", "ph": "/ˈempti/", "en": "with nothing inside", "zh": "adj. 空的", "eg": "This glass is empty."}, {"w": "milk", "ph": "/mɪlk/", "en": "the white drink from cows", "zh": "n. 牛奶", "eg": "Is there any milk in the fridge?"}],exprs:[{"en": "Where is …?", "zh": "……在哪儿？", "scene": "找不到东西时问位置。", "struct": "Where is / Where's + 单数名词?", "cat": "dailychat", "ex": ["Where is my cup?", "Where's the milk? It's not here."]}, {"en": "Is there a …?", "zh": "有……吗？", "scene": "确认某个地方有没有某样东西。", "struct": "Is there a / an + 单数名词 + 地点?", "cat": "dailychat", "ex": ["Is there a shop near here?", "Is there a cat in the room?"]}, {"en": "Yes, there is. / No, there isn't.", "zh": "有。／没有。", "scene": "回答 Is there 开头的提问。", "struct": "Yes, there is. / No, there isn't.", "cat": "dailychat", "ex": ["Is there a bank here? — Yes, there is.", "Is there a dog? — No, there isn't."]}],pats:[{"en": "Where is + 单数名词?", "zh": "……在哪儿？", "scene": "询问单个物品的位置。", "struct": "Where is + 名词? → It's + 介词短语.", "cat": "dailychat", "ex": ["Where is the milk? — It's in the fridge.", "Where is your bag?"]}, {"en": "Is there a / an + 单数名词 + 地点?", "zh": "某处有一个……吗？", "scene": "确认是否存在某物。", "struct": "Is there a / an + 名词 + 介词短语?", "cat": "dailychat", "ex": ["Is there a spoon on the table?", "Is there an apple in the bag?"]}],quiz:{"v": {"q": "empty 的意思是：", "opts": ["空的", "满的", "重的"], "a": 0}, "e": {"q": "想问冰箱里有没有牛奶，应该说：", "opts": ["Is there any milk in the fridge?", "Is there some milk in fridge?", "Are there milk in the fridge?"], "a": 0}, "p": {"q": "______ there a spoon on the table?", "opts": ["Is", "Are", "Am"], "a": 0}},speak:"说 3 句话：用 Where is …? 问两样东西在哪儿，并用 Is there a …? 确认第三样东西在不在。"},
{n:27,title:"Mrs. Smith's Living Room",topic:"there are 复数 · 客厅陈设描述",reading:"Mrs. Smith's living room is large. There is a television in the room. There are some magazines on the television. There is a table near the window. There are some newspapers on the table. There are four armchairs in the room. The armchairs are near the table. There is a stereo near the door. It's a very nice room.\n\nThere is a picture on the wall. There are some flowers on the table. It's a warm room.",zh:"（原创改写）史密斯太太的客厅很大。房间里有一台电视。电视上放着几本杂志。窗户旁边有一张桌子。桌子上有几份报纸。房间里有四把扶手椅。扶手椅在桌子旁边。门边有一台音响。这是个非常不错的房间。\n\n墙上有一幅画。桌上摆着一些花。这是个很温馨的房间。",vocab:[{"w": "television", "ph": "/ˈtelɪvɪʒn/", "en": "a thing you watch programmes on", "zh": "n. 电视机", "eg": "There is a television in the room."}, {"w": "magazine", "ph": "/ˌmæɡəˈziːn/", "en": "a thin book with pictures, sold every week", "zh": "n. 杂志", "eg": "There are some magazines on the table."}, {"w": "newspaper", "ph": "/ˈnjuːzpeɪpə/", "en": "big sheets of paper with the news", "zh": "n. 报纸", "eg": "He reads a newspaper every morning."}, {"w": "armchair", "ph": "/ˈɑːmtʃeə/", "en": "a big comfortable chair with sides for your arms", "zh": "n. 扶手椅", "eg": "There are four armchairs in the room."}],exprs:[{"en": "There are some …", "zh": "有一些……", "scene": "说明某处有几个东西。", "struct": "There are some + 复数名词 + 地点.", "cat": "dailychat", "ex": ["There are some magazines on the table.", "There are some books on the shelf."]}, {"en": "near the window / door", "zh": "在窗户／门旁边", "scene": "说明家具摆放在哪儿。", "struct": "near the + 名词", "cat": "dailychat", "ex": ["The table is near the window.", "Put the chair near the door."]}, {"en": "It's a very nice room.", "zh": "这是个很不错的房间", "scene": "参观别人家、看房时给出正面评价。", "struct": "It's a (very) nice / lovely + 名词.", "cat": "opinion", "ex": ["It's a very nice room. I like it.", "It's a lovely house. How much is it?"]}],pats:[{"en": "There are some + 复数名词 + 地点.", "zh": "某处有一些……", "scene": "描述房间里成组摆放的物品。", "struct": "There are some + 复数名词 + 介词短语.", "cat": "dailychat", "ex": ["There are some newspapers on the table.", "There are some pictures on the wall."]}, {"en": "There is a + 单数名词 + 地点.", "zh": "某处有一个……", "scene": "与 there are 搭配描述房间。", "struct": "There is a + 单数名词 + 介词短语.", "cat": "dailychat", "ex": ["There is a stereo near the door.", "There is a big table in the room."]}],quiz:{"v": {"q": "magazine 的意思是：", "opts": ["杂志", "报纸", "电视"], "a": 0}, "e": {"q": "想说「桌上有几份报纸」，应该说：", "opts": ["There are some newspapers on the table.", "There is some newspapers on the table.", "There are a newspaper on the table."], "a": 0}, "p": {"q": "There ______ some magazines on the table.", "opts": ["is", "are", "am"], "a": 1}},speak:"说 3 句话：用 There is a … 和 There are some … 各介绍你家客厅里的两样东西，最后用 It's a very nice room. 收尾。"},
{n:28,title:"Where Are They?",topic:"Are there any…? · 复数位置提问",reading:"Where are the magazines?\n\nThey're on the television.\n\nAre there any newspapers on the table?\n\nYes, there are. There are three.\n\nAre there any books in this room?\n\nNo, there aren't. There aren't any books here.\n\nWhere are the glasses?\n\nThey're in the cupboard. Are there any clean ones?\n\nYes, there are six clean ones. I can find them for you.\n\nWhere are the cups?\n\nThey're in the kitchen.\n\nAre there any clean ones?\n\nYes, there are. There are eight clean cups.",zh:"（原创改写）杂志在哪儿？\n\n在电视上。\n\n桌子上有报纸吗？\n\n有，有三份。\n\n这个房间里有书吗？\n\n没有。这儿一本书都没有。\n\n玻璃杯在哪儿？\n\n在橱柜里。有干净的吗？\n\n有，有六个干净的。我可以帮你找出来。\n\n杯子在哪儿？\n\n在厨房里。\n\n有干净的吗？\n\n有，有八个干净的杯子。",vocab:[{"w": "any", "ph": "/ˈeni/", "en": "some, used in questions and negative sentences", "zh": "pron. 一些（用于疑问句和否定句）", "eg": "Are there any books here?"}, {"w": "stereo", "ph": "/ˈsteriəʊ/", "en": "a machine you play music on", "zh": "n. 音响", "eg": "There is a stereo near the door."}, {"w": "room", "ph": "/ruːm/", "en": "one of the parts inside a building", "zh": "n. 房间", "eg": "Are there any books in this room?"}, {"w": "find", "ph": "/faɪnd/", "en": "to get something you were looking for", "zh": "v. 找到；发现", "eg": "I can't find my glasses."}],exprs:[{"en": "Where are they?", "zh": "它们在哪儿？", "scene": "找复数物品时问位置。", "struct": "Where are + 复数名词 / they?", "cat": "dailychat", "ex": ["Where are my keys?", "Where are the glasses? — They're in the cupboard."]}, {"en": "Are there any …?", "zh": "有……吗？（复数／不可数）", "scene": "确认某处有没有某样东西。", "struct": "Are there any + 复数名词 + 地点?", "cat": "dailychat", "ex": ["Are there any clean glasses?", "Are there any shops near here?"]}, {"en": "Yes, there are. / No, there aren't.", "zh": "有。／没有。", "scene": "回答 Are there 开头的提问。", "struct": "Yes, there are. / No, there aren't.", "cat": "dailychat", "ex": ["Are there any books? — No, there aren't.", "Are there any clean ones? — Yes, there are six."]}],pats:[{"en": "Are there any + 复数名词 + 地点?", "zh": "某处有一些……吗？", "scene": "确认复数物品是否存在。", "struct": "Are there any + 复数名词 + 介词短语?", "cat": "dailychat", "ex": ["Are there any newspapers on the table?", "Are there any students in the room?"]}, {"en": "Where are + 复数名词?", "zh": "……在哪儿？（复数）", "scene": "询问多个物品的位置。", "struct": "Where are + 复数名词? → They're + 介词短语.", "cat": "dailychat", "ex": ["Where are the magazines? — They're on the TV.", "Where are my shoes?"]}],quiz:{"v": {"q": "find 的意思是：", "opts": ["找到", "丢失", "寻找（强调动作）"], "a": 0}, "e": {"q": "想问「这个房间里有书吗」，应该说：", "opts": ["Are there any books in this room?", "Is there any books in this room?", "Are there some book in this room?"], "a": 0}, "p": {"q": "______ there any books in the room?", "opts": ["Are", "Is", "Am"], "a": 0}},speak:"说 3 句话：用 Where are …? 问几样东西在哪儿，再用 Are there any …? 确认数量，最后说 There aren't any … 表示没有。"},
{n:29,title:"Come In, Amy",topic:"祈使句与 must · 整理房间的指令",reading:"Come in, Amy. Shut the door, please.\n\nWhat must I do, Mrs. Smith?\n\nOpen the window and air the room. Then put these clothes in the wardrobe.\n\nYes, Mrs. Smith.\n\nThen make the bed. Dust the table and sweep the floor.\n\nIs this your new hat, Mrs. Smith?\n\nYes, it is. Put it on the bed, please.\n\nOK. The room is clean and tidy now!\n\nWhat must I do now?\n\nPlease dust the table and clean the window.\n\nAll right. Is that all?",zh:"（原创改写）进来吧，艾米。请把门关上。\n\n史密斯太太，我该做什么？\n\n把窗户打开，给房间通通风。然后把这些衣服放进衣柜。\n\n好的，史密斯太太。\n\n然后整理床铺。擦一下桌子，再扫一下地。\n\n史密斯太太，这是您的新帽子吗？\n\n是的。请把它放在床上。\n\n好的。现在房间又干净又整齐了！\n\n那我现在该做什么？\n\n请把桌子擦一下，把窗户擦干净。\n\n好的。就这些吗？",vocab:[{"w": "shut", "ph": "/ʃʌt/", "en": "to close something", "zh": "v. 关上；关闭", "eg": "Shut the door, please."}, {"w": "air", "ph": "/eə/", "en": "to let fresh air into a room", "zh": "v. 使通风", "eg": "Open the window and air the room."}, {"w": "wardrobe", "ph": "/ˈwɔːdrəʊb/", "en": "a big piece of furniture for clothes", "zh": "n. 衣柜", "eg": "Put these clothes in the wardrobe."}, {"w": "sweep", "ph": "/swiːp/", "en": "to clean the floor with a brush", "zh": "v. 扫；打扫", "eg": "Please sweep the floor."}],exprs:[{"en": "Come in.", "zh": "请进", "scene": "对方敲门后你答应他进来。", "struct": "Come in（, please）.", "cat": "dailychat", "ex": ["Come in! The door is open.", "Come in and sit down."]}, {"en": "What must I do?", "zh": "我该做什么？", "scene": "接受任务时问负责人下一步干什么。", "struct": "What must I do?", "cat": "work", "ex": ["What must I do first?", "I'm new here. What must I do?"]}, {"en": "Open the window, please.", "zh": "请把窗户打开", "scene": "请别人开窗通风。", "struct": "动词原形 + 宾语, please.（祈使句）", "cat": "dailychat", "ex": ["Open the window, please. It's hot.", "Shut the door, please. It's cold."]}],pats:[{"en": "动词原形 + 宾语, please.", "zh": "请（做）……", "scene": "发出指令或请求。", "struct": "动词原形开头 + 宾语 + , please.", "cat": "dailychat", "ex": ["Shut the door, please.", "Make the bed, please."]}, {"en": "What must I do?", "zh": "我必须做什么？", "scene": "询问自己的任务。", "struct": "What must I do? → You must + 动词原形.", "cat": "work", "ex": ["What must I do? — You must clean the floor.", "What must I do now?"]}],quiz:{"v": {"q": "sweep 的意思是：", "opts": ["扫（地）", "擦（桌子）", "洗（碗）"], "a": 0}, "e": {"q": "想请对方把窗户打开，最自然的说法是：", "opts": ["Open the window, please.", "You open the window.", "Opening the window, please."], "a": 0}, "p": {"q": "What must ______ do?", "opts": ["I", "me", "my"], "a": 0}},speak:"说 3 句话：用 Come in. 让对方进来，用 What must I do? 问任务，再用两个祈使句（Open/Shut/Put …）下指令。"},
{n:30,title:"What Must I Do?",topic:"must 义务 · 家务与日常指令",reading:"What must I do first?\n\nFirst, turn on the light. It's very dark in here.\n\nThen what must I do?\n\nTurn off the television and put the magazines on the shelf.\n\nMust I clean the cooker?\n\nYes, you must. It's very dirty.\n\nMust I wash the dishes now?\n\nNo, not now. Do it later. Wash them after lunch.\n\nAll right. Thank you very much!\n\nMust I clean the floor now?\n\nYes, please. It's very dirty.\n\nAll right. What must I do after that?",zh:"（原创改写）我该先做什么？\n\n先开灯。这里太暗了。\n\n然后我要做什么？\n\n把电视关掉，把杂志放到架子上。\n\n我必须清理厨灶吗？\n\n是的，必须清理。它太脏了。\n\n我现在必须洗碗吗？\n\n不，现在不用。待会儿再洗。午饭后再洗。\n\n好的。非常感谢！\n\n我现在必须擦地吗？\n\n是的，麻烦了。地很脏。\n\n好的。之后我还要做什么？",vocab:[{"w": "light", "ph": "/laɪt/", "en": "the thing on the ceiling that makes a room bright", "zh": "n. 灯；灯光", "eg": "Turn on the light, please."}, {"w": "dark", "ph": "/dɑːk/", "en": "with little or no light", "zh": "adj. 黑暗的；暗的", "eg": "It's very dark in this room."}, {"w": "wash", "ph": "/wɒʃ/", "en": "to clean something with water", "zh": "v. 洗", "eg": "Please wash the dishes after lunch."}, {"w": "later", "ph": "/ˈleɪtə/", "en": "at a time after now", "zh": "adv. 稍后；以后", "eg": "Do it later. I'm busy now."}],exprs:[{"en": "turn on / turn off", "zh": "打开／关掉（电器）", "scene": "操作灯、电视、电脑、空调。", "struct": "turn on / turn off + 名词", "cat": "habit", "ex": ["Turn on the light, please.", "Don't forget to turn off the TV."]}, {"en": "Must I …?", "zh": "我必须……吗？", "scene": "确认某件事是不是非做不可。", "struct": "Must I + 动词原形? → Yes, you must. / No, not now.", "cat": "work", "ex": ["Must I do it today?", "Must I come at eight?"]}, {"en": "Do it later.", "zh": "待会儿再做", "scene": "告诉对方这件事不急。", "struct": "Do + 代词 + later. / 动词短语 + later.", "cat": "habit", "ex": ["Don't worry. Do it later.", "We can eat later."]}],pats:[{"en": "Must I + 动词原形?", "zh": "我必须……吗？", "scene": "询问是否有义务做某事。", "struct": "Must I + 动词原形? → Yes, you must. / No, you needn't.", "cat": "work", "ex": ["Must I clean the cooker? — Yes, you must.", "Must I go now?"]}, {"en": "祈使句（动词原形开头）", "zh": "（你）去做……", "scene": "直接下指令或给建议。", "struct": "动词原形 + 宾语（+ please）.", "cat": "dailychat", "ex": ["Turn off the television.", "Put the magazines on the shelf."]}],quiz:{"v": {"q": "dark 的意思是：", "opts": ["黑暗的", "明亮的", "干净的"], "a": 0}, "e": {"q": "想问「我现在必须洗碗吗」，应该说：", "opts": ["Must I wash the dishes now?", "Must I to wash the dishes now?", "Do I must wash the dishes now?"], "a": 0}, "p": {"q": "Turn ______ the light, please.", "opts": ["on", "in", "at"], "a": 0}},speak:"说 3 句话：用 What must I do first? 问任务，用 Must I …? 确认其中一项，最后用 Do it later. 说明另一项不急。"},
{n:31,title:"Where's Sally?",topic:"现在进行时初步 · Where is she? 与 What's she doing?",reading:"Where's Sally, Jack?\n\nShe's in the garden, Jean.\n\nWhat's she doing?\n\nShe's sitting under the tree. She's reading a book.\n\nWhere's Tim?\n\nHe's in the garden too. He's climbing the tree.\n\nWhat about the dog?\n\nIt's running across the grass. It's chasing a cat!\n\nOh no! Stop, dog, stop!\n\nWhat's Mrs. Blake doing?\n\nShe's reading in the garden.\n\nWhat are the birds doing?\n\nThey're singing in the tree.\n\nIt's a very quiet afternoon.",zh:"（原创改写）杰克，萨莉在哪儿？\n\n她在花园里，琼。\n\n她在做什么？\n\n她坐在树下，正在看书。\n\n蒂姆在哪儿？\n\n他也在花园里。他正在爬树。\n\n那狗呢？\n\n它正在草地上跑。它在追一只猫！\n\n糟糕！停下，狗狗，快停下！\n\n布莱克太太在做什么？\n\n她在花园里看书。\n\n鸟儿在做什么？\n\n它们在树上唱歌。\n\n这是个很安静的下午。",vocab:[{"w": "garden", "ph": "/ˈɡɑːdn/", "en": "the piece of land next to a house, with grass and flowers", "zh": "n. 花园", "eg": "The children are in the garden."}, {"w": "tree", "ph": "/triː/", "en": "a tall plant with a wooden trunk", "zh": "n. 树", "eg": "She's sitting under the tree."}, {"w": "climb", "ph": "/klaɪm/", "en": "to go up something using your hands and feet", "zh": "v. 爬；攀登", "eg": "He's climbing the tree."}, {"w": "grass", "ph": "/ɡrɑːs/", "en": "the green plants that cover the ground", "zh": "n. 草；草地", "eg": "Don't walk on the grass."}],exprs:[{"en": "Where's …?", "zh": "……在哪儿？", "scene": "找人时问去向。", "struct": "Where's + 人名 / 名词?", "cat": "dailychat", "ex": ["Where's Sally? — She's in the garden.", "Where's Tim? I can't find him."]}, {"en": "What's she doing?", "zh": "她在做什么？", "scene": "看到某人在忙，想知道具体动作。", "struct": "What's + 主语 + doing?", "cat": "dailychat", "ex": ["What's she doing in the garden?", "What's he doing up there?"]}, {"en": "under the tree / in the garden", "zh": "在树下／在花园里", "scene": "说明位置。", "struct": "under / in / on + the + 名词", "cat": "dailychat", "ex": ["She's reading under the tree.", "The cat is sleeping in the garden."]}],pats:[{"en": "Where is + 人名?", "zh": "……在哪儿？", "scene": "询问某人的位置。", "struct": "Where's + 人名? → He's / She's + 介词短语.", "cat": "dailychat", "ex": ["Where's Sally? — She's in the kitchen.", "Where's your brother?"]}, {"en": "What is he / she doing?", "zh": "他／她正在做什么？", "scene": "询问当下正在进行的动作。", "struct": "What's + 主语 + doing? → 主语 + be + 动词-ing.", "cat": "dailychat", "ex": ["What's she doing? — She's reading.", "What's the dog doing? — It's running."]}],quiz:{"v": {"q": "climb 的意思是：", "opts": ["爬", "跑", "跳"], "a": 0}, "e": {"q": "想问「她在做什么」，应该说：", "opts": ["What's she doing?", "What she is doing?", "What does she doing?"], "a": 0}, "p": {"q": "What ______ she doing?", "opts": ["is", "are", "am"], "a": 0}},speak:"说 3 句话：用 Where's …? 找一个人，用 What's she/he doing? 问他在做什么，并用 be + 动词-ing 回答两个动作。"},
{n:32,title:"What's He Doing?",topic:"现在进行时 · What is he/she/it doing?",reading:"What's he doing?\n\nHe's reading a book in his room.\n\nWhat's she doing?\n\nShe's cooking in the kitchen.\n\nWhat's the cat doing?\n\nIt's sleeping on the chair.\n\nWhat are the children doing?\n\nThey're playing in the garden.\n\nAnd what are you doing?\n\nI'm watching them. They're very happy today!\n\nWhat's he doing?\n\nHe's writing a letter.\n\nWhat's she doing?\n\nShe's watching television.\n\nAnd what are you doing? I'm waiting for dinner!",zh:"（原创改写）他在做什么？\n\n他在自己房间里看书。\n\n她在做什么？\n\n她在厨房里做饭。\n\n猫在做什么？\n\n它在椅子上睡觉。\n\n孩子们在做什么？\n\n他们在花园里玩。\n\n那你在做什么？\n\n我在看着他们。他们今天特别开心！\n\n他在做什么？\n\n他在写信。\n\n她在做什么？\n\n她在看电视。\n\n那你在做什么？我在等晚饭！",vocab:[{"w": "cook", "ph": "/kʊk/", "en": "to make food ready to eat", "zh": "v. 做饭；烹饪", "eg": "She's cooking in the kitchen."}, {"w": "sleep", "ph": "/sliːp/", "en": "to rest with your eyes closed", "zh": "v. 睡觉", "eg": "The cat is sleeping on the chair."}, {"w": "play", "ph": "/pleɪ/", "en": "to do something fun, especially for children", "zh": "v. 玩；玩耍", "eg": "The children are playing outside."}, {"w": "watch", "ph": "/wɒtʃ/", "en": "to look at something for a while", "zh": "v. 观看；注视", "eg": "I'm watching the children."}],exprs:[{"en": "What's he / she doing?", "zh": "他／她正在做什么？", "scene": "想知道别人此刻正在做什么。", "struct": "What's + he / she / it + doing?", "cat": "dailychat", "ex": ["What's he doing in his room?", "What's she doing? She looks busy."]}, {"en": "He's / She's + 动词-ing.", "zh": "他／她正在……", "scene": "描述当下正在发生的动作。", "struct": "主语 + be + 动词-ing.", "cat": "dailychat", "ex": ["He's reading a book.", "She's cooking dinner now."]}, {"en": "And what are you doing?", "zh": "那你在做什么？", "scene": "聊完别人后把话题转回对方。", "struct": "And what are you doing?", "cat": "dailychat", "ex": ["They're all working. And what are you doing?", "And what are you doing this afternoon?"]}],pats:[{"en": "What is + 主语 + doing?", "zh": "……正在做什么？", "scene": "询问当下动作。", "struct": "What + be + 主语 + doing?", "cat": "dailychat", "ex": ["What's the cat doing? — It's sleeping.", "What are the children doing?"]}, {"en": "主语 + be + 动词-ing.", "zh": "……正在……", "scene": "描述正在进行的动作。", "struct": "I'm / He's / She's / It's / We're / They're + 动词-ing.", "cat": "dailychat", "ex": ["They're playing in the garden.", "I'm watching them."]}],quiz:{"v": {"q": "sleep 的意思是：", "opts": ["睡觉", "做饭", "玩耍"], "a": 0}, "e": {"q": "「他们正在花园里玩」应该说：", "opts": ["They're playing in the garden.", "They playing in the garden.", "They're play in the garden."], "a": 0}, "p": {"q": "What ______ the children doing?", "opts": ["is", "are", "am"], "a": 1}},speak:"说 3 句话：用 What's he/she doing? 问两个人此刻在做什么，再用 And what are you doing? 反问，并用 I'm … 回答。"},
{n:33,title:"A Fine Day",topic:"现在进行时 · 天气与户外活动",reading:"It's a fine day today. The sun is shining and the birds are singing. Mr. Blake is walking with his family. They are walking over the bridge. There are some boats on the river. Mrs. Blake is looking at them. Their son is eating an ice cream. Their daughter is running on the grass. They are all very happy.\n\nThere are some children in the park. They're playing football. Their parents are sitting on the grass.",zh:"（原创改写）今天天气很好。阳光明媚，鸟儿在唱歌。布莱克先生正和家人一起散步。他们正走过那座桥。河上有几条船。布莱克太太正看着那些船。他们的儿子在吃冰淇淋。他们的女儿在草地上跑。他们都很开心。\n\n公园里有一些孩子。他们在踢足球。他们的父母坐在草地上。",vocab:[{"w": "shine", "ph": "/ʃaɪn/", "en": "to give out bright light", "zh": "v. 照耀；发光", "eg": "The sun is shining today."}, {"w": "bridge", "ph": "/brɪdʒ/", "en": "a thing built over a river so you can cross it", "zh": "n. 桥", "eg": "They are walking over the bridge."}, {"w": "river", "ph": "/ˈrɪvə/", "en": "a long line of water that goes to the sea", "zh": "n. 河；江", "eg": "There are some boats on the river."}, {"w": "boat", "ph": "/bəʊt/", "en": "a small thing you travel in on water", "zh": "n. 船", "eg": "We can see three boats."}],exprs:[{"en": "It's a fine day today.", "zh": "今天天气很好", "scene": "聊天开场白，引出户外活动。", "struct": "It's a fine / nice / lovely day today.", "cat": "dailychat", "ex": ["It's a fine day. Let's go out.", "It's a lovely day, isn't it?"]}, {"en": "The sun is shining.", "zh": "阳光灿烂", "scene": "描述好天气。", "struct": "The sun is shining.", "cat": "dailychat", "ex": ["Look! The sun is shining.", "The sun is shining and it's warm."]}, {"en": "They are all very happy.", "zh": "他们都很开心", "scene": "总结一家人或一群人的状态。", "struct": "They are all (very) + 形容词.", "cat": "emotion", "ex": ["They are all very happy today.", "We're all very tired after the trip."]}],pats:[{"en": "主语 + be + 动词-ing（现在进行时）.", "zh": "……正在……", "scene": "描述此刻正在发生的事。", "struct": "主语 + am / is / are + 动词-ing.", "cat": "dailychat", "ex": ["The birds are singing.", "Their daughter is running on the grass."]}, {"en": "There are some + 复数名词 + 地点.", "zh": "某处有一些……", "scene": "描述看到的东西。", "struct": "There are some + 复数名词 + 介词短语.", "cat": "dailychat", "ex": ["There are some boats on the river.", "There are some people in the park."]}],quiz:{"v": {"q": "bridge 的意思是：", "opts": ["桥", "河", "船"], "a": 0}, "e": {"q": "想说「阳光灿烂」，应该说：", "opts": ["The sun is shining.", "The sun shines bright.", "Sun is shine."], "a": 0}, "p": {"q": "The birds ______ singing.", "opts": ["is", "are", "am"], "a": 1}},speak:"说 3 句话：用 It's a fine day today. 开场，再用两个现在进行时句子描述家人正在户外做什么。"},
{n:34,title:"What Are They Doing?",topic:"现在进行时复数 · Are they…? 的一般疑问",reading:"What are they doing?\n\nThey're waiting for a bus.\n\nWhat are the men doing?\n\nThey're working in the garden.\n\nAre the children playing?\n\nNo, they aren't. They're sleeping.\n\nIs the woman cooking?\n\nNo, she isn't. She's reading a book.\n\nLook! The bus is coming! Everybody is running!\n\nWhat are the women doing?\n\nThey're talking in the street.\n\nAre they waiting for the bus?\n\nNo, they aren't. They're waiting for a taxi.\n\nLook! It's coming!",zh:"（原创改写）他们在做什么？\n\n他们在等公交车。\n\n那些男人在做什么？\n\n他们在花园里干活。\n\n孩子们在玩吗？\n\n不，他们没在玩。他们在睡觉。\n\n那位女士在做饭吗？\n\n不，她没有。她在看书。\n\n看！公交车来了！所有人都在跑！\n\n那些女士在做什么？\n\n她们在街上聊天。\n\n她们在等公交吗？\n\n不，她们不是。她们在等出租车。\n\n看！它来了！",vocab:[{"w": "wait", "ph": "/weɪt/", "en": "to stay in a place until something happens", "zh": "v. 等待", "eg": "They're waiting for a bus."}, {"w": "bus", "ph": "/bʌs/", "en": "a big thing that carries many people on the road", "zh": "n. 公共汽车", "eg": "The bus is coming!"}, {"w": "children", "ph": "/ˈtʃɪldrən/", "en": "more than one child", "zh": "n. 孩子们（child 的复数）", "eg": "The children are sleeping."}, {"w": "street", "ph": "/striːt/", "en": "a road in a town with houses or shops", "zh": "n. 街道", "eg": "There are many cars in the street."}],exprs:[{"en": "What are they doing?", "zh": "他们在做什么？", "scene": "看到一群人在忙，想知道他们在干什么。", "struct": "What are they doing? → They're + 动词-ing.", "cat": "dailychat", "ex": ["What are they doing over there?", "What are they doing in the street?"]}, {"en": "They're waiting for the bus.", "zh": "他们在等公交车", "scene": "解释一群人为什么站在那里。", "struct": "They're waiting for + 名词.", "cat": "dailychat", "ex": ["They're waiting for the bus. It's late.", "We're waiting for you!"]}, {"en": "Look! The bus is coming!", "zh": "看！车来了！", "scene": "提醒同伴赶紧准备上车。", "struct": "Look! + 主语 + be + coming!", "cat": "dailychat", "ex": ["Look! The bus is coming! Run!", "Look! The taxi is coming."]}],pats:[{"en": "What are they doing?", "zh": "他们正在做什么？", "scene": "询问多人的当下动作。", "struct": "What are they doing? → They're + 动词-ing.", "cat": "dailychat", "ex": ["What are they doing? — They're working.", "What are the men doing?"]}, {"en": "Are they + 动词-ing?", "zh": "他们正在……吗？", "scene": "确认一群人是否在做某事。", "struct": "Are they + 动词-ing? → Yes, they are. / No, they aren't.", "cat": "dailychat", "ex": ["Are the children playing? — No, they aren't.", "Are they watching TV? — Yes, they are."]}],quiz:{"v": {"q": "wait 的意思是：", "opts": ["等待", "行走", "寻找"], "a": 0}, "e": {"q": "「他们在等公交车」应该说：", "opts": ["They're waiting for a bus.", "They waiting for bus.", "They're wait for a bus."], "a": 0}, "p": {"q": "______ the children playing?", "opts": ["Are", "Is", "Am"], "a": 0}},speak:"说 3 句话：用 What are they doing? 问一群人在做什么，用 Are they …? 确认一次，最后用 Look! … is coming! 引起注意。"},
{n:35,title:"Our Village",topic:"现在进行时描述场景 · 地点与方位介词",reading:"This is a photograph of our village. Our village is in a valley. It is between two hills. Here is another photograph. This is our house. It is beside a small river. We are walking along the river. Our children are playing near the school. The school is beside a park. There are some big trees in the park. We love our village.\n\nThere are some old houses in the village. They're very small. Our friends live in a white house near the school.",zh:"（原创改写）这是一张我们村子的照片。我们的村子在一个山谷里。它在两座小山之间。这是另一张照片。这是我们的房子，它在一条小河旁边。我们正沿着河边散步。我们的孩子们在学校附近玩耍。学校在一个公园旁边。公园里有几棵大树。我们爱我们的村子。\n\n村子里有一些老房子。它们很小。我们的朋友住在学校附近的一座白房子里。",vocab:[{"w": "village", "ph": "/ˈvɪlɪdʒ/", "en": "a very small town in the country", "zh": "n. 村庄", "eg": "Our village is very small."}, {"w": "photograph", "ph": "/ˈfəʊtəɡrɑːf/", "en": "a picture you take with a camera", "zh": "n. 照片", "eg": "This is a photograph of my family."}, {"w": "hill", "ph": "/hɪl/", "en": "a small mountain", "zh": "n. 小山", "eg": "There are two hills behind the village."}, {"w": "valley", "ph": "/ˈvæli/", "en": "the low land between two hills", "zh": "n. 山谷", "eg": "The village is in the valley."}],exprs:[{"en": "This is a photograph of …", "zh": "这是一张……的照片", "scene": "给别人看照片时的开场白。", "struct": "This is a photograph of + 名词.", "cat": "dailychat", "ex": ["This is a photograph of my village.", "This is a photograph of our school."]}, {"en": "between A and B", "zh": "在A和B之间", "scene": "说明位置夹在两者中间。", "struct": "between + 名词 + and + 名词", "cat": "dailychat", "ex": ["It's between the bank and the shop.", "Our house is between two big trees."]}, {"en": "We love our village.", "zh": "我们爱我们的村子", "scene": "表达对家乡、住处的感情。", "struct": "I / We love + 名词.", "cat": "emotion", "ex": ["We love our village. It's so quiet.", "I love this city in spring."]}],pats:[{"en": "This is a photograph of + 名词.", "zh": "这是一张……的照片", "scene": "展示照片。", "struct": "This is a photograph of + 名词.", "cat": "dailychat", "ex": ["This is a photograph of my house.", "This is a photograph of the park."]}, {"en": "It is + 介词短语（地点）.", "zh": "它在……（位置）", "scene": "说明建筑、地点的方位。", "struct": "It is + in / beside / between / near + 名词.", "cat": "dailychat", "ex": ["It is beside a small river.", "It is between two hills."]}],quiz:{"v": {"q": "valley 的意思是：", "opts": ["山谷", "小山", "河流"], "a": 0}, "e": {"q": "想说「它在两座小山之间」，应该说：", "opts": ["It is between two hills.", "It is among two hills.", "It between two hills."], "a": 0}, "p": {"q": "Our village is ______ two hills.", "opts": ["between", "in", "on"], "a": 0}},speak:"说 3 句话：用 This is a photograph of … 介绍一张照片，用 It is between/beside … 说明位置，再用现在进行时说说照片里的人在做什么。"},
{n:36,title:"Where Are They Going?",topic:"现在进行时表去向 · Where 提问与移动方向",reading:"Where is he going?\n\nHe's going into the shop.\n\nWhere is she going?\n\nShe's going out of the house.\n\nWhere are they going?\n\nThey're going into the park.\n\nWhere is the dog going?\n\nIt's going across the street.\n\nWhere are you going?\n\nI'm going home. It's late!\n\nWhere is the cat going?\n\nIt's going into the garden.\n\nWhere are the boys going?\n\nThey're going across the street.\n\nAnd where are you going? I'm going to the shop!",zh:"（原创改写）他要去哪儿？\n\n他正走进那家商店。\n\n她要去哪儿？\n\n她正从房子里出来。\n\n他们要去哪儿？\n\n他们正走进公园。\n\n狗要去哪儿？\n\n它正穿过街道。\n\n你要去哪儿？\n\n我要回家了。太晚了！\n\n猫要去哪儿？\n\n它要进花园。\n\n那些男孩要去哪儿？\n\n他们要过马路。\n\n那你要去哪儿？我要去商店！",vocab:[{"w": "into", "ph": "/ˈɪntə/", "en": "to the inside of a place", "zh": "prep. 进入……里面", "eg": "He's going into the shop."}, {"w": "out of", "ph": "/ˈaʊt əv/", "en": "from the inside of a place to the outside", "zh": "prep. 从……出来", "eg": "She's going out of the house."}, {"w": "across", "ph": "/əˈkrɒs/", "en": "from one side of something to the other side", "zh": "prep. 穿过；横过", "eg": "The dog is going across the street."}, {"w": "park", "ph": "/pɑːk/", "en": "a place in a town with trees and grass", "zh": "n. 公园", "eg": "They're going into the park."}],exprs:[{"en": "Where are you going?", "zh": "你要去哪儿？", "scene": "路上遇见熟人时的寒暄。", "struct": "Where are you going? → I'm going + 地点.", "cat": "dailychat", "ex": ["Where are you going? — I'm going home.", "Where are you going with that bag?"]}, {"en": "I'm going home.", "zh": "我要回家了", "scene": "告辞时的常用说法。", "struct": "I'm going home / to the shop / to bed.", "cat": "dailychat", "ex": ["It's late. I'm going home.", "I'm going to bed. Good night!"]}, {"en": "He's going into the shop.", "zh": "他正走进商店", "scene": "描述某人移动的方向。", "struct": "主语 + be + going + into / out of / across + 名词.", "cat": "dailychat", "ex": ["She's going out of the office.", "They're going across the road."]}],pats:[{"en": "Where is / are + 主语 + going?", "zh": "……要去哪儿？", "scene": "询问他人的去向。", "struct": "Where + be + 主语 + going? → 主语 + be + going + 地点.", "cat": "dailychat", "ex": ["Where is he going? — He's going into the shop.", "Where are they going?"]}, {"en": "主语 + be + going + 介词短语.", "zh": "……正往……去", "scene": "描述正在发生的移动。", "struct": "主语 + be + going into / out of / across / to + 名词.", "cat": "dailychat", "ex": ["The dog is going across the street.", "We're going to the park."]}],quiz:{"v": {"q": "across 的意思是：", "opts": ["穿过；横过", "进入", "出来"], "a": 0}, "e": {"q": "路上碰到熟人，想问他去哪儿，应该说：", "opts": ["Where are you going?", "Where you going?", "Where do you going?"], "a": 0}, "p": {"q": "Where ______ they going?", "opts": ["is", "are", "am"], "a": 1}},speak:"说 3 句话：用 Where are you going? 问朋友去哪儿，用 I'm going … 回答，再用现在进行时说说一个家人正在往哪儿走。"},
{n:37,title:"Making a Bookcase",topic:"be going to 打算 · 动手做东西",reading:"What are you going to do, George?\n\nI'm going to make a bookcase.\n\nGood idea! What colour are you going to paint it?\n\nI'm going to paint it white. My books are white and blue.\n\nAre you going to do it now?\n\nNo, I'm not. I'm going to do it tomorrow morning.\n\nGive me the hammer, please.\n\nHere you are. What are you going to do with it?\n\nI'm going to hit this nail. Watch me!",zh:"（原创改写）乔治，你打算做什么？\n\n我打算做一个书架。\n\n好主意！你打算把它漆成什么颜色？\n\n我打算漆成白色。我的书是白色和蓝色的。\n\n你现在就做吗？\n\n不，我现在不做。我打算明天上午做。\n\n请把锤子给我。\n\n给你。你打算用它做什么？\n\n我打算把这颗钉子钉进去。看着啊！",vocab:[{"w": "bookcase", "ph": "/ˈbʊkkeɪs/", "en": "a piece of furniture with shelves for books", "zh": "n. 书架；书柜", "eg": "I'm going to make a bookcase."}, {"w": "paint", "ph": "/peɪnt/", "en": "to put colour on a wall or a thing", "zh": "v. 油漆；涂色", "eg": "I'm going to paint it white."}, {"w": "hammer", "ph": "/ˈhæmə/", "en": "a tool you use to hit nails", "zh": "n. 锤子", "eg": "Give me the hammer, please."}, {"w": "tomorrow", "ph": "/təˈmɒrəʊ/", "en": "the day after today", "zh": "adv. 明天", "eg": "I'm going to do it tomorrow morning."}],exprs:[{"en": "What are you going to do?", "zh": "你打算做什么？", "scene": "问别人接下来的计划，周末、假期、晚上都适用。", "struct": "What are you going to do (+ 时间)?", "cat": "dailychat", "ex": ["What are you going to do this weekend?", "What are you going to do with that box?"]}, {"en": "I'm going to …", "zh": "我打算……", "scene": "说出自己的计划或意图。", "struct": "I'm going to + 动词原形.", "cat": "dailychat", "ex": ["I'm going to make a bookcase.", "I'm going to paint it white."]}, {"en": "Good idea!", "zh": "好主意！", "scene": "赞成别人的提议，非常高频。", "struct": "Good idea! / That's a good idea!", "cat": "opinion", "ex": ["Let's eat out. — Good idea!", "Good idea! Let's do it tomorrow."]}],pats:[{"en": "What are you going to do?", "zh": "你打算做什么？", "scene": "询问计划。", "struct": "What are you going to do? → I'm going to + 动词原形.", "cat": "dailychat", "ex": ["What are you going to do? — I'm going to read.", "What are you going to do after work?"]}, {"en": "be going to + 动词原形", "zh": "打算／将要……", "scene": "表达已经想好的计划。", "struct": "主语 + be going to + 动词原形 (+ 时间).", "cat": "dailychat", "ex": ["He's going to help me tomorrow.", "We're going to visit them on Sunday."]}],quiz:{"v": {"q": "bookcase 的意思是：", "opts": ["书架", "书", "书店"], "a": 0}, "e": {"q": "想说「我打算做一个书架」，应该说：", "opts": ["I'm going to make a bookcase.", "I'm going make a bookcase.", "I going to make a bookcase."], "a": 0}, "p": {"q": "I'm going ______ make a bookcase.", "opts": ["to", "for", "at"], "a": 0}},speak:"说 3 句话：用 What are you going to do? 问朋友的计划，用 I'm going to … 说出自己的打算，再用 Good idea! 回应一次。"},
{n:38,title:"What Are You Going to Do?",topic:"be going to 与将来时间状语 · 计划与安排",reading:"What are you going to do this evening?\n\nI'm going to read a book at home.\n\nWhat are you going to do tomorrow?\n\nI'm going to visit my grandmother. She's in hospital.\n\nWhat is your brother going to do next week?\n\nHe's going to work in a big shop.\n\nWhat are you going to do at the weekend?\n\nI'm going to watch a film with Anna. And you? I'm going to sleep!",zh:"（原创改写）你今天晚上打算做什么？\n\n我打算在家看书。\n\n你明天打算做什么？\n\n我打算去看我奶奶。她住院了。\n\n你哥哥下周打算做什么？\n\n他打算去一家大商店上班。\n\n你周末打算做什么？\n\n我打算和安娜看场电影。你呢？我要睡觉！",vocab:[{"w": "evening", "ph": "/ˈiːvnɪŋ/", "en": "the time between late afternoon and night", "zh": "n. 晚上；傍晚", "eg": "What are you going to do this evening?"}, {"w": "visit", "ph": "/ˈvɪzɪt/", "en": "to go to see a person or a place", "zh": "v. 拜访；参观", "eg": "I'm going to visit my grandmother."}, {"w": "tonight", "ph": "/təˈnaɪt/", "en": "the night of today", "zh": "adv. 今晚", "eg": "I'm going to stay at home tonight."}, {"w": "weekend", "ph": "/ˌwiːkˈend/", "en": "Saturday and Sunday", "zh": "n. 周末", "eg": "What are you going to do at the weekend?"}],exprs:[{"en": "this evening / tomorrow / next week", "zh": "今天晚上／明天／下周", "scene": "给计划加上时间，让对方知道什么时候做。", "struct": "this evening, tonight, tomorrow, next week, at the weekend", "cat": "habit", "ex": ["I'm going to call you tonight.", "We're going to start next week."]}, {"en": "I'm going to visit my grandmother.", "zh": "我打算去看我奶奶", "scene": "说明要去看望的人。", "struct": "I'm going to visit + 人 / 地方.", "cat": "dailychat", "ex": ["I'm going to visit my old teacher.", "We're going to visit the museum tomorrow."]}, {"en": "And you?", "zh": "你呢？", "scene": "说完自己之后把话题抛回给对方。", "struct": "And you? / What about you?", "cat": "dailychat", "ex": ["I'm tired. And you?", "I'm going home. And you?"]}],pats:[{"en": "What are you going to do + 将来时间?", "zh": "你（某时）打算做什么？", "scene": "带时间地问计划。", "struct": "What are you going to do + this evening / tomorrow / next week?", "cat": "dailychat", "ex": ["What are you going to do tomorrow?", "What are you going to do at the weekend?"]}, {"en": "主语 + be going to + 动词原形 + 时间状语.", "zh": "……打算（某时）做……", "scene": "说明计划和时间。", "struct": "主语 + be going to + 动词原形 + 时间状语.", "cat": "dailychat", "ex": ["He's going to work in a shop next week.", "I'm going to read a book tonight."]}],quiz:{"v": {"q": "weekend 的意思是：", "opts": ["周末", "工作日", "今天晚上"], "a": 0}, "e": {"q": "想问「你今晚打算做什么」，应该说：", "opts": ["What are you going to do tonight?", "What you going to do tonight?", "What are you going do tonight?"], "a": 0}, "p": {"q": "What are you going to do ______ evening?", "opts": ["this", "these", "those"], "a": 0}},speak:"说 3 句话：用 What are you going to do …? 带时间问两次计划，最后用 And you? 把话题抛回给对方。"},
{n:39,title:"Don't Drop It!",topic:"祈使与警告 Don't… · Be careful",reading:"What are you going to do with that vase, Sam?\n\nI'm going to put it on this table, Penny.\n\nDon't do that! Give it to me.\n\nWhat are you going to do with it?\n\nI'm going to put it here, in front of the window.\n\nBe careful! Don't drop it!\n\nDon't put it there, Sam. Put it here, on this shelf.\n\nThere we are! It's a lovely vase. Don't touch it!",zh:"（原创改写）萨姆，你打算把这个花瓶怎么办？\n\n我打算把它放在这张桌子上，彭妮。\n\n别那么做！把它给我。\n\n你打算拿它怎么办？\n\n我打算把它放在这儿，窗户前面。\n\n小心！别摔了！\n\n别放那儿，萨姆。放这儿，这个架子上。\n\n好了！这个花瓶真漂亮。别碰它！",vocab:[{"w": "vase", "ph": "/vɑːz/", "en": "a pretty thing you put flowers in", "zh": "n. 花瓶", "eg": "Don't drop that vase!"}, {"w": "drop", "ph": "/drɒp/", "en": "to let something fall from your hands", "zh": "v. 掉下；使落下", "eg": "Be careful! Don't drop it."}, {"w": "careful", "ph": "/ˈkeəfl/", "en": "giving attention so you don't make a mistake", "zh": "adj. 小心的；仔细的", "eg": "Be careful with that glass."}, {"w": "touch", "ph": "/tʌtʃ/", "en": "to put your hand on something", "zh": "v. 触摸；碰", "eg": "Don't touch it! It's hot."}],exprs:[{"en": "Don't do that!", "zh": "别那么做！", "scene": "看到别人要做危险或不对的事，马上制止。", "struct": "Don't + 动词原形 (+ 宾语)!", "cat": "dailychat", "ex": ["Don't do that! It's dangerous.", "Don't open it now. Wait."]}, {"en": "Be careful!", "zh": "小心！", "scene": "提醒对方注意安全，尤其是搬东西、过马路时。", "struct": "Be careful! / Be careful with + 名词.", "cat": "dailychat", "ex": ["Be careful! The floor is wet.", "Be careful with that glass."]}, {"en": "There we are!", "zh": "好了！／搞定！", "scene": "做完一件事、把东西放好时的收尾语。", "struct": "There we are!（也可说 There you are!）", "cat": "dailychat", "ex": ["There we are! The room is clean.", "There we are! Two cups of tea."]}],pats:[{"en": "Don't + 动词原形.", "zh": "别……", "scene": "发出禁止或劝阻。", "struct": "Don't + 动词原形 (+ 宾语).", "cat": "dailychat", "ex": ["Don't drop it!", "Don't put it there."]}, {"en": "Put + 宾语 + 地点.", "zh": "把……放在……", "scene": "指挥对方摆放东西。", "struct": "Put + 宾语 + 介词短语.", "cat": "dailychat", "ex": ["Put it here, on this shelf.", "Put the books on the desk."]}],quiz:{"v": {"q": "drop 的意思是：", "opts": ["掉下；使落下", "举起", "打破（及物用法）"], "a": 0}, "e": {"q": "看到别人要把花瓶摔了，你最可能喊：", "opts": ["Be careful! Don't drop it!", "Be careful! Don't drop!", "Careful! No drop it!"], "a": 0}, "p": {"q": "______ drop it!", "opts": ["Don't", "Not", "No"], "a": 0}},speak:"说 3 句话：用两个 Don't … 提醒对方别做危险的事，再用 Put it … 告诉对方该放哪儿。"},
{n:40,title:"Give It to Me",topic:"双宾语 give/show/send/take · be going to 复习",reading:"What are you going to do with that photograph?\n\nI'm going to send it to my mother.\n\nShow it to me, please.\n\nHere you are. It's a photo of our new house.\n\nIt's lovely. Are you going to send her a letter too?\n\nYes, I am. I'm going to write to her tonight.\n\nGive me a pen, please.\n\nHere you are. Don't forget the stamp!\n\nThank you. Are you going to write it now?\n\nYes, I am. I'm going to write it after lunch.\n\nGood.",zh:"（原创改写）你打算拿这张照片怎么办？\n\n我打算把它寄给我妈妈。\n\n给我看看，行吗？\n\n给你。这是我们新房子的照片。\n\n真漂亮。你也打算给她寄封信吗？\n\n是的。我打算今晚给她写信。\n\n请给我一支钢笔。\n\n给你。别忘了贴邮票！\n\n谢谢。你现在就写吗？\n\n是的。我打算午饭后写。\n\n好的。",vocab:[{"w": "send", "ph": "/send/", "en": "to make something go to another place", "zh": "v. 寄；发送", "eg": "I'm going to send it to my mother."}, {"w": "show", "ph": "/ʃəʊ/", "en": "to let someone look at something", "zh": "v. 给……看；展示", "eg": "Show it to me, please."}, {"w": "letter", "ph": "/ˈletə/", "en": "a piece of paper you write and send to someone", "zh": "n. 信", "eg": "I'm going to write a letter tonight."}, {"w": "stamp", "ph": "/stæmp/", "en": "a small piece of paper you put on a letter", "zh": "n. 邮票", "eg": "Don't forget the stamp!"}],exprs:[{"en": "Show it to me.", "zh": "给我看看", "scene": "想看对方手里的东西。", "struct": "show + 物 + to + 人 / show + 人 + 物", "cat": "dailychat", "ex": ["Show it to me, please.", "Show me your new phone."]}, {"en": "send … to …", "zh": "把……寄给……", "scene": "说明寄件对象。", "struct": "send + 物 + to + 人 / send + 人 + 物", "cat": "dailychat", "ex": ["I'm going to send it to my mother.", "Send me a photo, please."]}, {"en": "Don't forget …", "zh": "别忘了……", "scene": "提醒对方别漏掉某件事。", "struct": "Don't forget + 名词 / to do.", "cat": "dailychat", "ex": ["Don't forget the stamp!", "Don't forget to call me."]}],pats:[{"en": "动词 + 物 + to + 人", "zh": "把某物（给／寄／拿）给某人", "scene": "give, send, show, take 等动词的常用语序。", "struct": "give / send / show / take + 物 + to + 人", "cat": "dailychat", "ex": ["Give it to me.", "Send it to my mother."]}, {"en": "动词 + 人 + 物", "zh": "给某人某物", "scene": "双宾语的另一种语序，人放前面。", "struct": "give / send / show / take + 人 + 物", "cat": "dailychat", "ex": ["Give me a pen, please.", "Send her a letter."]}],quiz:{"v": {"q": "send 的意思是：", "opts": ["寄；发送", "拿走", "收到"], "a": 0}, "e": {"q": "想请对方把照片给你看看，应该说：", "opts": ["Show it to me, please.", "Show me it, please — 语序不常用", "Show to me it."], "a": 0}, "p": {"q": "I'm going to send it ______ my mother.", "opts": ["to", "for", "at"], "a": 0}},speak:"说 3 句话：用 Show it to me. 要一样东西看，用 I'm going to send it to … 说打算寄给谁，最后用 Give me …, please. 要个工具。"},
{n:41,title:"Penny's Bag",topic:"不可数名词 · a bar/piece/loaf of 量词",reading:"Is that bag heavy, Penny?\n\nNot very. There's a bar of chocolate in it.\n\nIs there any bread?\n\nYes, there's a loaf of bread. And there's a piece of cheese.\n\nIs there any coffee?\n\nYes, there's a pound of coffee. And there's a bottle of milk.\n\nIs there any tea?\n\nNo, there isn't any tea. Can you buy some for me?\n\nIs there any sugar?\n\nYes, there's a pound of sugar.\n\nIs there any chocolate?\n\nYes, there's a bar of chocolate.",zh:"（原创改写）彭妮，那个包重吗？\n\n不太重。里面有一块巧克力。\n\n有面包吗？\n\n有，有一条面包。还有一块奶酪。\n\n有咖啡吗？\n\n有，有一磅咖啡。还有一瓶牛奶。\n\n有茶吗？\n\n没有茶。你能帮我买一些吗？\n\n有糖吗？\n\n有，有一磅糖。\n\n有巧克力吗？\n\n有，有一块巧克力。",vocab:[{"w": "chocolate", "ph": "/ˈtʃɒklət/", "en": "a sweet brown food made from cocoa", "zh": "n. 巧克力", "eg": "There's a bar of chocolate in my bag."}, {"w": "bread", "ph": "/bred/", "en": "a food made from flour, cut in slices", "zh": "n. 面包", "eg": "Is there any bread in the kitchen?"}, {"w": "cheese", "ph": "/tʃiːz/", "en": "a yellow or white food made from milk", "zh": "n. 奶酪", "eg": "I'd like a piece of cheese."}, {"w": "sugar", "ph": "/ˈʃʊɡə/", "en": "a sweet white thing you put in tea or coffee", "zh": "n. 糖", "eg": "There isn't any sugar in the tin."}],exprs:[{"en": "a bar of chocolate", "zh": "一块巧克力", "scene": "数巧克力、肥皂这类条状物。", "struct": "a bar of + 不可数名词", "cat": "dailychat", "ex": ["There's a bar of chocolate in the bag.", "I want two bars of chocolate."]}, {"en": "a piece of / a loaf of …", "zh": "一块……／一条……", "scene": "给不可数名词计数。", "struct": "a piece of + cheese / a loaf of + bread", "cat": "dailychat", "ex": ["There's a piece of cheese in the fridge.", "Buy a loaf of bread, please."]}, {"en": "Not very.", "zh": "不太……", "scene": "被问 Is it heavy/cold/big 时给一个折中回答。", "struct": "Not very.（= Not very heavy / cold / big.）", "cat": "dailychat", "ex": ["Is it heavy? — Not very.", "Are you tired? — Not very."]}],pats:[{"en": "Is there any + 不可数名词?", "zh": "有……吗？（不可数）", "scene": "问家里、包里有没有某样东西。", "struct": "Is there any + 不可数名词? → Yes, there is some. / No, there isn't any.", "cat": "dailychat", "ex": ["Is there any bread?", "Is there any coffee in the kitchen?"]}, {"en": "There is a + 量词 + of + 不可数名词.", "zh": "有一（块／条／磅）……", "scene": "给不可数名词配上量词。", "struct": "There is a bar / piece / loaf / pound / bottle of + 不可数名词.", "cat": "dailychat", "ex": ["There's a pound of coffee.", "There's a bottle of milk in the fridge."]}],quiz:{"v": {"q": "cheese 的意思是：", "opts": ["奶酪", "巧克力", "面包"], "a": 0}, "e": {"q": "想说「有一条面包」，应该说：", "opts": ["There's a loaf of bread.", "There's a bread.", "There's one bread."], "a": 0}, "p": {"q": "Is there ______ bread?", "opts": ["any", "a", "many"], "a": 0}},speak:"说 3 句话：用 Is there any …? 问包里有没有三样东西，并用 a bar/piece/loaf of 说出其中两样的数量。"},
{n:42,title:"Is There Any Tea?",topic:"不可数名词提问 · Is there any 与 there isn't any",reading:"Is there any milk in the kitchen?\n\nYes, there is some. There's a bottle of milk.\n\nIs there any sugar?\n\nNo, there isn't any sugar. The tin is empty.\n\nIs there any tea in this shop?\n\nYes, there is. There's half a pound of tea.\n\nIs there any coffee?\n\nNo, there isn't any. I'm sorry. Can I have some bread?\n\nIs there any cheese?\n\nYes, there is some.\n\nIs there any chocolate?\n\nNo, there isn't any.",zh:"（原创改写）厨房里有牛奶吗？\n\n有，还有一些。有一瓶牛奶。\n\n有糖吗？\n\n没有，一点糖都没有。罐子空了。\n\n这家店里有茶吗？\n\n有的。有半磅茶叶。\n\n有咖啡吗？\n\n没有。抱歉。我能买点面包吗？\n\n有奶酪吗？\n\n有，还有一些。\n\n有巧克力吗？\n\n没有，一点都没有。",vocab:[{"w": "tea", "ph": "/tiː/", "en": "a hot drink made from tea leaves", "zh": "n. 茶", "eg": "Is there any tea in this shop?"}, {"w": "tin", "ph": "/tɪn/", "en": "a metal box that keeps food dry and fresh", "zh": "n. 罐子；听", "eg": "The tin is empty."}, {"w": "half", "ph": "/hɑːf/", "en": "one of two equal parts; 50%", "zh": "n. 一半", "eg": "There's half a pound of tea."}, {"w": "pound", "ph": "/paʊnd/", "en": "a unit of weight, about 0.45 kg", "zh": "n. 磅（重量单位）", "eg": "I'd like a pound of coffee, please."}],exprs:[{"en": "Is there any …?", "zh": "有……吗？（不可数）", "scene": "在店里或家里问还有没有某样东西。", "struct": "Is there any + 不可数名词?", "cat": "dailychat", "ex": ["Is there any tea?", "Is there any milk in the fridge?"]}, {"en": "There isn't any …", "zh": "一点……都没有", "scene": "告诉对方东西用完了。", "struct": "There isn't any + 不可数名词.", "cat": "dailychat", "ex": ["There isn't any sugar. I'll buy some.", "Sorry, there isn't any coffee."]}, {"en": "I'm sorry.", "zh": "抱歉；不好意思", "scene": "无法满足对方需求时的礼貌回应。", "struct": "I'm sorry.（+ 说明）", "cat": "dailychat", "ex": ["I'm sorry. We don't have any tea.", "I'm sorry, the shop is closed."]}],pats:[{"en": "Is there any + 不可数名词?", "zh": "有……吗？", "scene": "确认是否还有某物。", "struct": "Is there any + 不可数名词 (+ 地点)?", "cat": "dailychat", "ex": ["Is there any sugar?", "Is there any water in the bottle?"]}, {"en": "Yes, there is some. / No, there isn't any.", "zh": "有，还有一些。／没有，一点都没有。", "scene": "回答不可数名词的存在与否。", "struct": "Yes, there is some. / No, there isn't any.", "cat": "dailychat", "ex": ["Is there any milk? — Yes, there is some.", "Is there any tea? — No, there isn't any."]}],quiz:{"v": {"q": "tin 在这里的意思是：", "opts": ["罐子；听", "锡（金属）", "薄片"], "a": 0}, "e": {"q": "想说「一点糖都没有了」，应该说：", "opts": ["There isn't any sugar.", "There isn't some sugar.", "There aren't any sugar."], "a": 0}, "p": {"q": "There isn't ______ sugar in the tin.", "opts": ["any", "some", "a"], "a": 0}},speak:"说 3 句话：用 Is there any …? 问两样不可数的东西，分别用 Yes, there is some. 和 No, there isn't any. 回答。"},
{n:43,title:"Hurry Up!",topic:"can 能力 · 沏茶与催促",reading:"Can you make the tea, Sam?\n\nYes, of course I can, Penny. Where's the water?\n\nIt's in the kettle. Can you see it?\n\nYes, I can see the kettle. But I can't find the cups!\n\nThey're in the cupboard. Hurry up, Sam!\n\nThe kettle's boiling! Here are the cups.\n\nCan you find the tea?\n\nYes, here it is. I can make the tea now!\n\nCan you put the tea in the pot?\n\nYes, I can. Here it is.\n\nThank you. The tea is ready!",zh:"（原创改写）萨姆，你能沏茶吗？\n\n当然能，彭妮。水在哪儿？\n\n在水壶里。你看到了吗？\n\n看到了，我看到水壶了。但我找不到杯子！\n\n杯子在橱柜里。快点，萨姆！\n\n水开了！杯子在这儿。\n\n你能找到茶叶吗？\n\n能，在这儿。我现在可以沏茶了！\n\n你能把茶叶放进茶壶吗？\n\n能。给你。\n\n谢谢。茶好了！",vocab:[{"w": "kettle", "ph": "/ˈketl/", "en": "a thing you boil water in", "zh": "n. 水壶", "eg": "The water is in the kettle."}, {"w": "boil", "ph": "/bɔɪl/", "en": "to heat water until it makes bubbles", "zh": "v. 沸腾；烧开", "eg": "The kettle's boiling!"}, {"w": "hurry", "ph": "/ˈhʌri/", "en": "to move or do something quickly", "zh": "v. 匆忙；赶快", "eg": "Hurry up! We're late."}, {"w": "make", "ph": "/meɪk/", "en": "to prepare something, like tea or a cake", "zh": "v. 做；沏（茶）", "eg": "Can you make the tea, please?"}],exprs:[{"en": "Hurry up!", "zh": "快点！", "scene": "赶时间时催促同伴。", "struct": "Hurry up (, + 人名)!", "cat": "dailychat", "ex": ["Hurry up! The bus is here.", "Hurry up, Sam! We're late."]}, {"en": "Can you …?", "zh": "你能／会……吗？", "scene": "请别人帮忙做某事。", "struct": "Can you + 动词原形?", "cat": "dailychat", "ex": ["Can you make the tea?", "Can you help me with this box?"]}, {"en": "Yes, of course I can.", "zh": "当然可以", "scene": "爽快地答应对方的请求。", "struct": "Yes, of course I can. / Sure, I can.", "cat": "dailychat", "ex": ["Can you help? — Yes, of course I can.", "Yes, of course I can. It's easy."]}],pats:[{"en": "Can you + 动词原形?", "zh": "你能否……？", "scene": "请求或确认能力。", "struct": "Can you + 动词原形? → Yes, I can. / No, I can't.", "cat": "dailychat", "ex": ["Can you see it? — Yes, I can.", "Can you find the cups?"]}, {"en": "I can / I can't + 动词原形.", "zh": "我能／我不能……", "scene": "说明自己能不能做到。", "struct": "I can / I can't + 动词原形.", "cat": "dailychat", "ex": ["I can't find the cups!", "I can make the tea now."]}],quiz:{"v": {"q": "kettle 的意思是：", "opts": ["水壶", "杯子", "茶"], "a": 0}, "e": {"q": "水开了，你催同伴快一点，应该说：", "opts": ["Hurry up!", "Wait a moment, please.", "Never mind."], "a": 0}, "p": {"q": "______ you make the tea?", "opts": ["Can", "Do", "Are"], "a": 0}},speak:"说 3 句话：用 Can you …? 请朋友帮忙沏茶，用 Yes, of course I can. 答应，再用 I can't find … 说明一个小困难。"},
{n:44,title:"Are There Any Cups?",topic:"可数复数与不可数对比 · Are there any / Is there any",reading:"Are there any cups in the cupboard?\n\nYes, there are. There are six clean cups.\n\nAre there any plates?\n\nNo, there aren't any plates. They're all in the kitchen.\n\nIs there any milk in the fridge?\n\nYes, there is some.\n\nIs there any sugar?\n\nYes, there is. There's a tin of sugar. Is that all? Yes, that's all. Thank you!\n\nAre there any glasses?\n\nYes, there are four.\n\nIs there any coffee?\n\nYes, there is some.",zh:"（原创改写）橱柜里有杯子吗？\n\n有，有六个干净的杯子。\n\n有盘子吗？\n\n没有，一个盘子都没有。它们都在厨房里。\n\n冰箱里有牛奶吗？\n\n有，还有一些。\n\n有糖吗？\n\n有。有一罐糖。就这些吗？是的，就这些。谢谢！\n\n有玻璃杯吗？\n\n有，有四个。\n\n有咖啡吗？\n\n有，还有一些。",vocab:[{"w": "fridge", "ph": "/frɪdʒ/", "en": "a cold box in the kitchen for food", "zh": "n. 冰箱（口语）", "eg": "Is there any milk in the fridge?"}, {"w": "ready", "ph": "/ˈredi/", "en": "prepared and able to start", "zh": "adj. 准备好的", "eg": "Tea is ready! Come and drink."}, {"w": "all", "ph": "/ɔːl/", "en": "every one; the whole amount", "zh": "pron. 全部；所有", "eg": "They're all in the kitchen."}, {"w": "dish", "ph": "/dɪʃ/", "en": "a plate or bowl for food", "zh": "n. 盘子；菜", "eg": "There aren't any clean dishes here."}],exprs:[{"en": "Are there any …?", "zh": "有……吗？（复数）", "scene": "确认某处有没有多个东西。", "struct": "Are there any + 复数名词 (+ 地点)?", "cat": "dailychat", "ex": ["Are there any cups in the cupboard?", "Are there any clean plates?"]}, {"en": "Is that all?", "zh": "就这些吗？", "scene": "买东西、点单时确认有没有遗漏。", "struct": "Is that all?", "cat": "dailychat", "ex": ["Two cups of tea, please. — Is that all?", "Is that all? Anything else?"]}, {"en": "Yes, that's all.", "zh": "是的，就这些", "scene": "结账、点单结束时收尾。", "struct": "Yes, that's all. (Thank you.)", "cat": "dailychat", "ex": ["Yes, that's all. How much is it?", "Yes, that's all, thanks."]}],pats:[{"en": "Are there any + 复数名词?", "zh": "有一些……吗？（可数）", "scene": "问可数复数的数量。", "struct": "Are there any + 复数名词? → Yes, there are. / No, there aren't.", "cat": "dailychat", "ex": ["Are there any plates?", "Are there any students in the room?"]}, {"en": "Is there any + 不可数名词?", "zh": "有……吗？（不可数）", "scene": "与可数复数形成对比。", "struct": "Is there any + 不可数名词? → Yes, there is some. / No, there isn't any.", "cat": "dailychat", "ex": ["Is there any milk in the fridge?", "Is there any sugar? — Yes, there is."]}],quiz:{"v": {"q": "fridge 的意思是：", "opts": ["冰箱", "橱柜", "水壶"], "a": 0}, "e": {"q": "想问「橱柜里有杯子吗」，应该说：", "opts": ["Are there any cups in the cupboard?", "Is there any cups in the cupboard?", "Are there some cup in the cupboard?"], "a": 0}, "p": {"q": "Are there ______ cups in the cupboard?", "opts": ["any", "some", "a"], "a": 0}},speak:"说 3 句话：用 Are there any …? 问两样可数东西，再用 Is there any …? 问一样不可数东西，最后用 Yes, that's all. 收尾。"},
{n:45,title:"The Boss's Letter",topic:"can 能力 · 职场请求与转交",reading:"Can you come to my office for a minute, Bob?\n\nYes, sir. What's the matter?\n\nCan you type this letter for me?\n\nYes, of course I can. But I can't read your handwriting.\n\nOh, I'm sorry. It's very bad, isn't it?\n\nCan you spell this word for me?\n\nYes. W-O-R-K, work.\n\nThank you. You're a very good secretary, Bob!\n\nCan you finish it before five?\n\nYes, I can. It's not very long.\n\nGood. Thank you very much, Bob.\n\nYou're welcome, sir.",zh:"（原创改写）鲍勃，你能来我办公室一下吗？\n\n好的，先生。什么事？\n\n你能帮我打这封信吗？\n\n当然可以。不过我看不懂您的字迹。\n\n哦，抱歉。写得很潦草，是吧？\n\n您能把这个单词拼给我听吗？\n\n好。W-O-R-K，work。\n\n谢谢。鲍勃，你真是个很出色的秘书！\n\n你能在五点前打完吗？\n\n能。这封信不长。\n\n很好。太谢谢你了，鲍勃。\n\n不客气，先生。",vocab:[{"w": "boss", "ph": "/bɒs/", "en": "the person who tells you what to do at work", "zh": "n. 老板；上司", "eg": "My boss is in a meeting."}, {"w": "type", "ph": "/taɪp/", "en": "to write something on a computer or keyboard", "zh": "v. 打字", "eg": "Can you type this letter for me?"}, {"w": "minute", "ph": "/ˈmɪnɪt/", "en": "sixty seconds; a very short time", "zh": "n. 分钟；一会儿", "eg": "Can you come here for a minute?"}, {"w": "spell", "ph": "/spel/", "en": "to say or write the letters of a word", "zh": "v. 拼写", "eg": "Can you spell this word for me?"}],exprs:[{"en": "for a minute", "zh": "一会儿；一下", "scene": "请别人过来一下，暗示不会耽误太久。", "struct": "come / wait / look + for a minute", "cat": "work", "ex": ["Can you come here for a minute?", "Wait for a minute, please."]}, {"en": "Can you type this for me?", "zh": "你能帮我打这个吗？", "scene": "请同事帮忙处理文件。", "struct": "Can you + 动词 + 宾语 + for me?", "cat": "work", "ex": ["Can you type this letter for me?", "Can you check this for me?"]}, {"en": "I can't read your handwriting.", "zh": "我看不懂你的字", "scene": "对方手写字太潦草时的委婉说法。", "struct": "I can't read + 名词.", "cat": "work", "ex": ["Sorry, I can't read your handwriting.", "I can't read this word. Can you spell it?"]}],pats:[{"en": "Can you + 动词原形 + for me?", "zh": "你能帮我……吗？", "scene": "请人代劳。", "struct": "Can you + 动词 + 宾语 + for me?", "cat": "work", "ex": ["Can you open the door for me?", "Can you spell this word for me?"]}, {"en": "I can / I can't + 动词原形.", "zh": "我能／我不能……", "scene": "说明自己是否能完成。", "struct": "I can (not) + 动词原形.", "cat": "work", "ex": ["I can't read your handwriting.", "I can do it before five."]}],quiz:{"v": {"q": "spell 的意思是：", "opts": ["拼写", "打字", "阅读"], "a": 0}, "e": {"q": "老板想让你去他办公室一下，他会说：", "opts": ["Can you come to my office for a minute?", "You come my office, quick.", "Go to my office now!"], "a": 0}, "p": {"q": "Can you type this letter ______ me?", "opts": ["for", "to", "at"], "a": 0}},speak:"说 3 句话：用 Can you come … for a minute? 叫同事过来，用 Can you … for me? 请他帮忙，并用 Yes, of course I can. 答应一件事。"},
{n:46,title:"Can You Swim?",topic:"can/can't 能力 · 会做与不会做的事",reading:"Can you swim?\n\nYes, I can. I can swim very well.\n\nCan you drive a car?\n\nNo, I can't. But I can ride a bike.\n\nCan Anna cook?\n\nYes, she can. She can make a very good cake.\n\nCan your brother speak English?\n\nNo, he can't. He can speak a little French. What can you do? I can sing!\n\nCan you play the piano?\n\nNo, I can't. But I can play the guitar.\n\nCan your sister dance?\n\nYes, she can. She can dance very well.",zh:"（原创改写）你会游泳吗？\n\n会，我会。我游得很好。\n\n你会开车吗？\n\n不会。但我会骑自行车。\n\n安娜会做饭吗？\n\n会，她会。她做的蛋糕特别好吃。\n\n你哥哥会说英语吗？\n\n不会。他会说一点法语。你会做什么？我会唱歌！\n\n你会弹钢琴吗？\n\n不会。但我会弹吉他。\n\n你妹妹会跳舞吗？\n\n会。她跳得非常好。",vocab:[{"w": "swim", "ph": "/swɪm/", "en": "to move through water with your body", "zh": "v. 游泳", "eg": "Can you swim?"}, {"w": "drive", "ph": "/draɪv/", "en": "to make a car, bus or taxi move", "zh": "v. 驾驶；开车", "eg": "I can't drive a car."}, {"w": "ride", "ph": "/raɪd/", "en": "to sit on a bike or horse and control it", "zh": "v. 骑（车／马）", "eg": "I can ride a bike."}, {"w": "speak", "ph": "/spiːk/", "en": "to say words in a language", "zh": "v. 说（某种语言）", "eg": "Can you speak English?"}],exprs:[{"en": "Can you swim?", "zh": "你会游泳吗？", "scene": "聊特长、技能时的经典问法。", "struct": "Can you + 动词原形?", "cat": "hobby", "ex": ["Can you swim? The sea is warm.", "Can you play the piano?"]}, {"en": "I can … very well.", "zh": "我很会……", "scene": "强调自己的水平不错。", "struct": "I can + 动词原形 + very well.", "cat": "hobby", "ex": ["I can swim very well.", "She can cook very well."]}, {"en": "What can you do?", "zh": "你会做什么？", "scene": "反问对方的特长，或者夸人时引出话题。", "struct": "What can you do?", "cat": "hobby", "ex": ["What can you do? — I can sing!", "What can you do with this app?"]}],pats:[{"en": "Can you + 动词原形?", "zh": "你会／能……吗？", "scene": "询问能力。", "struct": "Can you + 动词原形? → Yes, I can. / No, I can't.", "cat": "hobby", "ex": ["Can you drive a car?", "Can your brother speak English?"]}, {"en": "主语 + can / can't + 动词原形.", "zh": "……会／不会……", "scene": "说明能力，第三人称也用 can。", "struct": "I / He / She / They can (not) + 动词原形.", "cat": "hobby", "ex": ["She can make a very good cake.", "He can't speak English."]}],quiz:{"v": {"q": "ride 的意思是：", "opts": ["骑（车／马）", "开车", "游泳"], "a": 0}, "e": {"q": "想问对方会不会游泳，应该说：", "opts": ["Can you swim?", "Do you can swim?", "Are you swim?"], "a": 0}, "p": {"q": "Can you swim? — Yes, I ______.", "opts": ["can", "can't", "am"], "a": 0}},speak:"说 3 句话：用 Can you …? 问朋友两项技能，再用 I can … very well. 说一个自己的强项，用 I can't … 说一个不会的。"},
{n:47,title:"A Cup of Coffee",topic:"like/want · Would you like…? 礼貌提供",reading:"Do you like coffee, Ann?\n\nYes, I do.\n\nDo you want a cup?\n\nYes, please, Mary. I'd like a cup of coffee.\n\nDo you want any sugar?\n\nYes, please. And some milk, please.\n\nWould you like a biscuit?\n\nNo, thank you. I don't like biscuits. I don't want one.\n\nWhat about a cup of tea? No, thanks. This is very nice!\n\nIs the coffee all right?\n\nYes, it's very good. I like it.\n\nWould you like another cup?\n\nYes, please!",zh:"（原创改写）安，你喜欢咖啡吗？\n\n是的，我喜欢。\n\n你想来一杯吗？\n\n好的，麻烦了，玛丽。我想要一杯咖啡。\n\n你要加糖吗？\n\n要，麻烦了。再来点牛奶。\n\n你想来块饼干吗？\n\n不用了，谢谢。我不喜欢饼干，我不想要。\n\n那来杯茶怎么样？不用了，谢谢。这杯咖啡很好喝！\n\n咖啡还合口味吗？\n\n嗯，很好喝。我喜欢。\n\n想再来一杯吗？\n\n好的，麻烦了！",vocab:[{"w": "coffee", "ph": "/ˈkɒfi/", "en": "a hot brown drink made from coffee beans", "zh": "n. 咖啡", "eg": "Do you like coffee?"}, {"w": "biscuit", "ph": "/ˈbɪskɪt/", "en": "a small hard sweet cake", "zh": "n. 饼干", "eg": "Would you like a biscuit?"}, {"w": "sweet", "ph": "/swiːt/", "en": "with a taste like sugar", "zh": "adj. 甜的", "eg": "This coffee is too sweet for me."}, {"w": "drink", "ph": "/drɪŋk/", "en": "to take liquid into your mouth", "zh": "v. 喝", "eg": "I drink two cups of coffee a day."}],exprs:[{"en": "Would you like …?", "zh": "你想要……吗？", "scene": "招待客人、请人吃东西时最礼貌的说法。", "struct": "Would you like + 名词 / to do?", "cat": "dailychat", "ex": ["Would you like a cup of coffee?", "Would you like to sit down?"]}, {"en": "Yes, please. / No, thank you.", "zh": "好的，麻烦了。／不用了，谢谢。", "scene": "接受或婉拒别人的好意。", "struct": "Yes, please. / No, thank you.", "cat": "dailychat", "ex": ["More tea? — Yes, please.", "A biscuit? — No, thank you."]}, {"en": "I don't like …", "zh": "我不喜欢……", "scene": "委婉说明自己的口味偏好。", "struct": "I don't like + 名词 / 动词-ing.", "cat": "opinion", "ex": ["I don't like biscuits.", "I don't like getting up early."]}],pats:[{"en": "Do you like + 名词?", "zh": "你喜欢……吗？", "scene": "询问长期的喜好。", "struct": "Do you like + 名词? → Yes, I do. / No, I don't.", "cat": "opinion", "ex": ["Do you like coffee? — Yes, I do.", "Do you like this city?"]}, {"en": "Would you like + 名词?", "zh": "你想要……吗？", "scene": "此刻提供某物，比 Do you want 更礼貌。", "struct": "Would you like + a / some + 名词?", "cat": "dailychat", "ex": ["Would you like a biscuit?", "Would you like some milk in your coffee?"]}],quiz:{"v": {"q": "biscuit 的意思是：", "opts": ["饼干", "咖啡", "糖"], "a": 0}, "e": {"q": "想礼貌地问客人要不要来杯咖啡，应该说：", "opts": ["Would you like a cup of coffee?", "Do you like a cup of coffee?", "You want a cup of coffee?"], "a": 0}, "p": {"q": "______ you like a cup of coffee?", "opts": ["Would", "Do", "Are"], "a": 0}},speak:"说 3 句话：用 Do you like …? 问朋友的口味，用 Would you like …? 招待他，并用 Yes, please. 或 No, thank you. 回应一次。"},
{n:48,title:"Do You Like Apples?",topic:"一般现在时喜好 · like/want 与第三人称",reading:"Do you like apples?\n\nYes, I do. I like sweet apples very much.\n\nDo you like oranges?\n\nNo, I don't. I don't like oranges.\n\nDo you want one?\n\nNo, thank you. I want an apple, please.\n\nDoes your brother like coffee?\n\nNo, he doesn't. He likes tea. But he doesn't want any now.\n\nWhat do you like? I like fruit!\n\nDo you like bananas?\n\nYes, I do. I eat one every morning.\n\nDo you like fruit?\n\nYes, I do. What about you?",zh:"（原创改写）你喜欢苹果吗？\n\n是的，我喜欢。我很喜欢甜苹果。\n\n你喜欢橘子吗？\n\n不，我不喜欢。我不喜欢橘子。\n\n你想要一个吗？\n\n不用了，谢谢。我想要一个苹果。\n\n你哥哥喜欢咖啡吗？\n\n不，他不喜欢。他喜欢茶。但他现在不想喝。\n\n你喜欢什么？我喜欢水果！\n\n你喜欢香蕉吗？\n\n喜欢。我每天早上吃一根。\n\n你喜欢水果吗？\n\n喜欢。你呢？",vocab:[{"w": "apple", "ph": "/ˈæpl/", "en": "a round fruit with red or green skin", "zh": "n. 苹果", "eg": "I like sweet apples very much."}, {"w": "orange", "ph": "/ˈɒrɪndʒ/", "en": "a round sweet fruit with orange skin", "zh": "n. 橘子；橙子", "eg": "I don't like oranges."}, {"w": "fruit", "ph": "/fruːt/", "en": "apples, oranges, bananas and so on", "zh": "n. 水果", "eg": "I like fruit. It's good for you."}, {"w": "banana", "ph": "/bəˈnɑːnə/", "en": "a long yellow fruit", "zh": "n. 香蕉", "eg": "She eats a banana every morning."}],exprs:[{"en": "Do you like …?", "zh": "你喜欢……吗？", "scene": "了解对方的长期喜好。", "struct": "Do you like + 名词 / 动词-ing?", "cat": "opinion", "ex": ["Do you like apples?", "Do you like reading in bed?"]}, {"en": "I like … very much.", "zh": "我很喜欢……", "scene": "强调喜欢的程度。", "struct": "I like + 名词 + very much / a lot.", "cat": "hobby", "ex": ["I like sweet apples very much.", "I like this song a lot."]}, {"en": "What do you like?", "zh": "你喜欢什么？", "scene": "把话题从「喜不喜欢」推进到「喜欢什么」。", "struct": "What do you like?", "cat": "hobby", "ex": ["What do you like? — I like fruit!", "What do you like to do at weekends?"]}],pats:[{"en": "Do you like + 名词?", "zh": "你喜欢……吗？", "scene": "询问一般喜好。", "struct": "Do you like + 名词? → Yes, I do. / No, I don't.", "cat": "opinion", "ex": ["Do you like oranges? — No, I don't.", "Do you like this book?"]}, {"en": "主语 + like(s) / don't(doesn't) like + 名词.", "zh": "……喜欢／不喜欢……", "scene": "说明自己或他人的喜好，第三人称加 s。", "struct": "I / You / We / They like… / He / She likes…", "cat": "hobby", "ex": ["He likes tea.", "She doesn't want any now."]}],quiz:{"v": {"q": "banana 的意思是：", "opts": ["香蕉", "苹果", "橘子"], "a": 0}, "e": {"q": "想问「你哥哥喜欢咖啡吗」，应该说：", "opts": ["Does your brother like coffee?", "Do your brother like coffee?", "Does your brother likes coffee?"], "a": 0}, "p": {"q": "______ your brother like coffee?", "opts": ["Do", "Does", "Are"], "a": 1}},speak:"说 3 句话：用 Do you like …? 和 Does he/she like …? 各问一个人的喜好，并说明自己 I like … very much. 和 I don't like …"},
{n:49,title:"At the Butcher's",topic:"一般现在时 · like/likes 与选择疑问句 Do you want A or B?",reading:"Good afternoon, Mrs. White. What can I do for you?\n\nI want some meat for dinner. Do you have beef or lamb?\n\nWe have both. The beef is very fresh today.\n\nMy husband likes beef, but my son doesn't. He likes lamb.\n\nThen take some of each. How much do you want?\n\nHalf a kilo of beef and half a kilo of lamb, please.\n\nHere you are. Anything else?\n\nYes, some eggs. We eat eggs every morning.\n\nIs that all? Thank you. How much is it?\n\nEight pounds. Have a nice dinner!",zh:"（原创改写）下午好，怀特太太，需要点什么？\n\n我想买些晚饭用的肉。你们有牛肉还是羊肉？\n\n两种都有。今天的牛肉很新鲜。\n\n我丈夫喜欢牛肉，但我儿子不喜欢，他喜欢羊肉。\n\n那就两样都来点。您要多少？\n\n半公斤牛肉，半公斤羊肉。\n\n给您。还要别的吗？\n\n再要些鸡蛋。我们每天早上都吃鸡蛋。\n\n就这些吗？谢谢，一共多少钱？\n\n八英镑。祝您晚餐愉快！",vocab:[{"w": "butcher", "ph": "/ˈbʊtʃə(r)/", "en": "a person who sells meat in a shop", "zh": "n. 肉贩；屠夫", "eg": "The butcher in this street is very kind."}, {"w": "beef", "ph": "/biːf/", "en": "the meat from a cow", "zh": "n. 牛肉", "eg": "My father cooks beef very well."}, {"w": "lamb", "ph": "/læm/", "en": "the meat from a young sheep", "zh": "n. 羊肉", "eg": "She wants half a kilo of lamb."}, {"w": "fresh", "ph": "/freʃ/", "en": "recently made or picked, not old", "zh": "adj. 新鲜的", "eg": "The fish is fresh this morning."}],exprs:[{"en": "What can I do for you?", "zh": "需要点什么？／我能为您做什么？", "scene": "店员、服务员招呼客人的开场白，语气客气。", "struct": "What can I do for you?", "cat": "dailychat", "ex": ["Good morning. What can I do for you?", "What can I do for you? We have fresh fish today."]}, {"en": "Here you are.", "zh": "给您；拿去吧", "scene": "把东西递给别人时说的固定话，非常常用。", "struct": "Here you are. / Here you go.", "cat": "dailychat", "ex": ["Here you are. One kilo of beef.", "Here you are. Please count your change."]}, {"en": "Is that all?", "zh": "就这些吗？", "scene": "购物或点餐时，确认对方是不是还要别的东西。", "struct": "Is that all?", "cat": "dailychat", "ex": ["Is that all? Anything else?", "Two bottles of milk. — Is that all?"]}],pats:[{"en": "Do you want A or B?", "zh": "您要 A 还是 B？", "scene": "让对方在两个选项里挑一个，叫选择疑问句，不能用 Yes/No 回答。", "struct": "Do you want + A + or + B?", "cat": "dailychat", "ex": ["Do you want beef or lamb?", "Do you want tea or coffee?"]}, {"en": "I like … , but he/she doesn't.", "zh": "我喜欢……，但他／她不喜欢。", "scene": "对比两个人的喜好。注意三单用 doesn't，后面动词打回原形。", "struct": "主语 + like(s) … , but + 三单主语 + doesn't.", "cat": "dailychat", "ex": ["I like beef, but my son doesn't.", "She likes tea, but her husband doesn't."]}],quiz:{"v": {"q": "fresh 的意思是：", "opts": ["新鲜的", "便宜的", "肥的"], "a": 0}, "e": {"q": "把东西递给客人时应该说：", "opts": ["Is that all?", "Here you are.", "What can I do for you?"], "a": 1}, "p": {"q": "My husband likes beef, but my son ______.", "opts": ["don't", "doesn't", "isn't"], "a": 1}},speak:"说 3 句话：先在 What can I do for you? 和 Is that all? 里选一句开口，再用 Do you want A or B? 问对方要哪一样，最后用 … likes …, but … doesn't. 说出两个人的不同喜好。"},
{n:50,title:"He Likes, But She Doesn't",topic:"一般现在时第三人称单数 · 动词 -s 与 doesn't",reading:"My friend Tom and I are very different.\n\nHe likes coffee, but I like tea. He drinks coffee every morning.\n\nDoes he like milk? No, he doesn't. He never puts milk in his coffee.\n\nHis sister Anna likes milk very much. She drinks a glass before bed.\n\nTom likes rice, but he doesn't like noodles at all.\n\nAnna doesn't like rice, but she loves bread.\n\nWhat about me? I like noodles, rice and bread. I like everything!",zh:"（原创改写）我朋友汤姆和我差别很大。\n\n他喜欢咖啡，但我喜欢茶。他每天早上都喝咖啡。\n\n他喜欢牛奶吗？不，他不喜欢。他从来不往咖啡里加牛奶。\n\n他妹妹安娜非常喜欢牛奶，她睡前喝一杯。\n\n汤姆喜欢米饭，但他一点也不喜欢面条。\n\n安娜不喜欢米饭，但她很爱面包。\n\n我呢？面条、米饭、面包我都喜欢。我什么都喜欢！",vocab:[{"w": "different", "ph": "/ˈdɪfrənt/", "en": "not the same", "zh": "adj. 不同的", "eg": "My brother and I are very different."}, {"w": "coffee", "ph": "/ˈkɒfi/", "en": "a hot brown drink", "zh": "n. 咖啡", "eg": "He drinks a cup of coffee at work."}, {"w": "milk", "ph": "/mɪlk/", "en": "a white drink from cows", "zh": "n. 牛奶", "eg": "She puts milk in her tea."}, {"w": "noodle", "ph": "/ˈnuːdl/", "en": "a long thin food made from flour and water", "zh": "n. 面条", "eg": "We have noodles for lunch today."}],exprs:[{"en": "not … at all", "zh": "一点也不……", "scene": "把否定说到最满，语气比 don't like 强很多。", "struct": "主语 + don't/doesn't + 动词 + … at all", "cat": "opinion", "ex": ["He doesn't like noodles at all.", "I don't like cold weather at all."]}, {"en": "… very much", "zh": "非常……", "scene": "把喜欢的程度说足，放在句尾最自然。", "struct": "主语 + like(s) … very much", "cat": "emotion", "ex": ["She likes milk very much.", "I like this city very much."]}, {"en": "What about … ?", "zh": "……呢？／……怎么样？", "scene": "把话题丢回给对方，或补问另一个人、另一件事。", "struct": "What about + 名词/代词?", "cat": "dailychat", "ex": ["I like tea. What about you?", "What about your sister? Does she like rice?"]}],pats:[{"en": "He/She + 动词 -s/-es", "zh": "他／她做……（第三人称单数）", "scene": "主语是 he、she、it 或单个人名时，一般现在时的动词要加 -s。", "struct": "He/She/It + 动词 -s/-es", "cat": "habit", "ex": ["He drinks coffee every morning.", "She likes milk very much."]}, {"en": "He/She doesn't + 动词原形", "zh": "他／她不做……", "scene": "三单的否定。记住 doesn't 已经带上 -s 了，后面的动词必须打回原形。", "struct": "主语(三单) + doesn't + 动词原形", "cat": "habit", "ex": ["Tom doesn't like noodles.", "She doesn't drink coffee at night."]}],quiz:{"v": {"q": "different 的意思是：", "opts": ["不同的", "困难的", "美味的"], "a": 0}, "e": {"q": "想说「我一点也不喜欢面条」，应该说：", "opts": ["I don't like noodles very much.", "I don't like noodles at all.", "I like noodles at all."], "a": 1}, "p": {"q": "She ______ a glass of milk before bed.", "opts": ["drink", "drinks", "drinking"], "a": 1}},speak:"说 3 句话：用 He/She + 动词 -s 说一个朋友的喜好，用 doesn't 说他／她不喜欢的东西，最后用 not … at all 把不喜欢说得更重一点。"},
{n:51,title:"A Pleasant Climate",topic:"国籍与语言 · Where do you come from? / What's the climate like?",reading:"Hello! Where do you come from?\n\nI come from Brazil. What about you?\n\nI'm from China. Is Brazil a big country?\n\nIt is very big. What's the climate like there?\n\nIt's very pleasant. It's warm in the south and hot in the north.\n\nDo you speak Portuguese?\n\nYes, I do. I speak Portuguese and a little English.\n\nWhat language do they speak in your country?\n\nWe speak Chinese. I sometimes speak English at work.\n\nThat's nice. I want to learn Chinese too!",zh:"（原创改写）你好！你是哪里人？\n\n我来自巴西。你呢？\n\n我来自中国。巴西很大吗？\n\n非常大。那儿的气候怎么样？\n\n很宜人。南方温暖，北方炎热。\n\n你说葡萄牙语吗？\n\n说。我说葡萄牙语，还会一点英语。\n\n你们国家的人说什么语言？\n\n我们说中文。我上班时有时说英语。\n\n真好。我也想学中文！",vocab:[{"w": "country", "ph": "/ˈkʌntri/", "en": "an area of land with its own people and government", "zh": "n. 国家", "eg": "China is a very big country."}, {"w": "climate", "ph": "/ˈklaɪmət/", "en": "the usual weather in a place", "zh": "n. 气候", "eg": "The climate here is warm in winter."}, {"w": "pleasant", "ph": "/ˈpleznt/", "en": "nice and enjoyable", "zh": "adj. 宜人的；令人愉快的", "eg": "We had a pleasant evening at home."}, {"w": "language", "ph": "/ˈlæŋɡwɪdʒ/", "en": "the words people use to speak, like English or Chinese", "zh": "n. 语言", "eg": "English is a useful language."}],exprs:[{"en": "Where do you come from?", "zh": "你是哪里人？／你来自哪里？", "scene": "初次见面聊国籍、家乡，比 Where are you from? 更课本、更正式一点。", "struct": "Where do/does + 主语 + come from?", "cat": "dailychat", "ex": ["Where do you come from? — I come from Brazil.", "Where does he come from? — He comes from Italy."]}, {"en": "What's the climate like?", "zh": "气候怎么样？", "scene": "问一个地方长期的天气特点，不是问今天下不下雨。", "struct": "What's the climate/weather like + 地点?", "cat": "dailychat", "ex": ["What's the climate like in your country?", "What's the weather like today?"]}, {"en": "a little", "zh": "一点儿", "scene": "说自己会一点点某样东西，比 a lot 谦虚，常挂在语言能力后面。", "struct": "speak/know + a little + 语言/名词", "cat": "dailychat", "ex": ["I speak a little English.", "She knows a little Japanese."]}],pats:[{"en": "I come from …", "zh": "我来自……", "scene": "回答来自哪个国家或城市，和 I am from … 一个意思。", "struct": "主语 + come(s) from + 地点", "cat": "dailychat", "ex": ["I come from China.", "He comes from a small town."]}, {"en": "What language do you speak?", "zh": "你说什么语言？", "scene": "聊到国籍之后自然跟的一句，问对方说什么语言。", "struct": "What language + do/does + 主语 + speak?", "cat": "dailychat", "ex": ["What language do they speak in your country?", "What language does your mother speak?"]}],quiz:{"v": {"q": "climate 的意思是：", "opts": ["气候", "国家", "语言"], "a": 0}, "e": {"q": "想问对方是哪里人，最合适的说法是：", "opts": ["What language do you speak?", "Where do you come from?", "What's the climate like?"], "a": 1}, "p": {"q": "Where ______ he come from?", "opts": ["do", "does", "is"], "a": 1}},speak:"说 3 句话：先用 Where do you come from? 问对方是哪里人，再用 What's the climate like? 问那儿的气候，最后用 I speak … and a little … 说说自己会什么语言。"},
{n:52,title:"Where Do They Come From?",topic:"国籍与语言 · Where does he come from? / 三单问答",reading:"Look at this photo. Who are they?\n\nThe tall boy is Marco. He comes from Italy. He speaks Italian.\n\nThe girl next to him is Yuki. She comes from Japan, and she speaks Japanese.\n\nAnd this is Anna. She comes from Russia. She speaks Russian and English.\n\nWhere does Marco come from? He comes from Italy.\n\nDoes Yuki speak English? Yes, she does. She speaks a little.\n\nThey are all my friends at school. We often help each other with our homework.",zh:"（原创改写）看看这张照片，他们是谁？\n\n那个高个子男孩是马可，他来自意大利，说意大利语。\n\n他旁边的女孩是优纪，她来自日本，说日语。\n\n这位是安娜，她来自俄罗斯，说俄语和英语。\n\n马可来自哪里？他来自意大利。\n\n优纪说英语吗？是的，她会说一点点。\n\n他们都是我在学校的朋友。我们经常互相帮忙写作业。",vocab:[{"w": "photo", "ph": "/ˈfəʊtəʊ/", "en": "a picture made with a camera", "zh": "n. 照片", "eg": "This is a photo of my family."}, {"w": "tall", "ph": "/tɔːl/", "en": "having a greater than usual height", "zh": "adj. 高的", "eg": "My brother is very tall now."}, {"w": "Italian", "ph": "/ɪˈtæliən/", "en": "the language of Italy; a person from Italy", "zh": "n./adj. 意大利语；意大利人（的）", "eg": "He can speak a little Italian."}, {"w": "Japanese", "ph": "/ˌdʒæpəˈniːz/", "en": "the language of Japan; a person from Japan", "zh": "n./adj. 日语；日本人（的）", "eg": "Yuki speaks Japanese at home."}],exprs:[{"en": "next to", "zh": "在……旁边", "scene": "说位置很方便，指人指物都能用。", "struct": "next to + 名词", "cat": "dailychat", "ex": ["The girl next to him is my sister.", "Our school is next to the park."]}, {"en": "a little", "zh": "一点儿", "scene": "接在语言或不可数名词前面，表示量不多。", "struct": "a little + 不可数名词", "cat": "dailychat", "ex": ["She speaks a little English.", "There is a little milk in the glass."]}, {"en": "help each other", "zh": "互相帮助", "scene": "说两个或多个人之间的关系，很温暖的一个表达。", "struct": "主语(复数) + help each other", "cat": "relationship", "ex": ["We often help each other with our homework.", "The two brothers help each other every day."]}],pats:[{"en": "Where does he/she come from?", "zh": "他／她来自哪里？", "scene": "问第三个人的国籍或家乡，注意用 does，后面 come 打回原形。", "struct": "Where + does + 三单主语 + come from?", "cat": "dailychat", "ex": ["Where does Marco come from?", "Where does your teacher come from?"]}, {"en": "Does he/she speak …? — Yes, … does. / No, … doesn't.", "zh": "他／她说……吗？——是的。／不。", "scene": "确认某人会不会某种语言，回答里用 does / doesn't 代替整句话。", "struct": "Does + 三单主语 + speak + 语言?", "cat": "dailychat", "ex": ["Does Yuki speak English? — Yes, she does.", "Does he speak Chinese? — No, he doesn't."]}],quiz:{"v": {"q": "tall 的意思是：", "opts": ["高的", "矮的", "胖的"], "a": 0}, "e": {"q": "想说「他旁边的女孩」，应该用：", "opts": ["the girl next to him", "the girl next him", "the girl in to him"], "a": 0}, "p": {"q": "Where does Yuki ______ from?", "opts": ["comes", "come", "coming"], "a": 1}},speak:"说 3 句话：用 Where does he/she come from? 介绍一位朋友来自哪个国家，用 He/She speaks … 说他／她会什么语言，再用 Does he/she speak …? 补问一句并自己回答。"},
{n:53,title:"An Interesting Climate",topic:"频率副词 · 季节与天气",reading:"The climate in my country is very interesting.\n\nIn spring it is warm, and it often rains. The trees turn green.\n\nIn summer it is hot. We sometimes go to the beach at the weekend.\n\nIn autumn it is cool. The wind always blows in the evening.\n\nIn winter it is cold and it often snows. The children play in the snow.\n\nWhich season do you like best?\n\nI like autumn best. The sky is blue and the air is fresh.",zh:"（原创改写）我们国家的气候很有意思。\n\n春天很暖和，而且常常下雨，树都变绿了。\n\n夏天很热。我们周末有时去海边。\n\n秋天很凉爽，傍晚总是刮风。\n\n冬天很冷，常常下雪，孩子们在雪地里玩。\n\n你最喜欢哪个季节？\n\n我最喜欢秋天。天空很蓝，空气很清新。",vocab:[{"w": "season", "ph": "/ˈsiːzn/", "en": "one of the four parts of the year: spring, summer, autumn, winter", "zh": "n. 季节", "eg": "Autumn is my favourite season."}, {"w": "spring", "ph": "/sprɪŋ/", "en": "the season after winter when plants grow", "zh": "n. 春天", "eg": "It often rains in spring here."}, {"w": "autumn", "ph": "/ˈɔːtəm/", "en": "the season between summer and winter", "zh": "n. 秋天", "eg": "The wind blows a lot in autumn."}, {"w": "snow", "ph": "/snəʊ/", "en": "soft white pieces of frozen water that fall from the sky", "zh": "n./v. 雪；下雪", "eg": "It often snows here in January."}],exprs:[{"en": "It often rains.", "zh": "常常下雨。", "scene": "描述一个地方常见的天气。频率副词放在动词前面。", "struct": "It + often/sometimes/always + rains/snows", "cat": "habit", "ex": ["It often rains in spring.", "It sometimes snows in December."]}, {"en": "go to the beach", "zh": "去海边", "scene": "夏天、假日的常见安排，go to the 后面直接接地点。", "struct": "go to the beach/park/zoo", "cat": "hobby", "ex": ["We sometimes go to the beach on Sunday.", "They go to the beach every summer."]}, {"en": "in the snow", "zh": "在雪地里", "scene": "下雪天玩乐的说法，注意介词用 in。", "struct": "play/walk + in the snow", "cat": "hobby", "ex": ["The children play in the snow.", "We walked in the snow for an hour."]}],pats:[{"en": "Which season do you like best?", "zh": "你最喜欢哪个季节？", "scene": "在四个季节里挑一个最喜欢的，best 是「最」的意思。", "struct": "Which + 名词 + do you like best?", "cat": "hobby", "ex": ["Which season do you like best?", "Which colour do you like best?"]}, {"en": "I like … best.", "zh": "我最喜欢……", "scene": "回答上面的提问，也可以用在颜色、食物、运动上。", "struct": "主语 + like(s) + 名词 + best", "cat": "opinion", "ex": ["I like autumn best.", "She likes summer best because she can swim."]}],quiz:{"v": {"q": "season 的意思是：", "opts": ["季节", "天气", "月份"], "a": 0}, "e": {"q": "想说「常常下雨」，应该说：", "opts": ["It often rain.", "It often rains.", "It is often rain."], "a": 1}, "p": {"q": "Which season do you like ______?", "opts": ["best", "better", "most good"], "a": 0}},speak:"说 3 句话：先用 It often/sometimes/always … 描述你家乡一个季节的天气，再用 Which season do you like best? 问一句，最后用 I like … best. 说出你的答案和理由。"},
{n:54,title:"Which Season Do You Like Best?",topic:"频率副词与季节喜好 · How often …? 频率问答",reading:"Tom, do you like summer?\n\nYes, I do. I always swim in the sea in summer.\n\nDoes your sister like summer too?\n\nNo, she doesn't. She never swims. She likes winter.\n\nWhy? Because she can skate. She often skates in the park.\n\nHow often do you go to the beach?\n\nWe go there every weekend in July.\n\nThat sounds fun! I usually stay at home and read.",zh:"（原创改写）汤姆，你喜欢夏天吗？\n\n喜欢。夏天我总在海里游泳。\n\n你妹妹也喜欢夏天吗？\n\n不，她不喜欢。她从不游泳，她喜欢冬天。\n\n为什么？因为她会滑冰。她常在公园里滑冰。\n\n你们多久去一次海边？\n\n七月的每个周末都去。\n\n听起来很有意思！我通常待在家里看书。",vocab:[{"w": "swim", "ph": "/swɪm/", "en": "to move through water using your arms and legs", "zh": "v. 游泳", "eg": "He swims in the river every summer."}, {"w": "skate", "ph": "/skeɪt/", "en": "to move on ice with special shoes", "zh": "v. 滑冰", "eg": "She skates with her friends on Sunday."}, {"w": "never", "ph": "/ˈnevə(r)/", "en": "not at any time", "zh": "adv. 从不；从来没有", "eg": "He never eats breakfast before seven."}, {"w": "weekend", "ph": "/ˌwiːkˈend/", "en": "Saturday and Sunday", "zh": "n. 周末", "eg": "We visit my grandparents every weekend."}],exprs:[{"en": "How often … ?", "zh": "多久一次……？", "scene": "专门问频率，回答用 always / often / sometimes / never 或 every day。", "struct": "How often + do/does + 主语 + 动词?", "cat": "habit", "ex": ["How often do you go to the beach?", "How often does she skate in the park?"]}, {"en": "That sounds fun!", "zh": "听起来很有意思！", "scene": "别人说完计划或爱好，用它捧个场，语气很自然。", "struct": "That sounds + 形容词!", "cat": "dailychat", "ex": ["We go to the beach every weekend. — That sounds fun!", "That sounds great! Can I come too?"]}, {"en": "stay at home", "zh": "待在家里", "scene": "说哪儿也不去，注意 home 前面不用 to。", "struct": "stay at home", "cat": "habit", "ex": ["I usually stay at home on rainy days.", "She stayed at home yesterday."]}],pats:[{"en": "主语 + usually/often/sometimes + 动词原形", "zh": "某人通常／常常／有时做……", "scene": "频率副词放在实义动词前面、be 动词后面，这是最容易记错的地方。", "struct": "主语 + always/usually/often/sometimes/never + 动词", "cat": "habit", "ex": ["I never swim in winter.", "He often skates in the park."]}, {"en": "every + 时间名词", "zh": "每……", "scene": "回答 How often 时用，比 often 更精确。", "struct": "every + day/week/weekend/morning/Sunday", "cat": "habit", "ex": ["We go there every weekend.", "She reads English every morning."]}],quiz:{"v": {"q": "never 的意思是：", "opts": ["从不", "经常", "有时"], "a": 0}, "e": {"q": "想问对方「多久去一次海边」，应该说：", "opts": ["How long do you go to the beach?", "How often do you go to the beach?", "How much do you go to the beach?"], "a": 1}, "p": {"q": "She ______ skates in the park in winter.", "opts": ["often", "is often", "does often"], "a": 0}},speak:"说 3 句话：用 How often do you …? 问对方做某事的频率，用 always/usually/often/sometimes/never 回答，最后用 That sounds fun! 对对方的安排回应一句。"},
{n:55,title:"The Sawyer Family",topic:"日常作息 · 一般现在时第三人称单数（-s/-es）",reading:"The Parker family lives on King Street.\n\nMr. Parker goes to work at seven every morning. He takes the bus.\n\nMrs. Parker stays at home. She does the housework and cooks lunch.\n\nTheir children, Ben and Sue, go to school at eight.\n\nThey come home at four in the afternoon and always do their homework first.\n\nIn the evening Mr. Parker reads the newspaper and Mrs. Parker watches TV.\n\nThe family goes to bed at ten. They are very happy together.",zh:"（原创改写）帕克一家住在国王街。\n\n帕克先生每天早上七点去上班，他坐公共汽车。\n\n帕克太太待在家里，做家务、做午饭。\n\n他们的孩子本和苏八点去上学。\n\n他们下午四点回家，总是先写作业。\n\n晚上帕克先生看报纸，帕克太太看电视。\n\n全家十点睡觉。他们在一起很开心。",vocab:[{"w": "housework", "ph": "/ˈhaʊswɜːk/", "en": "the work you do to keep your home clean", "zh": "n. 家务", "eg": "My mother does the housework every morning."}, {"w": "homework", "ph": "/ˈhəʊmwɜːk/", "en": "the work a teacher gives students to do at home", "zh": "n. 家庭作业", "eg": "I do my homework after dinner."}, {"w": "newspaper", "ph": "/ˈnjuːzpeɪpə(r)/", "en": "printed paper with news, sold every day", "zh": "n. 报纸", "eg": "My father reads the newspaper after dinner."}, {"w": "cook", "ph": "/kʊk/", "en": "to make food ready to eat", "zh": "v. 做饭；烹饪", "eg": "She cooks lunch for the family every day."}],exprs:[{"en": "go to work", "zh": "去上班", "scene": "说日常通勤。注意是 go to work，中间不加 the。", "struct": "go to work / go to school / go to bed", "cat": "habit", "ex": ["He goes to work at seven.", "My mother goes to work by bus."]}, {"en": "do the housework", "zh": "做家务", "scene": "打扫、洗衣、整理这些活儿的总称，固定搭配带 the。", "struct": "do the housework / do the cooking / do the shopping", "cat": "habit", "ex": ["She does the housework every morning.", "We all do the housework at the weekend."]}, {"en": "go to bed", "zh": "上床睡觉", "scene": "强调「上床」这个动作，不是「睡着了」；注意没有 the。", "struct": "go to bed + at + 钟点", "cat": "habit", "ex": ["I go to bed at ten every night.", "The children go to bed early."]}],pats:[{"en": "主语(三单) + 动词 -s/-es + at + 钟点", "zh": "某人几点做……（日常作息）", "scene": "介绍一家人每天的固定安排，动词要加 -s，时间前面用 at。", "struct": "主语 + 动词 -s/-es + at + 数字 (o'clock)", "cat": "habit", "ex": ["Mr. Parker goes to work at seven.", "Ben goes to school at eight."]}, {"en": "at + 钟点 / in the + 上午下午晚上", "zh": "在几点／在上午（下午、晚上）", "scene": "时间介词：钟点用 at，一天的某段时间用 in the，具体某天用 on。", "struct": "at seven / in the morning / in the afternoon / in the evening", "cat": "habit", "ex": ["They come home at four in the afternoon.", "He reads the newspaper in the evening."]}],quiz:{"v": {"q": "housework 的意思是：", "opts": ["家务", "作业", "上班"], "a": 0}, "e": {"q": "想说「去上班」，正确的说法是：", "opts": ["go to the work", "go to work", "go to a work"], "a": 1}, "p": {"q": "Mrs. Parker ______ the housework every morning.", "opts": ["do", "does", "doing"], "a": 1}},speak:"说 3 句话：用 主语(三单) + 动词 -s + at + 钟点 介绍一位家人一天的作息，至少说出上班（或上学）、回家、睡觉三件事中的两个。"},
{n:56,title:"What Do They Usually Do?",topic:"频率副词 always/usually/often/sometimes/never 与日常活动",reading:"What do you usually do on Sunday, Ben?\n\nI usually get up late. My mother sometimes makes pancakes for breakfast.\n\nAfter breakfast I often play football with my friends.\n\nDoes your father play too?\n\nNo, he never plays football. He always washes the car on Sunday.\n\nAnd your sister? She sometimes reads in her room.\n\nIn the evening we always visit my grandparents.\n\nYou have a busy Sunday!",zh:"（原创改写）本，你周日通常做什么？\n\n我通常起得很晚。我妈妈有时做薄饼当早饭。\n\n早饭后我常和朋友踢足球。\n\n你爸爸也踢吗？\n\n不，他从不踢足球。周日他总是洗车。\n\n你妹妹呢？她有时在房间里看书。\n\n晚上我们总是去看祖父母。\n\n你们的周日真忙啊！",vocab:[{"w": "usually", "ph": "/ˈjuːʒuəli/", "en": "most of the time", "zh": "adv. 通常", "eg": "I usually get up at seven on school days."}, {"w": "pancake", "ph": "/ˈpænkeɪk/", "en": "a thin round cake cooked in a pan", "zh": "n. 薄饼", "eg": "We had pancakes for breakfast."}, {"w": "wash", "ph": "/wɒʃ/", "en": "to clean something with water", "zh": "v. 洗", "eg": "He washes his car every Sunday."}, {"w": "visit", "ph": "/ˈvɪzɪt/", "en": "to go to see a person or a place", "zh": "v. 拜访；看望", "eg": "We visit my grandparents on Sunday."}],exprs:[{"en": "get up late", "zh": "起得晚", "scene": "周末最常见的一件事，反义是 get up early。", "struct": "get up late/early", "cat": "habit", "ex": ["I usually get up late on Sunday.", "He never gets up late on Monday."]}, {"en": "play football", "zh": "踢足球", "scene": "球类运动前面不加 the，这是固定规矩。", "struct": "play + football/basketball/tennis", "cat": "hobby", "ex": ["I often play football after school.", "They play football in the park."]}, {"en": "visit my grandparents", "zh": "看望祖父母", "scene": "说周末的家庭安排，visit 后面直接跟人。", "struct": "visit + 人/地方", "cat": "relationship", "ex": ["We always visit my grandparents on Sunday.", "She visits her aunt every month."]}],pats:[{"en": "What do you usually do on …?", "zh": "你（在……）通常做什么？", "scene": "问对方某一天、某个时候的固定活动，聊日常最常用的一句。", "struct": "What + do/does + 主语 + usually do + 时间?", "cat": "habit", "ex": ["What do you usually do on Sunday?", "What does your father usually do in the evening?"]}, {"en": "主语 + usually/often/sometimes + 动词原形", "zh": "某人通常／常常／有时做……", "scene": "频率副词放实义动词前；主语若是三单，动词本身也要加 -s。", "struct": "主语 + 频率副词 + 动词", "cat": "habit", "ex": ["My mother sometimes makes pancakes.", "He always washes the car on Sunday."]}],quiz:{"v": {"q": "usually 的意思是：", "opts": ["通常", "偶尔", "从不"], "a": 0}, "e": {"q": "想说「踢足球」，正确的说法是：", "opts": ["play the football", "play football", "play a football"], "a": 1}, "p": {"q": "What ______ your sister usually do on Sunday?", "opts": ["do", "does", "is"], "a": 1}},speak:"说 4 句话：用 What do you usually do on Sunday? 提问并自答，回答里至少用上 usually、often、sometimes 三个频率副词中的两个，讲讲你和一位家人的周日安排。"},
{n:57,title:"An Unusual Day",topic:"现在进行时 vs 一般现在时 · usually …, but today …",reading:"Mr. Parker usually goes to work by bus. He usually leaves home at seven.\n\nBut today is different. It is eight o'clock now, and he is still at home.\n\nHe is having breakfast. He is reading a book, too.\n\nThe children usually go to school at eight, but today they are playing in the garden.\n\nMrs. Parker usually goes to the shops in the morning. Today she is sitting in the garden.\n\nIt is a holiday! Nobody is working today.",zh:"（原创改写）帕克先生通常坐公共汽车上班，通常七点出门。\n\n但今天不一样。现在八点了，他还在家。\n\n他正在吃早饭，还在看一本书。\n\n孩子们通常八点去上学，但今天他们正在花园里玩。\n\n帕克太太通常上午去商店，今天她正坐在花园里。\n\n今天是假日！没有人上班。",vocab:[{"w": "unusual", "ph": "/ʌnˈjuːʒuəl/", "en": "different from what is normal", "zh": "adj. 不寻常的；特别的", "eg": "It is an unusual day for our family."}, {"w": "still", "ph": "/stɪl/", "en": "up to this time; even now", "zh": "adv. 仍然；还", "eg": "It is ten o'clock and he is still in bed."}, {"w": "garden", "ph": "/ˈɡɑːdn/", "en": "a piece of land next to a house with flowers or grass", "zh": "n. 花园", "eg": "The children are playing in the garden."}, {"w": "holiday", "ph": "/ˈhɒlədeɪ/", "en": "a day when you do not work or go to school", "zh": "n. 假日；假期", "eg": "We are going to the sea for our holiday."}],exprs:[{"en": "by bus", "zh": "乘公共汽车", "scene": "说交通方式，by 后面直接加交通工具，不加冠词。", "struct": "by + bus/train/car/bike/plane", "cat": "dailychat", "ex": ["He goes to work by bus.", "We go to Beijing by train."]}, {"en": "It is … o'clock.", "zh": "现在……点了。", "scene": "报整点时间，只在整点后面加 o'clock，几点半不能加。", "struct": "It is + 数字 + o'clock.", "cat": "dailychat", "ex": ["It is eight o'clock now.", "It is twelve o'clock. Time for lunch!"]}, {"en": "be different", "zh": "不一样", "scene": "把今天和往常对比，后面常跟 from。", "struct": "A + be + different (from B)", "cat": "dailychat", "ex": ["But today is different.", "My new school is different from the old one."]}],pats:[{"en": "主语 + usually …, but today + am/is/are + 动词 -ing", "zh": "某人通常……，但今天正在……", "scene": "一般现在时讲习惯，现在进行时讲此刻正在发生，用 but today 一对比就很清楚。", "struct": "主语 + usually + 动词(-s) …, but today + 主语 + am/is/are + 动词 -ing", "cat": "habit", "ex": ["He usually goes to work at seven, but today he is still at home.", "They usually go to school, but today they are playing in the garden."]}, {"en": "What is he/she doing now?", "zh": "他／她现在正在做什么？", "scene": "问此刻的动作，回答必须用 be + 动词 -ing。", "struct": "What + am/is/are + 主语 + doing (now)?", "cat": "dailychat", "ex": ["What is he doing now? — He is having breakfast.", "What are the children doing? — They are playing."]}],quiz:{"v": {"q": "unusual 的意思是：", "opts": ["不寻常的", "平常的", "无聊的"], "a": 0}, "e": {"q": "想说「乘公共汽车」，正确的说法是：", "opts": ["by a bus", "by the bus", "by bus"], "a": 2}, "p": {"q": "He usually walks to school, but today he ______ the bus.", "opts": ["takes", "is taking", "take"], "a": 1}},speak:"说 3 句话：用 主语 + usually …, but today + be + 动词 -ing 描述你和两位家人今天和平常不一样的地方，至少用上一个 o'clock 报时。"},
{n:58,title:"What's the Time?",topic:"时间表达 o'clock · 现在进行时与一般现在时对比",reading:"What's the time, please?\n\nIt's nine o'clock. Why do you ask?\n\nI usually go to bed at ten, but today I am very busy.\n\nWhat are you doing?\n\nI am writing an email to my teacher. She usually answers quickly.\n\nMy brother is watching TV. He usually does his homework at nine, but today he doesn't have any.\n\nAnd your sister? She is sleeping. She always sleeps at nine.",zh:"（原创改写）请问几点了？\n\n九点了。你问这个做什么？\n\n我通常十点睡觉，但今天我很忙。\n\n你在做什么？\n\n我正在给老师写邮件，她一般回得很快。\n\n我弟弟正在看电视。他通常九点写作业，但今天没有作业。\n\n你妹妹呢？她在睡觉。她总是九点就睡。",vocab:[{"w": "o'clock", "ph": "/əˈklɒk/", "en": "used to say the time exactly on the hour", "zh": "adv. ……点钟", "eg": "It's seven o'clock. Time to get up."}, {"w": "busy", "ph": "/ˈbɪzi/", "en": "having a lot of things to do", "zh": "adj. 忙碌的", "eg": "My father is busy every Monday."}, {"w": "answer", "ph": "/ˈɑːnsə(r)/", "en": "to say or write something back to someone", "zh": "v. 回答；回复", "eg": "Please answer my question in English."}, {"w": "sleep", "ph": "/sliːp/", "en": "to rest with your eyes closed", "zh": "v. 睡觉", "eg": "The baby sleeps for ten hours every night."}],exprs:[{"en": "What's the time?", "zh": "几点了？", "scene": "问时间最口语的一句，也可以说 What time is it?", "struct": "What's the time? / What time is it?", "cat": "dailychat", "ex": ["What's the time, please? — It's nine o'clock.", "What time is it now? We are late!"]}, {"en": "be busy", "zh": "很忙", "scene": "解释为什么没空，后面可接 with 或 doing。", "struct": "主语 + be + busy (with something / doing something)", "cat": "work", "ex": ["I am very busy today.", "She is busy with her homework."]}, {"en": "write an email to …", "zh": "给……写邮件", "scene": "说联系方式，注意「给某人」用 to。", "struct": "write an email/a letter + to + 人", "cat": "work", "ex": ["I am writing an email to my teacher.", "He writes an email to his friend every week."]}],pats:[{"en": "It's + 数字 + o'clock.", "zh": "现在……点了。", "scene": "整点报时。记住非整点（如 9:30）不能加 o'clock。", "struct": "It is / It's + 数字 + o'clock.", "cat": "dailychat", "ex": ["It's nine o'clock.", "It's twelve o'clock. Let's have lunch."]}, {"en": "主语 + usually + 动词 …, but today + be + 动词 -ing", "zh": "某人通常……，但今天正在……", "scene": "习惯用一般现在时，此刻正在做的事用现在进行时，两者放一起对比最有感觉。", "struct": "主语 + usually + 动词 …, but today + 主语 + be + 动词 -ing", "cat": "habit", "ex": ["He usually does his homework at nine, but today he is watching TV.", "I usually go to bed at ten, but today I am writing an email."]}],quiz:{"v": {"q": "busy 的意思是：", "opts": ["忙碌的", "空闲的", "困的"], "a": 0}, "e": {"q": "想问现在几点，应该说：", "opts": ["What's the time?", "What's the day?", "What's the date?"], "a": 0}, "p": {"q": "My sister ______ now. She always sleeps at nine.", "opts": ["sleeps", "is sleeping", "sleep"], "a": 1}},speak:"说 3 句话：先用 What's the time? 问时间并用 It's … o'clock. 回答，再用 be busy 解释你现在很忙，最后用现在进行时说出你此刻正在做的事。"},
{n:59,title:"Is That All?",topic:"have got / have · 购物与数量",reading:"Good morning. What can I do for you?\n\nI want a few things for lunch. Have you got any bread?\n\nYes, we have. How much do you want? One loaf, please.\n\nHave you got any cheese?\n\nYes, we've got some nice cheese. Do you want any eggs?\n\nNo, thank you. We've got a lot of eggs at home.\n\nAnything else? Some tomatoes, please.\n\nHere you are. Is that all?\n\nYes, that's all. How much is it? Five pounds, please.",zh:"（原创改写）早上好，需要点什么？\n\n我想买点午饭用的东西。你们有面包吗？\n\n有。您要多少？请给我一条。\n\n有奶酪吗？\n\n有，我们有些很不错的奶酪。您要鸡蛋吗？\n\n不用了，谢谢。我们家里有很多鸡蛋。\n\n还要别的吗？请再来些西红柿。\n\n给您。就这些吗？\n\n是的，就这些。多少钱？五英镑。",vocab:[{"w": "bread", "ph": "/bred/", "en": "a common food made from flour and water", "zh": "n. 面包", "eg": "We eat bread and milk for breakfast."}, {"w": "cheese", "ph": "/tʃiːz/", "en": "a yellow or white food made from milk", "zh": "n. 奶酪", "eg": "She puts cheese in her sandwich."}, {"w": "loaf", "ph": "/ləʊf/", "en": "one whole piece of bread", "zh": "n. 一条（面包）", "eg": "He bought two loaves of bread."}, {"w": "pound", "ph": "/paʊnd/", "en": "the money used in Britain", "zh": "n. 英镑", "eg": "This book costs ten pounds."}],exprs:[{"en": "Have you got any …?", "zh": "你们有……吗？", "scene": "买东西时问有没有货。英式英语爱用 have got，美式常说 Do you have …?", "struct": "Have you got any + 名词?", "cat": "dailychat", "ex": ["Have you got any bread?", "Have you got any cheese?"]}, {"en": "a lot of", "zh": "许多；很多", "scene": "可数不可数都能用，比 many / much 更口语。", "struct": "a lot of + 名词", "cat": "dailychat", "ex": ["We've got a lot of eggs at home.", "There are a lot of people in the shop."]}, {"en": "Anything else?", "zh": "还要别的吗？", "scene": "店员收尾时的常用问句，回答可以说 No, that's all.", "struct": "Anything else? — No, that's all.", "cat": "dailychat", "ex": ["Anything else? — Some tomatoes, please.", "Anything else? No? That's eight pounds."]}],pats:[{"en": "Have you got any …? — Yes, we have. / No, we haven't.", "zh": "你们有……吗？——有。／没有。", "scene": "have got 的一般疑问句。回答用 have / haven't，不用 do。", "struct": "Have + 主语 + got + 名词?", "cat": "dailychat", "ex": ["Have you got any bread? — Yes, we have.", "Have they got any milk? — No, they haven't."]}, {"en": "I've got … / I haven't got …", "zh": "我有……／我没有……", "scene": "说自己手上有什么、没什么，英式口语里比 I have / I don't have 更常用。", "struct": "主语 + have/has got + 名词 / 主语 + haven't/hasn't got + 名词", "cat": "dailychat", "ex": ["We've got a lot of eggs at home.", "She hasn't got any money with her."]}],quiz:{"v": {"q": "loaf 的意思是：", "opts": ["一条（面包）", "一片（面包）", "一袋（面包）"], "a": 0}, "e": {"q": "想说「我们家里有很多鸡蛋」，应该说：", "opts": ["We've got a lot of eggs at home.", "We've got a lot eggs at home.", "We have got lot of eggs at home."], "a": 0}, "p": {"q": "______ you got any cheese?", "opts": ["Have", "Do", "Are"], "a": 0}},speak:"说 4 句话：扮演顾客，用 Have you got any …? 问两样东西，用 I've got … / I haven't got … 说明家里有什么没什么，最后用 Is that all? 或 That's all. 收尾。"},
{n:60,title:"Have You Got Any…?",topic:"have got 的肯定、否定与疑问",reading:"Let's make a cake. What have we got?\n\nWe've got some flour and some sugar.\n\nHas Mum got any butter? Yes, she has. But she hasn't got any milk.\n\nHave you got any eggs? Yes, I've got six eggs.\n\nHave we got any apples?\n\nNo, we haven't got any apples, but we've got some bananas.\n\nGreat. Banana cake is my favourite. Let's start!\n\nWait. Have we got an oven? Of course we have!",zh:"（原创改写）我们做蛋糕吧。我们都有什么？\n\n我们有面粉和糖。\n\n妈妈有黄油吗？有，有黄油。但她没有牛奶了。\n\n你有鸡蛋吗？有，我有六个鸡蛋。\n\n我们有苹果吗？\n\n没有，我们没有苹果，但我们有一些香蕉。\n\n太好了。香蕉蛋糕是我的最爱。开始吧！\n\n等等，我们有烤箱吗？当然有啦！",vocab:[{"w": "flour", "ph": "/ˈflaʊə(r)/", "en": "a white powder used to make bread and cakes", "zh": "n. 面粉", "eg": "We need flour and eggs for the cake."}, {"w": "sugar", "ph": "/ˈʃʊɡə(r)/", "en": "a sweet white or brown food", "zh": "n. 糖", "eg": "He puts two spoons of sugar in his coffee."}, {"w": "butter", "ph": "/ˈbʌtə(r)/", "en": "a soft yellow food made from milk", "zh": "n. 黄油", "eg": "She puts butter on her bread."}, {"w": "banana", "ph": "/bəˈnɑːnə/", "en": "a long yellow fruit", "zh": "n. 香蕉", "eg": "I eat a banana every afternoon."}],exprs:[{"en": "Let's …", "zh": "我们……吧", "scene": "提建议最顺口的一句，后面直接跟动词原形。", "struct": "Let's + 动词原形", "cat": "dailychat", "ex": ["Let's make a cake.", "Let's go to the park this afternoon."]}, {"en": "… is my favourite", "zh": "……是我的最爱", "scene": "表达偏好，比 I like … best 更口语一点。", "struct": "名词 + be + my favourite", "cat": "opinion", "ex": ["Banana cake is my favourite.", "Football is my favourite sport."]}, {"en": "Of course …", "zh": "当然……", "scene": "觉得对方问得多余，用轻松的语气肯定。", "struct": "Of course + 主语 + 助动词", "cat": "humor", "ex": ["Have we got an oven? — Of course we have!", "Can you swim? — Of course I can."]}],pats:[{"en": "Have you got any …? — Yes, I have. / No, I haven't.", "zh": "你有……吗？——有。／没有。", "scene": "have got 的疑问句。疑问和否定里通常用 any，肯定句里用 some。", "struct": "Have/Has + 主语 + got + any + 名词?", "cat": "dailychat", "ex": ["Have you got any eggs? — Yes, I've got six.", "Has she got any milk? — No, she hasn't."]}, {"en": "… have got … / … haven't got …", "zh": "有……／没有……", "scene": "三单要用 has got / hasn't got，其余人称用 have got / haven't got。", "struct": "主语 + have/has got + 名词；主语 + haven't/hasn't got + any + 名词", "cat": "dailychat", "ex": ["She hasn't got any milk.", "We've got some bananas."]}],quiz:{"v": {"q": "butter 的意思是：", "opts": ["黄油", "面粉", "糖"], "a": 0}, "e": {"q": "想提议「我们做蛋糕吧」，应该说：", "opts": ["Let's make a cake.", "We make a cake.", "Let's making a cake."], "a": 0}, "p": {"q": "She ______ got any milk.", "opts": ["hasn't", "haven't", "doesn't have got"], "a": 0}},speak:"说 4 句话：用 Let's … 邀请朋友一起做某件事，用 Have you got any …? 问两样材料，再用 We've got … / We haven't got … 说出有什么没什么，最后用 … is my favourite. 收尾。"},
{n:61,title:"A Bad Cold",topic:"must / mustn't · What's the matter? 看病用语",reading:"Good morning, doctor.\n\nGood morning, Ben. What's the matter with you?\n\nI feel very ill. I have a bad cold and a headache.\n\nLet me take your temperature. Yes, you have a fever.\n\nMust I stay in bed?\n\nYes, you must. You must stay in bed for two days.\n\nMust I take this medicine?\n\nYes, three times a day. And you mustn't go to school this week.\n\nThank you, doctor.\n\nDon't worry. You will be better soon.",zh:"（原创改写）早上好，医生。\n\n早上好，本。你怎么了？\n\n我很难受。我得了重感冒，还头疼。\n\n我量一下你的体温。嗯，你在发烧。\n\n我必须卧床吗？\n\n是的，必须。你得卧床休息两天。\n\n我得吃这个药吗？\n\n要，一天三次。这周你不可以去上学。\n\n谢谢您，医生。\n\n别担心，你很快就会好起来的。",vocab:[{"w": "cold", "ph": "/kəʊld/", "en": "a common illness that makes you sneeze and cough", "zh": "n. 感冒；伤风", "eg": "She has a bad cold and stays at home."}, {"w": "headache", "ph": "/ˈhedeɪk/", "en": "a pain in your head", "zh": "n. 头痛", "eg": "I have a headache after a long day."}, {"w": "temperature", "ph": "/ˈtemprətʃə(r)/", "en": "how hot or cold your body is", "zh": "n. 体温；温度", "eg": "The nurse took my temperature this morning."}, {"w": "medicine", "ph": "/ˈmedsn/", "en": "something you take when you are ill", "zh": "n. 药", "eg": "Take this medicine three times a day."}],exprs:[{"en": "What's the matter (with you)?", "zh": "（你）怎么了？", "scene": "看到对方脸色不好、不舒服时第一句关心的话。", "struct": "What's the matter (with + 人)?", "cat": "dailychat", "ex": ["What's the matter with you? You look ill.", "What's the matter? Why are you crying?"]}, {"en": "have a cold", "zh": "感冒", "scene": "说自己生病了。注意英文用 have，不用「得」。", "struct": "have a cold / have a fever / have a headache", "cat": "dailychat", "ex": ["I have a bad cold.", "He has a cold and can't come to school."]}, {"en": "take medicine", "zh": "吃药", "scene": "医嘱里最常见的搭配，动词用 take 不用 eat。", "struct": "take + medicine/the medicine + 频率", "cat": "dailychat", "ex": ["Take this medicine three times a day.", "Did you take your medicine this morning?"]}],pats:[{"en": "Must I …? — Yes, you must. / No, you needn't.", "zh": "我必须……吗？——是的，必须。／不，不必。", "scene": "问自己有没有必要做某件事。否定回答不用 mustn't，而用 needn't。", "struct": "Must + 主语 + 动词原形?", "cat": "dailychat", "ex": ["Must I stay in bed? — Yes, you must.", "Must I come tomorrow? — No, you needn't."]}, {"en": "You must / mustn't + 动词原形", "zh": "你必须／不可以……", "scene": "医生、家长、老师给出强硬要求。mustn't 是「禁止」，不是「不必」。", "struct": "主语 + must/mustn't + 动词原形", "cat": "dailychat", "ex": ["You must stay in bed for two days.", "You mustn't go to school this week."]}],quiz:{"v": {"q": "headache 的意思是：", "opts": ["头痛", "感冒", "发烧"], "a": 0}, "e": {"q": "看到朋友脸色不好，关心地问一句，最自然的是：", "opts": ["What's the matter with you?", "What do you do?", "How old are you?"], "a": 0}, "p": {"q": "Must I stay in bed? — Yes, you ______.", "opts": ["must", "needn't", "mustn't"], "a": 0}},speak:"说 4 句话：先用 What's the matter with you? 问对方哪里不舒服，再用 have a cold / have a headache 描述症状，然后用 Must I …? 问一句医嘱，最后用 You must / mustn't … 给出建议。"},
{n:62,title:"What Must They Do?",topic:"must / mustn't · 医嘱与建议",reading:"Look at these people. What must they do?\n\nTom has a cold. He must stay at home and drink a lot of water.\n\nSue has a toothache. She must see the dentist this afternoon.\n\nMr. Hill is very tired. He mustn't drive at night.\n\nThe children are in the library. They mustn't make a noise.\n\nAnd you, Ben? What must you do?\n\nI must finish my homework before dinner. Then I can play outside.\n\nGood. We must all do our best.",zh:"（原创改写）看看这些人，他们必须做什么？\n\n汤姆感冒了，他必须待在家里多喝水。\n\n苏牙疼，她今天下午必须去看牙医。\n\n希尔先生很累，他晚上不可以开车。\n\n孩子们在图书馆里，他们不可以出声。\n\n本，你呢？你必须做什么？\n\n我必须在晚饭前写完作业，然后才能出去玩。\n\n很好，我们都得尽力。",vocab:[{"w": "toothache", "ph": "/ˈtuːθeɪk/", "en": "a pain in your tooth", "zh": "n. 牙痛", "eg": "He has a toothache and can't eat."}, {"w": "dentist", "ph": "/ˈdentɪst/", "en": "a doctor who looks after your teeth", "zh": "n. 牙医", "eg": "She goes to the dentist twice a year."}, {"w": "tired", "ph": "/ˈtaɪəd/", "en": "needing to rest or sleep", "zh": "adj. 疲倦的；累的", "eg": "I am very tired after the long walk."}, {"w": "noise", "ph": "/nɔɪz/", "en": "a loud or unpleasant sound", "zh": "n. 噪音；响声", "eg": "Don't make a noise in the library."}],exprs:[{"en": "have a toothache", "zh": "牙疼", "scene": "和 have a cold / have a headache 一个套路，都是 have a + 病名。", "struct": "have a + toothache/cold/headache/fever", "cat": "dailychat", "ex": ["She has a toothache.", "My brother had a toothache yesterday."]}, {"en": "make a noise", "zh": "发出响声；吵闹", "scene": "提醒别人安静，图书馆、电影院、会议室里都用得上。", "struct": "make a noise / make noises", "cat": "dailychat", "ex": ["They mustn't make a noise in the library.", "Please don't make a noise when the baby sleeps."]}, {"en": "do one's best", "zh": "尽最大努力", "scene": "给自己或给别人打气，语气积极。", "struct": "do + my/your/his/her/our/their + best", "cat": "work", "ex": ["We must all do our best.", "She always does her best at school."]}],pats:[{"en": "主语 + must + 动词原形", "zh": "某人必须……", "scene": "强调「非做不可」。must 后面永远跟动词原形，不加 to。", "struct": "主语 + must + 动词原形", "cat": "dailychat", "ex": ["He must stay at home.", "She must see the dentist this afternoon."]}, {"en": "主语 + mustn't + 动词原形", "zh": "某人不准／千万不要……", "scene": "表示禁止，语气很重。注意它跟 needn't（不必）完全不是一回事。", "struct": "主语 + mustn't + 动词原形", "cat": "dailychat", "ex": ["He mustn't drive at night.", "They mustn't make a noise in the library."]}],quiz:{"v": {"q": "dentist 的意思是：", "opts": ["牙医", "医生", "护士"], "a": 0}, "e": {"q": "想提醒别人「别吵」，应该说：", "opts": ["Don't make a noise.", "Don't do a noise.", "Don't take a noise."], "a": 0}, "p": {"q": "You mustn't ______ here. The children are sleeping.", "opts": ["to run", "run", "running"], "a": 1}},speak:"说 3 句话：用 have a … 说出两个人各自的问题，再用 must 和 mustn't 分别给他们一句建议。"},
{n:63,title:"Thank You, Doctor",topic:"Don't… 禁令与医嘱 · needn't 与 can",reading:"How are you today, Mrs. White?\n\nMuch better, thank you, doctor. But I still feel weak.\n\nDon't work too hard this week. Don't go out in the cold.\n\nMust I stay in bed all day?\n\nNo, you needn't. But you mustn't eat cold food.\n\nCan I drink tea?\n\nYes, you can. Drink a lot of warm water, too.\n\nAnd don't forget your medicine.\n\nThank you very much, doctor.\n\nDon't mention it. Take care!",zh:"（原创改写）怀特太太，今天感觉怎么样？\n\n好多了，谢谢您，医生。不过我还是觉得没力气。\n\n这周别太拼命工作，也别冷天往外跑。\n\n我必须整天躺在床上吗？\n\n不，不用。但是您不能吃凉的东西。\n\n我能喝茶吗？\n\n可以。再多喝些温水。\n\n还有，别忘了吃药。\n\n非常感谢您，医生。\n\n不客气，多保重！",vocab:[{"w": "weak", "ph": "/wiːk/", "en": "not strong; without much energy", "zh": "adj. 虚弱的；无力的", "eg": "He was weak after a week in bed."}, {"w": "better", "ph": "/ˈbetə(r)/", "en": "more well; not as ill as before", "zh": "adj. 更好的；好转的", "eg": "I feel much better today, thank you."}, {"w": "hard", "ph": "/hɑːd/", "en": "with a lot of effort", "zh": "adv. 努力地；猛烈地", "eg": "She works hard every day at the shop."}, {"w": "warm", "ph": "/wɔːm/", "en": "a little hot, in a nice way", "zh": "adj. 温暖的", "eg": "Drink a lot of warm water when you are ill."}],exprs:[{"en": "Take care!", "zh": "多保重！", "scene": "分别时对病人、朋友说的暖心话，等于 Take care of yourself。", "struct": "Take care! / Take care of + 人", "cat": "dailychat", "ex": ["Take care! See you next week.", "Please take care of your little sister."]}, {"en": "much better", "zh": "好多了", "scene": "回答 How are you? 时的常见说法，much 让 better 程度更深。", "struct": "much + 比较级", "cat": "dailychat", "ex": ["I feel much better today.", "He is much taller than last year."]}, {"en": "Don't mention it.", "zh": "不客气；别客气", "scene": "对方郑重道谢时的回应，比 You're welcome 更客气一点。", "struct": "Don't mention it.（单独成句）", "cat": "dailychat", "ex": ["Thank you so much! — Don't mention it.", "Thanks for your help. — Don't mention it."]}],pats:[{"en": "Don't + 动词原形", "zh": "别……；不要……", "scene": "直接叫对方别做某事，祈使句的否定式。后面永远跟动词原形。", "struct": "Don't + 动词原形 (+ 其他)", "cat": "dailychat", "ex": ["Don't work too hard this week.", "Don't go out in the cold."]}, {"en": "主语 + needn't + 动词原形", "zh": "某人不必……", "scene": "表示「没这个必要」，语气温和。它是 must 的否定回答，不是禁止。", "struct": "主语 + needn't + 动词原形", "cat": "dailychat", "ex": ["Must I stay in bed all day? — No, you needn't.", "You needn't come early tomorrow."]}],quiz:{"v": {"q": "weak 的意思是：", "opts": ["虚弱的", "暖和的", "努力的"], "a": 0}, "e": {"q": "医生叮嘱「别工作太累」，应该说：", "opts": ["Don't work too hard.", "You needn't work hard.", "You mustn't to work hard."], "a": 0}, "p": {"q": "Must I stay in bed all day? — No, you ______.", "opts": ["mustn't", "needn't", "don't"], "a": 1}},speak:"说 3 句话：用 Don't … 给病人两句叮嘱，再用 Must I …? — No, you needn't. 回应一个担心，最后用 Take care! 收尾。"},
{n:64,title:"Don't…! You Mustn't…!",topic:"禁令 Don't… 与 You mustn't… 的互换",reading:"Come on, children! Listen to me.\n\nDon't run in the classroom. You mustn't run here.\n\nDon't draw on the wall. You mustn't do that.\n\nDon't be late for school. You must be here at eight.\n\nDon't forget your homework. You must bring it every day.\n\nAnd don't make a noise when I am talking.\n\nSorry, Miss Lee. We will be good.\n\nGood. Now open your books, please.",zh:"（原创改写）快点，孩子们！听我说。\n\n别在教室里跑，你们不能在这儿跑。\n\n别在墙上画，你们不能这么做。\n\n上学别迟到，你们必须八点到校。\n\n别忘了带作业，你们每天都得带来。\n\n还有，我讲话的时候别出声。\n\n对不起，李老师，我们会乖的。\n\n很好。现在请打开课本。",vocab:[{"w": "run", "ph": "/rʌn/", "en": "to move very fast on your legs", "zh": "v. 跑；奔跑", "eg": "Don't run in the classroom, please."}, {"w": "draw", "ph": "/drɔː/", "en": "to make a picture with a pen or pencil", "zh": "v. 画", "eg": "She draws a cat on the paper."}, {"w": "forget", "ph": "/fəˈɡet/", "en": "to not remember something", "zh": "v. 忘记", "eg": "Don't forget your homework."}, {"w": "bring", "ph": "/brɪŋ/", "en": "to take something with you to a place", "zh": "v. 带来", "eg": "Bring your book to school tomorrow."}],exprs:[{"en": "Come on!", "zh": "快点！／加油！", "scene": "催人动作快点，或者给人打气，语气很活。", "struct": "Come on! / Come on, + 称呼", "cat": "dailychat", "ex": ["Come on! We are late for school.", "Come on, Ben, you can do it!"]}, {"en": "be late for …", "zh": "……迟到", "scene": "上学、上班、开会迟到都能用，后面接名词。", "struct": "be late for + 名词", "cat": "dailychat", "ex": ["Don't be late for school.", "He was late for the meeting this morning."]}, {"en": "Don't forget …", "zh": "别忘了……", "scene": "出门前、分手前的提醒，后面接名词或 to do。", "struct": "Don't forget + 名词 / to + 动词原形", "cat": "dailychat", "ex": ["Don't forget your homework.", "Don't forget to call me tonight."]}],pats:[{"en": "Don't + 动词原形", "zh": "别做……", "scene": "祈使句否定，现场叫停一个动作，最直接的禁令。", "struct": "Don't + 动词原形", "cat": "dailychat", "ex": ["Don't run in the classroom.", "Don't draw on the wall."]}, {"en": "You mustn't + 动词原形 / You must + 动词原形", "zh": "你不许／你必须……", "scene": "把禁令说成规矩。Don't 和 You mustn't 意思一样，后者更强调「规定」。", "struct": "主语 + mustn't/must + 动词原形", "cat": "dailychat", "ex": ["You mustn't run here.", "You must be here at eight."]}],quiz:{"v": {"q": "forget 的意思是：", "opts": ["忘记", "记得", "带来"], "a": 0}, "e": {"q": "想说「上学别迟到」，正确的是：", "opts": ["Don't be late for school.", "Don't late for school.", "You mustn't late for school."], "a": 0}, "p": {"q": "Don't ______ on the wall!", "opts": ["drawing", "draw", "to draw"], "a": 1}},speak:"说 4 句话：用 Come on! 开头，再用 Don't … 和 You mustn't … 各说一条规矩，最后用 Don't forget … 提醒对方一件事。"},
{n:65,title:"Not a Baby",topic:"反身代词 myself/yourself · must 与钟点 half past",reading:"Dad, can I go to the party on Saturday?\n\nYes, but you must be home at half past ten.\n\nHalf past ten! That's early. All my friends stay out later.\n\nYou mustn't come home late, Sue. You are only fourteen.\n\nBut I'm not a baby! I can look after myself.\n\nI know you can. But I worry about you.\n\nPlease, Dad. I will come home at eleven.\n\nAll right. Eleven, and not a minute later. Enjoy yourself!",zh:"（原创改写）爸爸，周六我能去参加聚会吗？\n\n可以，但你十点半必须到家。\n\n十点半！太早了。我朋友们都待得更晚。\n\n苏，你不能回来太晚，你才十四岁。\n\n可我不是小孩子了！我能照顾好自己。\n\n我知道你能。但我担心你。\n\n求你了爸爸，我十一点回来。\n\n好吧，十一点，一分钟都不能晚。玩得开心！",vocab:[{"w": "party", "ph": "/ˈpɑːti/", "en": "a time when people meet to eat, talk and have fun", "zh": "n. 聚会；派对", "eg": "We are going to a party on Saturday."}, {"w": "myself", "ph": "/maɪˈself/", "en": "a word meaning 'me' when I am also the one who does it", "zh": "pron. 我自己", "eg": "I can look after myself."}, {"w": "yourself", "ph": "/jɔːˈself/", "en": "a word meaning 'you' when you are also the one who does it", "zh": "pron. 你自己", "eg": "Enjoy yourself at the party!"}, {"w": "worry", "ph": "/ˈwʌri/", "en": "to keep thinking about something bad", "zh": "v. 担心；担忧", "eg": "Don't worry. I will be fine."}],exprs:[{"en": "half past ten", "zh": "十点半", "scene": "非整点最简单的一档。几点半就是 half past + 小时。", "struct": "half past + 小时", "cat": "dailychat", "ex": ["You must be home at half past ten.", "The film starts at half past seven."]}, {"en": "look after", "zh": "照顾；照看", "scene": "说照顾自己、孩子、宠物都能用，等于 take care of。", "struct": "look after + 人/物", "cat": "relationship", "ex": ["I can look after myself.", "She looks after her little brother."]}, {"en": "Enjoy yourself!", "zh": "玩得开心！", "scene": "送人去聚会、旅行前说的祝福，等于 Have a good time!", "struct": "Enjoy + 反身代词!", "cat": "dailychat", "ex": ["Enjoy yourself at the party!", "Enjoy yourselves on holiday!"]}],pats:[{"en": "主语 + must + be + 时间点", "zh": "某人必须在几点（到）", "scene": "给回家、赴约定死线。must 后面跟 be，因为后面是时间不是动作。", "struct": "主语 + must + be + 地点/时间", "cat": "dailychat", "ex": ["You must be home at half past ten.", "We must be at the station at eight."]}, {"en": "主语 + 动词 + 反身代词", "zh": "某人自己……（myself/yourself/himself）", "scene": "主语和宾语是同一个人时，宾语要用反身代词，不能再说 me、him。", "struct": "主语 + 动词 + myself/yourself/himself/herself/ourselves/themselves", "cat": "dailychat", "ex": ["I can look after myself.", "Enjoy yourself at the party!"]}],quiz:{"v": {"q": "worry 的意思是：", "opts": ["担心", "生气的", "照看"], "a": 0}, "e": {"q": "朋友要去参加聚会，送他一句祝福应该说：", "opts": ["Enjoy yourself!", "Look after me!", "Worry about it!"], "a": 0}, "p": {"q": "I can look after ______.", "opts": ["me", "myself", "my"], "a": 1}},speak:"说 3 句话：用 must be home at half past … 和父母讨价还价一个回家时间，用 look after myself 说明自己能照顾自己，最后让对方用 Enjoy yourself! 祝福你。"},
{n:66,title:"When's Your Birthday?",topic:"日期与序数词 · 反身代词 enjoy oneself",reading:"When's your birthday, Ben?\n\nIt's on the twelfth of June. When's yours?\n\nMine is on the third of May. That's next week!\n\nWill you have a party?\n\nYes. We always have a big party in the garden.\n\nWhat's the date today?\n\nIt's the first of May.\n\nGreat. I can enjoy myself at your party.\n\nOf course. Don't forget to come!",zh:"（原创改写）本，你的生日是什么时候？\n\n六月十二号。你的呢？\n\n我的是五月三号，就在下周！\n\n你会办聚会吗？\n\n会，我们总是在花园里办个大聚会。\n\n今天几号？\n\n五月一号。\n\n太好了，我可以在你的聚会上好好玩一场。\n\n当然啦。别忘了来！",vocab:[{"w": "birthday", "ph": "/ˈbɜːθdeɪ/", "en": "the day in each year when you were born", "zh": "n. 生日", "eg": "My birthday is on the twelfth of June."}, {"w": "date", "ph": "/deɪt/", "en": "the day, month and year", "zh": "n. 日期", "eg": "What's the date today?"}, {"w": "first", "ph": "/fɜːst/", "en": "number one in order", "zh": "num. 第一", "eg": "It's the first of May today."}, {"w": "twelfth", "ph": "/twelfθ/", "en": "number twelve in order", "zh": "num. 第十二", "eg": "His birthday is on the twelfth of June."}],exprs:[{"en": "on the + 序数词 + of + 月份", "zh": "在……月……号", "scene": "英式日期的读法，具体某一天介词用 on。", "struct": "on the + 序数词 + of + 月份", "cat": "dailychat", "ex": ["It's on the twelfth of June.", "We go to the sea on the first of July."]}, {"en": "What's the date today?", "zh": "今天几号？", "scene": "问日期。注意它和 What day is it?（问星期几）不一样。", "struct": "What's the date (today)? — It's the + 序数词 + of + 月份.", "cat": "dailychat", "ex": ["What's the date today? — It's the first of May.", "What's the date? — It's the third of May."]}, {"en": "have a party", "zh": "办聚会", "scene": "生日、节日最常见的安排，动词固定用 have。", "struct": "have a party (+ 地点/时间)", "cat": "dailychat", "ex": ["We always have a big party in the garden.", "Did you have a party on your birthday?"]}],pats:[{"en": "When's your birthday? — It's on the + 序数词 + of + 月份.", "zh": "你的生日是什么时候？——在……月……号。", "scene": "问生日固定用 When's，回答里日期前必须加 on。", "struct": "When's + 形容词性物主代词 + birthday? — It's on the + 序数词 + of + 月份.", "cat": "dailychat", "ex": ["When's your birthday? — It's on the twelfth of June.", "When's her birthday? — It's on the third of May."]}, {"en": "enjoy + 反身代词", "zh": "玩得开心", "scene": "聚会、旅行、演出都能用，反身代词要跟着主语变。", "struct": "enjoy + myself/yourself/himself/herself/ourselves/themselves", "cat": "dailychat", "ex": ["I can enjoy myself at your party.", "They enjoyed themselves at the beach."]}],quiz:{"v": {"q": "twelfth 的意思是：", "opts": ["第十二", "第十二月", "十二"], "a": 0}, "e": {"q": "想知道今天是几月几号，应该问：", "opts": ["What's the date today?", "What day is it today?", "What's the time?"], "a": 0}, "p": {"q": "My birthday is ______ the twelfth of June.", "opts": ["in", "on", "at"], "a": 1}},speak:"说 4 句话：用 When's your birthday? 问对方生日并用 on the + 序数词 + of + 月份 回答，再用 What's the date today? 问今天日期，最后用 enjoy myself 说说你在聚会上会玩得怎样。"},
{n:67,title:"The Weekend",topic:"be 动词过去式 was/were",reading:"Hello, Sue. How was your weekend?\n\nIt was wonderful. I was at my grandmother's house.\n\nWere you there on Saturday and Sunday?\n\nYes, we were. The weather was beautiful.\n\nWas your brother there too?\n\nNo, he wasn't. He was at home because he was ill.\n\nWere your cousins there?\n\nYes, they were. We were very happy together. What about you?\n\nI was at home. It was a quiet weekend.",zh:"（原创改写）你好，苏。周末过得怎么样？\n\n棒极了。我在我奶奶家。\n\n周六周日你都在那儿吗？\n\n是的，都在。天气特别好。\n\n你弟弟也在那儿吗？\n\n不，他不在。他生病了，待在家里。\n\n你的表兄弟姐妹在吗？\n\n在，他们都在。我们在一起很开心。你呢？\n\n我待在家里，过了一个安静的周末。",vocab:[{"w": "weekend", "ph": "/ˌwiːkˈend/", "en": "Saturday and Sunday", "zh": "n. 周末", "eg": "How was your weekend?"}, {"w": "wonderful", "ph": "/ˈwʌndəfl/", "en": "very good; making you happy", "zh": "adj. 极好的；精彩的", "eg": "We had a wonderful time at the party."}, {"w": "ill", "ph": "/ɪl/", "en": "not well; sick", "zh": "adj. 生病的", "eg": "He was ill and stayed in bed."}, {"w": "cousin", "ph": "/ˈkʌzn/", "en": "the child of your aunt or uncle", "zh": "n. 堂（表）兄弟姐妹", "eg": "My cousins came to see us on Sunday."}],exprs:[{"en": "How was your weekend?", "zh": "周末过得怎么样？", "scene": "周一见面最常用的一句寒暄。was 说明问的是已经过去的周末。", "struct": "How was + your/the + weekend/holiday/day?", "cat": "dailychat", "ex": ["How was your weekend? — It was wonderful.", "How was your holiday? — It was great."]}, {"en": "be at home", "zh": "在家", "scene": "说待的地方。过去时就是 was/were at home。", "struct": "be + at home / at school / at work", "cat": "habit", "ex": ["He was at home because he was ill.", "I was at home all day yesterday."]}, {"en": "because + 句子", "zh": "因为……", "scene": "解释原因，后面跟一整个句子，不是 because of。", "struct": "主句 + because + 主语 + 谓语", "cat": "dailychat", "ex": ["He was at home because he was ill.", "We stayed inside because it rained."]}],pats:[{"en": "主语 + was/were + 地点/形容词", "zh": "某人（那时）在……／是……样的", "scene": "过去的状态。I/he/she/it 用 was，you/we/they 用 were。", "struct": "主语 + was/were + 表语", "cat": "dailychat", "ex": ["I was at my grandmother's house.", "The weather was beautiful."]}, {"en": "Was/Were + 主语 …? — Yes, … was/were. / No, … wasn't/weren't.", "zh": "……（过去）是吗？——是的。／不是。", "scene": "把 was/were 提到句首就成疑问句，回答里不重复后面的内容。", "struct": "Was/Were + 主语 + 表语?", "cat": "dailychat", "ex": ["Was your brother there? — No, he wasn't.", "Were your cousins there? — Yes, they were."]}],quiz:{"v": {"q": "wonderful 的意思是：", "opts": ["极好的", "糟糕的", "安静的"], "a": 0}, "e": {"q": "周一见朋友，想问周末过得怎么样，应该说：", "opts": ["How was your weekend?", "How is your weekend?", "What was your weekend?"], "a": 0}, "p": {"q": "They ______ at the party last night.", "opts": ["was", "were", "are"], "a": 1}},speak:"说 4 句话：用 How was your weekend? 提问，用 I was … / We were … 说出你上周日在哪、天气怎样，再用 Was he/she there? — Yes/No 回答一句，最后解释原因用 because。"},
{n:68,title:"Where Were You?",topic:"was/were 的疑问与否定 · 过去地点",reading:"I called you yesterday, but you weren't at home.\n\nWhere were you at three o'clock?\n\nI was at the library. My sister was with me.\n\nWas Tom there too?\n\nNo, he wasn't. He was at the sports ground.\n\nWere your parents at home?\n\nNo, they weren't. They were at work.\n\nWhere were you last night?\n\nI was at a friend's birthday party. It was great fun!",zh:"（原创改写）我昨天给你打电话，但你不在家。\n\n三点的时候你在哪儿？\n\n我在图书馆，我妹妹和我在一起。\n\n汤姆也在那儿吗？\n\n不，他不在。他在运动场。\n\n你父母在家吗？\n\n不在，他们在上班。\n\n昨晚你在哪儿？\n\n我在一个朋友的生日聚会上，特别好玩！",vocab:[{"w": "library", "ph": "/ˈlaɪbrəri/", "en": "a place where you can read or borrow books", "zh": "n. 图书馆", "eg": "I was at the library yesterday afternoon."}, {"w": "yesterday", "ph": "/ˈjestədeɪ/", "en": "the day before today", "zh": "adv. 昨天", "eg": "I called you yesterday, but you were out."}, {"w": "parents", "ph": "/ˈpeərənts/", "en": "your mother and father", "zh": "n. 父母", "eg": "My parents were at work all day."}, {"w": "fun", "ph": "/fʌn/", "en": "something that makes you happy and laugh", "zh": "n. 乐趣；好玩的事", "eg": "The party was great fun."}],exprs:[{"en": "call somebody", "zh": "给某人打电话", "scene": "打电话给某人，中间不加 to；说「给我打电话」就是 call me。", "struct": "call + 人 (宾语)", "cat": "dailychat", "ex": ["I called you yesterday, but you weren't at home.", "Call me when you get home."]}, {"en": "at work", "zh": "在上班", "scene": "说在工作的状态，不是具体的办公室，所以 work 前不加 the。", "struct": "be at work / be at school / be at home", "cat": "work", "ex": ["They were at work all afternoon.", "My father is at work now."]}, {"en": "last night", "zh": "昨晚", "scene": "过去时间状语，一组要记牢：last night/week/month/year。", "struct": "last + night/week/month/year", "cat": "dailychat", "ex": ["Where were you last night?", "We were at the cinema last week."]}],pats:[{"en": "Where were you + 过去时间?", "zh": "你（过去某时）在哪儿？", "scene": "询问对方过去的位置。注意 you 不管单复数都用 were。", "struct": "Where + was/were + 主语 + 过去时间?", "cat": "dailychat", "ex": ["Where were you at three o'clock?", "Where was she yesterday evening?"]}, {"en": "主语 + wasn't/weren't + 地点", "zh": "某人（那时）不在……", "scene": "was/were 的否定式，直接加 not。口语里几乎总用缩写 wasn't / weren't。", "struct": "主语 + wasn't/weren't + 表语", "cat": "dailychat", "ex": ["You weren't at home yesterday.", "My parents weren't in town last week."]}],quiz:{"v": {"q": "library 的意思是：", "opts": ["图书馆", "运动场", "电影院"], "a": 0}, "e": {"q": "想说「我昨天给你打电话了」，正确的是：", "opts": ["I called you yesterday.", "I called to you yesterday.", "I call you yesterday."], "a": 0}, "p": {"q": "My parents ______ at home last night. They were at work.", "opts": ["wasn't", "weren't", "aren't"], "a": 1}},speak:"说 4 句话：用 Where were you …? 问对方昨天某个时间在哪儿，用 I was at … 回答，再用 Was he/she …? — No, … wasn't. 提到另一个人，最后用 last night 或 yesterday 加一句时间状语。"},
{n:69,title:"The Car Race",topic:"there was / there were · 过去时",reading:"There was a car race near our town last Sunday.\n\nThere were twenty cars in the race. There were hundreds of people there, too.\n\nMy father and I were in the crowd. It was very exciting.\n\nWas your friend in the race?\n\nNo, he wasn't. But his brother was. He was in car number five.\n\nWas he the winner?\n\nNo, he wasn't. He was fifth. But there was a big smile on his face!",zh:"（原创改写）上个星期天我们镇附近有一场汽车比赛。\n\n比赛里有二十辆车，还有成百上千的人。\n\n我和爸爸在人群里，特别激动人心。\n\n你朋友参加比赛了吗？\n\n没有，但他哥哥参加了，他在五号车里。\n\n他是冠军吗？\n\n不是，他是第五名。不过他脸上挂着大大的笑容！",vocab:[{"w": "race", "ph": "/reɪs/", "en": "a competition to see who is fastest", "zh": "n. 比赛；赛跑", "eg": "There was a car race near our town."}, {"w": "crowd", "ph": "/kraʊd/", "en": "a lot of people in one place", "zh": "n. 人群", "eg": "We were in the crowd near the road."}, {"w": "exciting", "ph": "/ɪkˈsaɪtɪŋ/", "en": "making you feel happy and interested", "zh": "adj. 令人兴奋的", "eg": "The football match was very exciting."}, {"w": "winner", "ph": "/ˈwɪnə(r)/", "en": "the person who wins", "zh": "n. 获胜者；冠军", "eg": "Who was the winner of the race?"}],exprs:[{"en": "car race", "zh": "汽车比赛", "scene": "说比赛类型，名词直接叠用，car 不加 s。", "struct": "a car race / a boat race / a horse race", "cat": "hobby", "ex": ["There was a car race near our town.", "He watches car races on TV."]}, {"en": "hundreds of", "zh": "成百上千的", "scene": "说数量很多但不精确。hundred 加了 s 以后要接 of。", "struct": "hundreds/thousands of + 名词复数", "cat": "dailychat", "ex": ["There were hundreds of people there.", "There are hundreds of books in the library."]}, {"en": "on one's face", "zh": "在某人脸上", "scene": "描写表情，常和 smile、look 一起用。", "struct": "a smile + on + 形容词性物主代词 + face", "cat": "emotion", "ex": ["There was a big smile on his face.", "She had a sad look on her face."]}],pats:[{"en": "There was/were … + 过去时间", "zh": "（过去）有……", "scene": "过去某处有某物。单数或不可数用 there was，复数用 there were。", "struct": "There + was/were + 名词 + 过去时间/地点", "cat": "experience", "ex": ["There was a car race last Sunday.", "There were twenty cars in the race."]}, {"en": "Was/Were there …? — Yes, there was/were. / No, there wasn't/weren't.", "zh": "（过去）有……吗？——有。／没有。", "scene": "there be 句型的过去时疑问，回答里要重复 there。", "struct": "Was/Were there + 名词 + 时间/地点?", "cat": "experience", "ex": ["Was there a race last Sunday? — Yes, there was.", "Were there many people? — Yes, there were."]}],quiz:{"v": {"q": "crowd 的意思是：", "opts": ["人群", "比赛", "冠军"], "a": 0}, "e": {"q": "想说「有成百上千的人」，正确的是：", "opts": ["There were hundreds of people.", "There were hundred of people.", "There was hundreds people."], "a": 0}, "p": {"q": "There ______ twenty cars in the race last Sunday.", "opts": ["was", "were", "is"], "a": 1}},speak:"说 4 句话：用 There was/were … + 过去时间 描述你上周看到的一场比赛或活动，说出有多少人和多少东西，再用 Was/Were there …? 问一句并回答。"},
{n:70,title:"There Was a Big Crowd",topic:"there was/were 的肯定、否定与疑问",reading:"There was a big crowd in the town square yesterday evening.\n\nThere were a lot of children there. There was a band on the stage.\n\nThere wasn't a cloud in the sky. The evening was warm.\n\nWas there a singer?\n\nYes, there was. She sang three songs.\n\nWere there any policemen?\n\nYes, there were about ten. They were very kind.\n\nWas it fun? It was wonderful. There was dancing in the square until ten.",zh:"（原创改写）昨天晚上镇上的广场上有一大群人。\n\n那儿有很多孩子，舞台上有一支乐队。\n\n天上没有一丝云，傍晚很暖和。\n\n有歌手吗？\n\n有，她唱了三首歌。\n\n有警察吗？\n\n有，大约十个。他们都很和气。\n\n好玩吗？太棒了。广场上的舞一直跳到十点。",vocab:[{"w": "square", "ph": "/skweə(r)/", "en": "an open place in the middle of a town", "zh": "n. 广场", "eg": "There was a band in the town square."}, {"w": "band", "ph": "/bænd/", "en": "a group of people who play music together", "zh": "n. 乐队", "eg": "The band played for two hours."}, {"w": "stage", "ph": "/steɪdʒ/", "en": "the high place where people perform", "zh": "n. 舞台", "eg": "The singer was on the stage."}, {"w": "cloud", "ph": "/klaʊd/", "en": "a white or grey thing in the sky made of water", "zh": "n. 云", "eg": "There wasn't a cloud in the sky."}],exprs:[{"en": "a lot of", "zh": "许多", "scene": "可数不可数都能搭，口语里比 many / much 常用得多。", "struct": "a lot of + 名词", "cat": "dailychat", "ex": ["There were a lot of children there.", "There was a lot of noise in the street."]}, {"en": "on the stage", "zh": "在舞台上", "scene": "说表演的位置，介词固定用 on。", "struct": "on the stage / on the bus / on the train", "cat": "hobby", "ex": ["There was a band on the stage.", "She stood on the stage and sang."]}, {"en": "in the sky", "zh": "在天上", "scene": "说云、太阳、星星的位置，介词用 in。", "struct": "in the sky", "cat": "dailychat", "ex": ["There wasn't a cloud in the sky.", "There were a lot of stars in the sky."]}],pats:[{"en": "There wasn't/weren't …", "zh": "（过去）没有……", "scene": "there be 过去时的否定。否定句和疑问句里，可数复数前习惯加 any。", "struct": "There + wasn't + a/an + 单数 / weren't + any + 复数", "cat": "experience", "ex": ["There wasn't a cloud in the sky.", "There weren't any chairs in the room."]}, {"en": "Was there a …? / Were there any …?", "zh": "有一个……吗？／有一些……吗？", "scene": "there be 过去时的疑问。单数前用 a，复数前用 any。", "struct": "Was there a + 单数? / Were there any + 复数?", "cat": "experience", "ex": ["Was there a singer? — Yes, there was.", "Were there any policemen? — Yes, there were."]}],quiz:{"v": {"q": "stage 的意思是：", "opts": ["舞台", "广场", "乐队"], "a": 0}, "e": {"q": "想说「天上没有一片云」，正确的是：", "opts": ["There wasn't a cloud in the sky.", "There weren't a cloud in the sky.", "There isn't cloud in sky."], "a": 0}, "p": {"q": "______ there any policemen at the square?", "opts": ["Was", "Were", "Are"], "a": 1}},speak:"说 4 句话：用 There was/were … 描述昨晚一个热闹的场面，用 There wasn't/weren't … 说一样没有的东西，再用 Was there a …? / Were there any …? 各问一句并回答。"},
{n:71,title:"He's Awful!",topic:"一般过去时入门 · 规则动词 -ed",reading:"Did you see Ron yesterday?\n\nYes, I did. He telephoned me four times!\n\nFour times! What did he say?\n\nHe asked about the football match and talked for an hour.\n\nYesterday he telephoned my sister five times.\n\nHe's awful! He always phones at dinner time.\n\nWhat did you do?\n\nI didn't answer the phone. I listened to music and finished my homework.",zh:"（原创改写）你昨天见到罗恩了吗？\n\n见到了。他给我打了四次电话！\n\n四次！他说什么了？\n\n他问了足球比赛的事，聊了一个小时。\n\n昨天他给我妹妹打了五次电话。\n\n他真讨厌！总是在吃饭的时候打来。\n\n你怎么办的？\n\n我没接电话。我听音乐，把作业做完了。",vocab:[{"w": "telephone", "ph": "/ˈtelɪfəʊn/", "en": "to call someone on the phone", "zh": "v. 打电话", "eg": "He telephoned me four times yesterday."}, {"w": "awful", "ph": "/ˈɔːfl/", "en": "very bad or unpleasant", "zh": "adj. 糟糕的；讨厌的", "eg": "The weather was awful last weekend."}, {"w": "match", "ph": "/mætʃ/", "en": "a game between two teams", "zh": "n. 比赛", "eg": "We watched the football match on TV."}, {"w": "listen", "ph": "/ˈlɪsn/", "en": "to hear something with attention", "zh": "v. 听", "eg": "I listened to music after dinner."}],exprs:[{"en": "telephone somebody", "zh": "给某人打电话", "scene": "过去时把 telephone 变成 telephoned，也可以说 phoned。", "struct": "telephone/phone + 人", "cat": "dailychat", "ex": ["He telephoned me four times yesterday.", "I phoned my mother last night."]}, {"en": "at dinner time", "zh": "在吃饭时间", "scene": "说某个日常时段，用 at + 名词 + time。", "struct": "at + breakfast/lunch/dinner + time", "cat": "habit", "ex": ["He always phones at dinner time.", "We talk about our day at dinner time."]}, {"en": "answer the phone", "zh": "接电话", "scene": "「接」电话用 answer，不用 receive，这是固定搭配。", "struct": "answer the phone / answer the door", "cat": "dailychat", "ex": ["I didn't answer the phone.", "Please answer the phone when it rings."]}],pats:[{"en": "主语 + 动词 -ed + 过去时间", "zh": "某人（过去）做了……", "scene": "规则动词过去式：词尾直接加 -ed。所有人称都一样，不用加 -s。", "struct": "主语 + 动词 -ed + (yesterday/last week…)", "cat": "experience", "ex": ["He telephoned me four times yesterday.", "I finished my homework at nine."]}, {"en": "主语 + didn't + 动词原形", "zh": "某人（过去）没有做……", "scene": "过去时的否定。didn't 已经表示过去了，后面的动词必须打回原形。", "struct": "主语 + didn't + 动词原形", "cat": "experience", "ex": ["I didn't answer the phone.", "She didn't watch TV last night."]}],quiz:{"v": {"q": "awful 的意思是：", "opts": ["讨厌的；糟糕的", "极好的", "安静的"], "a": 0}, "e": {"q": "想说「接电话」，正确的是：", "opts": ["answer the phone", "receive the phone", "take the phone"], "a": 0}, "p": {"q": "I ______ the phone because I was busy.", "opts": ["didn't answered", "didn't answer", "don't answered"], "a": 1}},speak:"说 4 句话：用 主语 + 动词 -ed + yesterday 讲两件你昨天做的事，用 didn't + 动词原形 说一件你没做的事，最后用 He's awful! 或类似的感叹评价一个人。"},
{n:72,title:"What Did You Do Yesterday?",topic:"一般过去时的疑问与否定 did / didn't",reading:"What did you do yesterday evening, Ben?\n\nI stayed at home and cleaned my room.\n\nDid you watch television?\n\nNo, I didn't. I listened to the radio.\n\nDid your sister help you?\n\nNo, she didn't. She visited her friend.\n\nWhat time did she come home?\n\nShe came home at nine o'clock.\n\nDid you cook dinner?\n\nYes, I did. I cooked noodles for everyone.",zh:"（原创改写）本，昨天晚上你做什么了？\n\n我待在家里，把房间打扫了一遍。\n\n你看电视了吗？\n\n没有。我听收音机来着。\n\n你妹妹帮你了吗？\n\n没有，她去看她朋友了。\n\n她几点回来的？\n\n她九点回来的。\n\n你做晚饭了吗？\n\n做了。我给大家煮了面条。",vocab:[{"w": "clean", "ph": "/kliːn/", "en": "to make something not dirty", "zh": "v. 打扫；弄干净", "eg": "I cleaned my room yesterday evening."}, {"w": "radio", "ph": "/ˈreɪdiəʊ/", "en": "a thing you use to listen to programmes", "zh": "n. 收音机", "eg": "He listens to the radio every morning."}, {"w": "dinner", "ph": "/ˈdɪnə(r)/", "en": "the main meal of the day", "zh": "n. 正餐；晚饭", "eg": "We have dinner at seven o'clock."}, {"w": "cook", "ph": "/kʊk/", "en": "to make food ready to eat", "zh": "v. 做饭；煮", "eg": "I cooked noodles for everyone."}],exprs:[{"en": "clean my room", "zh": "打扫我的房间", "scene": "日常家务里最基础的一项，过去时是 cleaned my room。", "struct": "clean + my/your/his + room", "cat": "habit", "ex": ["I cleaned my room yesterday evening.", "She cleans her room every Saturday."]}, {"en": "listen to the radio", "zh": "听收音机", "scene": "listen 是不及物动词，后面必须加 to 才能接收音机、音乐。", "struct": "listen to + the radio/music/me", "cat": "hobby", "ex": ["I listened to the radio last night.", "He listens to music after school."]}, {"en": "come home", "zh": "回家", "scene": "强调「回到家里」这个动作，home 前不加 to。", "struct": "come home / go home + 时间", "cat": "habit", "ex": ["She came home at nine o'clock.", "What time did you come home?"]}],pats:[{"en": "What did + 主语 + do + 过去时间?", "zh": "某人（过去）做了什么？", "scene": "问过去做了什么事。did 后面那个 do 是「做」，用原形。", "struct": "What + did + 主语 + do + 过去时间?", "cat": "dailychat", "ex": ["What did you do yesterday evening?", "What did she do last Sunday?"]}, {"en": "Did + 主语 + 动词原形? — Yes, … did. / No, … didn't.", "zh": "某人（过去）做……了吗？——做了。／没做。", "scene": "过去时的一般疑问句。did 一出，后面动词全打回原形。", "struct": "Did + 主语 + 动词原形 + 过去时间?", "cat": "dailychat", "ex": ["Did you watch television? — No, I didn't.", "Did you cook dinner? — Yes, I did."]}],quiz:{"v": {"q": "clean 的意思是：", "opts": ["打扫", "做饭", "回家"], "a": 0}, "e": {"q": "想说「听收音机」，正确的是：", "opts": ["listen to the radio", "listen the radio", "listen at the radio"], "a": 0}, "p": {"q": "What did you ______ yesterday evening?", "opts": ["do", "did", "does"], "a": 0}},speak:"说 4 句话：用 What did you do yesterday? 提问并回答，回答里至少用两个规则动词的 -ed 形式；再用 Did you …? — Yes, I did. / No, I didn't. 补一组问答。"},
{n:73,title:"The Way to King Street",topic:"问路与指路 · 一般过去时复习",reading:"Excuse me, can you tell me the way to King Street, please?\n\nYes. Go along this road and turn left at the traffic lights.\n\nIs it far from here?\n\nNo, it isn't. It's about five minutes on foot.\n\nThank you. Did you say left or right?\n\nLeft. Then you will see a small bridge. Cross it, and King Street is on your right.\n\nI see. The post office is there, isn't it?\n\nYes, it is. You can't miss it. Good luck!",zh:"（原创改写）打扰一下，请问去国王街怎么走？\n\n可以。沿着这条路走，到红绿灯处左转。\n\n离这儿远吗？\n\n不远，走路大概五分钟。\n\n谢谢。您刚说的是左转还是右转？\n\n左转。然后你会看到一座小桥，过了桥，国王街就在你右手边。\n\n我明白了。邮局就在那儿，对吧？\n\n对，就在那儿。你肯定能找到。祝你好运！",vocab:[{"w": "way", "ph": "/weɪ/", "en": "the road or direction to a place", "zh": "n. 路；路线", "eg": "Can you tell me the way to the station?"}, {"w": "bridge", "ph": "/brɪdʒ/", "en": "a thing built over a river or road so people can cross", "zh": "n. 桥", "eg": "Cross the bridge and you are there."}, {"w": "cross", "ph": "/krɒs/", "en": "to go from one side to the other", "zh": "v. 穿过；越过", "eg": "Cross the road at the traffic lights."}, {"w": "miss", "ph": "/mɪs/", "en": "to fail to find or see something", "zh": "v. 错过；找不到", "eg": "You can't miss it. It's the big red building."}],exprs:[{"en": "Can you tell me the way to …?", "zh": "请问去……怎么走？", "scene": "在街上问路最礼貌、最标准的一句开场。", "struct": "Can you tell me the way to + 地点?", "cat": "dailychat", "ex": ["Can you tell me the way to King Street?", "Can you tell me the way to the post office?"]}, {"en": "turn left / turn right", "zh": "左转／右转", "scene": "指路的核心动作词，后面常在哪个路口转。", "struct": "turn left/right + at + 地点", "cat": "dailychat", "ex": ["Turn left at the traffic lights.", "Turn right at the second corner."]}, {"en": "on foot", "zh": "步行", "scene": "强调走路去，不是坐车。前面常加时间表示步行多久。", "struct": "时间 + on foot / go … on foot", "cat": "dailychat", "ex": ["It's about five minutes on foot.", "We went to the museum on foot."]}],pats:[{"en": "Go along … and turn left/right at …", "zh": "沿着……走，在……处左／右转。", "scene": "指路的标准动作链：先沿着某条路，再说明在哪儿拐弯。", "struct": "Go along + 路名 + and + turn + 方向 + at + 地点", "cat": "dailychat", "ex": ["Go along this road and turn left at the traffic lights.", "Go along King Street and turn right at the bank."]}, {"en": "祈使句 + and + 句子", "zh": "做……，然后就……", "scene": "「照着做 + 结果」连着说，指路时特别好用。", "struct": "动词原形 …, and + 主语 + will + 动词原形", "cat": "dailychat", "ex": ["Cross it, and King Street is on your right.", "Turn left, and you will see the school."]}],quiz:{"v": {"q": "bridge 的意思是：", "opts": ["桥", "路", "红绿灯"], "a": 0}, "e": {"q": "想问路，最礼貌的说法是：", "opts": ["Can you tell me the way to King Street?", "Where King Street?", "Give me the way to King Street."], "a": 0}, "p": {"q": "Go along this road ______ turn left at the lights.", "opts": ["and", "but", "so"], "a": 0}},speak:"说 3 句话：用 Can you tell me the way to …? 问路，对方用 Go along … and turn left/right at … 指路，最后再用一段话说明步行要多久。"},
{n:74,title:"Where Did You Go?",topic:"一般过去时 · 常见不规则动词 went/saw/ate/bought",reading:"Where did you go last Sunday?\n\nWe went to the new museum in the city centre.\n\nDid you see the old paintings?\n\nYes, we saw them. They were beautiful.\n\nWhat did you eat for lunch?\n\nWe ate sandwiches in a small café near the museum.\n\nDid you buy anything?\n\nYes, I bought a postcard and a book about ships.\n\nWe had a great day!",zh:"（原创改写）上周日你们去哪儿了？\n\n我们去了市中心那家新开的博物馆。\n\n你们看到那些古老的画了吗？\n\n看到了，很美。\n\n午饭吃的什么？\n\n我们在博物馆附近的一家小咖啡馆吃了三明治。\n\n你们买东西了吗？\n\n买了，我买了一张明信片和一本讲船的书。\n\n我们度过了很棒的一天！",vocab:[{"w": "museum", "ph": "/mjuˈziːəm/", "en": "a place where old and interesting things are kept", "zh": "n. 博物馆", "eg": "We went to the museum last Sunday."}, {"w": "painting", "ph": "/ˈpeɪntɪŋ/", "en": "a picture made with paint", "zh": "n. 绘画；画作", "eg": "The old paintings in this room are famous."}, {"w": "postcard", "ph": "/ˈpəʊstkɑːd/", "en": "a card you send by post without an envelope", "zh": "n. 明信片", "eg": "I bought a postcard for my friend."}, {"w": "café", "ph": "/ˈkæfeɪ/", "en": "a small place where you can buy coffee and food", "zh": "n. 咖啡馆", "eg": "We had lunch in a small café."}],exprs:[{"en": "in the city centre", "zh": "在市中心", "scene": "说位置很常用，英式拼写 centre，美式写 center。", "struct": "in the city centre / in the centre of + 城市", "cat": "dailychat", "ex": ["The new museum is in the city centre.", "We met in the city centre at noon."]}, {"en": "have a great day", "zh": "度过很棒的一天", "scene": "结束一段游玩后的总结，great 可以换成 good、wonderful。", "struct": "have a + 形容词 + day/time", "cat": "experience", "ex": ["We had a great day at the museum.", "Have a great day! See you tomorrow."]}, {"en": "buy something for somebody", "zh": "给某人买某物", "scene": "带礼物、纪念品时的说法，也可以说 buy somebody something。", "struct": "buy + 物 + for + 人 / buy + 人 + 物", "cat": "relationship", "ex": ["I bought a postcard for my sister.", "She bought her mother some flowers."]}],pats:[{"en": "Where did + 主语 + go + 过去时间?", "zh": "某人（过去）去哪儿了？", "scene": "问过去去了哪里。did 后面用原形 go，回答才用 went。", "struct": "Where + did + 主语 + go + 过去时间? — 主语 + went to + 地点", "cat": "experience", "ex": ["Where did you go last Sunday? — We went to the museum.", "Where did she go yesterday? — She went to the park."]}, {"en": "不规则动词过去式：go→went, see→saw, eat→ate, buy→bought", "zh": "不规则动词的过去式", "scene": "这一批不能加 -ed，只能一个个记住，是过去时最常考的一组。", "struct": "主语 + went/saw/ate/bought/had + 其他", "cat": "experience", "ex": ["We saw the old paintings.", "I bought a postcard and a book."]}],quiz:{"v": {"q": "museum 的意思是：", "opts": ["博物馆", "咖啡馆", "图书馆"], "a": 0}, "e": {"q": "想说「我们度过了很棒的一天」，正确的是：", "opts": ["We had a great day.", "We have a great day.", "We had great day."], "a": 0}, "p": {"q": "Where did you ______ last Sunday? — We went to the museum.", "opts": ["went", "go", "going"], "a": 1}},speak:"说 4 句话：用 Where did you go …? 问对方上次出游去哪儿了，回答里用 went、saw、ate、bought 中的至少三个不规则动词过去式，讲讲看到了什么、吃了什么、买了什么。"},
{n:75,title:"Uncomfortable Shoes",topic:"一般过去时 · 购物与 too + 形容词",reading:"Do you like my new shoes?\n\nThey look nice. When did you buy them?\n\nI bought them last Saturday in that new shop.\n\nWere they expensive?\n\nNo, they were quite cheap. But they are very uncomfortable.\n\nWhat's the matter with them?\n\nThey are too small. My feet hurt after an hour.\n\nTake them back to the shop. I'm sure they will change them for you.",zh:"（原创改写）你喜欢我的新鞋吗？\n\n看着挺好看。你什么时候买的？\n\n上周六在那家新店里买的。\n\n贵吗？\n\n不贵，挺便宜的。但是穿着很不舒服。\n\n鞋子有什么问题？\n\n太小了。走一个小时我的脚就疼。\n\n拿回店里去吧，我相信他们会给你换的。",vocab:[{"w": "shoe", "ph": "/ʃuː/", "en": "a thing you wear on your foot", "zh": "n. 鞋", "eg": "These shoes are too small for me."}, {"w": "expensive", "ph": "/ɪkˈspensɪv/", "en": "costing a lot of money", "zh": "adj. 昂贵的", "eg": "That bag is too expensive for me."}, {"w": "cheap", "ph": "/tʃiːp/", "en": "costing little money", "zh": "adj. 便宜的", "eg": "The tickets were quite cheap."}, {"w": "uncomfortable", "ph": "/ʌnˈkʌmftəbl/", "en": "not making you feel comfortable", "zh": "adj. 不舒服的", "eg": "These shoes are very uncomfortable."}],exprs:[{"en": "What's the matter with them?", "zh": "它们有什么问题？", "scene": "问东西出了什么毛病。把 with you 换成 with them 就能问物件。", "struct": "What's the matter with + 名词/代词?", "cat": "dailychat", "ex": ["What's the matter with them? — They are too small.", "What's the matter with your car?"]}, {"en": "take something back", "zh": "把某物退回", "scene": "买的东西不合适、坏了，拿回店里退换。", "struct": "take + 物 + back (+ to + 地点)", "cat": "dailychat", "ex": ["Take them back to the shop.", "I took the shirt back yesterday."]}, {"en": "be too + 形容词", "zh": "太……了", "scene": "说程度过头了，含有「所以不合适」的意思。", "struct": "主语 + be + too + 形容词", "cat": "opinion", "ex": ["They are too small.", "This coffee is too hot."]}],pats:[{"en": "When did you buy …? — I bought … + 过去时间", "zh": "你什么时候买的……？——我……时候买的。", "scene": "buy 的过去式是不规则的 bought，疑问里用回原形 buy。", "struct": "When + did + 主语 + buy + 物? — 主语 + bought + 物 + 过去时间", "cat": "dailychat", "ex": ["When did you buy them? — I bought them last Saturday.", "When did she buy the bag? — She bought it last week."]}, {"en": "主语 + be + too + 形容词 (for + 人)", "zh": "……对（某人）来说太……了", "scene": "评价尺寸、价格、难度不合适。for 后面接「对谁而言」。", "struct": "主语 + be + too + 形容词 + (for + 人)", "cat": "opinion", "ex": ["These shoes are too small for me.", "The book is too difficult for him."]}],quiz:{"v": {"q": "uncomfortable 的意思是：", "opts": ["不舒服的", "不舒服地", "舒服的"], "a": 0}, "e": {"q": "买的东西不合适，建议对方拿回店里，应该说：", "opts": ["Take them back to the shop.", "Bring them to the shop.", "Put them back in the shop."], "a": 0}, "p": {"q": "When did you buy those shoes? — I ______ them last Saturday.", "opts": ["buyed", "bought", "buy"], "a": 1}},speak:"说 4 句话：用 When did you buy …? 问对方一样东西什么时候买的，用 I bought … + 过去时间 回答，再用 be too + 形容词 说它哪里不合适，最后用 Take it/them back … 给个建议。"},
{n:76,title:"Two Days Ago",topic:"一般过去时 · … ago 时间状语",reading:"When did you see Mr. Hill?\n\nI saw him two days ago. He was in his garden.\n\nDid you speak to him?\n\nYes, I did. We spoke for ten minutes.\n\nWhen did you finish that book?\n\nI finished it a week ago. It was very good.\n\nAnd when did you learn to swim?\n\nI learned five years ago, when I was ten. Time flies!",zh:"（原创改写）你什么时候见到希尔先生的？\n\n两天前见的，他当时在花园里。\n\n你跟他说话了吗？\n\n说了，我们聊了十分钟。\n\n那本书你什么时候看完的？\n\n一周前看完的，特别好看。\n\n那你什么时候学会游泳的？\n\n五年前学的，那时我十岁。时间过得真快！",vocab:[{"w": "ago", "ph": "/əˈɡəʊ/", "en": "back in time from now", "zh": "adv. ……以前", "eg": "I saw him two days ago."}, {"w": "minute", "ph": "/ˈmɪnɪt/", "en": "sixty seconds; a very short time", "zh": "n. 分钟", "eg": "We spoke for ten minutes."}, {"w": "learn", "ph": "/lɜːn/", "en": "to get knowledge or a new skill", "zh": "v. 学会；学习", "eg": "I learned to swim when I was ten."}, {"w": "year", "ph": "/jɪə(r)/", "en": "twelve months", "zh": "n. 年", "eg": "We moved here five years ago."}],exprs:[{"en": "… ago", "zh": "……以前", "scene": "从「现在」往回数的一段时间，动词必须用过去式。", "struct": "时间段 + ago（two days ago / a week ago / five years ago）", "cat": "experience", "ex": ["I saw him two days ago.", "She left home an hour ago."]}, {"en": "speak to somebody", "zh": "和某人说话", "scene": "强调「开口跟某人说」，比 talk 稍正式，过去式是 spoke。", "struct": "speak to/with + 人", "cat": "dailychat", "ex": ["Did you speak to him? — Yes, I did.", "I spoke to my teacher after class."]}, {"en": "Time flies!", "zh": "时间过得真快！", "scene": "感叹日子过得快，聊到往事时非常自然的一句。", "struct": "Time flies!（感叹句，单独使用）", "cat": "humor", "ex": ["Five years ago? Time flies!", "Time flies when you are having fun."]}],pats:[{"en": "主语 + 动词过去式 + 时间段 + ago", "zh": "某人在……以前做了……", "scene": "ago 要放在时间段后面，动词一定是过去式。ago 之前不加 for、in。", "struct": "主语 + 动词过去式 + (数字 + 时间单位) + ago", "cat": "experience", "ex": ["I finished it a week ago.", "They moved here three years ago."]}, {"en": "When did + 主语 + 动词原形? — … ago", "zh": "某人什么时候……的？——……以前。", "scene": "问过去某个动作发生的时间，回答用 ago 短语。", "struct": "When + did + 主语 + 动词原形? — 主语 + 过去式 + 时间段 + ago", "cat": "experience", "ex": ["When did you see him? — Two days ago.", "When did you learn to swim? — Five years ago."]}],quiz:{"v": {"q": "ago 的意思是：", "opts": ["以前", "以后", "现在"], "a": 0}, "e": {"q": "想说「我两天前见到他了」，正确的是：", "opts": ["I saw him two days ago.", "I see him two days ago.", "I saw him two days before."], "a": 0}, "p": {"q": "When did you finish that book? — I ______ it a week ago.", "opts": ["finish", "finished", "finishing"], "a": 1}},speak:"说 4 句话：用 When did you …? 问对方两件事各是什么时候做的，回答里都要用 时间段 + ago（比如 two days ago、a week ago、five years ago），最后加一句 Time flies!"},
{n:77,title:"Terrible Toothache",topic:"看病 · 过去时间与 When did it start?",reading:"Good morning. I want to see the dentist, please.\n\nDo you have an appointment?\n\nNo, I don't. I have a terrible toothache.\n\nI see. When did it start?\n\nIt started last night. I didn't sleep at all.\n\nCan you wait twenty minutes?\n\nYes, I can. Thank you very much.\n\nThe dentist will see you at ten. Please sit here and read a magazine.",zh:"（原创改写）早上好，我想看牙医。\n\n您有预约吗？\n\n没有。我牙疼得厉害。\n\n明白了。什么时候开始的？\n\n昨天晚上开始的，我一点也没睡着。\n\n您能等二十分钟吗？\n\n可以，非常感谢。\n\n牙医十点给您看。请坐这儿看看杂志吧。",vocab:[{"w": "appointment", "ph": "/əˈpɔɪntmənt/", "en": "a time you have arranged to see someone", "zh": "n. 预约", "eg": "I have an appointment at three o'clock."}, {"w": "terrible", "ph": "/ˈterəbl/", "en": "very bad", "zh": "adj. 可怕的；厉害的", "eg": "I have a terrible toothache."}, {"w": "start", "ph": "/stɑːt/", "en": "to begin", "zh": "v. 开始", "eg": "The film starts at eight o'clock."}, {"w": "magazine", "ph": "/ˌmæɡəˈziːn/", "en": "a thin book you can buy every week or month", "zh": "n. 杂志", "eg": "He read a magazine in the waiting room."}],exprs:[{"en": "see the dentist", "zh": "看牙医", "scene": "看医生一律用 see：see a doctor / see the dentist。", "struct": "see + a/the + doctor/dentist", "cat": "dailychat", "ex": ["I want to see the dentist, please.", "She saw the doctor yesterday morning."]}, {"en": "have an appointment", "zh": "有预约", "scene": "看病、理发、办业务前说明自己约没约上。", "struct": "have an appointment (+ with + 人 / at + 时间)", "cat": "dailychat", "ex": ["Do you have an appointment?", "I have an appointment with the dentist at ten."]}, {"en": "Can you wait …?", "zh": "您能等……吗？", "scene": "让别人稍等，后面直接加时间段。", "struct": "Can you wait + 时间段?", "cat": "dailychat", "ex": ["Can you wait twenty minutes?", "Can you wait here for a moment?"]}],pats:[{"en": "When did it start? — It started + 过去时间", "zh": "（病）什么时候开始的？——……时候开始的。", "scene": "医生问诊必问的一句，回答用 start 的过去式 started。", "struct": "When + did + it + start? — It + started + 过去时间", "cat": "dailychat", "ex": ["When did it start? — It started last night.", "When did the pain start? — It started this morning."]}, {"en": "主语 + didn't + 动词原形 + at all", "zh": "某人根本没……", "scene": "用 didn't 加 at all 把否定说满，强调一点都没有。", "struct": "主语 + didn't + 动词原形 + at all", "cat": "emotion", "ex": ["I didn't sleep at all.", "She didn't eat anything at all."]}],quiz:{"v": {"q": "appointment 的意思是：", "opts": ["预约", "牙医", "杂志"], "a": 0}, "e": {"q": "想说「我想看牙医」，正确的是：", "opts": ["I want to see the dentist.", "I want to look the dentist.", "I want to watch the dentist."], "a": 0}, "p": {"q": "When did it start? — It ______ last night.", "opts": ["starts", "started", "starting"], "a": 1}},speak:"说 4 句话：扮演病人，用 I want to see the dentist. 开口，用 have a terrible … 说症状，再用 When did it start? — It started … 回答医生的提问，最后用 didn't … at all 说你难受得怎么样。"},
{n:78,title:"When Did You See the Doctor?",topic:"看病 · 过去时问答与 give/have 的过去式",reading:"You look much better, Sue. When did you see the doctor?\n\nI saw him yesterday morning at the hospital.\n\nDid the nurse give you any medicine?\n\nYes, she gave me some. My cough is much better now.\n\nDid you have a fever?\n\nYes, I had a fever on Monday, but it went away on Tuesday.\n\nThe doctor told me to rest for two days. I went back to school this morning.",zh:"（原创改写）苏，你看起来好多了。你什么时候去看的医生？\n\n我昨天上午在医院看的。\n\n护士给你药了吗？\n\n给了。我的咳嗽现在好多了。\n\n你发烧了吗？\n\n烧了，周一起烧的，不过周二就退了。\n\n医生让我休息两天。我今天早上回学校了。",vocab:[{"w": "hospital", "ph": "/ˈhɒspɪtl/", "en": "a place where doctors and nurses work", "zh": "n. 医院", "eg": "She went to the hospital yesterday morning."}, {"w": "nurse", "ph": "/nɜːs/", "en": "a person who helps doctors and looks after ill people", "zh": "n. 护士", "eg": "The nurse gave me some medicine."}, {"w": "cough", "ph": "/kɒf/", "en": "to push air out of your throat noisily when you are ill", "zh": "n./v. 咳嗽", "eg": "He has a bad cough and can't sleep."}, {"w": "rest", "ph": "/rest/", "en": "to stop working and let your body get better", "zh": "v./n. 休息", "eg": "The doctor told me to rest for two days."}],exprs:[{"en": "at the hospital", "zh": "在医院", "scene": "说就医地点。英式里「住院」才用 in hospital，去看病用 at the hospital。", "struct": "at the hospital / at the doctor's", "cat": "dailychat", "ex": ["I saw him at the hospital.", "My mother works at the hospital."]}, {"en": "give somebody medicine", "zh": "给某人药", "scene": "give 后面先接人再接物，也可以说 give medicine to somebody。", "struct": "give + 人 + 物 / give + 物 + to + 人", "cat": "dailychat", "ex": ["The nurse gave me some medicine.", "She gave some water to the child."]}, {"en": "have a rest", "zh": "休息一下", "scene": "劝病人、劝累了的同事都好用，rest 在这里是名词。", "struct": "have a rest / take a rest", "cat": "dailychat", "ex": ["The doctor told me to have a rest.", "Sit down and have a rest."]}],pats:[{"en": "When did + 主语 + see …? — 主语 + saw … + 过去时间", "zh": "某人什么时候看的……？——……时候看的。", "scene": "see 的过去式是不规则的 saw，疑问句里要用原形 see。", "struct": "When + did + 主语 + see + 人? — 主语 + saw + 人 + 过去时间", "cat": "dailychat", "ex": ["When did you see the doctor? — I saw him yesterday morning.", "When did she see the nurse? — She saw her on Monday."]}, {"en": "主语 + had + 病名", "zh": "某人（过去）得了……", "scene": "have 表示「生病」时，过去式是 had：had a fever / had a cold。", "struct": "主语 + had + a + 病名", "cat": "dailychat", "ex": ["I had a fever on Monday.", "He had a bad cold last week."]}],quiz:{"v": {"q": "nurse 的意思是：", "opts": ["护士", "医生", "病人"], "a": 0}, "e": {"q": "想劝人「休息一下」，正确的是：", "opts": ["Have a rest.", "Make a rest.", "Do a rest."], "a": 0}, "p": {"q": "I ______ a fever on Monday, but it went away.", "opts": ["have", "had", "has"], "a": 1}},speak:"说 4 句话：用 When did you see the doctor? 问对方什么时候看的病，用 I saw him/her … 回答，再用 Did the nurse give you any medicine? 问一句，最后用 I had a … 说说你得过什么病。"},
{n:79,title:"Carol's Shopping List",topic:"购物清单 · need / have got / there isn't any",reading:"Carol is making a shopping list. What does she need?\n\nShe needs some tea and some sugar. She has got enough milk.\n\nHas she got any coffee?\n\nNo, she hasn't. Her husband drinks a lot of coffee every morning.\n\nWhat about vegetables?\n\nThere aren't any potatoes in the kitchen, and she hasn't got any tomatoes.\n\nShe must go to the shops before six o'clock.",zh:"（原创改写）卡罗尔正在写购物清单。她需要买什么？\n\n她需要些茶和糖。牛奶她已经够用了。\n\n她有咖啡吗？\n\n没有。她丈夫每天早上都喝很多咖啡。\n\n蔬菜呢？\n\n厨房里没有土豆了，她也没有西红柿。\n\n她得在六点前去一趟商店。",vocab:[{"w": "list", "ph": "/lɪst/", "en": "things written down one under another", "zh": "n. 清单；单子", "eg": "I always make a list before I shop."}, {"w": "need", "ph": "/niːd/", "en": "to want something because you do not have it", "zh": "v. 需要", "eg": "We need some tea and sugar."}, {"w": "vegetable", "ph": "/ˈvedʒtəbl/", "en": "plants you eat, like potatoes and tomatoes", "zh": "n. 蔬菜", "eg": "We haven't got any vegetables at home."}, {"w": "potato", "ph": "/pəˈteɪtəʊ/", "en": "a round white vegetable that grows underground", "zh": "n. 土豆", "eg": "There are three potatoes in the kitchen."}],exprs:[{"en": "make a shopping list", "zh": "列购物清单", "scene": "出门买东西前的准备动作，动词固定用 make。", "struct": "make a (shopping) list", "cat": "habit", "ex": ["Carol is making a shopping list.", "Make a list, or you will forget something."]}, {"en": "have got enough", "zh": "已经够了", "scene": "表示数量够用，不必再买。enough 放在名词前面。", "struct": "have/has got + enough + 名词", "cat": "dailychat", "ex": ["She has got enough milk.", "Have you got enough money?"]}, {"en": "go to the shops", "zh": "去商店买东西", "scene": "英式说法，shops 用复数，泛指「去买东西」。", "struct": "go to the shops (+ 时间)", "cat": "habit", "ex": ["She must go to the shops before six.", "I go to the shops every Saturday."]}],pats:[{"en": "主语 + need(s) + 名词 / need to + 动词", "zh": "某人需要……", "scene": "说缺什么。三单加 -s，后面接动词要用 need to do。", "struct": "主语 + need(s) + 名词 / 主语 + need(s) to + 动词原形", "cat": "dailychat", "ex": ["She needs some tea and some sugar.", "He needs to buy some bread."]}, {"en": "There isn't any … / There aren't any …", "zh": "没有……了", "scene": "说家里某样东西没了。单数用 isn't，复数用 aren't，后面都加 any。", "struct": "There + isn't + any + 不可数名词 / aren't + any + 复数名词", "cat": "dailychat", "ex": ["There aren't any potatoes in the kitchen.", "There isn't any milk in the fridge."]}],quiz:{"v": {"q": "vegetable 的意思是：", "opts": ["蔬菜", "水果", "清单"], "a": 0}, "e": {"q": "想说「牛奶已经够用了」，正确的是：", "opts": ["She has got enough milk.", "She has got milk enough.", "She has enough got milk."], "a": 0}, "p": {"q": "There ______ any potatoes in the kitchen.", "opts": ["isn't", "aren't", "haven't"], "a": 1}},speak:"说 4 句话：用 make a shopping list 起头，用 I need … 说出两样要买的东西，用 I've got enough … 说一样不用买的，最后用 There isn't/aren't any … 说家里缺了什么。"},
{n:80,title:"I Must Go to the Shops",topic:"must / need to · 购物与自理",reading:"Where are you going, Carol?\n\nI must go to the shops. We haven't got any bread.\n\nWhat do you need to buy?\n\nI need to buy bread, tea and some potatoes. And I want some fruit.\n\nHave you got any money?\n\nYes, I have. I've got fifty pounds.\n\nDo you need any help?\n\nNo, thank you. I can carry it myself. See you at seven!",zh:"（原创改写）卡罗尔，你要去哪儿？\n\n我得去趟商店，我们没面包了。\n\n你需要买什么？\n\n我要买面包、茶和一些土豆，还想买点水果。\n\n你带钱了吗？\n\n带了，我有五十英镑。\n\n需要帮忙吗？\n\n不用，谢谢。我自己拿得动。七点见！",vocab:[{"w": "money", "ph": "/ˈmʌni/", "en": "the coins and notes you use to buy things", "zh": "n. 钱", "eg": "Have you got any money with you?"}, {"w": "fruit", "ph": "/fruːt/", "en": "things like apples and bananas that grow on trees", "zh": "n. 水果", "eg": "I want to buy some fruit for the children."}, {"w": "carry", "ph": "/ˈkæri/", "en": "to take something in your hands or arms", "zh": "v. 拿；搬；提", "eg": "This bag is heavy. Can you carry it?"}, {"w": "buy", "ph": "/baɪ/", "en": "to get something by paying money", "zh": "v. 买", "eg": "I need to buy some bread and tea."}],exprs:[{"en": "go to the shops", "zh": "去商店买东西", "scene": "出门采购的常用说法，shops 习惯用复数。", "struct": "go to the shops (+ 时间)", "cat": "habit", "ex": ["I must go to the shops now.", "We go to the shops on Saturday morning."]}, {"en": "need to buy", "zh": "需要买", "scene": "need 后面接动词时必须加 to，这是最容易漏的一点。", "struct": "need to + 动词原形", "cat": "dailychat", "ex": ["I need to buy bread and tea.", "Do you need to buy anything else?"]}, {"en": "carry it myself", "zh": "我自己来拿", "scene": "婉拒别人帮忙时用，重点在句尾的反身代词。", "struct": "主语 + can + 动词 + 宾语 + 反身代词", "cat": "dailychat", "ex": ["I can carry it myself, thank you.", "He can do it himself."]}],pats:[{"en": "主语 + must + go to + 地点", "zh": "某人必须去……", "scene": "表示非去不可。must 后面永远直接跟动词原形，不加 to。", "struct": "主语 + must + go to + 地点", "cat": "dailychat", "ex": ["I must go to the shops now.", "She must go to the library this afternoon."]}, {"en": "主语 + need(s) to + 动词原形", "zh": "某人需要做……", "scene": "和 must 意思接近，但 need to 语气更客观、更日常。", "struct": "主语 + need(s) to + 动词原形", "cat": "dailychat", "ex": ["I need to buy bread, tea and some potatoes.", "He needs to leave before six."]}],quiz:{"v": {"q": "carry 的意思是：", "opts": ["拿；提", "买", "需要"], "a": 0}, "e": {"q": "想说「我需要买面包」，正确的是：", "opts": ["I need to buy bread.", "I need buy bread.", "I need buying bread."], "a": 0}, "p": {"q": "I must ______ to the shops before six o'clock.", "opts": ["to go", "go", "going"], "a": 1}},speak:"说 4 句话：用 I must go to the shops. 说明你要出门，用 I need to buy … 说出至少三样东西，用 Have you got any money? 问一句，最后用 carry it myself 婉拒帮忙。"},
{n:81,title:"Roast Beef and Potatoes",topic:"现在完成时初步 · have had / Have you had …?",reading:"Hello, Sam. Come in and sit down.\n\nIs dinner ready, Carol? I'm very hungry.\n\nIt's nearly ready. We can have dinner at seven o'clock.\n\nWhat are we having?\n\nRoast beef and potatoes. I've cooked a lot.\n\nOh, I've already had some beef today, but I can eat more.\n\nHave you had any potatoes?\n\nNo, I haven't had any today. I'm ready!",zh:"（原创改写）你好，山姆，进来坐吧。\n\n卡罗尔，饭好了吗？我饿坏了。\n\n快好了，我们七点开饭。\n\n我们吃什么？\n\n烤牛肉配土豆，我做了很多。\n\n哦，我今天已经吃过牛肉了，不过还能再吃点。\n\n你吃土豆了吗？\n\n没有，我今天还没吃土豆呢。我准备好了！",vocab:[{"w": "roast", "ph": "/rəʊst/", "en": "cooked in an oven or over a fire", "zh": "adj./v. 烤制的；烤", "eg": "We are having roast beef for dinner."}, {"w": "hungry", "ph": "/ˈhʌŋɡri/", "en": "wanting to eat", "zh": "adj. 饥饿的", "eg": "I'm very hungry. Is dinner ready?"}, {"w": "ready", "ph": "/ˈredi/", "en": "prepared; able to be used at once", "zh": "adj. 准备好的", "eg": "Dinner is nearly ready."}, {"w": "dinner", "ph": "/ˈdɪnə(r)/", "en": "the main meal of the day", "zh": "n. 正餐；晚饭", "eg": "We have dinner at seven o'clock."}],exprs:[{"en": "be ready", "zh": "准备好了；做好了", "scene": "说饭好了、人准备好了，都能用。nearly ready 是「快好了」。", "struct": "主语 + be + (nearly) ready", "cat": "dailychat", "ex": ["Is dinner ready?", "We are nearly ready. Wait a minute."]}, {"en": "have dinner", "zh": "吃晚饭", "scene": "三餐动词都用 have，不用 eat。have breakfast / lunch / dinner。", "struct": "have + breakfast/lunch/dinner (+ at + 时间)", "cat": "habit", "ex": ["We can have dinner at seven o'clock.", "They had dinner at a small restaurant."]}, {"en": "be hungry", "zh": "饿了", "scene": "「饿」是形容词，前面必须有 be 动词，不能说 I hungry。", "struct": "主语 + be + hungry/thirsty", "cat": "dailychat", "ex": ["I'm very hungry. Is dinner ready?", "Are you hungry? Let's eat something."]}],pats:[{"en": "主语 + have/has + 过去分词（现在完成时）", "zh": "某人已经……了", "scene": "讲过去发生、但和现在有关系的事（比如现在还饱着）。结构是 have + 过去分词。", "struct": "主语 + have/has + 过去分词", "cat": "dailychat", "ex": ["I've cooked a lot.", "I've already had some beef today."]}, {"en": "Have you had …? — Yes, I have. / No, I haven't.", "zh": "你吃过……了吗？——吃过了。／还没。", "scene": "have 的现在完成时。had 既是 have 的过去式也是过去分词。", "struct": "Have/Has + 主语 + had + 名词?", "cat": "dailychat", "ex": ["Have you had any potatoes? — No, I haven't.", "Has he had breakfast? — Yes, he has."]}],quiz:{"v": {"q": "ready 的意思是：", "opts": ["准备好的", "饥饿的", "烤的"], "a": 0}, "e": {"q": "想说「我饿了」，正确的是：", "opts": ["I'm very hungry.", "I very hungry.", "I have hungry."], "a": 0}, "p": {"q": "Have you ______ any potatoes today?", "opts": ["have", "had", "has"], "a": 1}},speak:"说 4 句话：用 be hungry 和 Is dinner ready? 聊一顿饭，用 have dinner at … 说开饭时间，再用 Have you had …? — Yes, I have. / No, I haven't. 问一句吃没吃过某样东西。"},
{n:82,title:"I Had…",topic:"现在完成时 · have had / just / yet",reading:"What did you have for breakfast, Sam?\n\nI had some toast and a cup of tea. I wasn't very hungry.\n\nHave you had lunch?\n\nYes, I have. I had lunch at twelve with Tom.\n\nWhat did you eat?\n\nI ate a sandwich and an apple. And I've just had a cup of coffee.\n\nHave you had any water today?\n\nNo, I haven't had any yet. I'll drink some now.",zh:"（原创改写）山姆，你早饭吃了什么？\n\n我吃了点吐司，喝了杯茶。我不太饿。\n\n你吃午饭了吗？\n\n吃了，十二点和汤姆一起吃的。\n\n你吃了什么？\n\n我吃了一个三明治和一个苹果。而且我刚喝了杯咖啡。\n\n你今天喝水了吗？\n\n还没喝。我现在就喝点。",vocab:[{"w": "breakfast", "ph": "/ˈbrekfəst/", "en": "the food you eat in the morning", "zh": "n. 早饭", "eg": "What did you have for breakfast?"}, {"w": "toast", "ph": "/təʊst/", "en": "bread cooked until it is brown and hard", "zh": "n. 吐司；烤面包片", "eg": "I had some toast and a cup of tea."}, {"w": "lunch", "ph": "/lʌntʃ/", "en": "the food you eat in the middle of the day", "zh": "n. 午饭", "eg": "I had lunch at twelve with Tom."}, {"w": "apple", "ph": "/ˈæpl/", "en": "a round hard fruit with red or green skin", "zh": "n. 苹果", "eg": "She eats an apple every afternoon."}],exprs:[{"en": "have breakfast/lunch", "zh": "吃早饭／午饭", "scene": "三餐前面既不加 the 也不加 a，直接 have + 餐名。", "struct": "have + breakfast/lunch/dinner", "cat": "habit", "ex": ["Have you had lunch? — Yes, I have.", "I had lunch at twelve."]}, {"en": "a cup of …", "zh": "一杯……", "scene": "喝茶、咖啡的量词，用 cup；喝水、牛奶常用 glass。", "struct": "a cup of + 茶/咖啡 / a glass of + 水/牛奶", "cat": "dailychat", "ex": ["I've just had a cup of coffee.", "She drinks a glass of milk every night."]}, {"en": "I've just …", "zh": "我刚刚……", "scene": "just 表示「刚刚」，放在 have 和过去分词中间。", "struct": "主语 + have/has + just + 过去分词", "cat": "dailychat", "ex": ["I've just had a cup of coffee.", "He's just finished his homework."]}],pats:[{"en": "主语 + have/has + just + 过去分词", "zh": "某人刚刚……", "scene": "just 一定要夹在 have 和过去分词中间，不能放句尾。", "struct": "主语 + have/has + just + 过去分词", "cat": "dailychat", "ex": ["I've just had a cup of coffee.", "We've just finished our dinner."]}, {"en": "Have you had … yet? — No, … haven't … yet.", "zh": "你已经……了吗？——还没。", "scene": "yet 用于疑问句和否定句，通常放句尾，表示「到现在为止」。", "struct": "Have/Has + 主语 + 过去分词 + yet?", "cat": "dailychat", "ex": ["Have you had any water today? — No, I haven't had any yet.", "Has she finished yet? — No, not yet."]}],quiz:{"v": {"q": "toast 的意思是：", "opts": ["吐司", "苹果", "三明治"], "a": 0}, "e": {"q": "想说「我刚喝了杯咖啡」，正确的是：", "opts": ["I've just had a cup of coffee.", "I have a cup of coffee just.", "I just have had a cup of coffee."], "a": 0}, "p": {"q": "Have you had any water today? — No, I ______.", "opts": ["haven't yet", "didn't", "hadn't"], "a": 0}},speak:"说 4 句话：用 What did you have for breakfast? 问对方早饭吃了什么，用 I had … 回答，再用 Have you had … yet? — No, I haven't … yet. 聊一件今天还没做的事，最后用 I've just … 说一件刚做完的事。"},
{n:83,title:"Going on a Holiday",topic:"already / yet / Have you ever …?",reading:"Hello, Carol. Where's Sam?\n\nHe's upstairs. He's having a bath.\n\nAre you going on holiday this year?\n\nYes, we are. We're going to the seaside in July.\n\nAren't you lucky! Have you packed the cases yet?\n\nI've already packed them. Sam hasn't finished his work yet.\n\nHave you ever been to the seaside in winter?\n\nNo, we haven't. But we'd like to try it!",zh:"（原创改写）你好，卡罗尔。山姆在哪儿？\n\n他在楼上，正在洗澡。\n\n你们今年要去度假吗？\n\n去，我们七月要去海边。\n\n你们可真幸运！行李箱打包好了吗？\n\n我已经打包好了。山姆还没忙完工作。\n\n你们冬天去过海边吗？\n\n没有，不过我们想试试！",vocab:[{"w": "upstairs", "ph": "/ˌʌpˈsteəz/", "en": "on a higher floor of a building", "zh": "adv. 在楼上", "eg": "He's upstairs. He's having a bath."}, {"w": "bath", "ph": "/bɑːθ/", "en": "washing your whole body in a bath of water", "zh": "n. 洗澡；浴缸", "eg": "The children have a bath every evening."}, {"w": "pack", "ph": "/pæk/", "en": "to put things into a bag or case", "zh": "v. 打包；装箱", "eg": "Have you packed the cases yet?"}, {"w": "seaside", "ph": "/ˈsiːsaɪd/", "en": "a town or place next to the sea", "zh": "n. 海边", "eg": "We're going to the seaside in July."}],exprs:[{"en": "go on holiday", "zh": "去度假", "scene": "英式说法，美式常说 go on vacation。介词固定用 on。", "struct": "go on holiday (+ 时间/地点)", "cat": "hobby", "ex": ["Are you going on holiday this year?", "We go on holiday every summer."]}, {"en": "have a bath", "zh": "洗澡（盆浴）", "scene": "泡澡用 have a bath，淋浴是 have a shower。", "struct": "have a bath / have a shower", "cat": "habit", "ex": ["He's upstairs. He's having a bath.", "I have a bath before bed."]}, {"en": "pack the cases", "zh": "收拾行李箱", "scene": "出行前的动作，也可以说 pack the bags。", "struct": "pack + the cases/bags", "cat": "hobby", "ex": ["Have you packed the cases yet?", "She packed her bag last night."]}],pats:[{"en": "主语 + have/has + already + 过去分词", "zh": "某人已经……了", "scene": "already 表示「早就做完了」，常放 have 和过去分词中间，语气带点小得意。", "struct": "主语 + have/has + already + 过去分词", "cat": "dailychat", "ex": ["I've already packed them.", "He has already finished his work."]}, {"en": "Have you ever + 过去分词 …? — Yes, … have. / No, … haven't.", "zh": "你曾经……过吗？——是的。／从来没有。", "scene": "问一辈子有没有过某种经历，ever 就是「曾经」。", "struct": "Have/Has + 主语 + ever + 过去分词 + …?", "cat": "experience", "ex": ["Have you ever been to the seaside in winter? — No, we haven't.", "Have you ever eaten Japanese food? — Yes, I have."]}],quiz:{"v": {"q": "pack 的意思是：", "opts": ["打包；装箱", "洗澡", "度假"], "a": 0}, "e": {"q": "想问「你去过海边吗（曾经）」，最合适的是：", "opts": ["Have you ever been to the seaside?", "Did you go to the seaside?", "Do you go to the seaside?"], "a": 0}, "p": {"q": "I ______ already packed the cases.", "opts": ["have", "had", "did"], "a": 0}},speak:"说 4 句话：用 Are you going on holiday? 聊出行计划，用 I've already … 说一件已经准备好的事，用 … hasn't … yet 说一件还没完成的，最后用 Have you ever …? 问对方有没有过某种经历。"},
{n:84,title:"Have You Had…?",topic:"现在完成时的疑问与否定 · just / yet",reading:"Have you had your breakfast, children?\n\nYes, we have. We had it at seven o'clock.\n\nHave you had any milk today?\n\nYes, I've had two glasses.\n\nHave you cleaned your teeth?\n\nYes, we have. We've just cleaned them.\n\nHave you washed your hands?\n\nYes, we've just washed them.\n\nHave you finished your homework?\n\nI've finished mine, but Sue hasn't finished hers yet.\n\nHas she put her books in her bag?\n\nNot yet. She can't find her pencil case.\n\nWell, hurry up! The bus is coming.",zh:"（原创改写）孩子们，早饭吃了吗？\n\n吃了，我们七点吃的。\n\n今天喝牛奶了吗？\n\n喝了，我喝了两杯。\n\n刷牙了吗？\n\n刷了，我们刚刷过。\n\n洗手了吗？\n\n洗了，我们刚洗过。\n\n作业写完了吗？\n\n我的写完了，不过苏的还没写完。\n\n她把书放进书包了吗？\n\n还没有，她找不到铅笔盒了。\n\n那快点儿！车来了。",vocab:[{"w": "wash", "ph": "/wɒʃ/", "en": "to clean something with water", "zh": "v. 洗", "eg": "Have you washed your hands?"}, {"w": "hand", "ph": "/hænd/", "en": "the part of your body at the end of your arm", "zh": "n. 手", "eg": "Wash your hands before dinner."}, {"w": "hurry", "ph": "/ˈhʌri/", "en": "to move or do something quickly", "zh": "v. 匆忙；赶快", "eg": "Hurry up! We are late for school."}, {"w": "glass", "ph": "/ɡlɑːs/", "en": "a cup without a handle, used for water or milk", "zh": "n. 玻璃杯", "eg": "I've had two glasses of milk today."}],exprs:[{"en": "wash one's hands", "zh": "洗手", "scene": "饭前便后的固定说法，one's 要跟着主语变成 my/your/his…", "struct": "wash + my/your/his/her + hands", "cat": "habit", "ex": ["Have you washed your hands?", "He washes his hands before every meal."]}, {"en": "Hurry up!", "zh": "快点！", "scene": "催人的常用句，语气直接但不算粗鲁。", "struct": "Hurry up!（祈使句）", "cat": "dailychat", "ex": ["Hurry up! The bus is coming.", "Hurry up, or we will be late."]}, {"en": "finish one's homework", "zh": "完成某人的作业", "scene": "说作业做完了没有，one's 跟着主语变。", "struct": "finish + my/your/his/her + homework", "cat": "work", "ex": ["I've finished mine, but Sue hasn't finished hers yet.", "Have you finished your homework?"]}],pats:[{"en": "Have you + 过去分词 + …? — Yes, … have. / No, … haven't.", "zh": "你已经……了吗？——是的。／还没有。", "scene": "现在完成时的一般疑问句，问某件事到现在做没做完。", "struct": "Have/Has + 主语 + 过去分词 (+ yet)?", "cat": "dailychat", "ex": ["Have you had your breakfast? — Yes, we have.", "Have you finished your homework? — No, I haven't."]}, {"en": "主语 + haven't/hasn't + 过去分词 + yet", "zh": "某人还没……", "scene": "yet 几乎总是待在句尾，和「还没」配套出现。", "struct": "主语 + haven't/hasn't + 过去分词 + yet", "cat": "dailychat", "ex": ["Sue hasn't finished hers yet.", "I haven't had any water today yet."]}],quiz:{"v": {"q": "hurry 的意思是：", "opts": ["赶快；匆忙", "洗", "完成"], "a": 0}, "e": {"q": "想催别人「快点」，应该说：", "opts": ["Hurry up!", "Wash up!", "Finish up!"], "a": 0}, "p": {"q": "Sue hasn't finished hers ______.", "opts": ["yet", "just", "already"], "a": 0}},speak:"说 4 句话：用 Have you had/finished/washed …? 连问三件出门前要完成的事并自己回答，其中至少一句用 just，一句用 yet（否定形式）。"},
{n:85,title:"Paris in the Spring",topic:"have been to · ever / never",reading:"Have you ever been to Paris, Ken?\n\nYes, I have. I was there in April.\n\nWas it nice?\n\nIt was lovely. The weather was warm and the parks were green.\n\nHave you ever been there in spring?\n\nNo, I've never been there in spring. Was it beautiful?\n\nOh yes. I've never seen so many flowers. But it rained a lot, too.\n\nI'd love to go next year.",zh:"（原创改写）肯，你去过巴黎吗？\n\n去过，我四月份在那儿。\n\n那儿好吗？\n\n特别好。天气暖和，公园里绿油油的。\n\n你春天去过那儿吗？\n\n没有，我从来没在春天去过。春天美吗？\n\n美极了。我从没见过那么多花。不过雨也下得多。\n\n我明年也想去。",vocab:[{"w": "Paris", "ph": "/ˈpærɪs/", "en": "the capital city of France", "zh": "n. 巴黎", "eg": "Have you ever been to Paris?"}, {"w": "spring", "ph": "/sprɪŋ/", "en": "the season after winter", "zh": "n. 春天", "eg": "I've never been there in spring."}, {"w": "lovely", "ph": "/ˈlʌvli/", "en": "very nice or beautiful", "zh": "adj. 可爱的；美好的", "eg": "It was a lovely day by the sea."}, {"w": "flower", "ph": "/ˈflaʊə(r)/", "en": "the coloured part of a plant", "zh": "n. 花", "eg": "I've never seen so many flowers."}],exprs:[{"en": "have been to …", "zh": "去过……（已经回来了）", "scene": "讲人生经历：去过某地和回来了。注意它和 have gone to（人还在那儿）不一样。", "struct": "have/has been to + 地点", "cat": "experience", "ex": ["Have you ever been to Paris?", "I've been to London three times."]}, {"en": "in spring / in April", "zh": "在春天／在四月", "scene": "季节、月份前面都用介词 in。", "struct": "in + 季节/月份", "cat": "dailychat", "ex": ["I was there in April.", "We go to the seaside in summer."]}, {"en": "I'd love to …", "zh": "我很想……", "scene": "表达强烈的愿望，比 I want to 更客气、更有感情。", "struct": "I'd love to + 动词原形", "cat": "opinion", "ex": ["I'd love to go next year.", "I'd love to meet your family."]}],pats:[{"en": "Have you ever been to …? — Yes, I have. / No, I've never been there.", "zh": "你去过……吗？——去过。／从来没去过。", "scene": "问人生经历。ever 是「曾经」，never 是「从未」，两者是一对。", "struct": "Have/Has + 主语 + ever + been to + 地点?", "cat": "experience", "ex": ["Have you ever been to Paris? — Yes, I have.", "Have you ever been there in winter? — No, I haven't."]}, {"en": "主语 + have/has never + 过去分词", "zh": "某人从未……过", "scene": "never 自带否定，句子里不能再加 not。常和 before 一起用。", "struct": "主语 + have/has + never + 过去分词 (+ before)", "cat": "experience", "ex": ["I've never been there in spring.", "She has never tried Chinese food."]}],quiz:{"v": {"q": "lovely 的意思是：", "opts": ["美好的", "可怕的", "昂贵的"], "a": 0}, "e": {"q": "想问「你去过巴黎吗」，应该说：", "opts": ["Have you ever been to Paris?", "Have you ever gone to Paris?", "Did you ever go Paris?"], "a": 0}, "p": {"q": "I ______ never been there in spring.", "opts": ["have", "am", "did"], "a": 0}},speak:"说 4 句话：用 Have you ever been to …? 问对方去过某地没有，用 Yes, I have. I was there in … 或 I've never been there. 回答，最后用 I'd love to … 表达你也想去。"},
{n:86,title:"What Have You Done?",topic:"现在完成时 vs 一般过去时 · 有／无具体过去时间",reading:"What have you done to my car, Tom?\n\nI've washed it. Look, it's clean now.\n\nWhen did you wash it?\n\nI washed it an hour ago, after lunch.\n\nHave you cleaned the windows?\n\nYes, I have. I cleaned them at two o'clock.\n\nHave you washed the seats?\n\nNo, I haven't. I'll do them after the windows.\n\nHave you finished?\n\nNot quite. I haven't put the things away yet. I'll do it now.",zh:"（原创改写）汤姆，你把我的车怎么了？\n\n我洗了车。你看，现在干净了。\n\n你什么时候洗的？\n\n一小时前洗的，午饭后。\n\n窗户擦了吗？\n\n擦了，我两点擦的。\n\n座椅洗了吗？\n\n还没。我擦完窗户就洗。\n\n你做完了吗？\n\n还没完全好。我还没把东西收起来，现在就收。",vocab:[{"w": "window", "ph": "/ˈwɪndəʊ/", "en": "the glass part of a wall or car", "zh": "n. 窗户", "eg": "Have you cleaned the windows?"}, {"w": "hour", "ph": "/ˈaʊə(r)/", "en": "sixty minutes", "zh": "n. 小时", "eg": "I washed it an hour ago."}, {"w": "quite", "ph": "/kwaɪt/", "en": "completely; very", "zh": "adv. 相当；完全", "eg": "Not quite. There is still work to do."}, {"w": "away", "ph": "/əˈweɪ/", "en": "to another place; not here", "zh": "adv. 离开；收起来", "eg": "Put your books away after class."}],exprs:[{"en": "What have you done to …?", "zh": "你把……怎么了？", "scene": "发现东西被动过，又惊又气地问一句。语气可以故意夸张。", "struct": "What have you done to + 名词?", "cat": "humor", "ex": ["What have you done to my car?", "What have you done to my computer?"]}, {"en": "an hour ago", "zh": "一小时前", "scene": "ago 前必须是「一段」时间，动词用过去式。", "struct": "an hour ago / two days ago / a week ago", "cat": "experience", "ex": ["I washed it an hour ago.", "She left an hour ago."]}, {"en": "put something away", "zh": "把某物收起来", "scene": "用完的东西归位，家长对孩子说得最多的一句。", "struct": "put + 物 + away", "cat": "habit", "ex": ["I haven't put the things away yet.", "Please put your toys away."]}],pats:[{"en": "I've + 过去分词（不提时间）/ I + 过去式 + 具体过去时间", "zh": "我已经……了／我（在某时）……了", "scene": "现在完成时只说「做没做」，一般过去时才说「什么时候做的」。一给具体时间就得换过去时。", "struct": "I've + 过去分词 (+ 无时间) / I + 过去式 + an hour ago / at two o'clock", "cat": "experience", "ex": ["I've washed it.", "I washed it an hour ago."]}, {"en": "Have you + 过去分词 …? — Yes, I have. I + 过去式 + 过去时间.", "zh": "你……了吗？——做了，我（某时）做的。", "scene": "先用完成时确认结果，再用过去时补上具体时间，这是最自然的组合。", "struct": "Have you + 过去分词? — Yes, I have. I + 过去式 + 过去时间.", "cat": "experience", "ex": ["Have you cleaned the windows? — Yes, I have. I cleaned them at two.", "Have you finished? — Yes, I finished it this morning."]}],quiz:{"v": {"q": "away 的意思是：", "opts": ["离开；收起来", "靠近", "回来"], "a": 0}, "e": {"q": "想问「你把我的车怎么了」，应该说：", "opts": ["What have you done to my car?", "What did you do my car?", "What have you done with my car?"], "a": 0}, "p": {"q": "Have you cleaned the windows? — Yes, I ______. I cleaned them at two.", "opts": ["have", "did", "do"], "a": 0}},speak:"说 4 句话：用 What have you done to …? 开头问一件事，用 I've + 过去分词 回答，再用 When did you …? — I + 过去式 + ago 补上具体时间，最后用 I haven't … yet 说一件还没做的。"},
{n:87,title:"A Car Crash",topic:"for 与 since · 现在完成时表示持续",reading:"Is your father's car ready yet?\n\nNo, it isn't. The mechanics are still working on it.\n\nWhen did he bring it here?\n\nHe brought it here three days ago, after the crash.\n\nHow long have they had it?\n\nThey've had it since Monday.\n\nHave they finished the work?\n\nNo, they haven't. They have worked on it for three days.\n\nLet's come back tomorrow. I hope it will be ready then.",zh:"（原创改写）你爸爸的车修好了吗？\n\n还没有。修车师傅还在修。\n\n他什么时候把车送来的？\n\n三天前送来的，撞车之后。\n\n他们拿到车多久了？\n\n从周一起就在他们那儿了。\n\n他们修完了吗？\n\n还没有。他们已经修了三天了。\n\n我们明天再来吧，希望到时候能好。",vocab:[{"w": "crash", "ph": "/kræʃ/", "en": "an accident when one thing hits another hard", "zh": "n. 碰撞；车祸", "eg": "He brought the car here after the crash."}, {"w": "mechanic", "ph": "/məˈkænɪk/", "en": "a person who repairs cars and machines", "zh": "n. 修理工；机修工", "eg": "The mechanics are still working on it."}, {"w": "since", "ph": "/sɪns/", "en": "from a time in the past until now", "zh": "prep./conj. 自从", "eg": "They've had it since Monday."}, {"w": "Monday", "ph": "/ˈmʌndeɪ/", "en": "the first day of the working week", "zh": "n. 星期一", "eg": "We have not seen him since Monday."}],exprs:[{"en": "work on something", "zh": "忙着做／修理某物", "scene": "强调「正在处理中」，还没完。比 repair 适用范围广。", "struct": "work on + 名词", "cat": "work", "ex": ["The mechanics are still working on it.", "I'm working on a new plan."]}, {"en": "bring something here", "zh": "把某物带来这儿", "scene": "bring 是「带过来」，take 是「带过去」，方向别搞反。", "struct": "bring + 物 + here / take + 物 + there", "cat": "dailychat", "ex": ["He brought it here three days ago.", "Please bring your book here tomorrow."]}, {"en": "come back", "zh": "回来", "scene": "约下次再来，后面可以直接加时间。", "struct": "come back + 时间", "cat": "dailychat", "ex": ["Let's come back tomorrow.", "He came back very late last night."]}],pats:[{"en": "主语 + have/has + 过去分词 + since + 时间点", "zh": "某人从……起就一直……", "scene": "since 后面接的是「时间点」：since Monday、since 2018、since last week。", "struct": "主语 + have/has + 过去分词 + since + 时间点", "cat": "experience", "ex": ["They've had it since Monday.", "I've known her since 2016."]}, {"en": "主语 + have/has + 过去分词 + for + 时间段", "zh": "某人已经……（多长时间）了", "scene": "for 后面接的是「一段」时间：for three days、for ten years。", "struct": "主语 + have/has + 过去分词 + for + 时间段", "cat": "experience", "ex": ["They have worked on it for three days.", "He has lived here for twenty years."]}],quiz:{"v": {"q": "mechanic 的意思是：", "opts": ["修理工", "司机", "警察"], "a": 0}, "e": {"q": "想说「他们从周一起就拿到车了」，正确的是：", "opts": ["They've had it since Monday.", "They've had it for Monday.", "They have it since Monday."], "a": 0}, "p": {"q": "They have worked on it ______ three days.", "opts": ["since", "for", "ago"], "a": 1}},speak:"说 4 句话：用 Have they finished … yet? 问一件事做没做完，用 since + 时间点 和 for + 时间段 各说一句，最后用 come back + 时间 约下次再来。"},
{n:88,title:"Have You…Yet?",topic:"yet 在疑问句与否定句中的位置",reading:"Have you typed the letter yet, Miss Lee?\n\nYes, I have. I typed it this morning.\n\nHave you sent the emails yet?\n\nNo, I haven't sent them yet. I'll do it after lunch.\n\nHas the postman come?\n\nYes, he has. He came at ten and brought three letters.\n\nHave you read them?\n\nI've read two, but I haven't read the third one yet.\n\nIs it important? Yes, it's from the bank.",zh:"（原创改写）李小姐，信打好了吗？\n\n打好了，我今天上午打的。\n\n邮件发出去了吗？\n\n还没有，我午饭后发。\n\n邮递员来了吗？\n\n来了。他十点来的，带来三封信。\n\n你看了吗？\n\n我看了两封，第三封还没看。\n\n要紧吗？要紧，是银行寄来的。",vocab:[{"w": "type", "ph": "/taɪp/", "en": "to write something on a computer or typewriter", "zh": "v. 打字", "eg": "Have you typed the letter yet?"}, {"w": "letter", "ph": "/ˈletə(r)/", "en": "a written message sent to someone", "zh": "n. 信", "eg": "He brought three letters this morning."}, {"w": "send", "ph": "/send/", "en": "to make something go to another place", "zh": "v. 发送；寄", "eg": "I haven't sent the emails yet."}, {"w": "postman", "ph": "/ˈpəʊstmən/", "en": "a person who brings letters to your house", "zh": "n. 邮递员", "eg": "The postman comes at ten every morning."}],exprs:[{"en": "type a letter", "zh": "打一封信", "scene": "办公室里最基础的一项工作，动词用 type。", "struct": "type + a letter/an email", "cat": "work", "ex": ["Have you typed the letter yet?", "She types very fast."]}, {"en": "send an email", "zh": "发一封邮件", "scene": "send 的过去式是不规则的 sent，别写成 sended。", "struct": "send + an email/a letter + to + 人", "cat": "work", "ex": ["I haven't sent the emails yet.", "He sent me a letter last week."]}, {"en": "after lunch", "zh": "午饭后", "scene": "约时间很方便：after lunch / before dinner / after school。", "struct": "after/before + 名词", "cat": "work", "ex": ["I'll do it after lunch.", "Let's talk before dinner."]}],pats:[{"en": "Have you + 过去分词 + yet? — No, … haven't … yet.", "zh": "你已经……了吗？——还没有。", "scene": "yet 放在句尾，只用在疑问句和否定句；肯定句要换成 already。", "struct": "Have/Has + 主语 + 过去分词 + yet?", "cat": "work", "ex": ["Have you sent the emails yet? — No, I haven't sent them yet.", "Has he finished yet? — No, not yet."]}, {"en": "Yes, … have. + 主语 + 过去式 + 过去时间", "zh": "是的，已经……了。我（某时）做的。", "scene": "先给完成时答案，再用一般过去时补上具体时间，一句话里两种时态配合。", "struct": "Yes, … have/has. + 主语 + 过去式 + 过去时间", "cat": "work", "ex": ["Yes, I have. I typed it this morning.", "Yes, he has. He came at ten."]}],quiz:{"v": {"q": "postman 的意思是：", "opts": ["邮递员", "警察", "修理工"], "a": 0}, "e": {"q": "想说「我还没发邮件」，正确的是：", "opts": ["I haven't sent the emails yet.", "I haven't sent the emails already.", "I don't sent the emails yet."], "a": 0}, "p": {"q": "Have you read them? — I've read two, but I ______ the third one yet.", "opts": ["haven't read", "didn't read", "haven't readed"], "a": 0}},speak:"说 4 句话：用 Have you + 过去分词 + yet? 问三件工作上的事，其中一句用 Yes, I have. I … + 过去时间 回答，另两句用 No, I haven't … yet. 回答。"},
{n:89,title:"For Sale",topic:"How long have you …? · for 与 since",reading:"Is this house for sale?\n\nYes, it is. It's a very nice house.\n\nHow long have you lived here?\n\nI've lived here for twenty years, since 2005.\n\nTwenty years! Why do you want to move?\n\nMy children have all left home. The house is too big for us now.\n\nHow much is it?\n\nIt's three hundred thousand pounds. Would you like to look inside?\n\nYes, please. We are looking for a bigger house.",zh:"（原创改写）这房子要卖吗？\n\n是的，要卖。房子很不错。\n\n您在这儿住多久了？\n\n我在这儿住了二十年了，从 2005 年开始。\n\n二十年！您为什么要搬走？\n\n孩子们都离开家了。这房子现在对我们来说太大了。\n\n多少钱？\n\n三十万英镑。您想进去看看吗？\n\n好的，我们正想找大一点的房子。",vocab:[{"w": "sale", "ph": "/seɪl/", "en": "the act of giving something for money", "zh": "n. 出售；卖", "eg": "Is this house for sale?"}, {"w": "move", "ph": "/muːv/", "en": "to go to live in a different place", "zh": "v. 搬家；移动", "eg": "Why do you want to move?"}, {"w": "inside", "ph": "/ˌɪnˈsaɪd/", "en": "in a building or container", "zh": "adv./prep. 在里面", "eg": "Would you like to look inside?"}, {"w": "thousand", "ph": "/ˈθaʊznd/", "en": "the number 1,000", "zh": "num. 一千", "eg": "It costs three hundred thousand pounds."}],exprs:[{"en": "for sale", "zh": "待售；出售中", "scene": "挂在房子、车子上的牌子。注意它不是 on sale（打折）。", "struct": "be for sale", "cat": "dailychat", "ex": ["Is this house for sale?", "Their old car is for sale."]}, {"en": "How long have you …?", "zh": "你……多久了？", "scene": "问某件事持续了多长时间，回答用 for 或 since。", "struct": "How long + have/has + 主语 + 过去分词?", "cat": "dailychat", "ex": ["How long have you lived here?", "How long has she worked in this school?"]}, {"en": "look inside", "zh": "进去看看", "scene": "看房、看店时邀请对方进内部参观。", "struct": "look inside (+ 名词)", "cat": "dailychat", "ex": ["Would you like to look inside?", "We looked inside but bought nothing."]}],pats:[{"en": "How long have you + 过去分词? — I've + 过去分词 + for/since …", "zh": "你……多久了？——我已经……（多久／从何时起）。", "scene": "问持续时间。for 接一段时长，since 接一个起点，两者都行。", "struct": "How long + have/has + 主语 + 过去分词? — 主语 + have/has + 过去分词 + for + 时间段 / since + 时间点", "cat": "experience", "ex": ["How long have you lived here? — I've lived here for twenty years.", "How long have you lived here? — I've lived here since 2005."]}, {"en": "主语 + be + too + 形容词 + for + 人", "zh": "……对某人来说太……了", "scene": "说明为什么不合适，for 后面接「对谁而言」。", "struct": "主语 + be + too + 形容词 + for + 人", "cat": "opinion", "ex": ["The house is too big for us now.", "This shirt is too small for my brother."]}],quiz:{"v": {"q": "for sale 的意思是：", "opts": ["待售；出售中", "打折", "已售出"], "a": 0}, "e": {"q": "想问对方在这儿住了多久，应该说：", "opts": ["How long have you lived here?", "How often have you lived here?", "How much have you lived here?"], "a": 0}, "p": {"q": "I've lived here ______ twenty years, ______ 2005.", "opts": ["for, since", "since, for", "for, for"], "a": 0}},speak:"说 4 句话：用 Is this … for sale? 问一样东西卖不卖，用 How long have you …? 问对方拥有它多久并用 for / since 回答，最后用 be too + 形容词 + for + 人 说明为什么要出手。"},
{n:90,title:"How Long Have You Known Him?",topic:"for 与 since 的区别 · 持续到现在",reading:"How long have you known Ben?\n\nI've known him for six years, since we were at school together.\n\nHave you ever worked with him?\n\nYes, I have. We worked in the same shop two years ago.\n\nHow long have you had this bike?\n\nI've had it since last March. It's still very good.\n\nHow long have they been married?\n\nThey've been married for ten years. They met at university.",zh:"（原创改写）你认识本多久了？\n\n我认识他六年了，从我们一起上学那会儿开始。\n\n你和他一起工作过吗？\n\n有过。两年前我们在同一家店工作。\n\n这辆自行车你骑多久了？\n\n从去年三月开始的，现在还很好骑。\n\n他们结婚多久了？\n\n他们结婚十年了，是在大学认识的。",vocab:[{"w": "know", "ph": "/nəʊ/", "en": "to have met someone or learned something before", "zh": "v. 认识；知道", "eg": "I've known him for six years."}, {"w": "since", "ph": "/sɪns/", "en": "from a past time until now", "zh": "prep./conj. 自从", "eg": "I've had it since last March."}, {"w": "married", "ph": "/ˈmærid/", "en": "having a husband or wife", "zh": "adj. 已婚的", "eg": "They have been married for ten years."}, {"w": "March", "ph": "/mɑːtʃ/", "en": "the third month of the year", "zh": "n. 三月", "eg": "I've had this bike since last March."}],exprs:[{"en": "for six years", "zh": "长达六年", "scene": "for 后面跟「一段」时间，回答 How long 的提问。", "struct": "for + 数字 + 时间单位", "cat": "experience", "ex": ["I've known him for six years.", "She has worked here for two months."]}, {"en": "since last March", "zh": "从去年三月起", "scene": "since 后面跟「一个起点」，可以是时间点，也可以是一句话。", "struct": "since + 时间点 / since + 主语 + 过去式", "cat": "experience", "ex": ["I've had it since last March.", "We've known each other since we were children."]}, {"en": "in the same shop", "zh": "在同一家店里", "scene": "强调「同一个」，same 前面永远有 the。", "struct": "the same + 名词", "cat": "work", "ex": ["We worked in the same shop two years ago.", "They go to the same school."]}],pats:[{"en": "for + 时间段 vs since + 时间点", "zh": "（长达）…… vs （自从）……", "scene": "最容易混的一对：for 回答「多久」，since 回答「从什么时候起」。", "struct": "for + 一段时间 / since + 某个起点", "cat": "experience", "ex": ["I've known him for six years.", "I've known him since we were at school."]}, {"en": "How long have you + 过去分词 + 名词?", "zh": "你（拥有／认识）……多久了？", "scene": "How long 后面可以带宾语，比如 known him、had this bike。", "struct": "How long + have/has + 主语 + 过去分词 + 宾语?", "cat": "dailychat", "ex": ["How long have you known Ben?", "How long have you had this bike?"]}],quiz:{"v": {"q": "married 的意思是：", "opts": ["已婚的", "单身的", "认识的"], "a": 0}, "e": {"q": "「I've known him since we were at school」中，since 后面接的是：", "opts": ["一个起点（一句话）", "一段时间", "一个终点"], "a": 0}, "p": {"q": "They've been married ______ ten years.", "opts": ["for", "since", "ago"], "a": 0}},speak:"说 4 句话：用 How long have you known …? 和 How long have you had …? 各问一次，回答里一个用 for + 时间段，一个用 since + 时间点，最后用 in the same … 补充一个共同经历。"},
{n:91,title:"Poor Ian!",topic:"just / already / yet 的位置",reading:"Has Ian sold his house yet?\n\nYes, he has. He sold it last week.\n\nHas he moved to his new house yet?\n\nNo, not yet. He's still here. He's going to move tomorrow.\n\nHe's a very nice person. We'll all miss him.\n\nWhen will he leave?\n\nHe's already packed his bags. He'll leave at eight in the morning.\n\nPoor Ian! He has worked here for fifteen years.",zh:"（原创改写）伊恩把房子卖了吗？\n\n卖了，上周卖的。\n\n他搬到新房子去了吗？\n\n还没有。他还在这儿，打算明天搬。\n\n他人很好，我们都会想他的。\n\n他什么时候走？\n\n他已经收拾好行李了，早上八点出发。\n\n可怜的伊恩！他在这儿工作十五年了。",vocab:[{"w": "sell", "ph": "/sel/", "en": "to give something to someone for money", "zh": "v. 卖", "eg": "He sold his house last week."}, {"w": "leave", "ph": "/liːv/", "en": "to go away from a place", "zh": "v. 离开", "eg": "He'll leave at eight in the morning."}, {"w": "miss", "ph": "/mɪs/", "en": "to feel sad because someone is not here", "zh": "v. 想念；错过", "eg": "We'll all miss him when he goes."}, {"w": "person", "ph": "/ˈpɜːsn/", "en": "a man, woman or child", "zh": "n. 人", "eg": "He's a very nice person."}],exprs:[{"en": "Poor Ian!", "zh": "可怜的伊恩！", "scene": "对别人的遭遇表示同情，Poor 放在人名前面。", "struct": "Poor + 人名/代词!", "cat": "emotion", "ex": ["Poor Ian! He has worked here for so long.", "Poor thing! Did you hurt your leg?"]}, {"en": "Not yet.", "zh": "还没有。", "scene": "回答完成时提问最省事的否定简答，完整句是 … hasn't … yet。", "struct": "Not yet.（单独成句）", "cat": "dailychat", "ex": ["Has he moved yet? — No, not yet.", "Have you finished? — Not yet."]}, {"en": "miss somebody", "zh": "想念某人", "scene": "分别时、送别后说的话，后面直接跟人。", "struct": "miss + 人/地方", "cat": "emotion", "ex": ["We'll all miss him.", "I miss my old friends very much."]}],pats:[{"en": "主语 + have/has + already/just + 过去分词", "zh": "某人已经／刚刚……了", "scene": "already 和 just 都夹在 have 和过去分词中间，不能放句尾。", "struct": "主语 + have/has + already/just + 过去分词", "cat": "dailychat", "ex": ["He's already packed his bags.", "I've just finished my work."]}, {"en": "主语 + haven't/hasn't + 过去分词 + yet / Not yet.", "zh": "某人还没……／还没有。", "scene": "yet 是 yet 家族里唯一一个待在句尾的，而且只出现在疑问句和否定句。", "struct": "主语 + haven't/hasn't + 过去分词 + yet", "cat": "dailychat", "ex": ["Has he moved yet? — No, he hasn't moved yet.", "I haven't had breakfast yet."]}],quiz:{"v": {"q": "miss（此处的意思是）：", "opts": ["想念", "错过", "女士"], "a": 0}, "e": {"q": "想说「他已经收拾好行李了」，正确的是：", "opts": ["He's already packed his bags.", "He already has packed his bags.", "He has packed his bags already yet."], "a": 0}, "p": {"q": "Has he moved to his new house yet? — No, ______.", "opts": ["not yet", "not already", "not just"], "a": 0}},speak:"说 4 句话：用 Has … yet? 问两件事做没做，一句用 Yes, … has/have. 加过去时间回答，一句用 Not yet. 回答，再用 already 或 just 说一件已经完成的事。"},
{n:92,title:"When Did He Move?",topic:"现在完成时 vs 一般过去时 · for months / ever since",reading:"When did Ian move to London?\n\nHe moved there in 2015. He has lived there ever since.\n\nHave you seen him lately?\n\nNo, I haven't seen him for months.\n\nDid you speak to him last week?\n\nYes, I did. He telephoned me on Friday.\n\nWhat did he say?\n\nHe said he likes his new job, but he misses his old friends.\n\nDid he tell you his new address? Yes, he did. I've written it in my book.",zh:"（原创改写）伊恩什么时候搬到伦敦的？\n\n他 2015 年搬过去的，从那以后就一直住在那儿。\n\n你最近见到他了吗？\n\n没有，我好几个月没见他了。\n\n上周你和他说话了吗？\n\n说了。他周五给我打了电话。\n\n他说什么了？\n\n他说他喜欢新工作，但想念老朋友。\n\n他告诉你新地址了吗？说了，我记在本子上了。",vocab:[{"w": "lately", "ph": "/ˈleɪtli/", "en": "in the recent past; recently", "zh": "adv. 最近；近来", "eg": "Have you seen him lately?"}, {"w": "month", "ph": "/mʌnθ/", "en": "about thirty days", "zh": "n. 月；月份", "eg": "I haven't seen him for months."}, {"w": "job", "ph": "/dʒɒb/", "en": "the work you do to earn money", "zh": "n. 工作", "eg": "He likes his new job very much."}, {"w": "Friday", "ph": "/ˈfraɪdeɪ/", "en": "the day between Thursday and Saturday", "zh": "n. 星期五", "eg": "He telephoned me on Friday."}],exprs:[{"en": "ever since", "zh": "从那以后一直", "scene": "强调从某个时间点起一直没变，语气比单纯的 since 更强。", "struct": "主语 + have/has + 过去分词 + ever since", "cat": "experience", "ex": ["He has lived there ever since.", "We've been friends ever since."]}, {"en": "for months", "zh": "好几个月（没）", "scene": "for 加复数时间单位，表示「长达好几个月」，常用于否定句。", "struct": "for + 复数时间单位（months/years/days）", "cat": "experience", "ex": ["I haven't seen him for months.", "They haven't written for years."]}, {"en": "miss one's old friends", "zh": "想念老朋友", "scene": "换了环境以后表达怀念，old 在这里是「老交情」不是「年纪大」。", "struct": "miss + one's + old friends/school/home", "cat": "emotion", "ex": ["He misses his old friends.", "I miss my old school."]}],pats:[{"en": "一般过去时（具体过去时间）vs 现在完成时（for/since）", "zh": "（某时）做了 vs 已经（多久）了", "scene": "只要出现 in 2015、last week、on Friday 这类具体过去时间，就必须用一般过去时。", "struct": "主语 + 过去式 + 具体过去时间 / 主语 + have/has + 过去分词 + for/since …", "cat": "experience", "ex": ["He moved there in 2015.", "He has lived there ever since."]}, {"en": "Have you seen … lately? — No, I haven't seen … for …", "zh": "你最近见过……吗？——没有，我……没见过了。", "scene": "lately 常和现在完成时搭配，回答里用 for + 一段时间说明多久没见。", "struct": "Have/Has + 主语 + seen + 人 + lately?", "cat": "dailychat", "ex": ["Have you seen him lately? — No, I haven't seen him for months.", "Have you seen her lately? — No, not for weeks."]}],quiz:{"v": {"q": "lately 的意思是：", "opts": ["最近", "迟到地", "后来"], "a": 0}, "e": {"q": "想说「我好几个月没见他了」，正确的是：", "opts": ["I haven't seen him for months.", "I don't see him for months.", "I haven't seen him since months."], "a": 0}, "p": {"q": "He moved there in 2015. He ______ there ever since.", "opts": ["has lived", "lived", "lives"], "a": 0}},speak:"说 4 句话：用 When did …? 问一个过去动作的时间并用过去式回答，用 主语 + have/has + 过去分词 + ever since 说明从那以后一直如此，再用 Have you seen … lately? — No, I haven't seen … for … 聊一位老朋友。"},
{n:93,title:"Our New Neighbour",topic:"ever / never · 现在完成时与过去时混用",reading:"Have you met our new neighbour?\n\nNo, I haven't met him yet. What's his name?\n\nHis name is Mr. Hill. He moved in last Saturday.\n\nWhere did he come from?\n\nHe came from Manchester. He has never lived in the south before.\n\nHas he ever worked in a school?\n\nYes, he has. He taught maths for twelve years.\n\nHe sounds interesting. Let's visit him this evening.\n\nGood idea. I'll take some flowers.",zh:"（原创改写）你见过我们的新邻居吗？\n\n还没有，他叫什么名字？\n\n他叫希尔先生，上周六搬进来的。\n\n他是从哪儿来的？\n\n他来自曼彻斯特，以前从没在南方住过。\n\n他在学校工作过吗？\n\n工作过，他教了十二年数学。\n\n听起来挺有意思的，我们今晚去拜访他吧。\n\n好主意，我带些花去。",vocab:[{"w": "neighbour", "ph": "/ˈneɪbə(r)/", "en": "a person who lives near you", "zh": "n. 邻居", "eg": "Have you met our new neighbour?"}, {"w": "south", "ph": "/saʊθ/", "en": "the direction opposite to north", "zh": "n. 南方", "eg": "He has never lived in the south before."}, {"w": "maths", "ph": "/mæθs/", "en": "the study of numbers and shapes", "zh": "n. 数学", "eg": "He taught maths for twelve years."}, {"w": "teach", "ph": "/tiːtʃ/", "en": "to give lessons to students", "zh": "v. 教", "eg": "She teaches English at a small school."}],exprs:[{"en": "move in", "zh": "搬进来", "scene": "搬进新家。搬走是 move out，搬家是 move house。", "struct": "move in / move out (+ 时间)", "cat": "dailychat", "ex": ["He moved in last Saturday.", "Our new neighbours moved in yesterday."]}, {"en": "come from …", "zh": "来自……", "scene": "说某人的老家。问句里 did 一出，come 就打回原形。", "struct": "Where did + 主语 + come from? — 主语 + came from + 地点", "cat": "dailychat", "ex": ["Where did he come from? — He came from Manchester.", "She comes from a small town."]}, {"en": "sound interesting", "zh": "听起来有意思", "scene": "对刚听到的人或事发表第一反应，sound 后面直接跟形容词。", "struct": "主语 + sound(s) + 形容词", "cat": "opinion", "ex": ["He sounds interesting.", "That sounds like a good idea."]}],pats:[{"en": "Have you met … yet? — No, I haven't met … yet.", "zh": "你见过……了吗？——还没有。", "scene": "meet 的过去分词是不规则的 met，别写成 meeted。", "struct": "Have/Has + 主语 + met + 人 + yet?", "cat": "dailychat", "ex": ["Have you met our new neighbour? — No, I haven't met him yet.", "Have you met her parents yet?"]}, {"en": "主语 + have/has never + 过去分词 (+ before)", "zh": "某人从未……过", "scene": "never 表示零经历，句尾常加 before 加强语气。", "struct": "主语 + have/has + never + 过去分词 (+ before)", "cat": "experience", "ex": ["He has never lived in the south before.", "I've never been there in winter."]}],quiz:{"v": {"q": "neighbour 的意思是：", "opts": ["邻居", "同事", "同学"], "a": 0}, "e": {"q": "想说「他上周六搬进来的」，正确的是：", "opts": ["He moved in last Saturday.", "He moved at last Saturday.", "He has moved in last Saturday."], "a": 0}, "p": {"q": "He has never ______ in the south before.", "opts": ["live", "lived", "living"], "a": 1}},speak:"说 4 句话：用 Have you met … yet? 问见没见过某人，用 He moved in + 过去时间 和 Where did he come from? 介绍背景，最后用 have/has never + 过去分词 说一件他从没做过的事。"},
{n:94,title:"When Did You Go There?",topic:"现在完成时 vs 一般过去时 · 经历与具体时间",reading:"Have you ever been to London?\n\nYes, I have. I've been there three times.\n\nWhen did you go there?\n\nI went there in 2019, and again last year.\n\nDid you go by train?\n\nNo, I didn't. I went by plane. It took only two hours.\n\nHave you ever been there in winter?\n\nNo, I haven't. I've never been there in winter.\n\nYou must go in December. The lights are beautiful.",zh:"（原创改写）你去过伦敦吗？\n\n去过，我去过三次。\n\n你什么时候去的？\n\n我 2019 年去过，去年又去了一次。\n\n你坐火车去的吗？\n\n不是，我坐飞机去的，只要两个小时。\n\n你冬天去过那儿吗？\n\n没有，我从来没在冬天去过。\n\n你一定要十二月去一趟，灯特别漂亮。",vocab:[{"w": "London", "ph": "/ˈlʌndən/", "en": "the capital city of Britain", "zh": "n. 伦敦", "eg": "Have you ever been to London?"}, {"w": "train", "ph": "/treɪn/", "en": "a long vehicle that runs on rails", "zh": "n. 火车", "eg": "Did you go by train?"}, {"w": "plane", "ph": "/pleɪn/", "en": "a vehicle that flies in the air", "zh": "n. 飞机", "eg": "I went there by plane."}, {"w": "again", "ph": "/əˈɡen/", "en": "one more time", "zh": "adv. 再一次", "eg": "I went there in 2019, and again last year."}],exprs:[{"en": "have been there … times", "zh": "去过那儿……次", "scene": "说去过几次。一次用 once，两次用 twice，三次以上用 three times。", "struct": "have/has been + 地点 + once/twice/three times", "cat": "experience", "ex": ["I've been there three times.", "She has been to Paris twice."]}, {"en": "go by train / by plane", "zh": "坐火车／坐飞机去", "scene": "交通方式用 by，中间不加冠词。走路是 on foot。", "struct": "go + 地点 + by + 交通工具", "cat": "dailychat", "ex": ["I went by plane. It took only two hours.", "Did you go by train?"]}, {"en": "It takes …", "zh": "花费（多少时间）", "scene": "说路上花多久，主语用 it，说过去用 took。", "struct": "It takes/took + 时间段", "cat": "dailychat", "ex": ["It took only two hours.", "It takes ten minutes on foot."]}],pats:[{"en": "Have you ever been to …? — Yes, I have. I've been there … times.", "zh": "你去过……吗？——去过，我去过……次。", "scene": "问「有没有过某种经历」，回答只说次数、不说时间。", "struct": "Have/Has + 主语 + ever + been to + 地点?", "cat": "experience", "ex": ["Have you ever been to London? — Yes, I've been there three times.", "Have you ever been to Paris? — No, never."]}, {"en": "When did you go there? — I went there + 过去时间", "zh": "你什么时候去的？——我……时候去的。", "scene": "一追问具体时间，就立刻从现在完成时切换到一般过去时。", "struct": "When + did + 主语 + go there? — 主语 + went there + 过去时间", "cat": "experience", "ex": ["When did you go there? — I went there in 2019.", "When did she go there? — She went there last year."]}],quiz:{"v": {"q": "again 的意思是：", "opts": ["再一次", "第一次", "几乎"], "a": 0}, "e": {"q": "想说「我去过那儿三次」，正确的是：", "opts": ["I've been there three times.", "I'm been there three times.", "I have been there three time."], "a": 0}, "p": {"q": "When did you go there? — I ______ there in 2019.", "opts": ["went", "have gone", "go"], "a": 0}},speak:"说 4 句话：用 Have you ever been to …? 问对方有没有去过某地，用 I've been there … times. 回答，再用 When did you go there? — I went there in … 追问时间，最后用 go by train/plane 说怎么去的。"},
{n:95,title:"Tickets, Please",topic:"yet / just / never · 现在完成时与 ago 的配合",reading:"Tickets, please. Have you got your tickets?\n\nYes, here you are. I bought them at the station.\n\nWhen did you buy them?\n\nI bought them ten minutes ago. The train leaves at four.\n\nHave you got the right train?\n\nYes, this is the four o'clock train to Bristol.\n\nHave you been on this train before?\n\nNo, I've never been to Bristol. This is my first visit.\n\nWell, enjoy your trip!",zh:"（原创改写）请出示车票。您的票带了吗？\n\n带了，给您。我在车站买的。\n\n您什么时候买的？\n\n十分钟前买的。火车四点开。\n\n您坐的是正确的车次吗？\n\n是的，这是四点开往布里斯托的火车。\n\n您以前坐过这趟车吗？\n\n没有，我从没去过布里斯托，这是第一次。\n\n那祝您旅途愉快！",vocab:[{"w": "ticket", "ph": "/ˈtɪkɪt/", "en": "a piece of paper that lets you travel or go in", "zh": "n. 票", "eg": "Have you got your tickets?"}, {"w": "station", "ph": "/ˈsteɪʃn/", "en": "a place where trains or buses stop", "zh": "n. 车站", "eg": "I bought them at the station."}, {"w": "right", "ph": "/raɪt/", "en": "correct; the one you want", "zh": "adj. 正确的；合适的", "eg": "Have you got the right train?"}, {"w": "before", "ph": "/bɪˈfɔː(r)/", "en": "at any time until now", "zh": "adv. 以前", "eg": "Have you been on this train before?"}],exprs:[{"en": "Tickets, please.", "zh": "请出示车票。", "scene": "列车员查票时的标准用语，简短有力。", "struct": "Tickets, please.（名词 + please）", "cat": "dailychat", "ex": ["Tickets, please. Have you got your tickets?", "Passports, please."]}, {"en": "ten minutes ago", "zh": "十分钟前", "scene": "ago 短语必须搭配一般过去时，不能和现在完成时连用。", "struct": "数字 + 时间单位 + ago", "cat": "experience", "ex": ["I bought them ten minutes ago.", "The bus left five minutes ago."]}, {"en": "the right train", "zh": "正确的那趟车", "scene": "right 表示「对的、正确的」，反义是 the wrong train。", "struct": "the right/wrong + 名词", "cat": "dailychat", "ex": ["Have you got the right train?", "I think we are on the wrong bus."]}],pats:[{"en": "主语 + have/has never + 过去分词 + before", "zh": "某人以前从未……过", "scene": "never 加 before 双重强调零经历，before 放句尾。", "struct": "主语 + have/has + never + 过去分词 + before", "cat": "experience", "ex": ["I've never been to Bristol before.", "Have you been on this train before?"]}, {"en": "When did you buy …? — I bought … + ago", "zh": "你什么时候买的……？——我……前买的。", "scene": "buy 的过去式是 bought。回答用 ago，动词必须用过去式。", "struct": "When + did + 主语 + buy + 物? — 主语 + bought + 物 + 时间段 + ago", "cat": "dailychat", "ex": ["When did you buy them? — I bought them ten minutes ago.", "When did you buy the ticket? — I bought it an hour ago."]}],quiz:{"v": {"q": "right（此处的意思是）：", "opts": ["正确的", "右边的", "权利"], "a": 0}, "e": {"q": "想说「我十分钟前买的」，正确的是：", "opts": ["I bought them ten minutes ago.", "I have bought them ten minutes ago.", "I buy them ten minutes ago."], "a": 0}, "p": {"q": "I ______ never been to Bristol before.", "opts": ["have", "did", "was"], "a": 0}},speak:"说 4 句话：扮演列车员，用 Tickets, please. 开场，用 When did you buy them? — I bought them … ago 问购票时间，再用 Have you been on … before? — I've never been … before 聊一聊乘车经历。"},
{n:96,title:"What's the Exact Time?",topic:"时间表达 a quarter past · 现在完成时 since",reading:"What's the exact time, please?\n\nIt's a quarter past three.\n\nA quarter past three! My train leaves at half past three.\n\nDon't worry. You've got fifteen minutes.\n\nHave you been to this station before?\n\nYes, I have. I've been here many times. I've worked in this city since 2018.\n\nThen you know it well. Which platform, please?\n\nPlatform five. Hurry up!\n\nThank you. You've been very kind.",zh:"（原创改写）请问现在准确时间是几点？\n\n三点一刻。\n\n三点一刻！我的火车三点半开。\n\n别担心，你还有十五分钟。\n\n你以前来过这个车站吗？\n\n来过，来过很多次了。我从 2018 年起就在这座城市工作。\n\n那你很熟了。请问在几号站台？\n\n五号站台。快点！\n\n谢谢，您真是太好了。",vocab:[{"w": "exact", "ph": "/ɪɡˈzækt/", "en": "completely correct in every way", "zh": "adj. 精确的；准确的", "eg": "What's the exact time, please?"}, {"w": "quarter", "ph": "/ˈkwɔːtə(r)/", "en": "fifteen minutes; one fourth", "zh": "n. 一刻钟；四分之一", "eg": "It's a quarter past three."}, {"w": "platform", "ph": "/ˈplætfɔːm/", "en": "the place in a station where you get on a train", "zh": "n. 站台", "eg": "Which platform, please? — Platform five."}, {"w": "city", "ph": "/ˈsɪti/", "en": "a large and important town", "zh": "n. 城市", "eg": "I've worked in this city since 2018."}],exprs:[{"en": "a quarter past …", "zh": "……点一刻", "scene": "比 half past 更细一档。差一刻到某点是 a quarter to。", "struct": "a quarter past/to + 小时", "cat": "dailychat", "ex": ["It's a quarter past three.", "The train leaves at a quarter to six."]}, {"en": "Don't worry.", "zh": "别担心。", "scene": "安抚对方，最万能的一句宽心话。", "struct": "Don't worry.（祈使句否定）", "cat": "emotion", "ex": ["Don't worry. You've got fifteen minutes.", "Don't worry about the exam."]}, {"en": "know something well", "zh": "对某事物很熟悉", "scene": "夸对方是熟门熟路的人，well 放在句尾。", "struct": "know + 名词 + well", "cat": "dailychat", "ex": ["Then you know it well.", "She knows this city very well."]}],pats:[{"en": "It's a quarter past/to + 小时", "zh": "现在是……点一刻／差一刻……点", "scene": "past 表示「过」，to 表示「差」。a quarter 是十五分钟。", "struct": "It's + a quarter + past/to + 小时", "cat": "dailychat", "ex": ["It's a quarter past three.", "It's a quarter to nine."]}, {"en": "主语 + have/has + 过去分词 + since + 年份", "zh": "某人从……年起就一直……", "scene": "since 后面接年份、月份、星期等起点，动词必须用现在完成时。", "struct": "主语 + have/has + 过去分词 + since + 年份", "cat": "experience", "ex": ["I've worked in this city since 2018.", "They have lived here since 2010."]}],quiz:{"v": {"q": "quarter（此处的意思是）：", "opts": ["一刻钟", "半小时", "一小时"], "a": 0}, "e": {"q": "想安抚对方「别担心」，应该说：", "opts": ["Don't worry.", "Don't hurry.", "Don't know."], "a": 0}, "p": {"q": "I've worked in this city ______ 2018.", "opts": ["since", "for", "ago"], "a": 0}},speak:"说 4 句话：用 What's the exact time? 问时间并用 a quarter past/to … 或 half past … 回答，用 Have you been … before? 问一句，最后用 since + 年份 说说你从哪年起做某件事。"},
{n:97,title:"A Small Blue Case",topic:"名词性物主代词 mine/yours/his/hers · belong to",reading:"Excuse me, is this small blue case yours?\n\nNo, it isn't mine. Mine is black and much bigger.\n\nWhose is it, then? There's a name on it.\n\nLet me look. It says P. Hall. I think it's Peter's.\n\nAre you sure? His case is old and brown.\n\nLook inside. There's a blue pen and an address card.\n\nYes, and these books are his, too. It must belong to him.\n\nI'm afraid I can't find him now. Let's take it to the office.",zh:"（原创改写）打扰一下，这只蓝色的小箱子是你的吗？\n\n不是我的。我的是黑色的，而且大得多。\n\n那是谁的呢？上面有个名字。\n\n我看一下。写着 P. Hall。我想是彼得的。\n\n你确定吗？他的箱子又旧又黄。\n\n看看里面。有一支蓝色钢笔，还有一张地址卡。\n\n是的，这些书也是他的。它一定是他的。\n\n恐怕我现在找不到他。我们把它交到办公室吧。",vocab:[{"w": "case", "ph": "/keɪs/", "en": "a box or bag you carry things in", "zh": "n. 箱子；盒子", "eg": "Is this small blue case yours?"}, {"w": "belong", "ph": "/bɪˈlɒŋ/", "en": "to be owned by someone", "zh": "v. 属于（常与 to 连用）", "eg": "Does this bag belong to you?"}, {"w": "address", "ph": "/əˈdres/", "en": "the place where a person lives or works", "zh": "n. 地址", "eg": "There's an address card in the case."}, {"w": "mine", "ph": "/maɪn/", "en": "my thing; the one that belongs to me", "zh": "pron. 我的（东西）", "eg": "This pen is mine, not yours."}],exprs:[{"en": "It is mine / yours / his.", "zh": "它是我的／你的／他的。", "scene": "回答 Whose 问句时直接用名词性物主代词，后面千万别再跟名词。", "struct": "It is + 名词性物主代词（mine/yours/his/hers/ours/theirs）", "cat": "dailychat", "ex": ["Is this case yours? — No, it isn't mine.", "Whose bag is it? — It's hers."]}, {"en": "belong to …", "zh": "属于……", "scene": "强调东西归谁所有，主语是「物」，人是 to 的宾语；没有被动语态。", "struct": "物 + belong(s) to + 人/代词宾格", "cat": "dailychat", "ex": ["It must belong to him.", "Does this book belong to you?"]}, {"en": "I'm afraid (that) …", "zh": "恐怕……", "scene": "礼貌地宣布坏消息或表示帮不上忙，比直接说 No 软得多。", "struct": "I'm afraid (that) + 从句", "cat": "emotion", "ex": ["I'm afraid I can't find him now.", "I'm afraid that I can't help you."]}],pats:[{"en": "Whose + 名词 + is this? — It's mine / yours / his.", "zh": "这是谁的……？——是我的／你的／他的。", "scene": "whose 问归属，答语可以只甩一个名词性物主代词，省掉后面的名词。", "struct": "Whose + 名词 + is this/that?", "cat": "dailychat", "ex": ["Whose case is this? — It's mine.", "Whose pen is that? — It's Peter's."]}, {"en": "形容词性物主代词 + 名词 = 名词性物主代词", "zh": "my case = mine，我的箱子", "scene": "后面跟着名词用 my/your/her；后面没名词就用 mine/yours/hers。", "struct": "my/your/his/her/our/their + 名词 = mine/yours/his/hers/ours/theirs", "cat": "dailychat", "ex": ["This is my case. This is mine.", "Those are their books. Those are theirs."]}],quiz:{"v": {"q": "belong to 的意思是：", "opts": ["属于", "拿走", "借来"], "a": 0}, "e": {"q": "想说「它不是我的」，应该说：", "opts": ["It isn't mine.", "It isn't my.", "It isn't me."], "a": 0}, "p": {"q": "I'm afraid that I ______ find him now.", "opts": ["can", "can't", "don't"], "a": 1}},speak:"说 4 句话：用 Whose … is this? 问一样东西是谁的，用名词性物主代词 mine/yours/his 回答，再用 belong to 换个说法，最后用 I'm afraid (that)… 表示你帮不上忙。"},
{n:98,title:"Whose Is It?",topic:"形容词性物主代词 vs 名词性物主代词 · hers/ours/theirs",reading:"Whose gloves are these? I found them on the floor.\n\nThey aren't mine. My gloves are in my bag.\n\nAre they Anna's?\n\nNo, hers are white. These are grey.\n\nMaybe they are ours.\n\nNo, ours are on the desk. I saw them there.\n\nThen they must be the twins'.\n\nYou're right. Theirs are grey, and they sat here this morning.\n\nThen let's put them on the teacher's desk. Someone will come for them.\n\nGood idea. I'll write a note with today's date.",zh:"（原创改写）这是谁的手套？我在地板上捡到的。\n\n不是我的。我的手套在我包里。\n\n是安娜的吗？\n\n不是，她的是白色的。这双是灰色的。\n\n也许是我们的。\n\n不，我们的在书桌上。我刚才在那儿看见的。\n\n那一定是那对双胞胎的。\n\n你说得对。他们的是灰色的，而且他们今天上午就坐在这儿。\n\n那我们把手套放到讲台上吧。会有人来认领的。\n\n好主意。我再写张便条，写上今天的日期。",vocab:[{"w": "glove", "ph": "/ɡlʌv/", "en": "a thing you wear on your hand to keep it warm", "zh": "n. 手套", "eg": "Whose gloves are these?"}, {"w": "ours", "ph": "/ˈaʊəz/", "en": "our thing; the one that belongs to us", "zh": "pron. 我们的（东西）", "eg": "Ours are on the desk."}, {"w": "theirs", "ph": "/ðeəz/", "en": "their thing; the one that belongs to them", "zh": "pron. 他们的（东西）", "eg": "Theirs are grey and old."}, {"w": "floor", "ph": "/flɔː(r)/", "en": "the part of a room you walk on", "zh": "n. 地板；地面", "eg": "I found my key on the floor."}],exprs:[{"en": "my gloves = mine", "zh": "我的手套 = 我的（东西）", "scene": "后面有名词用形容词性，没有名词就换成名词性，这是本课的核心开关。", "struct": "形容词性物主代词 + 名词 = 名词性物主代词", "cat": "dailychat", "ex": ["My gloves are white. Mine are white.", "Our bags are here. Ours are here."]}, {"en": "the twins' / Peter's", "zh": "双胞胎的／彼得的", "scene": "名词所有格：单数加 's，复数已带 s 的只加撇号。", "struct": "名词 + 's（单数） / 名词 s'（复数）", "cat": "dailychat", "ex": ["They must be the twins'.", "This is Peter's case."]}, {"en": "It must be + 名词性物主代词 / 名词所有格", "zh": "它一定是……的", "scene": "对归属做很有把握的肯定推测，must 后面直接跟 be。", "struct": "物 + must be + 名词性物主代词/名词所有格", "cat": "dailychat", "ex": ["They must be the twins'.", "This umbrella must be hers."]}],pats:[{"en": "Whose + 名词(复数) + are these? — They're mine / hers / theirs.", "zh": "这些……是谁的？——是我的／她的／他们的。", "scene": "复数东西用 are these 和 they're，注意别和单数混着用。", "struct": "Whose + 复数名词 + are these/those?", "cat": "dailychat", "ex": ["Whose gloves are these? — They're hers.", "Whose books are those? — They're theirs."]}, {"en": "名词性物主代词 + be + 形容词/介词短语", "zh": "我的／她的（那个）是……的／在……", "scene": "名词性物主代词能当主语，谓语的单复数看它指的东西是单数还是复数。", "struct": "Mine/Yours/Hers/Ours/Theirs + be + …", "cat": "dailychat", "ex": ["Hers are white. Ours are on the desk.", "Mine is black and much bigger."]}],quiz:{"v": {"q": "theirs 的意思是：", "opts": ["他们的（后接名词）", "他们的（东西）", "他们自己"], "a": 1}, "e": {"q": "These gloves aren't ______. Mine are in my bag.", "opts": ["mine", "my", "me"], "a": 0}, "p": {"q": "Whose gloves are these? — They're ______.", "opts": ["her", "she", "hers"], "a": 2}},speak:"说 4 句话：用 Whose … are these? 问东西是谁的，用 mine/hers/ours/theirs 逐个排除，最后用 They must be … 给出你的判断。"},
{n:99,title:"Ow!",topic:"that 引导的宾语从句 · I think that… / I'm afraid that…（意外与受伤）",reading:"Ow!\n\nWhat's the matter, Andy?\n\nI slipped on the wet floor and fell down.\n\nDid you hurt yourself?\n\nI think that I've hurt my back.\n\nI'm afraid that I can't stand up.\n\nDon't move. I'm sure that we need a doctor.\n\nI'm sorry that I didn't put a sign there.\n\nNever mind. I feel a little better now.\n\nCan you move your legs?\n\nYes, I can. But my back still hurts a little.\n\nThe doctor is coming. Please stay here and don't move.",zh:"（原创改写）哎哟！\n\n怎么了，安迪？\n\n我在湿地板上滑了一下，摔倒了。\n\n你伤着自己了吗？\n\n我想我把背给摔伤了。\n\n恐怕我站不起来了。\n\n别动。我确定我们得叫医生。\n\n很抱歉我那儿没放指示牌。\n\n没关系。我现在感觉好一点了。\n\n你的腿能动吗？\n\n能。不过背还有点疼。\n\n医生马上就来。请待在这儿别动。",vocab:[{"w": "slip", "ph": "/slɪp/", "en": "to slide by accident and lose your balance", "zh": "v. 滑倒；滑落", "eg": "I slipped on the wet floor."}, {"w": "hurt", "ph": "/hɜːt/", "en": "to cause pain or damage to part of the body", "zh": "v. 使受伤；疼痛", "eg": "I think that I've hurt my back."}, {"w": "back", "ph": "/bæk/", "en": "the part of your body behind your chest", "zh": "n. 背部；后背", "eg": "He carries a bag on his back."}, {"w": "sign", "ph": "/saɪn/", "en": "a notice that gives information or a warning", "zh": "n. 指示牌；标志", "eg": "We put a sign near the door."}],exprs:[{"en": "What's the matter?", "zh": "怎么了？／哪里不舒服？", "scene": "看到别人表情不对或出状况时的第一句话，也可以说 What's wrong?", "struct": "What's the matter (with + 人)?", "cat": "dailychat", "ex": ["What's the matter, Andy?", "What's the matter with your hand?"]}, {"en": "I think that …", "zh": "我想／我认为……", "scene": "说出自己的判断，语气比 I know 弱；口语里 that 经常省掉。", "struct": "I think (that) + 从句", "cat": "opinion", "ex": ["I think that I've hurt my back.", "I think you need a rest."]}, {"en": "I'm afraid that …", "zh": "恐怕……", "scene": "报告坏消息时的缓冲垫，让对方有个心理准备。", "struct": "I'm afraid (that) + 从句", "cat": "emotion", "ex": ["I'm afraid that I can't stand up.", "I'm afraid that he is out."]}],pats:[{"en": "I'm sure (that) + 从句", "zh": "我确信……", "scene": "afraid / sure / sorry / glad 这类形容词后面都能直接挂 that 从句。", "struct": "I'm + 形容词 + (that) + 从句", "cat": "opinion", "ex": ["I'm sure that we need a doctor.", "I'm glad that you are better."]}, {"en": "I'm sorry (that) + 从句", "zh": "很抱歉……", "scene": "道歉时把具体事由放进从句，比只说 Sorry 更完整。", "struct": "I'm sorry (that) + 从句", "cat": "emotion", "ex": ["I'm sorry that I didn't put a sign there.", "I'm sorry that I'm late."]}],quiz:{"v": {"q": "slip 的意思是：", "opts": ["滑倒", "撞到", "烧伤"], "a": 0}, "e": {"q": "想说「我想我把背弄伤了」，应该说：", "opts": ["I'm think that I've hurt my back.", "I think that I've hurt my back.", "I think I've hurt back me."], "a": 1}, "p": {"q": "I'm afraid that I ______ stand up.", "opts": ["can", "can't", "am"], "a": 1}},speak:"说 5 句话：用 What's the matter? 关心对方，用 I think that…、I'm afraid that…、I'm sure that… 描述一次小意外和你现在的状况，最后用 I'm sorry that… 收尾。"},
{n:100,title:"He Says That…",topic:"转述他人的话 · He says that…（宾语从句与主句时态配合）",reading:"Where's Tom? I haven't seen him all day.\n\nHe's in bed. He says that he has a cold.\n\nDid he go to work?\n\nNo. He says that he feels tired and his head hurts.\n\nDoes he want a doctor?\n\nHe says that he will take some medicine and sleep.\n\nI hope that he gets better soon.\n\nHe says that he will come back on Friday.\n\nPoor Tom. He never takes a rest.\n\nHe says that he is too busy.\n\nTell him that we can do his work here.",zh:"（原创改写）汤姆在哪儿？我一整天都没见到他。\n\n他躺在床上。他说他感冒了。\n\n他去上班了吗？\n\n没有。他说他觉得累，头也疼。\n\n他要去看医生吗？\n\n他说他吃点药然后睡一觉。\n\n我希望他快点好起来。\n\n他说他星期五回来。\n\n可怜的汤姆。他从来不休息。\n\n他说他太忙了。\n\n告诉他这边的活我们可以帮他做。",vocab:[{"w": "medicine", "ph": "/ˈmedsn/", "en": "something you take when you are ill", "zh": "n. 药（不可数）", "eg": "He will take some medicine and sleep."}, {"w": "tired", "ph": "/ˈtaɪəd/", "en": "needing rest or sleep", "zh": "adj. 疲倦的；累的", "eg": "He says that he feels tired."}, {"w": "hope", "ph": "/həʊp/", "en": "to want something to happen and think it can", "zh": "v. 希望；盼望", "eg": "I hope that he gets better soon."}, {"w": "rest", "ph": "/rest/", "en": "a time when you stop working and relax", "zh": "n./v. 休息", "eg": "The doctor told him to rest at home."}],exprs:[{"en": "have a cold", "zh": "感冒", "scene": "英语里说「得病」常用 have a + 病名，headache、fever 同理。", "struct": "have a cold / a headache / a fever", "cat": "dailychat", "ex": ["He says that he has a cold.", "I had a cold last week."]}, {"en": "He says that …", "zh": "他说……", "scene": "转述别人的话，主句是现在时，从句该用什么时态就用什么时态。", "struct": "主语 + say(s) (that) + 从句", "cat": "dailychat", "ex": ["He says that he feels tired.", "She says that she is busy now."]}, {"en": "I hope that …", "zh": "我希望……", "scene": "表达祝愿，后面接现在时或将来时都可以，不能说 I hope you to…。", "struct": "I hope (that) + 从句", "cat": "emotion", "ex": ["I hope that he gets better soon.", "I hope that you like it."]}],pats:[{"en": "主语 + say(s) + (that) + 从句", "zh": "某人说……", "scene": "主句现在时，从句时态自由；主句变成 said，从句一般往过去推一格。", "struct": "主语 + say/says/said + (that) + 从句", "cat": "dailychat", "ex": ["He says that he is tired.", "He said that he was tired."]}, {"en": "get better / feel better", "zh": "好转；感觉好些", "scene": "better 是 well 的比较级，说身体恢复时不用 more。", "struct": "get/feel better (soon)", "cat": "dailychat", "ex": ["I hope that he gets better soon.", "Are you feeling better today?"]}],quiz:{"v": {"q": "medicine 的意思是：", "opts": ["医生", "药", "休息"], "a": 1}, "e": {"q": "想转述「他说他很累」，应该说：", "opts": ["He says him tired.", "He says that he is tired.", "He says that him is tired."], "a": 1}, "p": {"q": "He says that he ______ back on Friday.", "opts": ["comes", "will come", "came"], "a": 1}},speak:"说 4 句话：用 He says that… 转述一位生病同事的三次说法（哪儿不舒服、打算怎么办、什么时候回来），最后用 I hope that… 表达祝愿。"},
{n:101,title:"A Card from Jimmy",topic:"书信与卡片的转述 · He says that he has just…（现在完成时 + just）",reading:"Look, Mum. There's a card from Jimmy.\n\nWhat does he say?\n\nHe says that he has just arrived in Scotland.\n\nHas he found a hotel?\n\nYes. He says that he is staying in a small hotel near the station.\n\nDoes he like it?\n\nHe says that the food is cheap and the people there are kind.\n\nWhen will he write again?\n\nHe says that he will send us a letter next week.\n\nI'm glad that he is having a good time.\n\nSo am I. Scotland is beautiful in autumn.",zh:"（原创改写）看，妈妈。有一张吉米寄来的卡片。\n\n他说什么？\n\n他说他刚到苏格兰。\n\n他找到旅馆了吗？\n\n找到了。他说他住在车站附近的一家小旅馆。\n\n他喜欢那儿吗？\n\n他说那儿吃的便宜，人也和气。\n\n他什么时候再写信？\n\n他说下周会给我们寄一封信。\n\n我真高兴他玩得这么开心。\n\n我也是。秋天的苏格兰很美。",vocab:[{"w": "arrive", "ph": "/əˈraɪv/", "en": "to get to a place at the end of a journey", "zh": "v. 到达", "eg": "He has just arrived in Scotland."}, {"w": "hotel", "ph": "/həʊˈtel/", "en": "a place where you pay to sleep when travelling", "zh": "n. 旅馆；酒店", "eg": "He is staying in a small hotel."}, {"w": "letter", "ph": "/ˈletə(r)/", "en": "a written message you send to someone", "zh": "n. 信；字母", "eg": "He will send us a letter next week."}, {"w": "station", "ph": "/ˈsteɪʃn/", "en": "a place where trains or buses stop", "zh": "n. 车站", "eg": "The hotel is near the station."}],exprs:[{"en": "a card / letter from …", "zh": "来自……的卡片／信", "scene": "说寄件人用 from，不用 of。", "struct": "a card/letter from + 人", "cat": "dailychat", "ex": ["There's a card from Jimmy.", "I got a letter from my sister."]}, {"en": "arrive in / arrive at", "zh": "到达……", "scene": "大地方用 in（国家、城市），小地方用 at（车站、机场、学校）。", "struct": "arrive in + 大地点 / arrive at + 小地点", "cat": "dailychat", "ex": ["He has just arrived in Scotland.", "We arrived at the station at six."]}, {"en": "have/has just + 过去分词", "zh": "刚刚……", "scene": "just 夹在 have 和过去分词中间，表示动作刚刚发生。", "struct": "have/has + just + 过去分词", "cat": "experience", "ex": ["He has just arrived in Scotland.", "I've just finished my homework."]}],pats:[{"en": "What does he say? — He says that + 从句", "zh": "他说什么？——他说……", "scene": "问转述内容的固定开场，注意 does 后面 say 用原形。", "struct": "What does + 主语 + say?", "cat": "dailychat", "ex": ["What does he say? — He says that he is fine.", "What does she say? — She says that she will wait."]}, {"en": "He says that he will + 动词原形", "zh": "他说他会……", "scene": "转述将来的打算，从句用 will，不受主句现在时影响。", "struct": "主语 + says (that) + 主语 + will + 动词原形", "cat": "dailychat", "ex": ["He says that he will send us a letter.", "She says that she will call you tonight."]}],quiz:{"v": {"q": "hotel 的意思是：", "opts": ["车站", "旅馆", "邮局"], "a": 1}, "e": {"q": "「他刚到苏格兰」应该说：", "opts": ["He has just arrive in Scotland.", "He has just arrived in Scotland.", "He just has arrived in Scotland yesterday."], "a": 1}, "p": {"q": "We arrived ______ Scotland this morning.", "opts": ["at", "in", "to"], "a": 1}},speak:"说 4 句话：用 There's a card from… 开头，用 He says that… 转述卡片里的两三条内容（刚到哪儿、住在哪儿、感觉如何），最后用 He says that he will… 收尾。"},
{n:102,title:"What Does She Say?",topic:"转述与转告 · tell sb that… / ask sb to do",reading:"Anna is on the phone. What does she say?\n\nShe says that her train is late.\n\nDoes she want us to wait?\n\nYes. She says that she will be here at seven.\n\nDoes she need any help?\n\nShe says that she has two heavy bags.\n\nTell her that we can meet her at the gate.\n\nAll right. She says that she is very sorry.\n\nDoes she want us to call her back?\n\nYes. She says that her phone is nearly dead.\n\nThen tell her that we'll wait at the gate.",zh:"（原创改写）安娜在电话里。她说什么？\n\n她说她的火车晚点了。\n\n她要我们等她吗？\n\n是的。她说她七点到这儿。\n\n她需要帮忙吗？\n\n她说她有两个很重的包。\n\n告诉她我们可以在大门口接她。\n\n好的。她说她非常抱歉。\n\n她要我们给她回电话吗？\n\n是的。她说她手机快没电了。\n\n那告诉她我们在大门口等她。",vocab:[{"w": "late", "ph": "/leɪt/", "en": "after the time something was planned", "zh": "adj. 迟到的；晚点的", "eg": "Her train is late again."}, {"w": "heavy", "ph": "/ˈhevi/", "en": "weighing a lot; hard to lift", "zh": "adj. 重的", "eg": "She has two heavy bags."}, {"w": "gate", "ph": "/ɡeɪt/", "en": "a door in a wall or fence outside", "zh": "n. 大门；门口", "eg": "We can meet her at the gate."}, {"w": "wait", "ph": "/weɪt/", "en": "to stay somewhere until something happens", "zh": "v. 等候；等待", "eg": "Please wait for me here."}],exprs:[{"en": "be late", "zh": "迟到；晚点", "scene": "人迟到、车晚点都能用；说「做什么迟到」后面接 for。", "struct": "主语 + be + late (for + 名词)", "cat": "dailychat", "ex": ["Her train is late.", "Don't be late for school."]}, {"en": "Tell her that …", "zh": "告诉她……", "scene": "让对方带话，that 从句里放要转达的内容。", "struct": "tell + 人 + (that) + 从句", "cat": "dailychat", "ex": ["Tell her that we can meet her at the gate.", "Tell him that I'm in a meeting."]}, {"en": "be on the phone", "zh": "在打电话／在电话里", "scene": "表示正在通话，介词用 on，不是 in。", "struct": "主语 + be + on the phone", "cat": "dailychat", "ex": ["Anna is on the phone.", "I was on the phone when you came in."]}],pats:[{"en": "What does she say? — She says that + 从句", "zh": "她说什么？——她说……", "scene": "转述第三人称的话，主语换成 she 就行。", "struct": "What does + she/he + say?", "cat": "dailychat", "ex": ["What does she say? — She says that she is sorry.", "What does he say? — He says that he is coming."]}, {"en": "tell / ask + 人 + to do", "zh": "叫／请某人做某事", "scene": "tell 偏指令，ask 更客气；否定时把 not 放在 to 前面。", "struct": "tell/ask + 人 + (not) + to do", "cat": "dailychat", "ex": ["Tell him to wait at the gate.", "Ask her to call me back."]}],quiz:{"v": {"q": "gate 的意思是：", "opts": ["花园", "大门", "车厢"], "a": 1}, "e": {"q": "想让别人转告她我们在门口接她，应该说：", "opts": ["Say her that we can meet her at the gate.", "Tell her that we can meet her at the gate.", "Tell her we can meeting her at the gate."], "a": 1}, "p": {"q": "She says that she has two ______ bags.", "opts": ["light", "heavy", "empty"], "a": 1}},speak:"说 4 句话：用 What does she say? 起头转述电话内容（车晚点、几点到、带了什么），再用 Tell her that… 让同伴带一句话。"},
{n:103,title:"Too, Very, Enough",topic:"too … to … 太……而不能 · 形容词 + enough 足够……",reading:"Do you like the soup, Ben?\n\nIt's very hot. I can't drink it now.\n\nIs it too hot to drink?\n\nYes, it's too hot. I'll wait a minute.\n\nIs your room warm enough?\n\nIt was cold this morning, but it's warm enough now.\n\nMy coffee isn't sweet enough. Pass me the sugar, please.\n\nHere you are. Don't make it too sweet.\n\nIs the bread fresh enough?\n\nYes, it's fresh enough, and the soup is better than yesterday's.\n\nI'm glad you like it. Shall I bring some more?",zh:"（原创改写）本，这汤你喜欢吗？\n\n很烫。我现在喝不了。\n\n烫得喝不下吗？\n\n是的，太烫了。我等一会儿。\n\n你房间够暖和吗？\n\n今天早上冷，不过现在够暖和了。\n\n我的咖啡不够甜。请把糖递给我。\n\n给你。别弄得太甜了。\n\n面包够新鲜吗？\n\n够新鲜，而且汤比昨天的好喝。\n\n你喜欢我真高兴。要不要再来一点？",vocab:[{"w": "soup", "ph": "/suːp/", "en": "a hot liquid food made from meat or vegetables", "zh": "n. 汤", "eg": "The soup is too hot to drink."}, {"w": "sugar", "ph": "/ˈʃʊɡə(r)/", "en": "a sweet white or brown substance in food", "zh": "n. 糖", "eg": "Pass me the sugar, please."}, {"w": "warm", "ph": "/wɔːm/", "en": "a little hot, but not too hot", "zh": "adj. 温暖的；暖和的", "eg": "The room is warm enough now."}, {"w": "sweet", "ph": "/swiːt/", "en": "tasting like sugar", "zh": "adj. 甜的", "eg": "My coffee isn't sweet enough."}],exprs:[{"en": "too + 形容词 + to do", "zh": "太……而不能……", "scene": "意思是「过头了，做不成」，自带否定，千万别再加 not。", "struct": "too + 形容词 + (for sb) + to do", "cat": "dailychat", "ex": ["The soup is too hot to drink.", "This box is too heavy for me to carry."]}, {"en": "形容词 + enough", "zh": "足够……", "scene": "enough 跟在形容词后面，这一条中国学生最容易记反。", "struct": "形容词 + enough (+ to do)", "cat": "dailychat", "ex": ["It's warm enough now.", "He's old enough to go to school."]}, {"en": "not + 形容词 + enough", "zh": "不够……", "scene": "表达「还差一点」，比 too 委婉。", "struct": "be + not + 形容词 + enough (+ to do)", "cat": "dailychat", "ex": ["My coffee isn't sweet enough.", "She isn't tall enough to reach the shelf."]}],pats:[{"en": "It's too + 形容词 + to do", "zh": "太……以致不能……", "scene": "主语是物时用 it 打头，句末的动词一般不再带宾语。", "struct": "It is too + 形容词 + to do", "cat": "dailychat", "ex": ["It's too hot to drink.", "It's too late to go out."]}, {"en": "It's + 形容词 + enough + to do", "zh": "足够……可以做……", "scene": "和 too…to 正好相反，表示条件达标了。", "struct": "It is + 形容词 + enough + to do", "cat": "dailychat", "ex": ["It's warm enough to sit outside.", "It's cheap enough to buy two."]}],quiz:{"v": {"q": "sweet 的意思是：", "opts": ["咸的", "甜的", "酸的"], "a": 1}, "e": {"q": "「这汤太烫了，喝不了」应该说：", "opts": ["The soup is too hot to drink it.", "The soup is too hot to drink.", "The soup is very hot to drink."], "a": 1}, "p": {"q": "It's ______ hot to drink now.", "opts": ["very", "too", "enough"], "a": 1}},speak:"说 4 句话：用 too … to … 抱怨一样东西过头了（太烫／太贵／太小），用 not … enough 说另一样还不够，最后给出你的解决办法。"},
{n:104,title:"Too Difficult",topic:"too … for sb to … · 形容词 + enough for sb to …",reading:"Can you read this English book, Sam?\n\nNo. It's too difficult for me to read.\n\nIs it too long?\n\nIt isn't too long. The words are too hard.\n\nTry this one. It's easy enough for you.\n\nOh, this story is interesting. I can read it.\n\nAre the sentences short enough?\n\nYes, they're short enough, and I know most of the words.\n\nCan you read the last page?\n\nYes. It isn't as hard as the first one.\n\nGood. Then you can finish the book this week.",zh:"（原创改写）山姆，这本英语书你能读吗？\n\n不能。它对我来说太难了，读不了。\n\n是太长了？\n\n不是太长，是词太难。\n\n试试这本。对你来说够简单。\n\n哦，这个故事有意思。我读得懂。\n\n句子够短吗？\n\n够短，而且大部分单词我都认识。\n\n最后一页你读得了吗？\n\n读得了。它没有第一页那么难。\n\n好。那你这周就能读完这本书了。",vocab:[{"w": "difficult", "ph": "/ˈdɪfɪkəlt/", "en": "not easy to do or understand", "zh": "adj. 困难的", "eg": "It's too difficult for me to read."}, {"w": "hard", "ph": "/hɑːd/", "en": "difficult; not soft", "zh": "adj. 难的；硬的", "eg": "The words are too hard."}, {"w": "easy", "ph": "/ˈiːzi/", "en": "not difficult", "zh": "adj. 容易的", "eg": "This one is easy enough for you."}, {"w": "sentence", "ph": "/ˈsentəns/", "en": "a group of words that ends with a full stop", "zh": "n. 句子", "eg": "Are the sentences short enough?"}],exprs:[{"en": "too + 形容词 + for sb + to do", "zh": "对某人来说太……而不能……", "scene": "加 for 引出「对谁而言」，把责任落在具体的人身上。", "struct": "too + 形容词 + for + 人 + to do", "cat": "dailychat", "ex": ["It's too difficult for me to read.", "The water is too cold for the children to swim in."]}, {"en": "形容词 + enough + for sb + to do", "zh": "对某人来说足够……可以……", "scene": "和上一句正好相反，enough 依旧跟在形容词后面。", "struct": "形容词 + enough + for + 人 + to do", "cat": "dailychat", "ex": ["It's easy enough for you.", "The room is big enough for us to use."]}, {"en": "most of the words", "zh": "大多数单词", "scene": "most of 后面接带限定词的名词，表示「……中的大多数」。", "struct": "most of + the/these/my + 名词", "cat": "dailychat", "ex": ["I know most of the words.", "Most of my friends live here."]}],pats:[{"en": "Is it too + 形容词? / Are they + 形容词 + enough?", "zh": "它太……吗？／它们够……吗？", "scene": "确认难度，把 be 提到句首变一般疑问句。", "struct": "Be + 主语 + too + 形容词 / 形容词 + enough?", "cat": "dailychat", "ex": ["Is it too long?", "Are the sentences short enough?"]}, {"en": "主语 + be + too + 形容词 + to do", "zh": "……太……以至于不能……", "scene": "主语是具体名词时，句末的动词后面通常还要补上介词。", "struct": "主语 + be + too + 形容词 + to do", "cat": "dailychat", "ex": ["The words are too hard to remember.", "The box is too heavy to carry."]}],quiz:{"v": {"q": "difficult 的反义词是：", "opts": ["hard", "easy", "long"], "a": 1}, "e": {"q": "「这对我来说太难了，读不了」应该说：", "opts": ["It's too difficult to me to read.", "It's too difficult for me to read.", "It's difficult enough for me to read."], "a": 1}, "p": {"q": "This story is easy ______ for you to understand.", "opts": ["too", "enough", "very"], "a": 1}},speak:"说 4 句话：用 It's too … for me to … 说一件事对你来说太难，再用 It's … enough for me to … 说另一件你能做到，最后用 most of … 补充一个细节。"},
{n:105,title:"Full of Mistakes",topic:"want sb to do · tell/ask sb to do（不定式作宾语补足语）",reading:"Your homework is full of mistakes, Paul.\n\nI'm sorry. I wanted to finish it quickly.\n\nI want you to do it again.\n\nDo you want me to do all of it?\n\nNo. I want you to check the first page.\n\nMy mother told me to write more slowly.\n\nShe was right. Slow writing is clean writing.\n\nThen tell me what to do next. I'll be more careful.\n\nThat's the right way to learn.\n\nI know. I'll write every word twice.",zh:"（原创改写）保罗，你的作业全是错误。\n\n对不起。我当时想快点做完。\n\n我想让你再做一遍。\n\n你要我把全部都重做吗？\n\n不。我想让你检查第一页。\n\n我妈妈叫我把字写慢一点。\n\n她是对的。慢慢写，字才干净。\n\n那你告诉我下一步做什么。我会更仔细的。\n\n这才是正确的学习方法。\n\n我知道。我会把每个词写两遍。",vocab:[{"w": "mistake", "ph": "/mɪˈsteɪk/", "en": "something wrong that you say or do", "zh": "n. 错误", "eg": "Your homework is full of mistakes."}, {"w": "check", "ph": "/tʃek/", "en": "to look at something to make sure it is right", "zh": "v. 检查；核对", "eg": "I want you to check the first page."}, {"w": "finish", "ph": "/ˈfɪnɪʃ/", "en": "to stop doing something because it is done", "zh": "v. 完成；结束", "eg": "I wanted to finish it quickly."}, {"w": "careful", "ph": "/ˈkeəfl/", "en": "giving attention so you do not make mistakes", "zh": "adj. 仔细的；认真的", "eg": "I'll be more careful next time."}],exprs:[{"en": "be full of …", "zh": "充满……；满是……", "scene": "强调数量多，常带一点负面味道。", "struct": "主语 + be full of + 名词", "cat": "dailychat", "ex": ["Your homework is full of mistakes.", "The bus is full of people."]}, {"en": "want sb to do sth", "zh": "想要某人做某事", "scene": "宾语后面接 to do，不是 do；否定时把 not 放在 to 前面。", "struct": "want + 人 + (not) to do", "cat": "dailychat", "ex": ["I want you to check the first page.", "Do you want me to do all of it?"]}, {"en": "tell / ask sb to do sth", "zh": "叫／请某人做某事", "scene": "tell 偏命令，ask 更客气；否定同样是 not to do。", "struct": "tell/ask + 人 + (not) to do", "cat": "dailychat", "ex": ["My mother told me to write more slowly.", "Ask him to come in, please."]}],pats:[{"en": "I want to + 动词原形", "zh": "我想做……", "scene": "主语和动作是同一个人，直接接 to do。", "struct": "主语 + want(s) + to do", "cat": "dailychat", "ex": ["I wanted to finish it quickly.", "She wants to go home early."]}, {"en": "I want you / him / them + to do", "zh": "我想要你／他／他们做……", "scene": "宾语换成别人，动作由别人去做，to do 紧跟宾语。", "struct": "主语 + want + 宾语 + to do", "cat": "dailychat", "ex": ["I want you to do it again.", "He wants me to wait here."]}],quiz:{"v": {"q": "check 的意思是：", "opts": ["抄写", "改正", "检查"], "a": 2}, "e": {"q": "「我想让你重写一遍」应该说：", "opts": ["I want you do it again.", "I want you to do it again.", "I want that you do it again."], "a": 1}, "p": {"q": "My mother told me ______ more slowly.", "opts": ["write", "to write", "writing"], "a": 1}},speak:"说 4 句话：用 be full of 描述一样东西满是问题，用 want sb to do 提出要求，用 tell/ask sb to do 给出指令，最后用 Do you want me to …? 确认。"},
{n:106,title:"I Want You to Try",topic:"不定式复习 · want to / ask sb to do / 疑问词 + to do",reading:"Come in, Lucy. I want to talk to you.\n\nIs there anything wrong?\n\nNo. I want you to try this exercise.\n\nI don't want to make more mistakes.\n\nDon't worry. I'll ask Joe to help you.\n\nJoe is busy. He told me to wait.\n\nThen I want you to listen to me for five minutes.\n\nAll right. Please tell me which page to open.\n\nJoe is free now. I'll ask him to come in.\n\nThank you. I want to ask him about page ten.",zh:"（原创改写）进来，露西。我想跟你谈谈。\n\n出什么事了吗？\n\n没有。我想让你试试这道练习。\n\n我可不想再犯更多错了。\n\n别担心。我会请乔来帮你。\n\n乔很忙。他叫我等着。\n\n那我想让你听我说五分钟。\n\n好吧。请告诉我该翻开哪一页。\n\n乔现在有空了。我去请他进来。\n\n谢谢。我想问问他第十页的事。",vocab:[{"w": "exercise", "ph": "/ˈeksəsaɪz/", "en": "a piece of work that helps you practise something", "zh": "n. 练习；习题", "eg": "I want you to try this exercise."}, {"w": "worry", "ph": "/ˈwʌri/", "en": "to feel unhappy because something may go wrong", "zh": "v. 担心；发愁", "eg": "Don't worry. I'll ask Joe to help you."}, {"w": "busy", "ph": "/ˈbɪzi/", "en": "having a lot of things to do", "zh": "adj. 忙碌的", "eg": "Joe is busy right now."}, {"w": "page", "ph": "/peɪdʒ/", "en": "one side of a sheet of paper in a book", "zh": "n. 页", "eg": "Please tell me which page to open."}],exprs:[{"en": "want to do sth", "zh": "想做某事", "scene": "主语和动作是同一个人，直接接 to do。", "struct": "主语 + want(s) + to do", "cat": "dailychat", "ex": ["I want to talk to you.", "She wants to go home early."]}, {"en": "ask sb to do sth", "zh": "请某人做某事", "scene": "拜托别人时用，语气比 tell 软。", "struct": "ask + 人 + to do", "cat": "dailychat", "ex": ["I'll ask Joe to help you.", "Ask the teacher to explain it again."]}, {"en": "疑问词 + to do", "zh": "该做什么／该怎么做", "scene": "把一整句压成一个短语，口语里特别省事。", "struct": "what/which/how/where + to do", "cat": "dailychat", "ex": ["Please tell me which page to open.", "I don't know what to say."]}],pats:[{"en": "主语 + want/would like + to do", "zh": "某人想／愿意做……", "scene": "would like 比 want 更客气，接线都是 to do。", "struct": "主语 + want/would like + to do", "cat": "dailychat", "ex": ["I want to talk to you.", "I'd like to have a cup of tea."]}, {"en": "主语 + tell/ask + 人 + (not) + to do", "zh": "某人叫／请某人（不要）做……", "scene": "否定一律放在 to 前面，不能说 to not do。", "struct": "主语 + tell/ask + 人 + (not) + to do", "cat": "dailychat", "ex": ["He told me to wait.", "She asked us not to be late."]}],quiz:{"v": {"q": "busy 的意思是：", "opts": ["累的", "忙的", "空的"], "a": 1}, "e": {"q": "「请告诉他翻开哪一页」应该说：", "opts": ["Please tell him open which page.", "Please tell him which page to open.", "Please tell him which page he open."], "a": 1}, "p": {"q": "I'll ask Joe ______ you.", "opts": ["help", "to help", "helping"], "a": 1}},speak:"说 4 句话：用 I want to… 说明自己的打算，用 want sb to / ask sb to 请别人做事，用 tell sb to 转述命令，最后用疑问词 + to do 问一个具体问题。"},
{n:107,title:"It's Too Small",topic:"形容词比较级入门 · 比较级 + than · too + 形容词 for sb",reading:"Do you like this green shirt, madam?\n\nIt's nice, but it's too small for me.\n\nTry the blue one. It's bigger.\n\nIt's very pretty. Is it bigger than the green one?\n\nYes, and it's cheaper, too.\n\nBut the green one is nicer, I think.\n\nThen let's look for a green one in a larger size.\n\nThat's a good idea. I'll take both.\n\nDo you have a green one in a bigger size?\n\nYes, madam. We have two in the back room.\n\nPlease bring them. I'll take the one that fits.",zh:"（原创改写）夫人，您喜欢这件绿衬衫吗？\n\n挺好看的，不过对我来说太小了。\n\n试试那件蓝色的。它大一些。\n\n很漂亮。它比绿色的那件大吗？\n\n是的，而且还更便宜。\n\n不过我觉得绿色的更好看。\n\n那我们找一件大一号的绿色款吧。\n\n好主意。两件我都要了。\n\n绿色的有大一号的吗？\n\n有的，夫人。里屋还有两件。\n\n请拿来吧。哪件合身我要哪件。",vocab:[{"w": "shirt", "ph": "/ʃɜːt/", "en": "a piece of clothing for the top of the body", "zh": "n. 衬衫", "eg": "Do you like this green shirt?"}, {"w": "size", "ph": "/saɪz/", "en": "how big or small something is", "zh": "n. 尺码；大小", "eg": "Do you have this in a larger size?"}, {"w": "pretty", "ph": "/ˈprɪti/", "en": "nice to look at", "zh": "adj. 漂亮的；好看的", "eg": "The blue one is very pretty."}, {"w": "cheap", "ph": "/tʃiːp/", "en": "costing little money", "zh": "adj. 便宜的", "eg": "It's cheaper than the green one."}],exprs:[{"en": "比较级 + than", "zh": "比……更……", "scene": "两者比较的标准句式，than 后面可以接名词、代词或句子。", "struct": "A + be + 形容词比较级 + than + B", "cat": "dailychat", "ex": ["Is it bigger than the green one?", "This one is cheaper than that one."]}, {"en": "too + 形容词 + for sb", "zh": "对某人来说太……", "scene": "试衣服、试鞋子时的高频句。", "struct": "It's/They're + too + 形容词 + for + 人", "cat": "dailychat", "ex": ["It's too small for me.", "These shoes are too big for her."]}, {"en": "a larger / smaller size", "zh": "大一码／小一码", "scene": "购物时想换尺码，size 前面用 large/small 的比较级。", "struct": "a + 比较级 + size", "cat": "dailychat", "ex": ["Let's look for a green one in a larger size.", "Do you have this in a smaller size?"]}],pats:[{"en": "A + be + 比较级 + than + B", "zh": "A 比 B 更……", "scene": "单音节形容词加 -er，than 后面如果是代词，口语里常用宾格。", "struct": "A + be + 比较级 + than + B", "cat": "dailychat", "ex": ["The blue one is cheaper than the green one.", "My bag is lighter than yours."]}, {"en": "Which + 名词 + is + 比较级, A or B?", "zh": "A 和 B，哪个更……？", "scene": "二选一时的问法，回答可以直接甩出其中一个。", "struct": "Which + be + 比较级, A or B?", "cat": "dailychat", "ex": ["Which shirt is nicer, the green one or the blue one?", "Which bag is heavier, the black one or the red one?"]}],quiz:{"v": {"q": "size 的意思是：", "opts": ["价格", "尺码", "颜色"], "a": 1}, "e": {"q": "「蓝色的比绿色的便宜」应该说：", "opts": ["The blue one is more cheap than the green one.", "The blue one is cheap than the green one.", "The blue one is cheaper than the green one."], "a": 2}, "p": {"q": "This shirt is ______ than that one.", "opts": ["big", "bigger", "biggest"], "a": 1}},speak:"说 4 句话：购物场景，用 too … for me 说尺码不合适，用比较级 + than 对比两件衣服，用 Which … is …, A or B? 问同伴意见，最后说出你买哪件。"},
{n:108,title:"Which Is Better?",topic:"as + 原级 + as 同级比较 · 比较级 + than · more + 多音节形容词",reading:"Which bag is heavier, the black one or the red one?\n\nThe black one is heavier. It's full of books.\n\nIs your bag as heavy as mine?\n\nNo, mine is lighter than yours.\n\nMy bag is older, but it's stronger.\n\nThis new bag is nicer, but it's more expensive.\n\nI like yours better. It's cheaper and lighter.\n\nThen let's change bags for a day.\n\nAll right. Yours is heavier, but mine is stronger.\n\nThat's true. Let's see who is happier at five o'clock.",zh:"（原创改写）哪个包更重，黑色的还是红色的？\n\n黑色的更重。里面全是书。\n\n你的包跟我的包一样重吗？\n\n不，我的比你的轻。\n\n我的包旧一些，但更结实。\n\n这个新包更好看，但更贵。\n\n我更喜欢你的。又便宜又轻。\n\n那我们换一天包背背看。\n\n好吧。你的更重，不过我的更结实。\n\n没错。看五点钟谁更高兴吧。",vocab:[{"w": "heavy", "ph": "/ˈhevi/", "en": "weighing a lot", "zh": "adj. 重的", "eg": "Which bag is heavier?"}, {"w": "light", "ph": "/laɪt/", "en": "not heavy", "zh": "adj. 轻的", "eg": "Mine is lighter than yours."}, {"w": "strong", "ph": "/strɒŋ/", "en": "not easily broken or damaged", "zh": "adj. 结实的；强壮的", "eg": "My old bag is stronger."}, {"w": "expensive", "ph": "/ɪkˈspensɪv/", "en": "costing a lot of money", "zh": "adj. 昂贵的", "eg": "This new bag is more expensive."}],exprs:[{"en": "as + 形容词原级 + as", "zh": "和……一样……", "scene": "两者程度相同，中间必须用原级，不能塞比较级进去。", "struct": "as + 形容词/副词原级 + as", "cat": "dailychat", "ex": ["Is your bag as heavy as mine?", "He is as tall as his father."]}, {"en": "比较级 + than", "zh": "比……更……", "scene": "去掉 as…as 的等号，换上 than，就变成差级比较。", "struct": "A + be + 比较级 + than + B", "cat": "dailychat", "ex": ["Mine is lighter than yours.", "This book is more interesting than that one."]}, {"en": "more + 多音节形容词", "zh": "更……", "scene": "三个音节以上的形容词，比较级前面加 more，不加 -er。", "struct": "more + 多音节形容词 (+ than)", "cat": "dailychat", "ex": ["It's more expensive than mine.", "This film is more exciting than that one."]}],pats:[{"en": "A + be + as + 原级 + as + B", "zh": "A 和 B 一样……", "scene": "否定时把第一个 as 换成 not so / not as，意思一样。", "struct": "A + be + as + 原级 + as + B", "cat": "dailychat", "ex": ["My bag is as heavy as yours.", "My bag isn't as heavy as yours."]}, {"en": "Which + be + 比较级, A or B?", "zh": "A 和 B，哪个更……？", "scene": "两者挑一个时的万能问句，比较级放句中。", "struct": "Which + be + 比较级, A or B?", "cat": "dailychat", "ex": ["Which bag is heavier, the black one or the red one?", "Which is more expensive, the bus or the train?"]}],quiz:{"v": {"q": "light 在文中的意思是：", "opts": ["明亮的", "轻的", "浅的"], "a": 1}, "e": {"q": "「我的包没有你的重」应该说：", "opts": ["Mine is not heavy as yours.", "Mine isn't as heavier as yours.", "Mine isn't as heavy as yours."], "a": 2}, "p": {"q": "This bag is ______ than that one.", "opts": ["expensive", "expensiver", "more expensive"], "a": 2}},speak:"说 4 句话：用 Which is …, A or B? 比较两样东西，用比较级 + than 给出结论，用 as … as 或 not as … as 补充一点，最后说你更喜欢哪一个。"},
{n:109,title:"A Good Idea",topic:"a little / a few · more … than / less … than · enough（数量的多少）",reading:"Shall I make some coffee, Jane?\n\nYes, please. Just a little for me.\n\nDo you want any sugar?\n\nA little, please. But less than last time.\n\nOne spoonful?\n\nNo, half a spoonful. That's enough for me.\n\nWhat about you, Tom?\n\nI'd like a cup too, but with more milk. I don't like it too strong.\n\nThen let's sit in the garden. It's warmer out there than in the kitchen.\n\nShall I bring the cups?\n\nYes, please. And bring a few biscuits, too.",zh:"（原创改写）简，我煮点咖啡好吗？\n\n好的，麻烦了。我只喝一点点。\n\n你要糖吗？\n\n来一点，谢谢。不过要比上次少。\n\n一勺？\n\n不，半勺就够了。\n\n你呢，汤姆？\n\n我也要一杯，但要多加牛奶。我不喜欢太浓。\n\n那我们坐到花园里去吧。那儿比厨房暖和。\n\n我把杯子拿来好吗？\n\n好的，麻烦了。再拿几块饼干来。",vocab:[{"w": "spoon", "ph": "/spuːn/", "en": "a small tool you use for eating or stirring", "zh": "n. 勺子", "eg": "Just half a spoon, please."}, {"w": "milk", "ph": "/mɪlk/", "en": "the white liquid that people drink", "zh": "n. 牛奶", "eg": "I'd like a cup with more milk."}, {"w": "less", "ph": "/les/", "en": "a smaller amount of something", "zh": "det./adv. 更少的（修饰不可数名词）", "eg": "Less than last time, please."}, {"w": "idea", "ph": "/aɪˈdɪə/", "en": "a plan or thought about what to do", "zh": "n. 主意；想法", "eg": "That's a good idea."}],exprs:[{"en": "Shall I …?", "zh": "我……好吗？", "scene": "主动提出帮忙或征求意见，主语只能用 I 或 we。", "struct": "Shall I/we + 动词原形?", "cat": "dailychat", "ex": ["Shall I make some coffee?", "Shall we sit in the garden?"]}, {"en": "a little / a few", "zh": "一点点", "scene": "不可数名词配 a little，可数复数配 a few，混着用会露怯。", "struct": "a little + 不可数名词 / a few + 可数复数", "cat": "dailychat", "ex": ["Just a little, please.", "I've got a few friends here."]}, {"en": "more / less + 名词 + than", "zh": "比……多／少的……", "scene": "more 可数不可数都能用，less 只管不可数，可数要用 fewer。", "struct": "more/less + 名词 + than + 参照", "cat": "dailychat", "ex": ["Less than last time, please.", "I'd like a cup with more milk."]}],pats:[{"en": "Shall I + 动词原形? — Yes, please. / No, thank you.", "zh": "我……好吗？——好，麻烦了。／不用了，谢谢。", "scene": "提议加回应的最小对话单位，答语要成套记。", "struct": "Shall I/we + 动词原形?", "cat": "dailychat", "ex": ["Shall I open the window? — Yes, please.", "Shall we go now? — No, let's wait."]}, {"en": "比较级 + than + last time / before", "zh": "比上次／以前更……", "scene": "拿现在和过去比，than 后面可以直接跟时间名词。", "struct": "比较级 + than + last time/before", "cat": "dailychat", "ex": ["Less than last time, please.", "This film is better than the last one."]}],quiz:{"v": {"q": "less than 的意思是：", "opts": ["多于", "少于", "等于"], "a": 1}, "e": {"q": "想说「比上次少一点（糖）」，应该说：", "opts": ["Fewer than last time, please.", "Less than last time, please.", "Little than last time, please."], "a": 1}, "p": {"q": "Shall I ______ some coffee?", "opts": ["make", "making", "to make"], "a": 0}},speak:"说 4 句话：用 Shall I…? 主动提议，用 a little / a few 说明分量，用 more … than 或 less … than 调整，最后用 That's enough for me. 收尾。"},
{n:110,title:"How Do They Compare?",topic:"more / less / fewer · 可数与不可数名词的比较",reading:"Tom has more books than Jim, but Jim has more time.\n\nWho has more money?\n\nJim has less money than Tom, but he needs less.\n\nWhat about friends?\n\nTom has fewer friends, because he works longer hours.\n\nAnd mistakes?\n\nOh, Tom makes fewer mistakes now. He checks everything twice.\n\nSo Jim is happier, and Tom is richer.\n\nThat's true. Both of them are busy, though.\n\nWho is happier, then?\n\nJim is. He has more time for his family.\n\nMoney isn't everything, I suppose.\n\nNo, it isn't.",zh:"（原创改写）汤姆的书比吉姆多，不过吉姆的时间更多。\n\n谁的钱更多？\n\n吉姆的钱比汤姆少，但他需要的也更少。\n\n朋友呢？\n\n汤姆的朋友更少，因为他工作时间更长。\n\n那错误呢？\n\n哦，汤姆现在犯的错更少了。他什么都检查两遍。\n\n所以吉姆更快乐，汤姆更富有。\n\n没错。不过他们俩都很忙。\n\n那谁更快乐？\n\n吉姆。他有更多时间陪家人。\n\n钱不是一切，我觉得。\n\n是啊，钱不是一切。",vocab:[{"w": "fewer", "ph": "/ˈfjuːə(r)/", "en": "a smaller number of people or things you can count", "zh": "adj. 更少的（修饰可数复数）", "eg": "Tom has fewer friends than Jim."}, {"w": "money", "ph": "/ˈmʌni/", "en": "what you use to buy things", "zh": "n. 钱（不可数）", "eg": "Jim has less money than Tom."}, {"w": "hour", "ph": "/ˈaʊə(r)/", "en": "sixty minutes", "zh": "n. 小时", "eg": "He works longer hours than me."}, {"w": "rich", "ph": "/rɪtʃ/", "en": "having a lot of money", "zh": "adj. 富有的", "eg": "Tom is richer than Jim."}],exprs:[{"en": "more + 名词 + than", "zh": "比……更多的……", "scene": "可数复数和不可数名词都能挂在 more 后面。", "struct": "more + 可数复数/不可数名词 + than", "cat": "dailychat", "ex": ["Tom has more books than Jim.", "Jim has more time than Tom."]}, {"en": "less + 不可数名词 + than", "zh": "比……更少的……（不可数）", "scene": "只管不可数：money、time、water、sugar。", "struct": "less + 不可数名词 + than", "cat": "dailychat", "ex": ["Jim has less money than Tom.", "I drink less coffee than you."]}, {"en": "fewer + 可数复数 + than", "zh": "比……更少的……（可数）", "scene": "能一个一个数清楚的用 fewer，这是和 less 的分界线。", "struct": "fewer + 可数复数 + than", "cat": "dailychat", "ex": ["Tom has fewer friends.", "He makes fewer mistakes now."]}],pats:[{"en": "A + have/has + more + 名词 + than + B", "zh": "A 比 B 有更多……", "scene": "have 表示「拥有」，比较数量最自然的说法。", "struct": "A + have/has + more + 名词 + than + B", "cat": "dailychat", "ex": ["Tom has more books than Jim.", "She has more time than me."]}, {"en": "比较级 + than + 人 + do/does/did", "zh": "比某人……（省略式）", "scene": "than 后面可以只留「人 + 助动词」，省掉重复的动词。", "struct": "比较级 + than + 人 + do/does/did", "cat": "dailychat", "ex": ["He works longer hours than I do.", "She checks things more carefully than he does."]}],quiz:{"v": {"q": "fewer 用在：", "opts": ["可数复数名词前", "不可数名词前", "两者都可以"], "a": 0}, "e": {"q": "「汤姆的钱比吉姆少」应该说：", "opts": ["Tom has fewer money than Jim.", "Tom has less money than Jim.", "Tom has little money than Jim."], "a": 1}, "p": {"q": "Jim has ______ books than Tom.", "opts": ["fewer", "less", "little"], "a": 0}},speak:"说 4 句话：比较两个人（或两种生活）在书／钱／时间／朋友上的多少，more … than、less … than、fewer … than 至少各用一次，注意可数与不可数别串台。"},
{n:111,title:"The Most Expensive Model",topic:"形容词最高级 the most … / the -est · not as … as",reading:"I like this television very much. How much does it cost?\n\nIt's the most expensive model in the shop. It costs five hundred pounds.\n\nThat's too expensive for us.\n\nThis one is cheaper. It's only three hundred pounds.\n\nBut it's not as good as the expensive one.\n\nIt's still the best one we can buy.\n\nCan we pay by instalments?\n\nYes. You can pay a deposit of thirty pounds, and then ten pounds a month.\n\nThat's fine. We'll take it home today.",zh:"（原创改写）我很喜欢这台电视。它多少钱？\n\n这是店里最贵的型号，售价五百英镑。\n\n这对我们来说太贵了。\n\n这台便宜些，只要三百英镑。\n\n但它不如那台贵的那么好。\n\n它仍然是我们能买得起的最好的一台。\n\n我们可以分期付款吗？\n\n可以。你们先付三十英镑定金，然后每月付十英镑。\n\n没问题。我们今天就把它搬回家。",vocab:[{"w": "model", "ph": "/ˈmɒdl/", "en": "one type of a product that a shop sells", "zh": "n. 型号；样式", "eg": "It's the most expensive model in the shop."}, {"w": "cost", "ph": "/kɒst/", "en": "to have a price of", "zh": "v. 价钱为；花费", "eg": "How much does it cost?"}, {"w": "pound", "ph": "/paʊnd/", "en": "the money used in Britain", "zh": "n. 英镑", "eg": "It costs five hundred pounds."}, {"w": "deposit", "ph": "/dɪˈpɒzɪt/", "en": "money you pay first when buying something", "zh": "n. 定金；押金", "eg": "You can pay a deposit of thirty pounds."}],exprs:[{"en": "the most + 多音节形容词", "zh": "最……", "scene": "三个音节以上的形容词，最高级前面加 the most，不加 -est。", "struct": "the most + 多音节形容词 (+ in/of 短语)", "cat": "dailychat", "ex": ["It's the most expensive model in the shop.", "She is the most careful student in the class."]}, {"en": "How much does it cost?", "zh": "这个多少钱？", "scene": "问价格：cost 的主语是东西；人作主语要换成 pay 或 spend。", "struct": "How much + does/did + 物 + cost?", "cat": "dailychat", "ex": ["How much does it cost?", "How much did your bag cost?"]}, {"en": "not as + 原级 + as", "zh": "不如……那样……", "scene": "把两件东西摆一摆，说后者稍逊一筹，语气比 worse 更客观。", "struct": "A + be + not as + 原级 + as + B", "cat": "dailychat", "ex": ["It's not as good as the expensive one.", "This one isn't as light as that one."]}],pats:[{"en": "the + 最高级 + 名词 + in/of + 范围", "zh": "在……中最……的……", "scene": "in 接地点或集体，of 接同一类的成员。", "struct": "the + 最高级 + 名词 + in/of + 范围", "cat": "dailychat", "ex": ["It's the most expensive model in the shop.", "He is the tallest boy of the three."]}, {"en": "It's too + 形容词 + for + 人", "zh": "对某人来说太……", "scene": "看完价格表示「买不起」，比直接说 I can't 更自然。", "struct": "It's too + 形容词 + for + 人", "cat": "dailychat", "ex": ["That's too expensive for us.", "It's too heavy for her."]}],quiz:{"v": {"q": "model 在文中的意思是：", "opts": ["模特", "型号", "模型"], "a": 1}, "e": {"q": "「它是店里最贵的型号」应该说：", "opts": ["It's the expensivest model in the shop.", "It's the most expensive model in the shop.", "It's most expensive model in the shop."], "a": 1}, "p": {"q": "It isn't ______ good as the expensive one.", "opts": ["so", "as", "than"], "a": 1}},speak:"说 4 句话：购物场景，用 How much does it cost? 问价，用 the most expensive / the best 说这是店里之最，用 not as … as 说便宜款不如贵款，最后用 It's too … for us. 说明买不起。"},
{n:112,title:"Not as Good as That One",topic:"as … as 与 not as (so) … as · 同级比较与最高级挑选",reading:"Is this camera as good as that one?\n\nNo, it isn't as good. That one takes better photos.\n\nIs it as expensive?\n\nNo, it's cheaper, but it isn't as strong.\n\nWhich one do you like best?\n\nI like the small black one best. It's the lightest.\n\nBut it's the most expensive, too.\n\nYes, and it's worth the money.\n\nIt's the lightest, but is it the easiest to use?\n\nYes. Even a child can use it.\n\nThen let's take the small black one.",zh:"（原创改写）这台相机和那台一样好吗？\n\n不，没那么好。那台拍出来的照片更好。\n\n它一样贵吗？\n\n不，它便宜些，但不如那台结实。\n\n你最喜欢哪一台？\n\n我最喜欢那台黑色的小的，它最轻。\n\n但它也是最贵的。\n\n是啊，不过它值这个价。\n\n它是最轻的，可它最好用吗？\n\n是的。连小孩都会用。\n\n那我们就要那台黑色的小的吧。",vocab:[{"w": "camera", "ph": "/ˈkæmərə/", "en": "a machine you use to take photos", "zh": "n. 照相机", "eg": "Is this camera as good as that one?"}, {"w": "photo", "ph": "/ˈfəʊtəʊ/", "en": "a picture made with a camera", "zh": "n. 照片", "eg": "That one takes better photos."}, {"w": "worth", "ph": "/wɜːθ/", "en": "good enough to pay the price for", "zh": "adj. 值……的", "eg": "It's worth the money."}, {"w": "choose", "ph": "/tʃuːz/", "en": "to decide which one you want", "zh": "v. 选择", "eg": "It's hard to choose between them."}],exprs:[{"en": "as + 原级 + as", "zh": "和……一样……", "scene": "同级比较，中间的形容词一律用原形。", "struct": "A + be + as + 原级 + as + B", "cat": "dailychat", "ex": ["Is this camera as good as that one?", "Is it as expensive?"]}, {"en": "not as / not so + 原级 + as", "zh": "不如……那样……", "scene": "两种写法都对，口语里 not as 更常见。", "struct": "A + be + not as/not so + 原级 + as + B", "cat": "dailychat", "ex": ["It isn't as strong as that one.", "This one isn't so good."]}, {"en": "be worth the money", "zh": "值这个钱", "scene": "贵是贵，但你觉得值；后面也能接 doing。", "struct": "be worth + 名词/doing", "cat": "opinion", "ex": ["It's worth the money.", "This book is worth reading."]}],pats:[{"en": "Which + 名词 + do you like best, A, B or C?", "zh": "A、B、C 你最喜欢哪一个？", "scene": "三者以上挑最优，best 前面可以省掉 the。", "struct": "Which + 名词 + do you like best?", "cat": "dailychat", "ex": ["Which one do you like best?", "Which colour do you like best, red, blue or green?"]}, {"en": "主语 + be + the + 最高级 (+ in/of 短语)", "zh": "……是最……的", "scene": "回答上面的问句：先说选哪个，再补一个最高级理由。", "struct": "主语 + be + the + 最高级", "cat": "dailychat", "ex": ["It's the lightest.", "She is the tallest in her family."]}],quiz:{"v": {"q": "worth 的意思是：", "opts": ["便宜的", "值……的", "免费的"], "a": 1}, "e": {"q": "「它没有那台好」应该说：", "opts": ["It isn't as better as that one.", "It isn't so good than that one.", "It isn't as good as that one."], "a": 2}, "p": {"q": "This camera isn't ______ expensive as that one.", "opts": ["so", "as", "than"], "a": 1}},speak:"说 4 句话：比较三样东西（相机、手机、包都行），用 as … as 或 not as … as 说两点差异，用 Which do you like best? 给出选择，最后用 It's worth the money. 收尾。"},
{n:113,title:"Small Change",topic:"neither / nor 倒装 · So do I / Neither can I",reading:"Can you change this ten-pound note, please?\n\nI'm afraid I can't. I haven't got any small change.\n\nNeither have I. I've only got a twenty-pound note.\n\nHave you got any coins?\n\nNo, I haven't. And I can't use my card here.\n\nNeither can I. This shop only takes cash.\n\nI've got a five-pound note in my bag.\n\nSo have I. Let's put them together and pay.\n\nThat's very kind of you.\n\nNot at all. I haven't got much change, either.",zh:"（原创改写）能麻烦您把这张十镑的纸币换开吗？\n\n恐怕不行。我没有零钱。\n\n我也没有。我只有一张二十镑的。\n\n您有硬币吗？\n\n没有。而且这儿也不能刷卡。\n\n我也不能。这家店只收现金。\n\n我包里有张五镑的。\n\n我也有。我们把钱凑一起付吧。\n\n您真是太好了。\n\n不客气。我也没多少零钱。",vocab:[{"w": "change", "ph": "/tʃeɪndʒ/", "en": "coins, or money you get back after paying", "zh": "n. 零钱；v. 兑换", "eg": "I haven't got any small change."}, {"w": "note", "ph": "/nəʊt/", "en": "paper money", "zh": "n. 纸币；便条", "eg": "Can you change this ten-pound note?"}, {"w": "coin", "ph": "/kɔɪn/", "en": "a small round piece of money", "zh": "n. 硬币", "eg": "Have you got any coins?"}, {"w": "cash", "ph": "/kæʃ/", "en": "money in notes and coins, not a card", "zh": "n. 现金", "eg": "This shop only takes cash."}],exprs:[{"en": "So + 助动词/be/情态动词 + 主语", "zh": "……也是", "scene": "上一句是肯定句，你想说「我也是」，把助动词提到主语前面。", "struct": "So + be/助动词/情态动词 + 主语", "cat": "dailychat", "ex": ["I've got a five-pound note. — So have I.", "I'm tired. — So am I."]}, {"en": "Neither / Nor + 助动词/be/情态动词 + 主语", "zh": "……也不", "scene": "上一句是否定句，你想说「我也不」，用 Neither 打头，句子里不能再加 not。", "struct": "Neither/Nor + be/助动词/情态动词 + 主语", "cat": "dailychat", "ex": ["I can't use my card. — Neither can I.", "I haven't got any change. — Neither have I."]}, {"en": "small change", "zh": "零钱", "scene": "不可数，不能加 s；换开大额纸币时最常用。", "struct": "small change", "cat": "dailychat", "ex": ["I haven't got any small change.", "Do you have any small change?"]}],pats:[{"en": "So + be/助动词/情态动词 + 主语", "zh": "……也一样（肯定附和）", "scene": "助动词要和前一句对上：be 对 be，情态对情态，实义动词用 do/does/did。", "struct": "So + be/助动词/情态动词 + 主语", "cat": "dailychat", "ex": ["I like coffee. — So do I.", "I can swim. — So can I."]}, {"en": "Neither / Nor + be/助动词/情态动词 + 主语", "zh": "……也不一样（否定附和）", "scene": "和 So 唯一的区别是否定，结构完全一样。", "struct": "Neither/Nor + be/助动词/情态动词 + 主语", "cat": "dailychat", "ex": ["I don't know. — Neither do I.", "I wasn't there. — Neither was I."]}],quiz:{"v": {"q": "coin 的意思是：", "opts": ["纸币", "硬币", "钱包"], "a": 1}, "e": {"q": "对方说 I haven't got any change，你想说「我也没有」：", "opts": ["So haven't I.", "Neither I have.", "Neither have I."], "a": 2}, "p": {"q": "I can't use my card here. — ______ can I.", "opts": ["So", "Neither do", "Neither"], "a": 2}},speak:"说 5 句话：和同伴一起发现两人都没零钱、都不能刷卡、都有一张五镑纸币，用 Neither … 与 So … 交替回应，注意助动词要和上一句对上。"},
{n:114,title:"So Am I",topic:"so / neither 附和 · 助动词的选择（am / do / did / can / have）",reading:"I'm very tired today.\n\nSo am I. I didn't sleep well.\n\nNeither did I. The baby cried all night.\n\nI can't work this afternoon.\n\nNeither can I. Let's have a short break.\n\nDo you want some coffee?\n\nYes, I'd love some. I've just finished this report.\n\nSo have I. Let's go together.\n\nI'm hungry, too. I didn't have breakfast.\n\nNeither did I. There's a small cafe next door.\n\nLet's go there. I want a sandwich and a large coffee.\n\nAnd a glass of water, please.",zh:"（原创改写）我今天特别累。\n\n我也是。我没睡好。\n\n我也没睡好。孩子哭了一整夜。\n\n今天下午我干不动了。\n\n我也是。我们休息一小会儿吧。\n\n你想喝咖啡吗？\n\n想，来一杯。我刚写完这份报告。\n\n我也是。那我们一起走吧。\n\n我也饿了。我早饭没吃。\n\n我也没吃。隔壁有家小咖啡馆。\n\n我们去那儿吧。我要一个三明治和一大杯咖啡。\n\n再来一杯水，谢谢。",vocab:[{"w": "break", "ph": "/breɪk/", "en": "a short time when you stop working", "zh": "n. 休息；间歇", "eg": "Let's have a short break."}, {"w": "report", "ph": "/rɪˈpɔːt/", "en": "a piece of writing about work or facts", "zh": "n. 报告", "eg": "I've just finished this report."}, {"w": "cry", "ph": "/kraɪ/", "en": "to make sounds with tears in your eyes", "zh": "v. 哭；喊叫", "eg": "The baby cried all night."}, {"w": "asleep", "ph": "/əˈsliːp/", "en": "sleeping", "zh": "adj. 睡着的", "eg": "The baby was asleep at last."}],exprs:[{"en": "So am I / So did I / So can I", "zh": "我也是", "scene": "倒装里的助动词必须和前一句同款：be 对 be，情态对情态，其余用 do。", "struct": "So + be/助动词/情态动词 + 主语", "cat": "dailychat", "ex": ["I'm tired. — So am I.", "I'd love some coffee. — So would I."]}, {"en": "Neither did I / Neither can I", "zh": "我也不", "scene": "否定附和，did、can、have 跟着前一句走。", "struct": "Neither + be/助动词/情态动词 + 主语", "cat": "dailychat", "ex": ["I didn't sleep well. — Neither did I.", "I can't work now. — Neither can I."]}, {"en": "have / take a break", "zh": "休息一下", "scene": "工作间隙喘口气，办公室里的高频句。", "struct": "have/take a (short) break", "cat": "work", "ex": ["Let's have a short break.", "I need a break after this meeting."]}],pats:[{"en": "So + be/助动词/情态动词 + 主语", "zh": "……也一样（肯定）", "scene": "前后两句主语不是同一个人，这点别和「So + 主语 + 助动词（可不是嘛）」搞混。", "struct": "So + be/助动词/情态动词 + 主语", "cat": "dailychat", "ex": ["I've finished. — So have I.", "I went home early. — So did I."]}, {"en": "Neither / Nor + be/助动词/情态动词 + 主语", "zh": "……也一样不（否定）", "scene": "句子里已经有 Neither，动词就不能再写成否定式。", "struct": "Neither/Nor + be/助动词/情态动词 + 主语", "cat": "dailychat", "ex": ["I didn't go. — Neither did I.", "I'm not ready. — Neither am I."]}],quiz:{"v": {"q": "have a break 中 break 的意思是：", "opts": ["打破", "休息", "打断"], "a": 1}, "e": {"q": "对方说 I didn't sleep well，你想说「我也没睡好」：", "opts": ["So did I.", "Neither didn't I.", "Neither did I."], "a": 2}, "p": {"q": "I'm very tired. — ______ am I.", "opts": ["So", "Neither", "Nor"], "a": 0}},speak:"说 5 句话：和同事互相附和——一句肯定用 So …，一句否定用 Neither …，am/did/can/have 要跟前一句对上，最后用 Let's … 提议休息。"},
{n:115,title:"Knock, Knock!",topic:"复合不定代词 anyone / nobody / nothing · must be 表推测",reading:"Knock, knock! Is there anyone at home?\n\nNobody answered. Let's look through the window.\n\nCan you see anything?\n\nNo, nothing at all. Everything is very quiet.\n\nBut that's impossible. Carol invited us to lunch.\n\nSomeone must be in the house.\n\nLook! There's somebody in the garden.\n\nSo there is. And I can smell something nice, too.\n\nSomething smells wonderful.\n\nCarol is cooking lunch in the garden, I think.\n\nThen let's go round to the back and surprise her.\n\nGood idea. She will be very happy.",zh:"（原创改写）咚，咚！有人在家吗？\n\n没人应。我们从窗户往里看看。\n\n你能看见什么吗？\n\n什么也没有。一切都静悄悄的。\n\n可这不可能啊。卡萝尔请我们来吃午饭的。\n\n屋里一定有人。\n\n看！花园里有个人。\n\n还真是。而且我还闻到一股香味。\n\n什么东西这么香。\n\n我想卡萝尔正在花园里做午饭。\n\n那我们绕到后面去给她个惊喜吧。\n\n好主意。她一定会很高兴。",vocab:[{"w": "knock", "ph": "/nɒk/", "en": "to hit a door to get someone's attention", "zh": "v./n. 敲；敲门声", "eg": "Knock at the door before you go in."}, {"w": "nobody", "ph": "/ˈnəʊbədi/", "en": "no person", "zh": "pron. 没有人", "eg": "Nobody answered the door."}, {"w": "quiet", "ph": "/ˈkwaɪət/", "en": "with little or no noise", "zh": "adj. 安静的", "eg": "Everything is very quiet."}, {"w": "invite", "ph": "/ɪnˈvaɪt/", "en": "to ask someone to come somewhere", "zh": "v. 邀请", "eg": "Carol invited us to lunch."}],exprs:[{"en": "Is there anyone / anything …?", "zh": "有人／有东西……吗？", "scene": "疑问句和否定句里用 any- 系列，肯定句里换成 some- 系列。", "struct": "Is there anyone/anything + 地点?", "cat": "dailychat", "ex": ["Is there anyone at home?", "Can you see anything?"]}, {"en": "nothing at all", "zh": "一点东西也没有", "scene": "at all 加在否定词后面，把「没有」的语气拉满。", "struct": "nothing/nobody + at all", "cat": "emotion", "ex": ["No, nothing at all.", "There's nobody at all in the office."]}, {"en": "主语 + must be …", "zh": "一定是……", "scene": "对眼下的情况做肯定推测，很有把握时用 must，沒把握用 may。", "struct": "主语 + must be + 表语/doing", "cat": "opinion", "ex": ["Someone must be in the house.", "He must be at work now."]}],pats:[{"en": "There is someone / nobody + 地点", "zh": "某地有人／没有人", "scene": "不定代词作主语，谓语一律按单数处理。", "struct": "There is + someone/somebody/nobody + 地点", "cat": "dailychat", "ex": ["There's somebody in the garden.", "There is nobody in the room."]}, {"en": "不定代词 + 形容词", "zh": "……的人／东西", "scene": "形容词修饰 something、anything、nobody 时必须放在后面。", "struct": "something/anything/nothing + 形容词", "cat": "dailychat", "ex": ["I can smell something nice.", "Is there anything wrong?"]}],quiz:{"v": {"q": "nobody 的意思是：", "opts": ["有人", "没有人", "每个人"], "a": 1}, "e": {"q": "敲门时问「有人在家吗」，应该说：", "opts": ["Is there someone at home?", "Is there anyone at home?", "Is there nobody at home?"], "a": 1}, "p": {"q": "I can smell ______ nice in the kitchen.", "opts": ["anything", "nothing", "something"], "a": 2}},speak:"说 4 句话：到朋友家门口敲门没人应，用 Is there anyone at home?、Can you see anything?、nothing at all 描述现场，最后用 Someone must be … 给出你的推断。"},
{n:116,title:"Nothing at All",topic:"everyone / someone / anyone / no one · 复合不定代词与附和",reading:"Everyone is busy this morning. Where shall we go?\n\nNobody wants to stay in the office, that's for sure.\n\nDoes anyone know a quiet place near here?\n\nSomebody told me about a small park.\n\nIs there anything to eat there?\n\nThere's a shop near the gate. It sells everything.\n\nAnd no one will find us there.\n\nGood. Let's tell everyone to meet at twelve.\n\nEveryone will bring something to eat.\n\nThen nobody has to cook. Let's go now.\n\nEveryone is waiting for us outside.",zh:"（原创改写）今天上午大家都很忙。我们去哪儿？\n\n没人愿意待在办公室，这点毫无疑问。\n\n有谁知道这附近有安静的地方吗？\n\n有人跟我提过一个小公园。\n\n那儿有吃的吗？\n\n门口有家店，什么都卖。\n\n而且没人会找到我们。\n\n好，那通知大家十二点集合。\n\n每个人都会带点吃的来。\n\n那就没人需要做饭了。我们现在走吧。\n\n大家都在外面等我们呢。",vocab:[{"w": "everyone", "ph": "/ˈevriwʌn/", "en": "every person", "zh": "pron. 每个人；大家", "eg": "Everyone is busy this morning."}, {"w": "somewhere", "ph": "/ˈsʌmweə(r)/", "en": "a place that you do not name exactly", "zh": "adv. 某处；某个地方", "eg": "Let's go somewhere quiet."}, {"w": "sell", "ph": "/sel/", "en": "to give something to someone for money", "zh": "v. 卖；出售", "eg": "The shop sells everything."}, {"w": "park", "ph": "/pɑːk/", "en": "a public place with grass and trees", "zh": "n. 公园", "eg": "There's a small park near here."}],exprs:[{"en": "everyone / everybody", "zh": "每个人；大家", "scene": "作主语时谓语用单数；后面不能直接接 of，要说 every one of us。", "struct": "Everyone + 单数动词", "cat": "dailychat", "ex": ["Everyone is busy this morning.", "Everyone wants to go."]}, {"en": "anyone / anybody", "zh": "任何人（疑问、否定）", "scene": "疑问句、否定句里用 any- 系列，肯定句里换 someone。", "struct": "Do/Does + anyone + 动词原形?", "cat": "dailychat", "ex": ["Does anyone know a quiet place?", "I don't know anyone here."]}, {"en": "no one / nobody", "zh": "没有人", "scene": "自带否定，句子里不能再加 not；作主语谓语用单数。", "struct": "No one/Nobody + 单数动词", "cat": "dailychat", "ex": ["No one will find us there.", "Nobody wants to stay in."]}],pats:[{"en": "Does anyone + 动词原形?", "zh": "有谁……吗？", "scene": "在人群里找人帮忙的标准问法。", "struct": "Does anyone + 动词原形?", "cat": "work", "ex": ["Does anyone know the answer?", "Does anyone have a pen?"]}, {"en": "Let's tell everyone to + 动词原形", "zh": "咱们通知大家去做……", "scene": "tell + 人 + to do，宾语换成 everyone 也一样成立。", "struct": "Let's tell + 人 + to do", "cat": "work", "ex": ["Let's tell everyone to meet at twelve.", "Let's tell him to wait here."]}],quiz:{"v": {"q": "everyone 作主语时谓语动词用：", "opts": ["复数", "单数", "视情况而定"], "a": 1}, "e": {"q": "「没有人想留下来」应该说：", "opts": ["Nobody don't want to stay.", "No one want to stay.", "Nobody wants to stay."], "a": 2}, "p": {"q": "Is there ______ to eat there?", "opts": ["something", "everything", "anything"], "a": 2}},speak:"说 4 句话：策划一次集体午休，用 Everyone is …、Does anyone …?、Nobody wants to …、There's something/anything … 各说一句。"},
{n:117,title:"Tommy's Breakfast",topic:"比较级与最高级综合 · 不规则形式 good/better/best, bad/worse/worst",reading:"Tommy eats the biggest breakfast in our family.\n\nReally? Does he eat more than you?\n\nMuch more. And he eats more quickly than anyone.\n\nWho gets up earliest?\n\nTommy does. He is always the first one in the kitchen.\n\nHe must be the hungriest boy in the street.\n\nHe isn't hungry. He just likes his mother's cooking best.\n\nThat's the best reason of all.\n\nDoes he eat the most at dinner, too?\n\nNo, he doesn't. His sister eats more than him then.",zh:"（原创改写）汤米是我们家早饭吃得最多的。\n\n真的吗？他吃得比你多？\n\n多得多。而且他吃得比谁都快。\n\n谁起得最早？\n\n汤米。他总是第一个到厨房。\n\n他一定是这条街上最饿的孩子。\n\n他不饿。他只是最喜欢他妈妈做的菜。\n\n这是所有理由里最好的一个。\n\n晚饭也是他吃得最多吗？\n\n不是。那时候他姐姐吃得比他还多。",vocab:[{"w": "breakfast", "ph": "/ˈbrekfəst/", "en": "the food you eat in the morning", "zh": "n. 早餐", "eg": "Tommy eats the biggest breakfast."}, {"w": "hungry", "ph": "/ˈhʌŋɡri/", "en": "wanting to eat", "zh": "adj. 饥饿的", "eg": "He must be very hungry."}, {"w": "quickly", "ph": "/ˈkwɪkli/", "en": "fast; in a short time", "zh": "adv. 快速地", "eg": "He eats more quickly than anyone."}, {"w": "early", "ph": "/ˈɜːli/", "en": "before the usual time", "zh": "adv./adj. 早", "eg": "Who gets up earliest?"}],exprs:[{"en": "the + 最高级 + in/of + 范围", "zh": "在……中最……", "scene": "三者以上才用最高级，前面的 the 别落下。", "struct": "the + 最高级 (+ 名词) + in/of + 范围", "cat": "dailychat", "ex": ["He eats the biggest breakfast in our family.", "She is the tallest girl in the class."]}, {"en": "more + 副词/多音节形容词 + than", "zh": "比……更……", "scene": "副词比较级也用 more：more quickly、more carefully。", "struct": "more + 副词/多音节形容词 + than", "cat": "dailychat", "ex": ["He eats more quickly than anyone.", "She works more carefully than me."]}, {"en": "good — better — best / bad — worse — worst", "zh": "好—更好—最好／坏—更坏—最坏", "scene": "这几个不规则变化只能硬背，不能加 -er/-est。", "struct": "不规则比较级/最高级", "cat": "dailychat", "ex": ["He likes his mother's cooking best.", "This one is better than that one."]}],pats:[{"en": "主语 + 动词 + the + 最高级 + in/of + 范围", "zh": "……是……里最……的", "scene": "动词不限于 be，eat、run、get up 都能带最高级。", "struct": "主语 + 动词 + the + 最高级 + in/of + 范围", "cat": "experience", "ex": ["He eats the most in our family.", "She gets up the earliest of us all."]}, {"en": "主语 + 动词 + 比较级 + than + 人/物", "zh": "……比……更……", "scene": "比较级前面还能加 much、a lot 来加强：much more。", "struct": "主语 + 动词 + (much) + 比较级 + than", "cat": "dailychat", "ex": ["He eats much more than me.", "She runs a lot faster than him."]}],quiz:{"v": {"q": "hungry 的意思是：", "opts": ["渴的", "饥饿的", "困的"], "a": 1}, "e": {"q": "「他吃得比谁都快」应该说：", "opts": ["He eats more quick than anyone.", "He eats more quickly than anyone.", "He eats quicker than anyone fast."], "a": 1}, "p": {"q": "Tommy is the ______ boy in the street.", "opts": ["hungryest", "hungriest", "hungrier"], "a": 1}},speak:"说 4 句话：用最高级说你家里或班上的三个「之最」（吃得最多、起得最早、最努力），再用比较级 + than 比一次，注意 good/bad 的不规则变化。"},
{n:118,title:"The Quickest Breakfast",topic:"副词比较级与最高级 · as + 副词原级 + as",reading:"Who finishes breakfast the most quickly in your family?\n\nMy brother does. He can finish in three minutes.\n\nCan you eat as quickly as he does?\n\nNo, I eat more slowly. I like to read the paper.\n\nMy sister eats the most slowly of all.\n\nBut she gets up the earliest, doesn't she?\n\nYes, and she works the hardest, too.\n\nThen she has the best reason to be in a hurry.\n\nThat's true. She is never in a hurry, and she is never late.",zh:"（原创改写）你们家早饭吃得最快的是谁？\n\n我哥哥。他三分钟就能吃完。\n\n你能吃得跟他一样快吗？\n\n不能，我吃得慢一些。我喜欢边吃边看报。\n\n我妹妹是所有人里吃得最慢的。\n\n可她起得最早，不是吗？\n\n是啊，而且她干活也最卖力。\n\n那她最不该着急才对。\n\n没错。她从来不着急，也从来不迟到。",vocab:[{"w": "paper", "ph": "/ˈpeɪpə(r)/", "en": "a newspaper, or the material you write on", "zh": "n. 报纸；纸", "eg": "I like to read the paper at breakfast."}, {"w": "slowly", "ph": "/ˈsləʊli/", "en": "not fast", "zh": "adv. 缓慢地", "eg": "I eat more slowly than my brother."}, {"w": "minute", "ph": "/ˈmɪnɪt/", "en": "sixty seconds", "zh": "n. 分钟", "eg": "He can finish in three minutes."}, {"w": "hard", "ph": "/hɑːd/", "en": "with a lot of effort", "zh": "adv. 努力地；adj. 困难的", "eg": "She works the hardest in the team."}],exprs:[{"en": "the most + 副词 / 副词 + -est", "zh": "最……地", "scene": "副词最高级前面的 the 可以省略，口语里经常省。", "struct": "(the) + 副词最高级 + in/of + 范围", "cat": "dailychat", "ex": ["He finishes the most quickly.", "She works (the) hardest of all."]}, {"en": "as + 副词原级 + as", "zh": "和……一样……地", "scene": "副词也能做同级比较，中间同样用原级。", "struct": "动词 + as + 副词原级 + as + 人/物", "cat": "dailychat", "ex": ["Can you eat as quickly as he does?", "I can't run as fast as you."]}, {"en": "work / study the hardest", "zh": "工作／学习最努力", "scene": "hard 的比较级、最高级是规则变化，别写成 more hard。", "struct": "动词 + (the) + hardest", "cat": "work", "ex": ["She works the hardest.", "He studies the hardest of us three."]}],pats:[{"en": "主语 + 动词 + (the) + 副词最高级 + in/of + 范围", "zh": "……做得最……", "scene": "副词最高级修饰动作，说明「程度到了顶」。", "struct": "主语 + 动词 + (the) + 副词最高级", "cat": "dailychat", "ex": ["He finishes (the) most quickly.", "She sings (the) most beautifully."]}, {"en": "主语 + 动词 + as + 副词原级 + as + 人/物", "zh": "……做得和……一样……", "scene": "否定时第一个 as 换成 not so 或 not as 都行。", "struct": "主语 + 动词 + as + 副词原级 + as", "cat": "dailychat", "ex": ["I don't eat as quickly as he does.", "She speaks as clearly as a teacher."]}],quiz:{"v": {"q": "slowly 的意思是：", "opts": ["缓慢地", "安静地", "快速地"], "a": 0}, "e": {"q": "「我吃得没有他快」应该说：", "opts": ["I don't eat as quick as he does.", "I don't eat as quickly as he does.", "I don't eat so quickly as him fast."], "a": 1}, "p": {"q": "My sister eats the ______ slowly of all.", "opts": ["more", "most", "much"], "a": 1}},speak:"说 4 句话：比较你和家人做事的速度，用 as … as 或 not as … as 说一次，再用副词最高级（the most quickly / the hardest / the earliest）说两次。"},
{n:119,title:"A True Story",topic:"as … as 与 not as … as · 打比方与纠正夸张",reading:"I'll tell you a true story. It happened last summer.\n\nWas it as strange as people say?\n\nNot as strange as that. A big dog ran into our garden.\n\nWas it dangerous?\n\nIt looked as big as a horse, but it was as gentle as a lamb.\n\nWhat did you do?\n\nI called the police. The dog just sat by the gate and waited.\n\nIt was as quiet as a mouse. The police found its owner an hour later.\n\nIt really happened, I promise.",zh:"（原创改写）我给你讲个真实的故事。去年夏天发生的。\n\n它有人们说的那么离奇吗？\n\n没那么离奇。一只大狗跑进了我们家花园。\n\n它危险吗？\n\n它看着像马一样大，性子却像羊羔一样温顺。\n\n你们怎么办的？\n\n我报了警。那只狗就蹲在门口等着。\n\n它安静得像只老鼠。一小时后警察找到了它的主人。\n\n这事真的发生了，我保证。",vocab:[{"w": "true", "ph": "/truː/", "en": "real; not invented", "zh": "adj. 真实的；真的", "eg": "I'll tell you a true story."}, {"w": "happen", "ph": "/ˈhæpən/", "en": "to take place, usually by chance", "zh": "v. 发生", "eg": "It happened last summer."}, {"w": "gentle", "ph": "/ˈdʒentl/", "en": "calm and kind; not violent", "zh": "adj. 温顺的；温和的", "eg": "It was as gentle as a lamb."}, {"w": "owner", "ph": "/ˈəʊnə(r)/", "en": "the person something belongs to", "zh": "n. 主人；所有者", "eg": "The police found its owner."}],exprs:[{"en": "as + 形容词 + as + a + 名词", "zh": "像……一样……", "scene": "用大家熟悉的东西打比方：as big as a horse、as quiet as a mouse。", "struct": "as + 形容词 + as + a + 名词", "cat": "humor", "ex": ["It looked as big as a horse.", "He is as busy as a bee."]}, {"en": "not as + 形容词 + as + 名词/从句", "zh": "不像……那样……", "scene": "把别人的夸张说法拉回现实，语气很自然。", "struct": "not as + 形容词 + as", "cat": "opinion", "ex": ["It wasn't as strange as that.", "It's not as difficult as you think."]}, {"en": "tell you a true story", "zh": "给你讲个真实的故事", "scene": "开场白：先声明是真事，再把人拉进情节。", "struct": "tell + 人 + a story", "cat": "experience", "ex": ["I'll tell you a true story.", "Let me tell you a story about my first day."]}],pats:[{"en": "It happened + 时间/地点", "zh": "事情发生在……", "scene": "讲故事的第一句，交代时间地点，happen 不用被动。", "struct": "主语 + happen + 时间/地点状语", "cat": "experience", "ex": ["It happened last summer.", "The accident happened near the station."]}, {"en": "主语 + look + as + 形容词 + as …", "zh": "看着像……一样……", "scene": "look 是系动词，后面直接跟形容词，说明「看起来如何」。", "struct": "主语 + look + as + 形容词 + as", "cat": "experience", "ex": ["It looked as big as a horse.", "She looks as tired as her brother."]}],quiz:{"v": {"q": "gentle 的意思是：", "opts": ["凶猛的", "温顺的", "聪明的"], "a": 1}, "e": {"q": "「它没有人们说的那么离奇」应该说：", "opts": ["It isn't as stranger as that.", "It isn't so strange than that.", "It isn't as strange as that."], "a": 2}, "p": {"q": "It wasn't ______ strange as people say.", "opts": ["so", "as", "than"], "a": 1}},speak:"说 5 句话：讲一件真实发生的小事，用 I'll tell you a true story. 开头，用 as … as 打一个比方，用 not as … as 纠正夸张的说法，最后交代结果。"},
{n:120,title:"Not as Easy as It Looks",topic:"比较级与最高级综合复习 · 同级比较",reading:"Is English as difficult as Chinese?\n\nNo, but it isn't as easy as some people think.\n\nWhich is more difficult, speaking or writing?\n\nSpeaking is more difficult for me. I speak more slowly than I write.\n\nWho is the best student in your class?\n\nLucy is. She reads the most and asks the most questions.\n\nDoes she study the longest?\n\nNo, she studies the most carefully. That's the secret.\n\nThen I should read more, too.\n\nYes. The more you read, the better you write.",zh:"（原创改写）英语和中文一样难吗？\n\n不，不过它也不像有些人想的那么容易。\n\n说和写，哪个更难？\n\n对我来说说更难。我说得比写得慢。\n\n你们班谁是最好的学生？\n\n露西。她读得最多，问题也问得最多。\n\n她学习时间最长吗？\n\n不，她学得最认真。这才是秘诀。\n\n那我也该多读点。\n\n对。读得越多，写得越好。",vocab:[{"w": "secret", "ph": "/ˈsiːkrət/", "en": "something only a few people know", "zh": "n. 秘诀；秘密", "eg": "That's the secret."}, {"w": "question", "ph": "/ˈkwestʃən/", "en": "something you ask someone", "zh": "n. 问题", "eg": "She asks the most questions."}, {"w": "study", "ph": "/ˈstʌdi/", "en": "to learn about a subject", "zh": "v. 学习；研究", "eg": "She studies the most carefully."}, {"w": "speak", "ph": "/spiːk/", "en": "to say words with your mouth", "zh": "v. 说；讲", "eg": "I speak more slowly than I write."}],exprs:[{"en": "Which is more difficult, A or B?", "zh": "A 和 B，哪个更难？", "scene": "二选一的比较问句，比较级放在中间。", "struct": "Which + be + 比较级, A or B?", "cat": "dailychat", "ex": ["Which is more difficult, speaking or writing?", "Which is more useful, a phone or a computer?"]}, {"en": "the most + 副词", "zh": "最……地", "scene": "副词最高级，表示动作做到极致。", "struct": "动词 + the most", "cat": "hobby", "ex": ["She reads the most.", "He travels the most in our office."]}, {"en": "not as + 形容词 + as some people think", "zh": "不像有些人想的那样……", "scene": "纠正刻板印象，非常地道的一句口语句型。", "struct": "not as + 形容词 + as + 人 + think", "cat": "opinion", "ex": ["It isn't as easy as some people think.", "It's not as boring as you think."]}],pats:[{"en": "A + be + as + 形容词原级 + as + B", "zh": "A 和 B 一样……", "scene": "同级比较，否定形式是把第一个 as 换成 not as / not so。", "struct": "A + be + as + 原级 + as + B", "cat": "dailychat", "ex": ["Is English as difficult as Chinese?", "It isn't as easy as that."]}, {"en": "主语 + 动词 + the most + 副词", "zh": "……做得最多／最……", "scene": "the most 本身就是副词最高级，后面不用再跟名词。", "struct": "主语 + 动词 + the most", "cat": "hobby", "ex": ["She reads the most in our class.", "He complains the most but works the least."]}],quiz:{"v": {"q": "secret 的意思是：", "opts": ["答案", "秘密；秘诀", "问题"], "a": 1}, "e": {"q": "「它不像有些人想的那么容易」应该说：", "opts": ["It isn't as easier as some people think.", "It isn't so easy than some people think.", "It isn't as easy as some people think."], "a": 2}, "p": {"q": "She studies the ______ carefully in our class.", "opts": ["more", "most", "much"], "a": 1}},speak:"说 5 句话：比较两门语言或两项技能，as … as、Which is more …, A or B?、the most … 各用一次，最后说出学好它的「秘诀」。"},
{n:121,title:"The Man in a Hat",topic:"定语从句 who / that 指人 · 描述与辨认人物",reading:"Do you know the man who is standing by the door?\n\nYou mean the man in the hat?\n\nYes. He's the man who came here yesterday.\n\nWhat does he want?\n\nHe's the teacher that my sister told me about.\n\nDoes he teach English?\n\nNo, he teaches music. He's the man who lives next to the bank.\n\nOh, I know him now. He's the man that bought the old piano.\n\nHe is the man that everyone likes.\n\nReally? Then let's go and say hello.",zh:"（原创改写）你认识站在门口的那个人吗？\n\n你是说戴帽子的那位？\n\n对。他就是昨天来过的那个人。\n\n他想干什么？\n\n他就是我姐姐跟我说起过的那位老师。\n\n他教英语吗？\n\n不，他教音乐。他就是住在银行隔壁的那个人。\n\n哦，我现在知道是谁了。他就是买下那架旧钢琴的人。\n\n他是人人都喜欢的那个人。\n\n真的吗？那我们过去打个招呼吧。",vocab:[{"w": "hat", "ph": "/hæt/", "en": "a thing you wear on your head", "zh": "n. 帽子", "eg": "Do you mean the man in the hat?"}, {"w": "stand", "ph": "/stænd/", "en": "to be on your feet", "zh": "v. 站；站立", "eg": "He's standing by the door."}, {"w": "piano", "ph": "/piˈænəʊ/", "en": "a large musical instrument with black and white keys", "zh": "n. 钢琴", "eg": "He bought an old piano."}, {"w": "bank", "ph": "/bæŋk/", "en": "a place where people keep and borrow money", "zh": "n. 银行；河岸", "eg": "He lives next to the bank."}],exprs:[{"en": "the man who …", "zh": "……的那个人", "scene": "who 引导定语从句修饰人，在从句里当主语，不能省掉。", "struct": "the + 人 + who + 谓语", "cat": "dailychat", "ex": ["He's the man who came here yesterday.", "She's the girl who lives next door."]}, {"en": "the + 名词 + that …", "zh": "……的那个（人或物）", "scene": "that 既能指人也能指物，口语里用得最多。", "struct": "the + 名词 + that + 从句", "cat": "dailychat", "ex": ["He's the teacher that my sister told me about.", "It's the book that I want."]}, {"en": "tell sb about …", "zh": "跟某人说起……", "scene": "定语从句里常见这个搭配，about 不能省。", "struct": "tell + 人 + about + 名词", "cat": "dailychat", "ex": ["She told me about the new teacher.", "Tell me about your trip."]}],pats:[{"en": "Do you know the man who …?", "zh": "你认识……的那个人吗？", "scene": "拜托别人认人的开场白，who 从句用来描述特征。", "struct": "Do you know the + 人 + who + 从句?", "cat": "dailychat", "ex": ["Do you know the man who is standing by the door?", "Do you know the girl who is talking to Tom?"]}, {"en": "主语 + be + the + 名词 + who/that + 从句", "zh": "……就是……的那个人", "scene": "定语从句放在名词后面，相当于一个大号形容词。", "struct": "主语 + be + the + 名词 + who/that + 从句", "cat": "dailychat", "ex": ["He's the man who lives next to the bank.", "She's the teacher that I told you about."]}],quiz:{"v": {"q": "hat 的意思是：", "opts": ["围巾", "帽子", "手套"], "a": 1}, "e": {"q": "「他就是昨天来的那个人」应该说：", "opts": ["He's the man which came yesterday.", "He's the man who came yesterday.", "He's the man what came yesterday."], "a": 1}, "p": {"q": "She's the girl ______ lives next door.", "opts": ["which", "whose", "who"], "a": 2}},speak:"说 4 句话：用 Do you know the man who…? 认人，用 the man/girl who… 和 the … that … 描述他的职业、住处以及你听说过的一件事。"},
{n:122,title:"The Book I Bought",topic:"省略关系代词 · the book (that) I bought",reading:"Is that the book you bought yesterday?\n\nYes, it is. It's the book I told you about.\n\nIs it the one you wanted?\n\nNo, it isn't. It's the one the shop assistant gave me.\n\nDid you pay a lot for it?\n\nIt cost ten pounds. That's the price he offered me.\n\nDo you like the story?\n\nYes. It's the best book I have ever read.\n\nWhere did you buy it?\n\nIn the small shop which is next to the library.",zh:"（原创改写）这就是你昨天买的那本书吗？\n\n是的。就是我跟你说过的那本。\n\n它是你想要的那本吗？\n\n不是。这是店员给我的那本。\n\n你花了很多钱吗？\n\n花了十英镑。那是他给我的价。\n\n你喜欢这个故事吗？\n\n喜欢。这是我读过的最好的一本书。\n\n你在哪儿买的？\n\n在图书馆旁边那家小店。",vocab:[{"w": "assistant", "ph": "/əˈsɪstənt/", "en": "a person who helps customers in a shop", "zh": "n. 店员；助手", "eg": "The shop assistant gave it to me."}, {"w": "price", "ph": "/praɪs/", "en": "how much you must pay for something", "zh": "n. 价格", "eg": "That's the price he offered me."}, {"w": "offer", "ph": "/ˈɒfə(r)/", "en": "to say you will give or pay something", "zh": "v. 出价；提供", "eg": "He offered me a good price."}, {"w": "story", "ph": "/ˈstɔːri/", "en": "a description of things that happened", "zh": "n. 故事", "eg": "Do you like the story?"}],exprs:[{"en": "the book (that) I bought", "zh": "我买的（那本）书", "scene": "关系代词在从句里作宾语时可以整个省掉，口语里几乎都省。", "struct": "the + 名词 + (that/which) + 主语 + 谓语", "cat": "dailychat", "ex": ["Is that the book you bought yesterday?", "It's the film I watched last night."]}, {"en": "the one (that) …", "zh": "……的那一个", "scene": "one 代替前面提过的东西，后面照样能挂定语从句。", "struct": "the one + (that) + 从句", "cat": "dailychat", "ex": ["It's the one the assistant gave me.", "Is it the one you wanted?"]}, {"en": "the best + 名词 + (that) + 现在完成时", "zh": "我曾经……过的最……的……", "scene": "最高级后面接定语从句，从句常用现在完成时。", "struct": "the + 最高级 + 名词 + (that) + 主语 + have/has + 过去分词", "cat": "experience", "ex": ["It's the best book I have ever read.", "It's the worst film I've ever seen."]}],pats:[{"en": "the + 名词 + (that/which) + 主语 + 谓语", "zh": "（某人）……的那个……", "scene": "关系代词作宾语时省略，句子更短更口语。", "struct": "the + 名词 + (that/which) + 主语 + 谓语", "cat": "dailychat", "ex": ["That's the pen I lost.", "It's the cake she made."]}, {"en": "the + 最高级 + 名词 + (that) + 主语 + have/has + 过去分词", "zh": "某人经历过的最……的……", "scene": "ever 常嵌在完成时里加强语气。", "struct": "the + 最高级 + 名词 + (that) + 主语 + have/has ever + 过去分词", "cat": "experience", "ex": ["It's the longest letter I've ever written.", "It's the best meal I've ever had."]}],quiz:{"v": {"q": "price 的意思是：", "opts": ["价格", "折扣", "尺寸"], "a": 0}, "e": {"q": "「这是我昨天买的书」应该说：", "opts": ["It's the book what I bought yesterday.", "It's the book I bought yesterday.", "It's the book which I bought it yesterday."], "a": 1}, "p": {"q": "It's the book ______ I told you about.", "opts": ["what", "who", "which"], "a": 2}},speak:"说 4 句话：用 the book/film (that) I … 省略关系代词描述你买过或看过的一样东西，用 the one (that) … 补充说明，最后用 the best … I have ever … 给出评价。"},
{n:123,title:"A Trip to Australia",topic:"定语从句 which / that 指物 · 描述旅行",reading:"Look at these photos which I took in Australia.\n\nWho is the man that is standing next to you?\n\nThat's my guide. He drove us across the desert.\n\nIs that the hotel which you stayed in?\n\nYes. It's the smallest hotel in the town, but the food was good.\n\nWhat is the animal that is sitting on the rock?\n\nIt's a koala. It's the animal which I liked most.\n\nI'd love to go there, too.\n\nIt was the best trip of my life.",zh:"（原创改写）看看这些我在澳大利亚拍的照片。\n\n站在你旁边那个人是谁？\n\n那是我的向导。他开车带我们穿过沙漠。\n\n那就是你住过的那家旅馆吗？\n\n是的。它是镇上最小的旅馆，不过饭菜不错。\n\n坐在石头上的那只动物是什么？\n\n是考拉。它是我最喜欢的动物。\n\n我也想去那儿。\n\n那是我这辈子最好的一次旅行。",vocab:[{"w": "guide", "ph": "/ɡaɪd/", "en": "a person who shows people around a place", "zh": "n. 向导；导游", "eg": "That's my guide. He drove us across the desert."}, {"w": "desert", "ph": "/ˈdezət/", "en": "a large dry area with very little water", "zh": "n. 沙漠", "eg": "We drove across the desert."}, {"w": "rock", "ph": "/rɒk/", "en": "a hard piece of stone", "zh": "n. 岩石；石头", "eg": "The animal is sitting on the rock."}, {"w": "trip", "ph": "/trɪp/", "en": "a journey to a place and back", "zh": "n. 旅行；行程", "eg": "It was the best trip of my life."}],exprs:[{"en": "the + 物 + which …", "zh": "……的那个东西", "scene": "which 引导定语从句修饰物，在从句里作主语时不能省。", "struct": "the + 名词 + which + 谓语", "cat": "experience", "ex": ["Look at the photos which I took in Australia.", "This is the train which goes to Sydney."]}, {"en": "the + 物 + that …", "zh": "……的那个东西（口语）", "scene": "that 指物时和 which 通用，口语里更常见。", "struct": "the + 名词 + that + 从句", "cat": "experience", "ex": ["What is the animal that is sitting on the rock?", "It's the bag that I lost."]}, {"en": "the hotel (which) I stayed in", "zh": "我住过的那家旅馆", "scene": "stay 是不及物动词，句末的 in 必须留着，否则句子缺一块。", "struct": "the + 地点 + (which/that) + 主语 + 动词 + 介词", "cat": "experience", "ex": ["Is that the hotel you stayed in?", "It's the town I grew up in."]}],pats:[{"en": "the + 物 + which/that + 谓语（作主语）", "zh": "……的那个……", "scene": "关系词在从句里作主语时，一个字都不能少。", "struct": "the + 名词 + which/that + 谓语 + 宾语", "cat": "experience", "ex": ["These are the photos which I took there.", "That's the car which broke down."]}, {"en": "the + 物 + (which/that) + 主语 + 动词 + 介词", "zh": "（某人）……过的那个……", "scene": "口语里省掉关系词，但介词要跟在动词后面。", "struct": "the + 名词 + (which/that) + 主语 + 动词 + 介词", "cat": "experience", "ex": ["It's the hotel we stayed in.", "That's the chair he sat on."]}],quiz:{"v": {"q": "guide 的意思是：", "opts": ["司机", "向导；导游", "旅客"], "a": 1}, "e": {"q": "「这是我住过的那家旅馆」应该说：", "opts": ["It's the hotel which I stayed.", "It's the hotel which I stayed in it.", "It's the hotel which I stayed in."], "a": 2}, "p": {"q": "Look at the photos ______ I took in Australia.", "opts": ["what", "who", "which"], "a": 2}},speak:"说 4 句话：展示一组旅行照片，用 the photo/place which …、the man who … 介绍其中两张，用 the hotel (that) I stayed in 说住宿，最后用 I'd love to … 表达愿望。"},
{n:124,title:"The Photos I Took",topic:"省略 which/that · 定语从句作宾语",reading:"Are these the photos you took on holiday?\n\nYes. This is the beach we swam at every morning.\n\nWho is the boy you are standing with?\n\nHe's the boy I met on the first day.\n\nIs that the food you ate there?\n\nYes, it's the fish they cook in a banana leaf.\n\nAnd this is the present I bought for you.\n\nOh, thank you! It's the nicest present I've had.\n\nI'm glad you like it.\n\nI love it. It's the best holiday I've ever had.",zh:"（原创改写）这些是你度假时拍的照片吗？\n\n是的。这就是我们每天早上游泳的那片海滩。\n\n和你站在一起的那个男孩是谁？\n\n他是我第一天认识的那个男孩。\n\n那是你在那儿吃的东西吗？\n\n对，就是他们用香蕉叶包着烤的鱼。\n\n这个是我给你买的礼物。\n\n哦，谢谢！这是我收到的最好的礼物。\n\n你喜欢我真高兴。\n\n我太喜欢了。这是我过得最好的一次假期。",vocab:[{"w": "beach", "ph": "/biːtʃ/", "en": "the area of sand next to the sea", "zh": "n. 海滩", "eg": "This is the beach we swam at."}, {"w": "present", "ph": "/ˈpreznt/", "en": "a gift you give someone", "zh": "n. 礼物", "eg": "This is the present I bought for you."}, {"w": "holiday", "ph": "/ˈhɒlədeɪ/", "en": "a time when you do not work and often travel", "zh": "n. 假期", "eg": "Are these the photos you took on holiday?"}, {"w": "cook", "ph": "/kʊk/", "en": "to prepare food with heat", "zh": "v. 烹饪；做饭", "eg": "It's the fish they cook in a banana leaf."}],exprs:[{"en": "the + 名词 + (that/which) + 主语 + 谓语", "zh": "（某人）……过的那个……", "scene": "关系词在从句里作宾语，直接省掉，最口语。", "struct": "the + 名词 + (that/which) + 主语 + 谓语", "cat": "dailychat", "ex": ["Are these the photos you took on holiday?", "That's the food we ate there."]}, {"en": "the + 人 + (who/that) + 主语 + 谓语", "zh": "（某人）……过的那个人", "scene": "指人时省掉 who 或 that，读起来更顺。", "struct": "the + 人 + (who/that) + 主语 + 谓语", "cat": "relationship", "ex": ["He's the boy I met on the first day.", "She's the teacher I like most."]}, {"en": "buy sth for sb", "zh": "给某人买某物", "scene": "两种说法都行：buy sb sth 或 buy sth for sb。", "struct": "buy + 物 + for + 人", "cat": "dailychat", "ex": ["This is the present I bought for you.", "I bought a gift for my mother."]}],pats:[{"en": "Are these the + 复数名词 + (that) + 从句?", "zh": "这些就是……的……吗？", "scene": "复数名词作先行词，be 动词用 are，从句照旧。", "struct": "Are these the + 复数名词 + (that) + 从句?", "cat": "dailychat", "ex": ["Are these the photos you took?", "Are those the books he gave you?"]}, {"en": "the + 名词 + (that) + 主语 + 动词 + 介词", "zh": "（某人）……过的那个地方", "scene": "省了关系词也别忘了介词：swam at the beach → the beach we swam at。", "struct": "the + 名词 + (that) + 主语 + 动词 + 介词", "cat": "experience", "ex": ["This is the beach we swam at.", "That's the desk he wrote at."]}],quiz:{"v": {"q": "beach 的意思是：", "opts": ["海滩", "山", "湖"], "a": 0}, "e": {"q": "「这是我给你买的礼物」应该说：", "opts": ["This is the present what I bought.", "This is the present I bought for you.", "This is the present I bought you it."], "a": 1}, "p": {"q": "This is the beach ______ we swam at.", "opts": ["what", "who", "which"], "a": 2}},speak:"说 4 句话：给朋友看你度假的照片，用 the beach/place (that) we …、the boy (who) I met、the present (that) I bought for you 各说一句。"},
{n:125,title:"Tea for Two",topic:"定语从句综合 · who / which / that 与省略",reading:"Is there anyone who wants a cup of tea?\n\nYes, please. I'm the person who needs it most.\n\nDo we have everything we need?\n\nThere's the milk which I bought this morning.\n\nAnd the sugar you put on the table?\n\nIt's in the cup which is next to the window.\n\nHere's your tea. It's the tea I make for my best friend.\n\nThank you. It's the nicest cup I've had today.\n\nShall I make another cup?\n\nYes, please. This is the best tea in the world.",zh:"（原创改写）有人想喝杯茶吗？\n\n我要，谢谢。我是最需要它的人。\n\n我们要的东西都齐了吗？\n\n有我今天早上买的牛奶。\n\n你放在桌上的糖呢？\n\n在窗边那个杯子里。\n\n给你茶。这是我给我最好的朋友泡的茶。\n\n谢谢。这是我今天喝过的最好的一杯。\n\n我再泡一杯好吗？\n\n好的，麻烦了。这是世界上最好的茶。",vocab:[{"w": "person", "ph": "/ˈpɜːsn/", "en": "a human being", "zh": "n. 人", "eg": "I'm the person who needs it most."}, {"w": "cup", "ph": "/kʌp/", "en": "a small container you drink from", "zh": "n. 杯子", "eg": "It's in the cup next to the window."}, {"w": "kitchen", "ph": "/ˈkɪtʃɪn/", "en": "the room where you cook food", "zh": "n. 厨房", "eg": "The cups are in the kitchen."}, {"w": "thirsty", "ph": "/ˈθɜːsti/", "en": "wanting to drink", "zh": "adj. 渴的", "eg": "I'm very thirsty after the walk."}],exprs:[{"en": "anyone who …", "zh": "任何……的人", "scene": "不定代词后面也能挂定语从句，指人只能用 who。", "struct": "anyone/someone/everyone + who + 从句", "cat": "dailychat", "ex": ["Is there anyone who wants a cup of tea?", "Someone who knows him will help."]}, {"en": "everything (that) …", "zh": "所有……的东西", "scene": "everything、something 后面用 that，而且 that 常常省掉。", "struct": "everything/something + (that) + 从句", "cat": "dailychat", "ex": ["Do we have everything we need?", "Everything he says is true."]}, {"en": "the + 名词 + I + 动词", "zh": "我……的那个……", "scene": "省略关系代词，最口语、最省事的说法。", "struct": "the + 名词 + (that) + 主语 + 动词", "cat": "dailychat", "ex": ["It's the tea I make for my best friend.", "That's the cake I baked."]}],pats:[{"en": "Is there anyone who + 从句?", "zh": "有谁……吗？", "scene": "在人群里找人，后面用 who 从句说明条件。", "struct": "Is there anyone who + 谓语?", "cat": "dailychat", "ex": ["Is there anyone who wants tea?", "Is there anyone who can drive?"]}, {"en": "Do we have everything (that) + 从句?", "zh": "我们需要的都齐了吗？", "scene": "出门前、开饭前的万能检查句。", "struct": "Do you have everything (that) + 主语 + 谓语?", "cat": "dailychat", "ex": ["Do we have everything we need?", "Have you got everything you want?"]}],quiz:{"v": {"q": "thirsty 的意思是：", "opts": ["饿的", "渴的", "困的"], "a": 1}, "e": {"q": "「有人想喝茶吗」应该说：", "opts": ["Is there anyone which wants tea?", "Is there anyone who wants tea?", "Is there anyone what wants tea?"], "a": 1}, "p": {"q": "Do we have everything we ______?", "opts": ["need", "what need", "which need"], "a": 0}},speak:"说 4 句话：招待朋友喝茶，用 Is there anyone who…?、everything (that) we need、the tea I make for… 介绍，最后用 the nicest … I've had 夸一句。"},
{n:126,title:"The Girl I Went With",topic:"介词 + whom / which · 正式说法与口语说法",reading:"Who is the girl you went to the cinema with?\n\nShe's the girl I work with.\n\nYou mean the girl with whom you share an office?\n\nYes. She's also the friend I travelled to Italy with.\n\nAnd the one you borrowed the camera from?\n\nThat's her, too. She's the person I write to every week.\n\nShe must be a very kind friend.\n\nShe is. She's the kindest person I know.\n\nHow long have you known her?\n\nFor three years. She's the friend I trust most.",zh:"（原创改写）跟你一起去看电影的那个女孩是谁？\n\n她是和我一起工作的女孩。\n\n你是说和你共用一间办公室的那位？\n\n对。她也是和我一起去意大利旅行的朋友。\n\n还有那个你向她借相机的人？\n\n也是她。她是我每周都写信的人。\n\n她一定是个很善良的朋友。\n\n是的。她是我认识的最善良的人。\n\n你认识她多久了？\n\n三年了。她是我最信任的朋友。",vocab:[{"w": "cinema", "ph": "/ˈsɪnəmə/", "en": "a place where you go to watch films", "zh": "n. 电影院", "eg": "We went to the cinema together."}, {"w": "share", "ph": "/ʃeə(r)/", "en": "to use something together with another person", "zh": "v. 分享；共用", "eg": "We share an office."}, {"w": "borrow", "ph": "/ˈbɒrəʊ/", "en": "to take and use something and give it back later", "zh": "v. 借入", "eg": "I borrowed a camera from her."}, {"w": "travel", "ph": "/ˈtrævl/", "en": "to go from one place to another", "zh": "v. 旅行", "eg": "We travelled to Italy together."}],exprs:[{"en": "the + 人 + (who/that) + 主语 + 动词 + 介词", "zh": "和我一起……的那个人（口语）", "scene": "口语里介词留在句末，关系代词整个省掉。", "struct": "the + 名词 + (that/who) + 主语 + 动词 + 介词", "cat": "relationship", "ex": ["She's the girl I work with.", "He's the man I went with."]}, {"en": "介词 + whom / which", "zh": "和……的那个人（正式）", "scene": "介词提到关系词前面时，只能用 whom，不能省也不能换成 who。", "struct": "介词 + whom/which + 从句", "cat": "work", "ex": ["the girl with whom you share an office", "the company for which I work"]}, {"en": "borrow sth from sb", "zh": "向某人借某物", "scene": "borrow 是借进，lend 是借出，方向别搞反。", "struct": "borrow + 物 + from + 人", "cat": "dailychat", "ex": ["the one you borrowed the camera from", "I borrowed a pen from him."]}],pats:[{"en": "the + 名词 + (that) + 主语 + 动词 + 介词", "zh": "（某人）……过的那个……（口语）", "scene": "口语首选：关系词省掉，介词跟在动词后面。", "struct": "the + 名词 + (that) + 主语 + 动词 + 介词", "cat": "dailychat", "ex": ["She's the friend I travelled with.", "He's the man I spoke to."]}, {"en": "介词 + whom + 从句", "zh": "……的那个人（正式）", "scene": "书面、正式场合用；介词提前后，whom 绝不能写成 who。", "struct": "the + 名词 + 介词 + whom + 从句", "cat": "work", "ex": ["the girl with whom I work", "the person to whom I wrote"]}],quiz:{"v": {"q": "borrow 的意思是：", "opts": ["借出", "借入", "归还"], "a": 1}, "e": {"q": "正式说法「和你共用办公室的那个女孩」是：", "opts": ["the girl with who you share an office", "the girl with whom you share an office", "the girl who you share an office with her"], "a": 1}, "p": {"q": "She's the friend ______ I travelled to Italy.", "opts": ["with who", "with whom", "who with"], "a": 1}},speak:"说 4 句话：介绍一位既是同事又是朋友的人，用 the girl (who) I work with、the friend (that) I travelled with、the person (that) I borrowed … from，再换成一次正式的 介词 + whom。"},
{n:127,title:"A Famous Actress",topic:"who / that 描述人物 · 定语从句与最高级综合",reading:"Look at that woman who is getting out of the car.\n\nIs she the actress who was on television last night?\n\nYes. She's the actress that everyone is talking about.\n\nDoes she live here?\n\nNo. She's the woman who owns the big house by the lake.\n\nWho is the man that is standing beside her?\n\nHe's the man who drives her car and looks after the garden.\n\nShe's the most famous person I've ever met.\n\nShe smiles at everyone she meets here.",zh:"（原创改写）看那个正从车里出来的女人。\n\n她就是昨晚电视上出现的那个女演员吗？\n\n是的。她就是大家都在谈论的那个女演员。\n\n她住这儿吗？\n\n不。她就是拥有湖边那栋大房子的女人。\n\n站在她旁边那个男人是谁？\n\n他是给她开车、照看花园的人。\n\n她是我见过的最有名的人。\n\n她对这儿遇见的每个人都微笑。",vocab:[{"w": "actress", "ph": "/ˈæktrəs/", "en": "a woman who acts in films or plays", "zh": "n. 女演员", "eg": "She's the actress who was on television."}, {"w": "famous", "ph": "/ˈfeɪməs/", "en": "known by many people", "zh": "adj. 著名的", "eg": "She's the most famous person here."}, {"w": "gardener", "ph": "/ˈɡɑːdnə(r)/", "en": "a person who looks after a garden", "zh": "n. 园丁", "eg": "The gardener looks after the house."}, {"w": "beside", "ph": "/bɪˈsaɪd/", "en": "next to", "zh": "prep. 在……旁边", "eg": "Who is the man beside her?"}],exprs:[{"en": "the + 人 + who + 谓语", "zh": "……的那个人", "scene": "who 在从句里作主语，紧紧跟在先行词后面。", "struct": "the + 人 + who + 谓语 + 宾语", "cat": "dailychat", "ex": ["Look at the woman who is getting out of the car.", "He's the man who drives her car."]}, {"en": "everyone is talking about …", "zh": "大家都在谈论……", "scene": "形容某人正红、某事正热，很地道的一句。", "struct": "everyone + be + talking about + 名词", "cat": "humor", "ex": ["She's the actress that everyone is talking about.", "It's the film everyone is talking about."]}, {"en": "the most famous + 名词 + (that) + 现在完成时", "zh": "我见过／听说过的最有名的……", "scene": "最高级 + 定语从句，从句用现在完成时最自然。", "struct": "the + 最高级 + 名词 + (that) + 主语 + have/has + 过去分词", "cat": "experience", "ex": ["She's the most famous person I've ever met.", "It's the strangest thing I've ever heard."]}],pats:[{"en": "Is she the + 名词 + who + 从句?", "zh": "她就是……的那个人吗？", "scene": "确认身份，把 be 提到句首。", "struct": "Be + 主语 + the + 名词 + who + 从句?", "cat": "dailychat", "ex": ["Is she the actress who was on television?", "Is he the man who called you?"]}, {"en": "the + 人 + who + 动词 + and + 动词", "zh": "做……又做……的那个人", "scene": "一个从句里可以并列两个动作，还是同一个 who 管着。", "struct": "the + 人 + who + 动词 + and + 动词", "cat": "dailychat", "ex": ["He's the man who drives her car and cleans the house.", "She's the woman who cooks and teaches."]}],quiz:{"v": {"q": "actress 的意思是：", "opts": ["女演员", "导演", "歌手"], "a": 0}, "e": {"q": "「她就是昨晚电视上那个女演员」应该说：", "opts": ["She's the actress which was on TV last night.", "She's the actress who was on TV last night.", "She's the actress what was on TV last night."], "a": 1}, "p": {"q": "He's the man ______ drives her car.", "opts": ["which", "what", "who"], "a": 2}},speak:"说 4 句话：指着照片或街上的某个人，用 the woman who…、the man that…、the most famous person (that) I've ever met 认人并描述。"},
{n:128,title:"The Girl Who Sat Here",topic:"whom 作宾语 · 介词 + whom 综合",reading:"Do you remember the girl who sat here yesterday?\n\nThe girl whom you spoke to for an hour?\n\nYes. She's the student whom the teacher praised.\n\nWhat did she want?\n\nShe's the person from whom I borrowed this dictionary.\n\nIs she the girl who lives in Green Street?\n\nYes. She's also the one with whom I go to class.\n\nShe seems to know everyone in this school.\n\nShe is the kind of person who helps everyone.\n\nThen I must meet her one day.",zh:"（原创改写）你记得昨天坐在这儿的那个女孩吗？\n\n你跟她聊了一个小时的那个？\n\n对。她是老师表扬过的那个学生。\n\n她来干什么？\n\n她就是我向她借这本词典的人。\n\n她是住在格林街的那个女孩吗？\n\n是的。她也是和我一起上课的人。\n\n她好像认识这所学校所有的人。\n\n她是那种谁都愿意帮的人。\n\n那我一定得见见她。",vocab:[{"w": "remember", "ph": "/rɪˈmembə(r)/", "en": "to keep something in your mind", "zh": "v. 记得；想起", "eg": "Do you remember the girl who sat here?"}, {"w": "praise", "ph": "/preɪz/", "en": "to say someone did something well", "zh": "v. 表扬；称赞", "eg": "She's the student whom the teacher praised."}, {"w": "dictionary", "ph": "/ˈdɪkʃənri/", "en": "a book that gives the meaning of words", "zh": "n. 词典", "eg": "I borrowed this dictionary from her."}, {"w": "seem", "ph": "/siːm/", "en": "to give the feeling of being something", "zh": "v. 似乎；好像", "eg": "She seems to know everyone here."}],exprs:[{"en": "whom（作宾语，正式）", "zh": "……的那个人（宾格）", "scene": "whom 是 who 的宾格，正式文体里作宾语用它；口语常用 who 或干脆省掉。", "struct": "the + 人 + whom + 主语 + 谓语", "cat": "work", "ex": ["the girl whom you spoke to", "the student whom the teacher praised"]}, {"en": "speak to sb for + 一段时间", "zh": "和某人谈了……（多久）", "scene": "谈了多长时间用 for 引出一段时长。", "struct": "speak/talk to + 人 + for + 一段时间", "cat": "dailychat", "ex": ["the girl whom you spoke to for an hour", "I spoke to her for a few minutes."]}, {"en": "from whom / with whom", "zh": "正式说法里的介词 + whom", "scene": "介词提到前面时只能用 whom，不能省，也不能换成 who。", "struct": "介词 + whom + 从句", "cat": "work", "ex": ["the person from whom I borrowed it", "the one with whom I go to class"]}],pats:[{"en": "Do you remember the + 名词 + who + 从句?", "zh": "你记得……的那个人吗？", "scene": "提起一个共同认识的人，用 who 从句帮对方回忆。", "struct": "Do you remember the + 名词 + who + 从句?", "cat": "dailychat", "ex": ["Do you remember the boy who broke the window?", "Do you remember the man who sold us the car?"]}, {"en": "the + 人 + whom + 从句 / 介词 + whom + 从句", "zh": "（某人）……过的那个人（正式）", "scene": "whom 作宾语，或把介词提到 whom 前面，都属正式写法。", "struct": "the + 名词 + (介词 +) whom + 从句", "cat": "work", "ex": ["the student whom the teacher praised", "the person from whom I borrowed it"]}],quiz:{"v": {"q": "praise 的意思是：", "opts": ["批评", "表扬", "提问"], "a": 1}, "e": {"q": "正式说法「我向她借这本词典的那个人」是：", "opts": ["the person from who I borrowed it", "the person who I borrowed it from her", "the person from whom I borrowed it"], "a": 2}, "p": {"q": "She's the student ______ the teacher praised.", "opts": ["which", "whose", "whom"], "a": 2}},speak:"说 4 句话：回忆一个昨天见过的人，用 Do you remember the girl who…?、the person (whom) I spoke to、以及一次正式的 介词 + whom。"},
{n:129,title:"Seventy Miles an Hour",topic:"过去进行时 was/were doing · when 引导的时间状语",reading:"I saw you in town yesterday. You were driving very fast.\n\nWas I? I was doing seventy miles an hour on the motorway.\n\nWhen I saw you, you were talking on your phone.\n\nNo, I wasn't. I was listening to the radio.\n\nWhat were you doing at three o'clock?\n\nI was having a meeting with my boss.\n\nAnd in the evening?\n\nI was cooking dinner when the phone rang.\n\nYou shouldn't talk on the phone while you are driving.\n\nI know. I won't do it again.",zh:"（原创改写）我昨天在城里看见你了。你开得很快。\n\n是吗？我在高速上开到每小时七十英里。\n\n我看见你的时候，你正在打电话。\n\n不，我没有。我在听收音机。\n\n三点钟的时候你在做什么？\n\n我在和老板开会。\n\n那晚上呢？\n\n我正在做晚饭，电话响了。\n\n你开车的时候不该打电话。\n\n我知道。我不会再这样了。",vocab:[{"w": "motorway", "ph": "/ˈməʊtəweɪ/", "en": "a wide road where cars travel fast", "zh": "n. 高速公路", "eg": "I was doing seventy miles an hour on the motorway."}, {"w": "mile", "ph": "/maɪl/", "en": "a unit of distance, about 1.6 kilometres", "zh": "n. 英里", "eg": "We drove fifty miles this morning."}, {"w": "boss", "ph": "/bɒs/", "en": "the person you work for", "zh": "n. 老板；上司", "eg": "I was having a meeting with my boss."}, {"w": "ring", "ph": "/rɪŋ/", "en": "to make a sound, like a phone or bell", "zh": "v. （铃、电话）响", "eg": "The phone rang while I was cooking."}],exprs:[{"en": "was/were + doing", "zh": "（过去某个时刻）正在做……", "scene": "过去进行时，常配一个具体时间点，说明当时动作正在进行。", "struct": "主语 + was/were + 动词-ing", "cat": "experience", "ex": ["I was doing seventy miles an hour.", "What were you doing at three o'clock?"]}, {"en": "When + 过去式, 主语 + was/were + doing", "zh": "当……的时候，（某人）正在……", "scene": "when 引出一个短动作，长动作用进行时当背景。", "struct": "When + 主语 + 过去式, 主语 + was/were + doing", "cat": "experience", "ex": ["When I saw you, you were talking on your phone.", "I was cooking dinner when the phone rang."]}, {"en": "数字 + miles an hour", "zh": "每小时……英里", "scene": "速度的口语说法，等于 miles per hour。", "struct": "数字 + miles an hour", "cat": "dailychat", "ex": ["I was doing seventy miles an hour.", "The car was going thirty miles an hour."]}],pats:[{"en": "What were you doing at + 时间? — I was + doing.", "zh": "你在……（时刻）正在做什么？——我在……", "scene": "过去进行时的标准问答，时间点用 at 引出。", "struct": "What + was/were + 主语 + doing + at + 时间?", "cat": "experience", "ex": ["What were you doing at three o'clock?", "What was he doing at midnight?"]}, {"en": "主语 + was/were + doing when + 主语 + 过去式", "zh": "正在……，这时……", "scene": "一个动作被另一个短动作打断，被断的用进行时。", "struct": "主语 + was/were + doing + when + 主语 + 过去式", "cat": "experience", "ex": ["I was cooking when the phone rang.", "We were sleeping when it started to rain."]}],quiz:{"v": {"q": "motorway 的意思是：", "opts": ["高速公路", "加油站", "停车场"], "a": 0}, "e": {"q": "「昨天三点我正在开会」应该说：", "opts": ["I had a meeting at three yesterday.", "I was having a meeting at three yesterday.", "I have a meeting at three yesterday."], "a": 1}, "p": {"q": "I ______ dinner when the phone rang.", "opts": ["cooked", "was cooking", "am cooking"], "a": 1}},speak:"说 5 句话：用 What were you doing at …? 问对方昨天某个时刻在做什么，用 I was … 回答两次，再用 when 引出一个打断它的动作。"},
{n:130,title:"What Was She Doing?",topic:"过去进行时复习 · 过去进行时与一般过去时的对比",reading:"What was Anna doing when you arrived?\n\nShe was reading a book. She didn't hear me come in.\n\nWas Tom working?\n\nNo, he wasn't. He was sleeping on the sofa.\n\nWhat did he do when he saw you?\n\nHe stood up and made some tea.\n\nWere the children playing outside?\n\nYes, they were. They were running in the rain, and they all caught colds.\n\nDid Tom finish his work?\n\nNo, he didn't. He was too tired after the meeting.\n\nHe went home at about six o'clock.",zh:"（原创改写）你到的时候安娜在做什么？\n\n她在看书。她没听见我进来。\n\n汤姆在工作吗？\n\n没有，他在沙发上睡觉。\n\n他看见你时做了什么？\n\n他站起来，泡了点茶。\n\n孩子们在外面玩吗？\n\n是的。他们在雨里跑，结果全都感冒了。\n\n汤姆把活干完了吗？\n\n没有。开完会他太累了。\n\n他大约六点钟回家了。",vocab:[{"w": "sofa", "ph": "/ˈsəʊfə/", "en": "a long soft seat for two or more people", "zh": "n. 沙发", "eg": "He was sleeping on the sofa."}, {"w": "rain", "ph": "/reɪn/", "en": "water that falls from the clouds", "zh": "n. 雨；v. 下雨", "eg": "They were running in the rain."}, {"w": "hear", "ph": "/hɪə(r)/", "en": "to notice sound with your ears", "zh": "v. 听见", "eg": "She didn't hear me come in."}, {"w": "outside", "ph": "/ˌaʊtˈsaɪd/", "en": "not inside a building", "zh": "adv. 在外面", "eg": "The children were playing outside."}],exprs:[{"en": "Was/Were + 主语 + doing? — Yes, … was/were. / No, … wasn't/weren't.", "zh": "（当时）在做……吗？", "scene": "过去进行时的一般疑问句，把 was/were 提到句首。", "struct": "Was/Were + 主语 + doing?", "cat": "experience", "ex": ["Was Tom working? — No, he wasn't.", "Were the children playing outside? — Yes, they were."]}, {"en": "过去进行时 vs 一般过去时", "zh": "正在做 vs 做了", "scene": "进行时铺背景，一般过去时报动作本身，两者常成对出现。", "struct": "was/were doing（背景）+ 过去式（动作）", "cat": "experience", "ex": ["She was reading when I came in.", "He stood up and made some tea."]}, {"en": "hear sb do / doing sth", "zh": "听见某人（正在）做某事", "scene": "hear 后面接动词原形强调全过程，接 -ing 强调片段。", "struct": "hear + 人 + 动词原形/doing", "cat": "experience", "ex": ["She didn't hear me come in.", "I heard him open the door."]}],pats:[{"en": "What was + 主语 + doing when + 主语 + 过去式?", "zh": "当……的时候，（某人）正在做什么？", "scene": "问过去某个瞬间正在进行的动作。", "struct": "What + was/were + 主语 + doing + when + 主语 + 过去式?", "cat": "experience", "ex": ["What was she doing when you arrived?", "What were you doing when it happened?"]}, {"en": "主语 + was/were + doing, and + 主语 + 过去式", "zh": "（某人）正在……，结果……", "scene": "进行时报背景，and 后面接一个突然发生的结果。", "struct": "主语 + was/were + doing, and + 主语 + 过去式", "cat": "experience", "ex": ["They were running in the rain, and they caught colds.", "I was reading, and the light went out."]}],quiz:{"v": {"q": "sofa 的意思是：", "opts": ["地毯", "沙发", "窗帘"], "a": 1}, "e": {"q": "「她进来时我正在看书」应该说：", "opts": ["I read a book when she came in.", "I was reading a book when she came in.", "I am reading a book when she came in."], "a": 1}, "p": {"q": "______ Tom working when you arrived?", "opts": ["Was", "Were", "Did"], "a": 0}},speak:"说 5 句话：用 What was … doing when …? 和 Was/Were …? 询问昨天办公室或家里的情景，用过去进行时铺背景，用一般过去时说中间发生了什么。"},
{n:131,title:"Don't Be So Sure!",topic:"must be / can't be 表推测 · 对眼下情况的判断",reading:"That man over there must be the new manager.\n\nHe can't be the manager. He's far too young.\n\nHe may be the manager's son, then.\n\nLook at the car he is driving. It can't be his.\n\nIt must be his father's. The number is the same.\n\nWhere is the real manager?\n\nHe may be in a meeting. He can't be at home today.\n\nDon't be so sure! Let's go and ask him.\n\nWait. He is coming this way.\n\nThen we'll know the truth in a minute.",zh:"（原创改写）那边那个人一定是新来的经理。\n\n他不可能是经理。他太年轻了。\n\n那他也许是经理的儿子。\n\n看看他开的那辆车。不可能是他自己的。\n\n一定是他父亲的。车牌号是一样的。\n\n真正的经理在哪儿？\n\n他也许在开会。今天他不可能在家。\n\n别那么肯定！我们去问问他吧。\n\n等等。他朝这边走过来了。\n\n那我们马上就知道真相了。",vocab:[{"w": "manager", "ph": "/ˈmænɪdʒə(r)/", "en": "the person who runs a shop or office", "zh": "n. 经理；管理者", "eg": "That man must be the new manager."}, {"w": "may", "ph": "/meɪ/", "en": "used to say something is possible", "zh": "modal v. 可能；也许", "eg": "He may be in a meeting."}, {"w": "sure", "ph": "/ʃʊə(r)/", "en": "certain about something", "zh": "adj. 确定的；肯定的", "eg": "Don't be so sure!"}, {"w": "number", "ph": "/ˈnʌmbə(r)/", "en": "the sign or set of signs for a thing in a list", "zh": "n. 号码；数字", "eg": "The number is the same."}],exprs:[{"en": "主语 + must be …", "zh": "一定是……", "scene": "很有把握的肯定推测，把握度大约九成。", "struct": "主语 + must be + 表语/doing", "cat": "opinion", "ex": ["He must be the new manager.", "It must be his father's car."]}, {"en": "主语 + can't be …", "zh": "不可能是……", "scene": "很有把握的否定推测；注意否定推测用 can't，绝不用 mustn't。", "struct": "主语 + can't be + 表语/doing", "cat": "opinion", "ex": ["He can't be the manager.", "She can't be at home now."]}, {"en": "Don't be so sure!", "zh": "别那么肯定！", "scene": "提醒对方别把推测当事实，语气带点打趣。", "struct": "Don't be so sure!", "cat": "humor", "ex": ["Don't be so sure! Let's go and ask him.", "You think he'll come? Don't be so sure."]}],pats:[{"en": "主语 + must be + 表语", "zh": "……肯定是……", "scene": "must 后面永远接动词原形，推测现在用 be，推测正在做用 be doing。", "struct": "主语 + must be + 名词/形容词/doing", "cat": "opinion", "ex": ["It must be his father's.", "He must be working late."]}, {"en": "主语 + can't be + 表语", "zh": "……不可能是……", "scene": "和 must be 是一对，一个往肯定推，一个往否定推。", "struct": "主语 + can't be + 名词/形容词/doing", "cat": "opinion", "ex": ["He can't be at home today.", "It can't be true."]}],quiz:{"v": {"q": "manager 的意思是：", "opts": ["经理", "工人", "顾客"], "a": 0}, "e": {"q": "「他不可能是经理」应该说：", "opts": ["He mustn't be the manager.", "He can't be the manager.", "He doesn't be the manager."], "a": 1}, "p": {"q": "It ______ be his father's car. The number is the same.", "opts": ["can't", "must", "mustn't"], "a": 1}},speak:"说 5 句话：看见一个陌生人，用 must be、can't be、may be 各猜一次他的身份、那辆车或他的来意，最后用 Don't be so sure! 收尾。"},
{n:132,title:"He May Be Right",topic:"may / might 表可能 · 推测程度的区别与过去进行时复习",reading:"Where's Peter? He wasn't at his desk this morning.\n\nHe may be ill. He looked tired yesterday.\n\nHe can't be ill. I saw him at the bus stop.\n\nThen he may be working at home.\n\nHe might be. He was carrying a big bag.\n\nWhat was he doing at the bus stop?\n\nHe was waiting for the nine o'clock bus, I think.\n\nThen he may be in Brighton now.\n\nOr he may be visiting his mother.\n\nShe lives in Brighton, doesn't she?",zh:"（原创改写）彼得在哪儿？今天上午他不在座位上。\n\n他也许病了。昨天他看起来很累。\n\n他不可能生病。我在公交车站看见他了。\n\n那他也许在家工作。\n\n有可能。他当时提着一个大包。\n\n他在公交车站干什么？\n\n我想他在等九点的那班车。\n\n那他现在也许在布莱顿了。\n\n或者他也许去看他母亲了。\n\n她住在布莱顿，是吧？",vocab:[{"w": "ill", "ph": "/ɪl/", "en": "not well; sick", "zh": "adj. 生病的", "eg": "He may be ill today."}, {"w": "carry", "ph": "/ˈkæri/", "en": "to hold something and take it somewhere", "zh": "v. 提；搬运", "eg": "He was carrying a big bag."}, {"w": "desk", "ph": "/desk/", "en": "a table you sit at to work or study", "zh": "n. 书桌；办公桌", "eg": "He wasn't at his desk this morning."}, {"w": "might", "ph": "/maɪt/", "en": "used to say something is possible, less sure than may", "zh": "modal v. 可能（把握更低）", "eg": "He might be at home."}],exprs:[{"en": "may + 动词原形", "zh": "也许／可能……", "scene": "把握度大约五成：比 must 弱，比 can't 强。", "struct": "主语 + may + 动词原形", "cat": "opinion", "ex": ["He may be ill.", "He may be working at home."]}, {"en": "might + 动词原形", "zh": "也许……（把握更低）", "scene": "might 比 may 更没把握；口语里也常单独用来附和。", "struct": "主语 + might + 动词原形 / He might be.", "cat": "opinion", "ex": ["He might be. He was carrying a big bag.", "It might rain tonight."]}, {"en": "may/might be doing", "zh": "也许正在……", "scene": "情态动词也能接进行时，推测眼前正在发生的事。", "struct": "主语 + may/might be + doing", "cat": "opinion", "ex": ["He may be working at home.", "She might be sleeping now."]}],pats:[{"en": "主语 + may/might + be + 表语", "zh": "……也许是……", "scene": "对现状的弱推测，后面可以再补一句理由。", "struct": "主语 + may/might be + 名词/形容词", "cat": "opinion", "ex": ["He may be ill.", "She might be right."]}, {"en": "主语 + may/might be + doing", "zh": "……也许正在……", "scene": "推测正在进行的动作，把 be + doing 整个跟在情态动词后面。", "struct": "主语 + may/might be + 动词-ing", "cat": "opinion", "ex": ["He may be waiting for the bus.", "They might be having lunch."]}],quiz:{"v": {"q": "ill 的意思是：", "opts": ["生病的", "忙碌的", "疲倦的"], "a": 0}, "e": {"q": "「他也许在家工作」应该说：", "opts": ["He may working at home.", "He may be working at home.", "He maybe work at home."], "a": 1}, "p": {"q": "He ______ be ill. I saw him at the bus stop.", "opts": ["must", "may", "can't"], "a": 2}},speak:"说 5 句话：找一位不在座位上的同事，用 may be、might be、can't be 各猜一次他在哪里、在干什么，最后用过去进行时说他昨天在做什么。"},
{n:133,title:"Sensational News!",topic:"对正在发生之事的推断 · must be doing / may be doing",reading:"Have you heard the news? It's absolutely sensational!\n\nWhat's happened?\n\nA famous writer is coming to our town this afternoon.\n\nHe can't be serious. Writers never come here.\n\nLook at the crowd outside the hotel. They must be waiting for him.\n\nWho is that woman who is standing there?\n\nShe may be his wife. She was talking to the police a minute ago.\n\nLet's wait and see. Everyone is very excited.\n\nHere comes a black car.\n\nEveryone is shouting. He must be inside it.",zh:"（原创改写）你听说那个消息了吗？简直太轰动了！\n\n出什么事了？\n\n一位著名作家今天下午要来我们镇上。\n\n他不会是认真的吧。作家从来不来这儿。\n\n看看旅馆外面那群人。他们一定是在等他。\n\n站在那边的那个女人是谁？\n\n她也许是他的妻子。一分钟前她还在跟警察说话。\n\n我们等着瞧吧。大家都特别兴奋。\n\n来了一辆黑色的车。\n\n大家都在喊。他一定在车里。",vocab:[{"w": "sensational", "ph": "/senˈseɪʃənl/", "en": "very exciting and surprising", "zh": "adj. 轰动的；极好的", "eg": "The news was absolutely sensational."}, {"w": "crowd", "ph": "/kraʊd/", "en": "a large group of people in one place", "zh": "n. 人群", "eg": "There was a big crowd outside the hotel."}, {"w": "excited", "ph": "/ɪkˈsaɪtɪd/", "en": "very happy and interested about something", "zh": "adj. 兴奋的；激动的", "eg": "Everyone is excited about the visit."}, {"w": "writer", "ph": "/ˈraɪtə(r)/", "en": "a person who writes books or articles", "zh": "n. 作家；作者", "eg": "A famous writer is coming this afternoon."}],exprs:[{"en": "must be doing", "zh": "一定正在……", "scene": "推测此时此刻正在发生的事，比 must be 多一层「正在进行」。", "struct": "主语 + must be + 动词-ing", "cat": "opinion", "ex": ["They must be waiting for him.", "He must be working late tonight."]}, {"en": "Have you heard the news?", "zh": "你听说那个消息了吗？", "scene": "分享八卦或大事的开场白，后面常接 about。", "struct": "Have you heard + the news / about + 名词?", "cat": "dailychat", "ex": ["Have you heard the news?", "Have you heard about the new manager?"]}, {"en": "Let's wait and see.", "zh": "我们等着瞧吧。", "scene": "不急着下结论，语气里带一点保留。", "struct": "Let's wait and see.", "cat": "humor", "ex": ["Let's wait and see what happens.", "It may be true. Let's wait and see."]}],pats:[{"en": "主语 + must be + doing", "zh": "……一定正在……", "scene": "情态动词后面接 be + 动词-ing，用来推测正发生的动作。", "struct": "主语 + must be + 动词-ing", "cat": "opinion", "ex": ["They must be waiting for the writer.", "She must be cooking dinner now."]}, {"en": "主语 + may/might be + doing", "zh": "……也许正在……", "scene": "把握度低一档，用来推测眼前但不确定的动作。", "struct": "主语 + may/might be + 动词-ing", "cat": "opinion", "ex": ["She may be talking to the police.", "He might be sleeping at this hour."]}],quiz:{"v": {"q": "crowd 的意思是：", "opts": ["人群", "队伍", "看台"], "a": 0}, "e": {"q": "「他们一定在等他」应该说：", "opts": ["They must wait for him.", "They must waiting for him.", "They must be waiting for him."], "a": 2}, "p": {"q": "She ______ be his wife. She's standing next to him.", "opts": ["can't", "may", "mustn't"], "a": 1}},speak:"说 5 句话：用 Have you heard the news? 分享一条消息，用 must be doing、may be doing 推断现场的人在干什么，用 can't be 排除一个可能，最后用 Let's wait and see. 收尾。"},
{n:134,title:"What Were They Doing?",topic:"when 与 while 引导的时间状语 · 过去进行时复习",reading:"Where were you yesterday when the power went out?\n\nI was having dinner with my family.\n\nWhat was your brother doing while you were eating?\n\nHe was playing computer games.\n\nAnd your sister?\n\nShe was doing her homework, so she lit a candle.\n\nWhat did you do then?\n\nWe sat in the dark and told stories until the lights came back.\n\nThat sounds fun.\n\nIt was. The power came back at about ten o'clock.\n\nDid the children enjoy it?\n\nYes. They want the lights to go out again.",zh:"（原创改写）昨天停电的时候你在哪儿？\n\n我正和家人吃晚饭。\n\n你吃饭的时候你弟弟在做什么？\n\n他在玩电脑游戏。\n\n你妹妹呢？\n\n她在写作业，所以点了根蜡烛。\n\n那你们后来干什么了？\n\n我们坐在黑暗里讲故事，一直讲到来电为止。\n\n听起来挺有意思。\n\n是挺有意思。大约十点来电的。\n\n孩子们喜欢吗？\n\n喜欢。他们还想再停一次电。",vocab:[{"w": "candle", "ph": "/ˈkændl/", "en": "a stick of wax you burn for light", "zh": "n. 蜡烛", "eg": "She lit a candle and went on reading."}, {"w": "dark", "ph": "/dɑːk/", "en": "with no light", "zh": "n./adj. 黑暗（的）", "eg": "We sat in the dark and talked."}, {"w": "until", "ph": "/ənˈtɪl/", "en": "up to the time when something happens", "zh": "conj./prep. 直到……为止", "eg": "We waited until the lights came back."}, {"w": "power", "ph": "/ˈpaʊə(r)/", "en": "the electricity that makes things work", "zh": "n. 电力；力量", "eg": "The power went out at eight."}],exprs:[{"en": "while + 过去进行时", "zh": "在……期间", "scene": "while 后面跟可持续的动作，两个动作同时进行。", "struct": "While + 主语 + was/were + doing, 主语 + was/were + doing", "cat": "experience", "ex": ["While I was eating, he was playing games.", "While she was working, I was cooking."]}, {"en": "主语 + was/were + doing + when + 过去式", "zh": "正在……，这时……", "scene": "when 引出一个短动作，把进行时的动作打断。", "struct": "主语 + was/were + doing + when + 主语 + 过去式", "cat": "experience", "ex": ["I was having dinner when the power went out.", "We were sleeping when the phone rang."]}, {"en": "until + 从句", "zh": "一直……直到……", "scene": "说明动作持续到某个时间点为止。", "struct": "主语 + 动词 + until + 从句", "cat": "dailychat", "ex": ["We talked until the lights came back.", "Wait here until I call you."]}],pats:[{"en": "What was + 主语 + doing while + 主语 + was/were + doing?", "zh": "（某人）做……的时候，另一个人在做什么？", "scene": "两个过去动作并行，都用进行时。", "struct": "What + was/were + 主语 + doing + while + 主语 + was/were + doing?", "cat": "experience", "ex": ["What was he doing while you were eating?", "What were they doing while I was out?"]}, {"en": "Where were you when + 过去式?", "zh": "……发生的时候你在哪儿？", "scene": "问对方在某一事件发生时的位置和状态。", "struct": "Where + was/were + 主语 + when + 主语 + 过去式?", "cat": "experience", "ex": ["Where were you when the power went out?", "Where was she when it started to rain?"]}],quiz:{"v": {"q": "candle 的意思是：", "opts": ["手电", "蜡烛", "火柴"], "a": 1}, "e": {"q": "「我吃饭的时候他在打游戏」应该说：", "opts": ["While I ate, he played games.", "While I was eating, he was playing games.", "While I was eating, he was play games."], "a": 1}, "p": {"q": "What was she doing ______ you were eating?", "opts": ["when", "while", "until"], "a": 1}},speak:"说 5 句话：用 Where were you when …? 问对方，用 I was … 回答，用 What was … doing while …? 问另一个人，最后用 until 说明动作持续到什么时候。"},
{n:135,title:"The Latest Report",topic:"must be / can't be 推测综合 · 转述报道与他人的话",reading:"Have you read the latest report about the factory?\n\nYes. It says that the factory will close next month.\n\nIt can't be true. My brother works there.\n\nHe must be very worried. Has he told you anything?\n\nHe says that the boss is looking for new buyers.\n\nHe can't be serious. Nobody wants a factory like that.\n\nHe may be right, though. Let's wait for the next report.\n\nI hope that he finds a new job soon.\n\nSo do I. He works very hard.",zh:"（原创改写）你看了那份关于工厂的最新报告吗？\n\n看了。报告说工厂下个月就要关闭。\n\n这不可能。我哥哥在那儿上班。\n\n他一定非常担心。他跟你说过什么吗？\n\n他说老板正在找新的买主。\n\n他不可能是认真的。没人想要那样的工厂。\n\n不过他也许是对的。我们等下一份报告吧。\n\n我希望他能快点找到新工作。\n\n我也是。他工作很努力。",vocab:[{"w": "factory", "ph": "/ˈfæktri/", "en": "a place where things are made by machines", "zh": "n. 工厂", "eg": "The factory will close next month."}, {"w": "close", "ph": "/kləʊz/", "en": "to stop being open or working", "zh": "v. 关闭；关上", "eg": "They will close the old office."}, {"w": "worried", "ph": "/ˈwʌrid/", "en": "unhappy because something bad may happen", "zh": "adj. 担心的", "eg": "He must be very worried."}, {"w": "buyer", "ph": "/ˈbaɪə(r)/", "en": "a person who buys something", "zh": "n. 买主；买家", "eg": "The boss is looking for new buyers."}],exprs:[{"en": "the latest report / news", "zh": "最新的报告／消息", "scene": "latest 表示「最新的」，前面加 the，没有比较的意思。", "struct": "the latest + 名词", "cat": "work", "ex": ["Have you read the latest report?", "Do you know the latest news?"]}, {"en": "It says that …", "zh": "（报道／上面）说……", "scene": "转述书面内容，主语可以是 it、the report、the letter。", "struct": "It/名词 + says (that) + 从句", "cat": "work", "ex": ["It says that the factory will close.", "The letter says that he is coming."]}, {"en": "look for …", "zh": "寻找……", "scene": "强调寻找的过程；find 是找到的结果，别混用。", "struct": "look for + 名词", "cat": "work", "ex": ["The boss is looking for new buyers.", "I'm looking for a bigger office."]}],pats:[{"en": "He says that + 从句", "zh": "他说……", "scene": "转述别人的话，主句现在时，从句时态按实情走。", "struct": "主语 + says (that) + 从句", "cat": "work", "ex": ["He says that the boss is looking for buyers.", "She says that the report is wrong."]}, {"en": "主语 + must/can't be + 形容词/名词", "zh": "……一定／不可能是……", "scene": "对人或事做出判断，后面接形容词或名词。", "struct": "主语 + must/can't be + 形容词/名词", "cat": "opinion", "ex": ["He must be very worried.", "It can't be true."]}],quiz:{"v": {"q": "factory 的意思是：", "opts": ["公司", "工厂", "商店"], "a": 1}, "e": {"q": "「报告说工厂下个月会关闭」应该说：", "opts": ["It says what the factory will close.", "It says the factory closes next month it.", "It says that the factory will close next month."], "a": 2}, "p": {"q": "He ______ be very worried. His job is at risk.", "opts": ["can't", "must", "mustn't"], "a": 1}},speak:"说 5 句话：转述一条新闻或报告（It says that…），用 can't be、must be、may be 表明你的判断，最后用 I hope that… 收尾。"},
{n:136,title:"She Can't Be Serious",topic:"推测与转述综合 · 对他人的想法与计划做判断",reading:"Anna says that she wants to sell her house.\n\nShe can't be serious. She has lived there for years.\n\nShe says that she is moving to Canada.\n\nShe must be joking. Her whole family is here.\n\nShe says that she has already bought the ticket.\n\nThen she may be telling the truth.\n\nShe was packing boxes when I called her.\n\nWell, I hope that she knows what she is doing.\n\nShe has always done what she wants.\n\nThat's true. I just hope that she is happy there.",zh:"（原创改写）安娜说她想把房子卖了。\n\n她不可能是认真的。她在那儿住了好多年了。\n\n她说她要搬到加拿大去。\n\n她一定是在开玩笑。她全家人都在这儿。\n\n她说她已经把票买好了。\n\n那她也许说的是实话。\n\n我打电话给她的时候，她正在装箱子。\n\n好吧，希望她知道自己在做什么。\n\n她向来是想做什么就做什么。\n\n没错。我只希望她在那儿过得开心。",vocab:[{"w": "joke", "ph": "/dʒəʊk/", "en": "to say something funny, not serious", "zh": "v. 开玩笑；n. 笑话", "eg": "She must be joking."}, {"w": "pack", "ph": "/pæk/", "en": "to put things into a bag or box", "zh": "v. 打包；装箱", "eg": "She was packing boxes all morning."}, {"w": "ticket", "ph": "/ˈtɪkɪt/", "en": "a piece of paper that lets you travel or enter", "zh": "n. 票", "eg": "She has already bought the ticket."}, {"w": "truth", "ph": "/truːθ/", "en": "what really happened", "zh": "n. 真相；实话", "eg": "She may be telling the truth."}],exprs:[{"en": "主语 + must be joking", "zh": "一定是在开玩笑", "scene": "听到离谱的消息时的固定反应，语气比 You're joking 更强烈。", "struct": "主语 + must be joking", "cat": "humor", "ex": ["She must be joking.", "You must be joking! That's impossible."]}, {"en": "tell the truth", "zh": "说实话", "scene": "truth 前面要加 the；反义说法是 tell a lie。", "struct": "tell the truth", "cat": "relationship", "ex": ["She may be telling the truth.", "Please tell me the truth."]}, {"en": "move to + 地点", "zh": "搬到……去", "scene": "搬家、工作调动都能用，后面直接跟目的地。", "struct": "move to + 地点", "cat": "dailychat", "ex": ["She is moving to Canada.", "We moved to this town in 2019."]}],pats:[{"en": "She says that + 从句", "zh": "她说……", "scene": "转述别人的打算或说法，从句时态跟着内容走。", "struct": "主语 + say(s) (that) + 从句", "cat": "dailychat", "ex": ["She says that she is moving to Canada.", "He says that he has bought the ticket."]}, {"en": "主语 + must/may be + doing", "zh": "……一定／也许在做……", "scene": "推测某人此刻的行为或心思，比 must be 更动态。", "struct": "主语 + must/may be + 动词-ing", "cat": "opinion", "ex": ["She may be telling the truth.", "He must be joking again."]}],quiz:{"v": {"q": "truth 的意思是：", "opts": ["故事", "借口", "真相；实话"], "a": 2}, "e": {"q": "「她一定是在开玩笑」应该说：", "opts": ["She must joke.", "She must to be joking.", "She must be joking."], "a": 2}, "p": {"q": "She was packing boxes ______ I called her.", "opts": ["while", "until", "when"], "a": 2}},speak:"说 5 句话：转述一个让你惊讶的决定（He/She says that…），用 can't be serious、must be joking 表达不相信，用 may be telling the truth 让步，最后用 I hope that… 收尾。"},
{n:137,title:"A Pleasant Dream",topic:"if 引导的真实条件句 · 主将从现",reading:"What will you do if you win the competition?\n\nIf I win, I'll take my family to the seaside.\n\nWhat will you do if it rains?\n\nIf it rains, we'll stay in a hotel and play games.\n\nWill you buy a new car?\n\nIf I have enough money, I'll buy a small blue one.\n\nAnd if you don't win?\n\nIf I don't win, I'll try again next year. Dreams are free.\n\nThen you must enter the competition.\n\nI will. Somebody has to win it.",zh:"（原创改写）如果你赢了比赛，你会做什么？\n\n如果我赢了，我就带家人去海边。\n\n如果下雨你们怎么办？\n\n如果下雨，我们就待在旅馆里打游戏。\n\n你会买新车吗？\n\n如果我钱够，我会买一辆蓝色的小车。\n\n要是没赢呢？\n\n如果没赢，我明年再试一次。梦想又不花钱。\n\n那你一定得报名参赛。\n\n我会的。总得有人赢吧。",vocab:[{"w": "win", "ph": "/wɪn/", "en": "to be the best in a game or competition", "zh": "v. 赢；获胜", "eg": "What will you do if you win?"}, {"w": "competition", "ph": "/ˌkɒmpəˈtɪʃn/", "en": "an event that people try to win", "zh": "n. 比赛；竞赛", "eg": "There is a writing competition this month."}, {"w": "seaside", "ph": "/ˈsiːsaɪd/", "en": "a place by the sea where people go on holiday", "zh": "n. 海边；海滨", "eg": "We'll go to the seaside in July."}, {"w": "dream", "ph": "/driːm/", "en": "something you hope for very much", "zh": "n. 梦；梦想", "eg": "It was a pleasant dream."}],exprs:[{"en": "If + 一般现在时, 主语 + will + 动词原形", "zh": "如果……，就会……", "scene": "真实条件句：if 从句用现在时，主句用将来时，这就是「主将从现」。", "struct": "If + 主语 + 动词现在式, 主语 + will + 动词原形", "cat": "dailychat", "ex": ["If I win, I'll take my family to the seaside.", "If it rains, we'll stay in a hotel."]}, {"en": "win + 比赛/奖品", "zh": "赢得……", "scene": "win 后面接比赛或奖品，不接人；赢了某人要说 beat。", "struct": "win + 名词", "cat": "hobby", "ex": ["I hope you win the competition.", "Who won the race?"]}, {"en": "take sb to + 地点", "zh": "带某人去……", "scene": "带人去某处的固定搭配，地点跟在 to 后面。", "struct": "take + 人 + to + 地点", "cat": "dailychat", "ex": ["I'll take my family to the seaside.", "He took us to the station."]}],pats:[{"en": "What will you do if + 一般现在时?", "zh": "如果……，你会做什么？", "scene": "问对方在某个条件下的打算，主句用将来时。", "struct": "What + will + 主语 + do + if + 主语 + 动词现在式?", "cat": "dailychat", "ex": ["What will you do if you win?", "What will she do if it rains?"]}, {"en": "If + 主语 + 现在式, 主语 + will (not) + 动词原形", "zh": "如果……，（某人）就（不）会……", "scene": "if 从句放在句首时，中间要加逗号。", "struct": "If + 从句, 主句", "cat": "dailychat", "ex": ["If I don't win, I'll try again.", "If you have time, we'll go together."]}],quiz:{"v": {"q": "competition 的意思是：", "opts": ["奖品", "比赛", "队员"], "a": 1}, "e": {"q": "「如果下雨，我们就待在家里」应该说：", "opts": ["If it will rain, we stay at home.", "If it rained, we will stay at home.", "If it rains, we'll stay at home."], "a": 2}, "p": {"q": "If I ______ enough money, I'll buy a car.", "opts": ["have", "will have", "had"], "a": 0}},speak:"说 5 句话：用 What will you do if …? 问对方，用 If …, I'll … 回答三个不同的假设（赢了／下雨了／钱不够），最后说如果没成功你会怎么办。"},
{n:138,title:"If I Have Time",topic:"if 条件句练习 · 主句在前时 if 从句的位置",reading:"Are you coming to the party on Saturday?\n\nIf I have time, I'll come. I have to finish my project first.\n\nWhat will you do if you finish it early?\n\nIf I finish early, I'll help you with the food.\n\nAnd if the weather is fine?\n\nWe'll have the party in the garden.\n\nIf it's cold, don't worry. I'll bring some warm coats.\n\nGood. Call me if you need anything.\n\nThanks. I'll call you on Friday.\n\nFine. If you can't come, I'll understand.",zh:"（原创改写）星期六的聚会你来吗？\n\n如果有时间我就来。我得先把项目做完。\n\n如果你提前做完了会做什么？\n\n如果做得早，我就来帮你弄吃的。\n\n要是天气好呢？\n\n我们就在花园里办聚会。\n\n如果冷也别担心，我会带几件厚外套来。\n\n好的。需要什么就给我打电话。\n\n谢啦。我星期五给你打电话。\n\n好的。如果你来不了，我也能理解。",vocab:[{"w": "project", "ph": "/ˈprɒdʒekt/", "en": "a piece of work that takes time to finish", "zh": "n. 项目；课题", "eg": "I have to finish my project first."}, {"w": "weather", "ph": "/ˈweðə(r)/", "en": "how hot, cold, wet or dry it is outside", "zh": "n. 天气", "eg": "If the weather is fine, we'll eat outside."}, {"w": "party", "ph": "/ˈpɑːti/", "en": "a time when people meet to enjoy themselves", "zh": "n. 聚会；派对", "eg": "Are you coming to the party?"}, {"w": "bring", "ph": "/brɪŋ/", "en": "to come to a place carrying something", "zh": "v. 带来", "eg": "I'll bring some warm coats."}],exprs:[{"en": "If + 现在时, 主语 + will …", "zh": "如果……，就……", "scene": "if 从句在前，主句在后，中间记得加逗号。", "struct": "If + 主语 + 现在式, 主语 + will + 动词原形", "cat": "dailychat", "ex": ["If I have time, I'll come.", "If it's cold, we'll stay inside."]}, {"en": "主句 + if + 从句", "zh": "……，如果……", "scene": "if 从句挪到后面时，中间不加逗号，意思不变。", "struct": "主语 + will + 动词原形 + if + 主语 + 现在式", "cat": "dailychat", "ex": ["Call me if you need anything.", "I'll come if I have time."]}, {"en": "have to + 动词原形", "zh": "不得不；必须", "scene": "客观上的必须，和主观的 must 略有区别。", "struct": "have to/has to + 动词原形", "cat": "work", "ex": ["I have to finish my project first.", "She has to work on Saturday."]}],pats:[{"en": "If + 主语 + 现在式, 主语 + will + 动词原形", "zh": "如果……，（某人）就会……", "scene": "「主将从现」的核心：条件用现在时，结果用将来时。", "struct": "If + 从句（现在时）, 主句（will + 原形）", "cat": "dailychat", "ex": ["If you finish early, I'll help you.", "If the weather is fine, we'll eat outside."]}, {"en": "祈使句 + if + 从句", "zh": "如果……，就……（命令或建议）", "scene": "主句换成祈使句，语气更直接。", "struct": "动词原形 (+ 宾语) + if + 从句", "cat": "dailychat", "ex": ["Call me if you need anything.", "Don't wait if you're in a hurry."]}],quiz:{"v": {"q": "project 的意思是：", "opts": ["假期", "项目；课题", "计划表"], "a": 1}, "e": {"q": "「如果你需要什么就给我打电话」应该说：", "opts": ["Call me if you will need anything.", " You call me if you needed anything.", "Call me if you need anything."], "a": 2}, "p": {"q": "If it ______ cold, we'll stay inside.", "opts": ["will be", "is", "was"], "a": 1}},speak:"说 5 句话：用 if 条件句安排一次周末聚会——你来不来、谁带吃的、天气好或不好怎么办，注意 if 从句在前要加逗号。"},
{n:139,title:"Is That You, John?",topic:"打电话用语 · 宾语从句综合",reading:"Hello. Is that you, John?\n\nYes, it's me. Who's speaking, please?\n\nIt's Mary. I'm afraid I can't hear you very well.\n\nI'm sorry. There's something wrong with my phone.\n\nI'll call you back in five minutes.\n\nAll right. Do you know when the meeting starts?\n\nIt starts at two. Tell Tom that I'll be a little late.\n\nOK. I'll give him the message. Goodbye for now.\n\nAnd tell Tom that the report is on my desk.\n\nAll right. I'll tell him as soon as he comes in.",zh:"（原创改写）喂，是你吗，约翰？\n\n是我。请问您是哪位？\n\n我是玛丽。恐怕我听不太清你说话。\n\n抱歉。我的电话有点问题。\n\n我五分钟后给你回过去。\n\n好的。你知道会议几点开始吗？\n\n两点开始。告诉汤姆我会晚到一会儿。\n\n好，我会把话带到。先再见。\n\n再告诉汤姆，报告在我桌上。\n\n好的。他一进来我就告诉他。",vocab:[{"w": "wrong", "ph": "/rɒŋ/", "en": "not correct, or not working properly", "zh": "adj. 有问题的；错误的", "eg": "There's something wrong with my phone."}, {"w": "meeting", "ph": "/ˈmiːtɪŋ/", "en": "a time when people come together to talk", "zh": "n. 会议", "eg": "The meeting starts at two."}, {"w": "phone", "ph": "/fəʊn/", "en": "a machine you use to call someone", "zh": "n. 电话；手机", "eg": "Something is wrong with my phone."}, {"w": "message", "ph": "/ˈmesɪdʒ/", "en": "information you send or give to someone", "zh": "n. 口信；留言", "eg": "I'll give him the message."}],exprs:[{"en": "Is that you, …?", "zh": "是你吗，……？", "scene": "打电话确认对方身份，不用 Are you …? 这是电话英语的习惯。", "struct": "Is that + 人 (speaking)?", "cat": "dailychat", "ex": ["Is that you, John?", "Is that Mr Smith speaking?"]}, {"en": "This is … speaking. / Who's speaking, please?", "zh": "我是……。／请问您是哪位？", "scene": "电话里报身份用 this，不说 I am 或 Who are you。", "struct": "This is + 人 + speaking.", "cat": "dailychat", "ex": ["This is Mary speaking.", "Who's speaking, please?"]}, {"en": "There's something wrong with …", "zh": "……出了毛病", "scene": "机器坏了、信号不好、身体不适，都能套这个句型。", "struct": "There's something wrong with + 名词", "cat": "dailychat", "ex": ["There's something wrong with my phone.", "There's something wrong with the printer."]}],pats:[{"en": "I'll call (you) back + 时间", "zh": "我过……给你回电话", "scene": "信号不好或正在忙时的标准回应，call back 是「回电」。", "struct": "主语 + will + call back + in + 一段时间", "cat": "work", "ex": ["I'll call you back in five minutes.", "He'll call me back this afternoon."]}, {"en": "Tell + 人 + that + 从句", "zh": "告诉某人……", "scene": "请对方带话，that 从句里放要转达的内容。", "struct": "Tell + 人 + (that) + 从句", "cat": "work", "ex": ["Tell Tom that I'll be a little late.", "Tell her that the meeting is at two."]}],quiz:{"v": {"q": "message 的意思是：", "opts": ["邮件", "口信；留言", "通知单"], "a": 1}, "e": {"q": "打电话时想说「我是玛丽」，应该说：", "opts": ["I am Mary.", "Here is Mary.", "This is Mary speaking."], "a": 2}, "p": {"q": "I'm afraid I ______ hear you very well.", "opts": ["can", "can't", "don't"], "a": 1}},speak:"说 5 句话：模拟一次打电话——确认对方是谁、说明自己是谁、说信号不好、约好回电话时间，最后请对方给某人带一句话（Tell … that …）。"},
{n:140,title:"What Did He Ask?",topic:"间接引语综合 · 转述问题与请求",reading:"What did the manager ask you?\n\nHe asked me where I was born.\n\nWhat else did he want to know?\n\nHe asked me if I could start work next Monday.\n\nWhat did you say?\n\nI told him that I could start at once.\n\nDid he ask about your last job?\n\nYes. He asked me why I left my last company, and I said I wanted a change.\n\nWhat did he say at the end?\n\nHe said that he would call me on Friday.\n\nI hope that you get the job.",zh:"（原创改写）经理问你什么了？\n\n他问我在哪里出生。\n\n他还想知道什么？\n\n他问我能不能下周一开工。\n\n你怎么说的？\n\n我告诉他我可以马上开始。\n\n他问你上一份工作了吗？\n\n问了。他问我为什么离开上一家公司，我说我想换个环境。\n\n最后他还说什么了？\n\n他说他星期五会给我打电话。\n\n希望你能得到这份工作。",vocab:[{"w": "born", "ph": "/bɔːn/", "en": "having come out of your mother's body", "zh": "adj. 出生的", "eg": "He asked me where I was born."}, {"w": "company", "ph": "/ˈkʌmpəni/", "en": "a business that sells or makes things", "zh": "n. 公司", "eg": "I left my last company in June."}, {"w": "change", "ph": "/tʃeɪndʒ/", "en": "something different from what it was before", "zh": "n./v. 改变；变化", "eg": "I said I wanted a change."}, {"w": "else", "ph": "/els/", "en": "other; more", "zh": "adv. 另外；其他", "eg": "What else did he want to know?"}],exprs:[{"en": "ask sb + 疑问词从句", "zh": "问某人……", "scene": "转述特殊疑问句时，从句要改回陈述句语序，末尾不再用问号语序。", "struct": "ask + 人 + 疑问词 + 主语 + 谓语", "cat": "work", "ex": ["He asked me where I was born.", "She asked him what he wanted."]}, {"en": "ask sb if / whether …", "zh": "问某人是否……", "scene": "转述一般疑问句，用 if 或 whether 打头，语序照旧是陈述句。", "struct": "ask + 人 + if/whether + 从句", "cat": "work", "ex": ["He asked me if I could start next Monday.", "She asked us whether we were ready."]}, {"en": "at once", "zh": "立刻；马上", "scene": "比 right now 更正式，常用于回复工作安排。", "struct": "at once", "cat": "work", "ex": ["I told him that I could start at once.", "Please send the file at once."]}],pats:[{"en": "He asked me + 疑问词 + 主语 + 谓语", "zh": "他问我……", "scene": "注意从句里主谓不再倒装，时态也往往跟着主句往过去挪。", "struct": "主语 + asked + 宾语 + 疑问词 + 从句", "cat": "work", "ex": ["He asked me why I left the company.", "She asked us when we could start."]}, {"en": "He asked me if + 从句", "zh": "他问我是否……", "scene": "间接一般疑问句，用 if 连接，句末用句号。", "struct": "主语 + asked + 宾语 + if + 从句", "cat": "work", "ex": ["He asked me if I could start next Monday.", "They asked us if we needed help."]}],quiz:{"v": {"q": "company 的意思是：", "opts": ["工厂", "公司", "团队"], "a": 1}, "e": {"q": "「他问我能不能下周一开工」应该说：", "opts": ["He asked me could I start next Monday.", "He asked me if I can start next Monday.", "He asked me if can I start next Monday."], "a": 1}, "p": {"q": "He asked me where I ______ born.", "opts": ["am", "was", "will be"], "a": 1}},speak:"说 5 句话：转述一次面试或问询——他问你哪里人、能否某时到岗、为什么离开上一家公司，你又是怎么回答的（I told him that…）。"},
{n:141,title:"Sally's First Train Ride",topic:"被动语态入门 · was/were + 过去分词",reading:"Sally was taken to London by train last week.\n\nWas she? She must have been very excited.\n\nShe was dressed in a blue coat and a red hat.\n\nWas the ticket bought by her mother?\n\nYes, and the seats were booked a week before.\n\nShe was given a window seat, so she saw everything.\n\nWas the luggage carried by her father?\n\nYes, and she was met at the station by her aunt.\n\nDid she enjoy the journey?\n\nYes. She was given a window seat and never stopped talking.",zh:"（原创改写）萨莉上周被带着坐火车去了伦敦。\n\n是吗？她一定特别兴奋。\n\n她穿着一件蓝色外套，戴着一顶红帽子。\n\n票是她妈妈买的吗？\n\n是的，座位也是一周前就订好的。\n\n她被安排了一个靠窗的座位，所以什么都看见了。\n\n行李是她爸爸提的吗？\n\n是的，而且她姑姑到车站接的她。\n\n她这趟旅途开心吗？\n\n开心。她被安排在靠窗的座位，一路上说个不停。",vocab:[{"w": "seat", "ph": "/siːt/", "en": "a place where you sit", "zh": "n. 座位", "eg": "She was given a window seat."}, {"w": "luggage", "ph": "/ˈlʌɡɪdʒ/", "en": "the bags you take on a journey", "zh": "n. 行李（不可数）", "eg": "The luggage was carried by her father."}, {"w": "aunt", "ph": "/ɑːnt/", "en": "your father's or mother's sister", "zh": "n. 姑姑；姨妈；阿姨", "eg": "She was met at the station by her aunt."}, {"w": "coat", "ph": "/kəʊt/", "en": "a piece of clothing you wear over others", "zh": "n. 外套；大衣", "eg": "She was dressed in a blue coat."}],exprs:[{"en": "be + 过去分词 (+ by + 人)", "zh": "被……（被动语态）", "scene": "强调动作的承受者，或者不知道谁做的时用被动。", "struct": "主语 + be + 过去分词 (+ by + 人)", "cat": "experience", "ex": ["Sally was taken to London by train.", "The ticket was bought by her mother."]}, {"en": "be dressed in …", "zh": "穿着……", "scene": "描述穿着状态，dressed 后面接 in + 衣服。", "struct": "be dressed in + 衣服", "cat": "dailychat", "ex": ["She was dressed in a blue coat.", "He was dressed in a dark suit."]}, {"en": "be met + 地点", "zh": "在某地被接", "scene": "接人用 meet，被动形式就是 be met，后面接地点。", "struct": "主语 + be met + at/in + 地点", "cat": "experience", "ex": ["She was met at the station by her aunt.", "We were met at the airport."]}],pats:[{"en": "主语 + was/were + 过去分词 (+ by + 人)", "zh": "……被……（过去时被动）", "scene": "过去时被动：was/were 加过去分词，动作执行者用 by 引出。", "struct": "主语 + was/were + 过去分词 + by + 人", "cat": "experience", "ex": ["The seats were booked a week before.", "The luggage was carried by her father."]}, {"en": "Was/Were + 主语 + 过去分词? — Yes, … was/were. / No, … wasn't/weren't.", "zh": "……被……了吗？", "scene": "被动语态的疑问句，把 was/were 提到句首。", "struct": "Was/Were + 主语 + 过去分词 (+ by + 人)?", "cat": "experience", "ex": ["Was the ticket bought by her mother?", "Were the seats booked in advance?"]}],quiz:{"v": {"q": "luggage 的意思是：", "opts": ["车票", "行李", "座位"], "a": 1}, "e": {"q": "「票是她妈妈买的」应该说：", "opts": ["The ticket bought by her mother.", "The ticket was buy by her mother.", "The ticket was bought by her mother."], "a": 2}, "p": {"q": "The seats ______ booked a week before.", "opts": ["was", "were", "is"], "a": 1}},speak:"说 5 句话：用被动语态讲一次旅行或活动的安排——谁被带去、票谁买的、行李谁拿的、在车站被谁接的。"},
{n:142,title:"It Was Made in China",topic:"被动语态 · 产地、材料与制作者的被动表达",reading:"Where was this bag made?\n\nIt was made in China.\n\nWas it designed in China, too?\n\nNo, it was designed in Italy by a young woman.\n\nWhere were the materials bought?\n\nThey were bought in Spain, I think.\n\nWas it sold in that small shop?\n\nNo. It was sent to a big store in London and sold there.\n\nIt's beautifully made.\n\nYes, and it was not very expensive.\n\nWhere did you buy it?\n\nIt was bought in a small shop near the station.",zh:"（原创改写）这个包是哪儿生产的？\n\n它是在中国制造的。\n\n它也是在中国设计的吗？\n\n不，它是一位年轻女性在意大利设计的。\n\n原材料是在哪儿买的？\n\n我想是在西班牙买的。\n\n它是在那家小店卖的吗？\n\n不是。它被送到伦敦的一家大商店，在那儿卖掉的。\n\n它做得真精致。\n\n是啊，而且不太贵。\n\n你在哪儿买的？\n\n是在车站附近的一家小店买的。",vocab:[{"w": "design", "ph": "/dɪˈzaɪn/", "en": "to plan how something will look or work", "zh": "v. 设计", "eg": "It was designed in Italy."}, {"w": "leather", "ph": "/ˈleðə(r)/", "en": "the skin of an animal used for bags and shoes", "zh": "n. 皮革", "eg": "The bag is made of leather."}, {"w": "store", "ph": "/stɔː(r)/", "en": "a big shop", "zh": "n. 商店；店铺", "eg": "It was sold in a big store in London."}, {"w": "material", "ph": "/məˈtɪəriəl/", "en": "what something is made from", "zh": "n. 材料；原料", "eg": "Where were the materials bought?"}],exprs:[{"en": "be made in + 地点", "zh": "产自……", "scene": "问产地用 in；说材料改用 be made of（看得出原料）或 from（看不出）。", "struct": "be made in + 地点 / be made of/from + 材料", "cat": "dailychat", "ex": ["It was made in China.", "The bag is made of leather."]}, {"en": "be + 过去分词 + by + 人", "zh": "由某人……（被动）", "scene": "被动语态里用 by 引出动作的执行者。", "struct": "be + 过去分词 + by + 人", "cat": "work", "ex": ["It was designed by a young woman.", "The song was written by my friend."]}, {"en": "be sent to + 地点", "zh": "被送到……", "scene": "send 是不规则动词：send—sent—sent，被动里要用 sent。", "struct": "be sent to + 地点", "cat": "work", "ex": ["It was sent to a store in London.", "The letter was sent to my old address."]}],pats:[{"en": "Where was/were + 主语 + 过去分词?", "zh": "……是在哪儿被……的？", "scene": "被动语态的特殊疑问句，疑问词后面跟一般疑问句语序。", "struct": "疑问词 + was/were + 主语 + 过去分词?", "cat": "dailychat", "ex": ["Where was this bag made?", "Where were the materials bought?"]}, {"en": "主语 + was/were + 过去分词 + by/in + 名词", "zh": "……被（某人／在某地）……", "scene": "地点前用 in，执行者前用 by，两个别搞混。", "struct": "主语 + was/were + 过去分词 + by/in + 名词", "cat": "dailychat", "ex": ["It was made in China.", "It was designed by a young woman."]}],quiz:{"v": {"q": "leather 的意思是：", "opts": ["布料", "皮革", "金属"], "a": 1}, "e": {"q": "「它是在中国制造的」应该说：", "opts": ["It made in China.", "It was make in China.", "It was made in China."], "a": 2}, "p": {"q": "It was made ______ China.", "opts": ["of", "in", "by"], "a": 1}},speak:"说 5 句话：用 Where was it made?、It was made in …、It was designed by …、It was sent to … 介绍一件你喜欢的物品的来历。"},
{n:143,title:"A Walk Through the Woods",topic:"被动语态 + 定语从句综合 · 描述地点与规定",reading:"I live in an old town which is surrounded by beautiful woods.\n\nIs it a famous place?\n\nYes. It is visited by hundreds of people every weekend.\n\nAre the woods kept clean?\n\nVisitors are asked to keep them clean, and litter baskets are put under the trees.\n\nWhat did you see on Sunday?\n\nI saw some bags which were left on the grass.\n\nThat's a shame. Everyone should be told to take their rubbish home.\n\nI'll take my own bag next time.",zh:"（原创改写）我住在一个古老的镇上，四周环绕着美丽的树林。\n\n那儿有名吗？\n\n有名。每个周末都有成百上千的人来参观。\n\n树林保持得干净吗？\n\n游客被要求保持清洁，树下也放了垃圾筐。\n\n星期天你看见什么了？\n\n我看见几个被人丢在草地上的袋子。\n\n真遗憾。应该告诉大家把垃圾带回家。\n\n下次我自己带袋子。",vocab:[{"w": "surround", "ph": "/səˈraʊnd/", "en": "to be all around something", "zh": "v. 环绕；包围", "eg": "The town is surrounded by woods."}, {"w": "visitor", "ph": "/ˈvɪzɪtə(r)/", "en": "a person who comes to see a place", "zh": "n. 游客；来访者", "eg": "Visitors are asked to keep it clean."}, {"w": "litter", "ph": "/ˈlɪtə(r)/", "en": "rubbish that people leave in public places", "zh": "n. 废弃物；垃圾", "eg": "Litter baskets are put under the trees."}, {"w": "grass", "ph": "/ɡrɑːs/", "en": "the green plants that cover the ground", "zh": "n. 草；草地", "eg": "Some bags were left on the grass."}],exprs:[{"en": "be surrounded by …", "zh": "被……环绕", "scene": "描述地理位置时非常常见的被动表达。", "struct": "be surrounded by + 名词", "cat": "experience", "ex": ["The town is surrounded by woods.", "The house is surrounded by a garden."]}, {"en": "be asked to do sth", "zh": "被要求做某事", "scene": "被动形式的要求或规定，语气比命令客气。", "struct": "be asked + to do", "cat": "dailychat", "ex": ["Visitors are asked to keep them clean.", "We were asked to arrive early."]}, {"en": "the + 名词 + which + be + 过去分词", "zh": "被……的……", "scene": "定语从句和被动语态常常一起出现，which 后面直接跟被动谓语。", "struct": "the + 名词 + which + be + 过去分词", "cat": "experience", "ex": ["a town which is surrounded by woods", "bags which were left on the grass"]}],pats:[{"en": "主语 + be + 过去分词 + by + 人", "zh": "……被……（一般现在时被动）", "scene": "经常性、习惯性的被动，用 am/is/are + 过去分词。", "struct": "主语 + am/is/are + 过去分词 + by + 人", "cat": "experience", "ex": ["It is visited by hundreds of people.", "The woods are kept clean."]}, {"en": "主语 + should be + 过去分词 + to do", "zh": "……应该被……去做……", "scene": "情态动词也能进被动：should be + 过去分词。", "struct": "主语 + should be + 过去分词 + to do", "cat": "opinion", "ex": ["Everyone should be told to take their rubbish home.", "The work should be finished today."]}],quiz:{"v": {"q": "surround 的意思是：", "opts": ["环绕；包围", "穿过", "离开"], "a": 0}, "e": {"q": "「游客被要求保持树林干净」应该说：", "opts": ["Visitors asked to keep the woods clean.", "Visitors are asking to keep the woods clean.", "Visitors are asked to keep the woods clean."], "a": 2}, "p": {"q": "I live in a town ______ is surrounded by woods.", "opts": ["what", "which", "who"], "a": 1}},speak:"说 5 句话：介绍你家附近的一个地方——用 which is surrounded by、is visited by、be asked to 描述，再说说那里存在的问题。"},
{n:144,title:"A Notice in the Woods",topic:"综合复习 · 问路、认人、告示与被动语态",reading:"Excuse me, can you tell me the way to Green Wood?\n\nGo straight on, and the wood is on your left. It's about ten minutes.\n\nThank you. Is there anyone who looks after it?\n\nYes. All the trees were planted by a group of volunteers.\n\nI see a notice on the gate. What does it say?\n\nIt says that everyone is asked not to pick the flowers.\n\nDo you know the man who is standing by the gate?\n\nYes, he's the gardener who was given the job last year.",zh:"（原创改写）打扰一下，您能告诉我去格林树林怎么走吗？\n\n一直往前走，树林就在你左手边，大约十分钟。\n\n谢谢。有人照管这片林子吗？\n\n有。所有的树都是一群志愿者种的。\n\n我看见门上有个告示，上面写的什么？\n\n上面写着，请大家不要摘花。\n\n您认识站在门口的那个人吗？\n\n认识，他就是去年得到这份工作的园丁。",vocab:[{"w": "straight", "ph": "/streɪt/", "en": "without turning left or right", "zh": "adv./adj. 直地；直的", "eg": "Go straight on for five minutes."}, {"w": "volunteer", "ph": "/ˌvɒlənˈtɪə(r)/", "en": "a person who works without being paid", "zh": "n. 志愿者", "eg": "The trees were planted by volunteers."}, {"w": "notice", "ph": "/ˈnəʊtɪs/", "en": "a written paper that gives information", "zh": "n. 告示；通知", "eg": "There's a notice on the gate."}, {"w": "pick", "ph": "/pɪk/", "en": "to take a flower or fruit from a plant", "zh": "v. 采摘；挑选", "eg": "Please don't pick the flowers."}],exprs:[{"en": "Can you tell me the way to …?", "zh": "能告诉我去……怎么走吗？", "scene": "问路最礼貌的开口方式，比 Where is … 更客气。", "struct": "Can you tell me the way to + 地点?", "cat": "dailychat", "ex": ["Can you tell me the way to Green Wood?", "Can you tell me the way to the station?"]}, {"en": "Go straight on, and … is on your left/right.", "zh": "一直往前走，……在你左边／右边。", "scene": "指路的标准句式，方向词用 left 或 right。", "struct": "Go straight on, and + 地点 + be + on your left/right", "cat": "dailychat", "ex": ["Go straight on, and the wood is on your left.", "Go straight on, and the bank is on your right."]}, {"en": "be asked not to do", "zh": "被要求不要做某事", "scene": "被动语态里的否定，not 放在 to 前面。", "struct": "be + 过去分词 + not to do", "cat": "dailychat", "ex": ["Everyone is asked not to pick the flowers.", "We were asked not to be late."]}],pats:[{"en": "Is there anyone who + 从句?", "zh": "有谁……吗？", "scene": "找负责人的问法，后面用 who 从句说明条件。", "struct": "Is there anyone who + 谓语?", "cat": "dailychat", "ex": ["Is there anyone who looks after it?", "Is there anyone who can help me?"]}, {"en": "It says that + 从句", "zh": "（告示／信上）说……", "scene": "转述告示、招牌、信件的文字内容，主语用 it。", "struct": "It says (that) + 从句", "cat": "dailychat", "ex": ["It says that everyone is asked not to pick the flowers.", "It says that the shop opens at nine."]}],quiz:{"v": {"q": "volunteer 的意思是：", "opts": ["游客", "园丁", "志愿者"], "a": 2}, "e": {"q": "想问「能告诉我去格林树林怎么走吗」：", "opts": ["Can you tell me where Green Wood?", "Can you tell me the way to Green Wood?", "Can you tell me the Green Wood way?"], "a": 1}, "p": {"q": "Everyone is asked ______ pick the flowers.", "opts": ["to not", "not to", "don't"], "a": 1}},speak:"说 6 句话：综合演练——先问路并听懂指路，再问这片林子由谁照管（被动语态 were planted by），问问告示上写了什么（It says that…），最后认一认门口那个人（the man who…）。"}].map(function(x){
  return {
    b: 1, n: x.n, title: x.title, topic: x.topic,
    reading: x.reading || "", zh: x.zh || "",
    vocab: x.vocab || [], exprs: x.exprs || [], pats: x.pats || [],
    quiz: x.quiz || null, speak: x.speak || "", audio: x.audio || ""
  };
});
